window.FG_FLK = window.FG_FLK || [];
window.FG_FLK.push([{"id":"n1266","sections":[{"name":"","text":"中国人民银行货币政策委员会条例\n（1997年4月15日中华人民共和国国务院令第215号发布 根据2024年1月13日《国务院关于修改部分行政法规和国务院决定的决定》修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了有助于国家货币政策的正确制定，根据中国人民银行法的规定，制定本条例。\n第二条 货币政策委员会工作坚持中国共产党的领导，推动健全现代货币政策框架，重要事项报党中央、国务院。\n第三条 货币政策委员会是中国人民银行制定货币政策的咨询议事机构。\n货币政策委员会依照本条例组成。\n第四条 货币政策委员会的职责是，在综合分析宏观经济形势的基础上，依据国家的宏观经济调控目标，讨论下列货币政策事项，并提出建议：\n（一）货币政策的制定、调整；\n（二）一定时期内的货币政策控制目标；\n（三）货币政策工具的运用；\n（四）有关货币政策的重要措施；\n（五）货币政策与其他宏观经济政策的协调。\n第五条 货币政策委员会通过全体会议履行职责。","level":1},{"name":"第二章 组织机构","text":"第六条 货币政策委员会由下列单位和人员组成：\n中国人民银行行长；\n国务院副秘书长1人；\n国家发展和改革委员会副主任1人；\n财政部副部长1人；\n中国人民银行副行长2人；\n国家金融监督管理总局局长；\n中国证券监督管理委员会主席；\n国家统计局局长；\n国家外汇管理局局长；\n中国银行业协会会长；\n专家委员3人。\n货币政策委员会组成单位和人员的调整，由国务院决定。\n第七条 货币政策委员会委员包括当然委员和提名委员。中国人民银行行长、国家金融监督管理总局局长、中国证券监督管理委员会主席、国家外汇管理局局长为货币政策委员会的当然委员。货币政策委员会其他委员为提名委员，其人选由中国人民银行提名或者中国人民银行商有关部门提名，报请国务院任命。\n第八条 货币政策委员会设主席一人，副主席一人。主席由中国人民银行行长担任；副主席由主席指定。\n第九条 货币政策委员会委员应当具备下列条件：\n（一）年龄一般在65周岁以下，具有中华人民共和国国籍；\n（二）公正廉洁，忠于职守，无违法、违纪记录；\n（三）具有宏观经济、金融等方面的专业知识和实践经验，熟悉有关法律、法规和政策。\n第十条 货币政策委员会中的专家委员除应当符合本条例第九条规定的条件外，还应当具备下列条件：\n（一）具有高级专业技术职称，从事经济金融工作10年以上，具有较高的学术水平；\n（二）非国家公务员，并且不在任何营利性机构任职。\n第十一条 货币政策委员会委员中的中国银行业协会会长任期一般不超过5年；专家委员一届任期不超过3年，最长任期一般不超过两届。\n第十二条 货币政策委员会委员有下列情形之一的，由中国人民银行报请国务院免去其货币政策委员会委员职务：\n（一）本人提出书面辞职申请的；\n（二）任职期间因职务变动，已经不能代表有关单位担任货币政策委员会委员的；\n（三）依照本条例第十一条规定任期已满的；\n（四）不履行委员义务或者因各种原因不能胜任委员工作的。\n第十三条 货币政策委员会设立秘书处，作为货币政策委员会的常设办事机构。","level":1},{"name":"第三章 委员的权利与义务","text":"第十四条 货币政策委员会委员具有同等的权利与义务。\n第十五条 货币政策委员会委员为履行职责需要，享有下列权利：\n（一）了解经济、金融和货币政策方面的情况；\n（二）对货币政策委员会所讨论的问题发表意见；\n（三）向货币政策委员会就货币政策问题提出议案，并享有表决权。\n第十六条 货币政策委员会委员应当出席货币政策委员会会议，并就有关货币政策事项提出意见和建议。\n第十七条 货币政策委员会委员应当恪尽职守，不得滥用职权、徇私舞弊。\n第十八条 货币政策委员会委员应当保守国家秘密、商业秘密，遵守货币政策委员会的工作制度，不得违反规定透露货币政策及有关情况。\n货币政策委员会委员违反规定泄露国家秘密、商业秘密的，撤销货币政策委员会委员的职务，并依法追究法律责任。\n第十九条 货币政策委员会委员在任职期内和离职以后一年内，不得公开反对已按法定程序制定的货币政策。","level":1},{"name":"第四章 工作程序","text":"第二十条 货币政策委员会实行例会制度，每季度召开1次。\n货币政策委员会主席或者1/3以上委员联名，可以提议召开临时会议。\n中国人民银行在货币政策委员会例会召开后，采取多种方式加强预期引导和市场沟通。\n第二十一条 货币政策委员会秘书处应当在货币政策委员会例会召开前，将会议议题及有关资料送达全部委员。\n第二十二条 货币政策委员会会议有2/3以上委员出席，方可举行。\n第二十三条 货币政策委员会会议应当以会议纪要的形式记录各种意见。\n货币政策委员会委员提出的货币政策议案，经出席会议的2/3以上委员表决通过，形成货币政策委员会建议书。\n第二十四条 中国人民银行报请国务院批准有关利率、汇率或者其他货币政策重要事项的决定方案时，可以将货币政策委员会建议书或者会议纪要作为附件一并报送。\n第二十五条 货币政策委员会的内部工作制度，由货币政策委员会制定。","level":1},{"name":"第五章 附 则","text":"第二十六条 本条例自发布之日起施行。","level":1}]},{"id":"n1267","sections":[{"name":"","text":"教学成果奖励条例\n（1994年3月14日中华人民共和国国务院令第151号发布 根据2024年3月10日《国务院关于修改和废止部分行政法规的决定》修订）\n第一条 为奖励取得教学成果的集体和个人，鼓励教育工作者从事教育教学研究，提高教学水平和教育质量，制定本条例。\n第二条 本条例所称教学成果，是指反映教育教学规律，具有独创性、新颖性、实用性，对提高教学水平和教育质量、实现培养目标产生明显效果的教育教学方案。\n第三条 各级各类学校、学术团体和其他社会组织、教师及其他个人，均可以依照本条例的规定申请教学成果奖。\n第四条 教学成果奖，按其对提高教学水平和教育质量、实现培养目标产生的效果，分为国家级和省（部）级。\n第五条 具备下列条件的，可以申请国家级教学成果奖：\n（一）国内首创的；\n（二）经过2年以上教育教学实践检验的；\n（三）在全国产生一定影响的。\n第六条 国家级教学成果奖分为特等奖、一等奖、二等奖三个等级，授予相应的证书、奖章和奖金。\n第七条 国家级教学成果奖的评审、批准和授予工作，由国务院教育行政部门负责；其中授予特等奖的，应当报经国务院批准。\n第八条 申请国家级教学成果奖，由成果的持有单位或者个人，按照其行政隶属关系，向省、自治区、直辖市人民政府教育行政部门或者国务院有关部门教育管理机构提出申请，由受理申请的教育行政部门或者教育管理机构向国务院教育行政部门推荐。\n国务院有关部门所属单位或者个人也可以向所在地省、自治区、直辖市人民政府教育行政部门提出申请，由受理申请的教育行政部门向国务院教育行政部门推荐。\n第九条 不属于同一省、自治区、直辖市或者国务院部门的两个以上单位或者个人共同完成的教学成果项目申请国家级教学成果奖的，由参加单位或者个人联合向主持单位或者主持人所在地省、自治区、直辖市人民政府教育行政部门或者国务院有关部门教育管理机构提出申请，由受理申请的教育行政部门或者教育管理机构向国务院教育行政部门推荐。\n第十条 国务院教育行政部门对申请国家级教学成果奖的项目，应当自收到推荐之日起90日内予以公布；任何单位或者个人对该教学成果权属有异议的，可以自公布之日起90日内提出，报国务院教育行政部门裁定。\n第十一条 国家级教学成果奖每4年评审一次。\n第十二条 省（部）级教学成果奖的评奖条件、奖励等级、奖金数额、评审组织和办法，由省、自治区、直辖市人民政府、国务院有关部门参照本条例规定。其奖金来源，属于省、自治区、直辖市人民政府批准授予的，从地方预算安排的事业费中支付；属于国务院有关部门批准授予的，从其事业费中支付。\n第十三条 教学成果奖的奖金，归项目获奖者所有，任何单位或者个人不得截留。\n第十四条 获得教学成果奖，应当记入本人考绩档案，作为评定职称、晋级增薪的一项重要依据。\n第十五条 弄虚作假或者剽窃他人教学成果获奖的，由授奖单位予以撤销，收回证书、奖章和奖金，并责成有关单位给予行政处分。\n第十六条 本条例自发布之日起施行。","level":0}]},{"id":"n1268","sections":[{"name":"","text":"企业信息公示暂行条例\n（2014年8月7日中华人民共和国国务院令第654号公布 根据2024年3月10日《国务院关于修改和废止部分行政法规的决定》修订）\n第一条 为了保障公平竞争，促进企业诚信自律，规范企业信息公示，强化企业信用约束，维护交易安全，提高政府监管效能，扩大社会监督，制定本条例。\n第二条 本条例所称企业信息，是指在市场监督管理部门登记的企业从事生产经营活动过程中形成的信息，以及政府部门在履行职责过程中产生的能够反映企业状况的信息。\n第三条 企业信息公示应当真实、及时。公示的企业信息涉及国家秘密、国家安全或者社会公共利益的，应当报请主管的保密行政管理部门或者国家安全机关批准。县级以上地方人民政府有关部门公示的企业信息涉及企业商业秘密或者个人隐私的，应当报请上级主管部门批准。\n第四条 省、自治区、直辖市人民政府领导本行政区域的企业信息公示工作，按照国家社会信用信息平台建设的总体要求，推动本行政区域企业信用信息公示系统的建设。\n第五条 国务院市场监督管理部门推进、监督企业信息公示工作，组织国家企业信用信息公示系统的建设。国务院其他有关部门依照本条例规定做好企业信息公示相关工作。\n县级以上地方人民政府有关部门依照本条例规定做好企业信息公示工作。\n第六条 市场监督管理部门应当通过国家企业信用信息公示系统，公示其在履行职责过程中产生的下列企业信息：\n（一）注册登记、备案信息；\n（二）动产抵押登记信息；\n（三）股权出质登记信息；\n（四）行政处罚信息；\n（五）其他依法应当公示的信息。\n前款规定的企业信息应当自产生之日起20个工作日内予以公示。\n第七条 市场监督管理部门以外的其他政府部门（以下简称其他政府部门）应当公示其在履行职责过程中产生的下列企业信息：\n（一）行政许可准予、变更、延续信息；\n（二）行政处罚信息；\n（三）其他依法应当公示的信息。\n其他政府部门可以通过国家企业信用信息公示系统，也可以通过其他系统公示前款规定的企业信息。市场监督管理部门和其他政府部门应当按照国家社会信用信息平台建设的总体要求，实现企业信息的互联共享。\n第八条 企业应当于每年1月1日至6月30日，通过国家企业信用信息公示系统向市场监督管理部门报送上一年度年度报告，并向社会公示。\n当年设立登记的企业，自下一年起报送并公示年度报告。\n第九条 企业年度报告内容包括：\n（一）企业通信地址、邮政编码、联系电话、电子邮箱等信息；\n（二）企业开业、歇业、清算等存续状态信息；\n（三）企业投资设立企业、购买股权信息；\n（四）企业为有限责任公司或者股份有限公司的，其股东或者发起人认缴和实缴的出资额、出资时间、出资方式等信息；\n（五）有限责任公司股东股权转让等股权变更信息；\n（六）企业网站以及从事网络经营的网店的名称、网址等信息；\n（七）企业从业人数、资产总额、负债总额、对外提供保证担保、所有者权益合计、营业总收入、主营业务收入、利润总额、净利润、纳税总额信息。\n前款第一项至第六项规定的信息应当向社会公示，第七项规定的信息由企业选择是否向社会公示。\n经企业同意，公民、法人或者其他组织可以查询企业选择不公示的信息。\n第十条 企业应当自下列信息形成之日起20个工作日内通过国家企业信用信息公示系统向社会公示：\n（一）有限责任公司股东或者股份有限公司发起人认缴和实缴的出资额、出资时间、出资方式等信息；\n（二）有限责任公司股东股权转让等股权变更信息；\n（三）行政许可取得、变更、延续信息；\n（四）知识产权出质登记信息；\n（五）受到行政处罚的信息；\n（六）其他依法应当公示的信息。\n市场监督管理部门发现企业未依照前款规定履行公示义务的，应当责令其限期履行。\n第十一条 政府部门和企业分别对其公示信息的真实性、及时性负责。\n第十二条 政府部门发现其公示的信息不准确的，应当及时更正。公民、法人或者其他组织有证据证明政府部门公示的信息不准确的，有权要求该政府部门予以更正。\n企业发现其公示的信息不准确的，应当及时更正；但是，企业年度报告公示信息的更正应当在每年6月30日之前完成。更正前后的信息应当同时公示。\n第十三条 公民、法人或者其他组织发现企业公示的信息虚假的，可以向市场监督管理部门举报，接到举报的市场监督管理部门应当自接到举报材料之日起20个工作日内进行核查，予以处理，并将处理情况书面告知举报人。\n公民、法人或者其他组织对依照本条例规定公示的企业信息有疑问的，可以向政府部门申请查询，收到查询申请的政府部门应当自收到申请之日起20个工作日内书面答复申请人。\n第十四条 国务院市场监督管理部门和省、自治区、直辖市人民政府市场监督管理部门应当按照公平规范的要求，根据企业注册号等随机摇号，确定抽查的企业，组织对企业公示信息的情况进行检查。\n市场监督管理部门抽查企业公示的信息，可以采取书面检查、实地核查、网络监测等方式。市场监督管理部门抽查企业公示的信息，可以委托会计师事务所、税务师事务所、律师事务所等专业机构开展相关工作，并依法利用其他政府部门作出的检查、核查结果或者专业机构作出的专业结论。\n抽查结果由市场监督管理部门通过国家企业信用信息公示系统向社会公布。\n第十五条 市场监督管理部门对企业公示的信息依法开展抽查或者根据举报进行核查，企业应当配合，接受询问调查，如实反映情况，提供相关材料。\n对不予配合情节严重的企业，市场监督管理部门应当通过国家企业信用信息公示系统公示。\n第十六条 市场监督管理部门对涉嫌违反本条例规定的行为进行查处，可以行使下列职权：\n（一）进入企业的经营场所实施现场检查；\n（二）查阅、复制、收集与企业经营活动相关的合同、票据、账簿以及其他资料；\n（三）向与企业经营活动有关的单位和个人调查了解情况；\n（四）依法查询涉嫌违法的企业银行账户；\n（五）法律、行政法规规定的其他职权。\n市场监督管理部门行使前款第四项规定的职权的，应当经市场监督管理部门主要负责人批准。\n第十七条 任何公民、法人或者其他组织不得非法修改公示的企业信息，不得非法获取企业信息。\n第十八条 企业未按照本条例规定的期限公示年度报告或者未按照市场监督管理部门责令的期限公示有关企业信息的，由县级以上市场监督管理部门列入经营异常名录，并依法给予行政处罚。企业因连续2年未按规定报送年度报告被列入经营异常名录未改正，且通过登记的住所或者经营场所无法取得联系的，由县级以上市场监督管理部门吊销营业执照。\n企业公示信息隐瞒真实情况、弄虚作假的，法律、行政法规有规定的，依照其规定；没有规定的，由市场监督管理部门责令改正，处1万元以上5万元以下罚款；情节严重的，处5万元以上20万元以下罚款，列入市场监督管理严重违法失信名单，并可以吊销营业执照。被列入市场监督管理严重违法失信名单的企业的法定代表人、负责人，3年内不得担任其他企业的法定代表人、负责人。\n企业被吊销营业执照后，应当依法办理注销登记；未办理注销登记的，由市场监督管理部门依法作出处理。\n第十九条 县级以上地方人民政府及其有关部门应当建立健全信用约束机制，在政府采购、工程招投标、国有土地出让、授予荣誉称号等工作中，将企业信息作为重要考量因素，对被列入经营异常名录或者市场监督管理严重违法失信名单的企业依法予以限制或者禁入。\n第二十条 鼓励企业主动纠正违法失信行为、消除不良影响，依法申请修复失信记录。政府部门依法解除相关管理措施并修复失信记录的，应当及时将上述信息与有关部门共享。\n第二十一条 政府部门未依照本条例规定履行职责的，由监察机关、上一级政府部门责令改正；情节严重的，对负有责任的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。\n第二十二条 非法修改公示的企业信息，或者非法获取企业信息的，依照有关法律、行政法规规定追究法律责任。\n第二十三条 公民、法人或者其他组织认为政府部门在企业信息公示工作中的具体行政行为侵犯其合法权益的，可以依法申请行政复议或者提起行政诉讼。\n第二十四条 企业依照本条例规定公示信息，不免除其依照其他有关法律、行政法规规定公示信息的义务。\n第二十五条 法律、法规授权的具有管理公共事务职能的组织公示企业信息适用本条例关于政府部门公示企业信息的规定。\n第二十六条 国务院市场监督管理部门负责制定国家企业信用信息公示系统的技术规范。\n个体工商户、农民专业合作社信息公示的具体办法由国务院市场监督管理部门另行制定。\n第二十七条 本条例自2014年10月1日起施行。","level":0}]},{"id":"n1269","sections":[{"name":"","text":"中华人民共和国人类遗传资源管理条例\n（2019年5月28日中华人民共和国国务院令第717号公布 根据2024年3月10日《国务院关于修改和废止部分行政法规的决定》修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了有效保护和合理利用我国人类遗传资源，维护公众健康、国家安全和社会公共利益，制定本条例。\n第二条 本条例所称人类遗传资源包括人类遗传资源材料和人类遗传资源信息。\n人类遗传资源材料是指含有人体基因组、基因等遗传物质的器官、组织、细胞等遗传材料。\n人类遗传资源信息是指利用人类遗传资源材料产生的数据等信息资料。\n第三条 采集、保藏、利用、对外提供我国人类遗传资源，应当遵守本条例。\n为临床诊疗、采供血服务、查处违法犯罪、兴奋剂检测和殡葬等活动需要，采集、保藏器官、组织、细胞等人体物质及开展相关活动，依照相关法律、行政法规规定执行。\n第四条 国务院卫生健康主管部门负责全国人类遗传资源管理工作；国务院其他有关部门在各自的职责范围内，负责有关人类遗传资源管理工作。\n省、自治区、直辖市人民政府人类遗传资源主管部门负责本行政区域人类遗传资源管理工作；省、自治区、直辖市人民政府其他有关部门在各自的职责范围内，负责本行政区域有关人类遗传资源管理工作。\n第五条 国家加强对我国人类遗传资源的保护，开展人类遗传资源调查，对重要遗传家系和特定地区人类遗传资源实行申报登记制度。\n国务院卫生健康主管部门负责组织我国人类遗传资源调查，制定重要遗传家系和特定地区人类遗传资源申报登记具体办法。\n第六条 国家支持合理利用人类遗传资源开展科学研究、发展生物医药产业、提高诊疗技术，提高我国生物安全保障能力，提升人民健康保障水平。\n第七条 外国组织、个人及其设立或者实际控制的机构不得在我国境内采集、保藏我国人类遗传资源，不得向境外提供我国人类遗传资源。\n第八条 采集、保藏、利用、对外提供我国人类遗传资源，不得危害我国公众健康、国家安全和社会公共利益。\n第九条 采集、保藏、利用、对外提供我国人类遗传资源，应当符合伦理原则，并按照国家有关规定进行伦理审查。\n采集、保藏、利用、对外提供我国人类遗传资源，应当尊重人类遗传资源提供者的隐私权，取得其事先知情同意，并保护其合法权益。\n采集、保藏、利用、对外提供我国人类遗传资源，应当遵守国务院卫生健康主管部门制定的技术规范。\n第十条 禁止买卖人类遗传资源。\n为科学研究依法提供或者使用人类遗传资源并支付或者收取合理成本费用，不视为买卖。","level":1},{"name":"第二章 采集和保藏","text":"第十一条 采集我国重要遗传家系、特定地区人类遗传资源或者采集国务院卫生健康主管部门规定种类、数量的人类遗传资源的，应当符合下列条件，并经国务院卫生健康主管部门批准：\n（一）具有法人资格；\n（二）采集目的明确、合法；\n（三）采集方案合理；\n（四）通过伦理审查；\n（五）具有负责人类遗传资源管理的部门和管理制度；\n（六）具有与采集活动相适应的场所、设施、设备和人员。\n第十二条 采集我国人类遗传资源，应当事先告知人类遗传资源提供者采集目的、采集用途、对健康可能产生的影响、个人隐私保护措施及其享有的自愿参与和随时无条件退出的权利，征得人类遗传资源提供者书面同意。\n在告知人类遗传资源提供者前款规定的信息时，必须全面、完整、真实、准确，不得隐瞒、误导、欺骗。\n第十三条 国家加强人类遗传资源保藏工作，加快标准化、规范化的人类遗传资源保藏基础平台和人类遗传资源大数据建设，为开展相关研究开发活动提供支撑。\n国家鼓励科研机构、高等学校、医疗机构、企业根据自身条件和相关研究开发活动需要开展人类遗传资源保藏工作，并为其他单位开展相关研究开发活动提供便利。\n第十四条 保藏我国人类遗传资源、为科学研究提供基础平台的，应当符合下列条件，并经国务院卫生健康主管部门批准：\n（一）具有法人资格；\n（二）保藏目的明确、合法；\n（三）保藏方案合理；\n（四）拟保藏的人类遗传资源来源合法；\n（五）通过伦理审查；\n（六）具有负责人类遗传资源管理的部门和保藏管理制度；\n（七）具有符合国家人类遗传资源保藏技术规范和要求的场所、设施、设备和人员。\n第十五条 保藏单位应当对所保藏的人类遗传资源加强管理和监测，采取安全措施，制定应急预案，确保保藏、使用安全。\n保藏单位应当完整记录人类遗传资源保藏情况，妥善保存人类遗传资源的来源信息和使用信息，确保人类遗传资源的合法使用。\n保藏单位应当就本单位保藏人类遗传资源情况向国务院卫生健康主管部门提交年度报告。\n第十六条 国家人类遗传资源保藏基础平台和数据库应当依照国家有关规定向有关科研机构、高等学校、医疗机构、企业开放。\n为公众健康、国家安全和社会公共利益需要，国家可以依法使用保藏单位保藏的人类遗传资源。","level":1},{"name":"第三章 利用和对外提供","text":"第十七条 国务院卫生健康主管部门和省、自治区、直辖市人民政府人类遗传资源主管部门应当会同本级人民政府有关部门对利用人类遗传资源开展科学研究、发展生物医药产业统筹规划，合理布局，加强创新体系建设，促进生物科技和产业创新、协调发展。\n第十八条 科研机构、高等学校、医疗机构、企业利用人类遗传资源开展研究开发活动，对其研究开发活动以及成果的产业化依照法律、行政法规和国家有关规定予以支持。\n第十九条 国家鼓励科研机构、高等学校、医疗机构、企业根据自身条件和相关研究开发活动需要，利用我国人类遗传资源开展国际合作科学研究，提升相关研究开发能力和水平。\n第二十条 利用我国人类遗传资源开展生物技术研究开发活动或者开展临床试验的，应当遵守有关生物技术研究、临床应用管理法律、行政法规和国家有关规定。\n第二十一条 外国组织及外国组织、个人设立或者实际控制的机构（以下称外方单位）需要利用我国人类遗传资源开展科学研究活动的，应当遵守我国法律、行政法规和国家有关规定，并采取与我国科研机构、高等学校、医疗机构、企业（以下称中方单位）合作的方式进行。\n第二十二条 利用我国人类遗传资源开展国际合作科学研究的，应当符合下列条件，并由合作双方共同提出申请，经国务院卫生健康主管部门批准：\n（一）对我国公众健康、国家安全和社会公共利益没有危害；\n（二）合作双方为具有法人资格的中方单位、外方单位，并具有开展相关工作的基础和能力；\n（三）合作研究目的和内容明确、合法，期限合理；\n（四）合作研究方案合理；\n（五）拟使用的人类遗传资源来源合法，种类、数量与研究内容相符；\n（六）通过合作双方各自所在国（地区）的伦理审查；\n（七）研究成果归属明确，有合理明确的利益分配方案。\n为获得相关药品和医疗器械在我国上市许可，在临床机构利用我国人类遗传资源开展国际合作临床试验、不涉及人类遗传资源材料出境的，不需要审批。但是，合作双方在开展临床试验前应当将拟使用的人类遗传资源种类、数量及其用途向国务院卫生健康主管部门备案。国务院卫生健康主管部门和省、自治区、直辖市人民政府人类遗传资源主管部门加强对备案事项的监管。\n第二十三条 在利用我国人类遗传资源开展国际合作科学研究过程中，合作方、研究目的、研究内容、合作期限等重大事项发生变更的，应当办理变更审批手续。\n第二十四条 利用我国人类遗传资源开展国际合作科学研究，应当保证中方单位及其研究人员在合作期间全过程、实质性地参与研究，研究过程中的所有记录以及数据信息等完全向中方单位开放并向中方单位提供备份。\n利用我国人类遗传资源开展国际合作科学研究，产生的成果申请专利的，应当由合作双方共同提出申请，专利权归合作双方共有。研究产生的其他科技成果，其使用权、转让权和利益分享办法由合作双方通过合作协议约定；协议没有约定的，合作双方都有使用的权利，但向第三方转让须经合作双方同意，所获利益按合作双方贡献大小分享。\n第二十五条 利用我国人类遗传资源开展国际合作科学研究，合作双方应当按照平等互利、诚实信用、共同参与、共享成果的原则，依法签订合作协议，并依照本条例第二十四条的规定对相关事项作出明确、具体的约定。\n第二十六条 利用我国人类遗传资源开展国际合作科学研究，合作双方应当在国际合作活动结束后6个月内共同向国务院卫生健康主管部门提交合作研究情况报告。\n第二十七条 利用我国人类遗传资源开展国际合作科学研究，或者因其他特殊情况确需将我国人类遗传资源材料运送、邮寄、携带出境的，应当符合下列条件，并取得国务院卫生健康主管部门出具的人类遗传资源材料出境证明：\n（一）对我国公众健康、国家安全和社会公共利益没有危害；\n（二）具有法人资格；\n（三）有明确的境外合作方和合理的出境用途；\n（四）人类遗传资源材料采集合法或者来自合法的保藏单位；\n（五）通过伦理审查。\n利用我国人类遗传资源开展国际合作科学研究，需要将我国人类遗传资源材料运送、邮寄、携带出境的，可以单独提出申请，也可以在开展国际合作科学研究申请中列明出境计划一并提出申请，由国务院卫生健康主管部门合并审批。\n将我国人类遗传资源材料运送、邮寄、携带出境的，凭人类遗传资源材料出境证明办理海关手续。\n第二十八条 将人类遗传资源信息向外国组织、个人及其设立或者实际控制的机构提供或者开放使用，不得危害我国公众健康、国家安全和社会公共利益；可能影响我国公众健康、国家安全和社会公共利益的，应当通过国务院卫生健康主管部门组织的安全审查。\n将人类遗传资源信息向外国组织、个人及其设立或者实际控制的机构提供或者开放使用的，应当向国务院卫生健康主管部门备案并提交信息备份。\n利用我国人类遗传资源开展国际合作科学研究产生的人类遗传资源信息，合作双方可以使用。","level":1},{"name":"第四章 服务和监督","text":"第二十九条 国务院卫生健康主管部门应当加强电子政务建设，方便申请人利用互联网办理审批、备案等事项。\n第三十条 国务院卫生健康主管部门应当制定并及时发布有关采集、保藏、利用、对外提供我国人类遗传资源的审批指南和示范文本，加强对申请人办理有关审批、备案等事项的指导。\n第三十一条 国务院卫生健康主管部门应当聘请生物技术、医药、卫生、伦理、法律等方面的专家组成专家评审委员会，对依照本条例规定提出的采集、保藏我国人类遗传资源，开展国际合作科学研究以及将我国人类遗传资源材料运送、邮寄、携带出境的申请进行技术评审。评审意见作为作出审批决定的参考依据。\n第三十二条 国务院卫生健康主管部门应当自受理依照本条例规定提出的采集、保藏我国人类遗传资源，开展国际合作科学研究以及将我国人类遗传资源材料运送、邮寄、携带出境申请之日起20个工作日内，作出批准或者不予批准的决定；不予批准的，应当说明理由。因特殊原因无法在规定期限内作出审批决定的，经国务院卫生健康主管部门负责人批准，可以延长10个工作日。\n第三十三条 国务院卫生健康主管部门和省、自治区、直辖市人民政府人类遗传资源主管部门应当加强对采集、保藏、利用、对外提供人类遗传资源活动各环节的监督检查，发现违反本条例规定的，及时依法予以处理并向社会公布检查、处理结果。\n第三十四条 国务院卫生健康主管部门和省、自治区、直辖市人民政府人类遗传资源主管部门进行监督检查，可以采取下列措施：\n（一）进入现场检查；\n（二）询问相关人员；\n（三）查阅、复制有关资料；\n（四）查封、扣押有关人类遗传资源。\n第三十五条 任何单位和个人对违反本条例规定的行为，有权向国务院卫生健康主管部门和省、自治区、直辖市人民政府人类遗传资源主管部门投诉、举报。\n国务院卫生健康主管部门和省、自治区、直辖市人民政府人类遗传资源主管部门应当公布投诉、举报电话和电子邮件地址，接受相关投诉、举报。对查证属实的，给予举报人奖励。","level":1},{"name":"第五章 法律责任","text":"第三十六条 违反本条例规定，有下列情形之一的，由国务院卫生健康主管部门责令停止违法行为，没收违法采集、保藏的人类遗传资源和违法所得，处50万元以上500万元以下罚款，违法所得在100万元以上的，处违法所得5倍以上10倍以下罚款：\n（一）未经批准，采集我国重要遗传家系、特定地区人类遗传资源，或者采集国务院卫生健康主管部门规定种类、数量的人类遗传资源；\n（二）未经批准，保藏我国人类遗传资源；\n（三）未经批准，利用我国人类遗传资源开展国际合作科学研究；\n（四）未通过安全审查，将可能影响我国公众健康、国家安全和社会公共利益的人类遗传资源信息向外国组织、个人及其设立或者实际控制的机构提供或者开放使用；\n（五）开展国际合作临床试验前未将拟使用的人类遗传资源种类、数量及其用途向国务院卫生健康主管部门备案。\n第三十七条 提供虚假材料或者采取其他欺骗手段取得行政许可的，由国务院卫生健康主管部门撤销已经取得的行政许可，处50万元以上500万元以下罚款，5年内不受理相关责任人及单位提出的许可申请。\n第三十八条 违反本条例规定，未经批准将我国人类遗传资源材料运送、邮寄、携带出境的，由海关依照法律、行政法规的规定处罚。人类遗传资源主管部门应当配合海关开展鉴定等执法协助工作。海关应当将依法没收的人类遗传资源材料移送省、自治区、直辖市人民政府人类遗传资源主管部门进行处理。\n第三十九条 违反本条例规定，有下列情形之一的，由省、自治区、直辖市人民政府人类遗传资源主管部门责令停止开展相关活动，没收违法采集、保藏的人类遗传资源和违法所得，处50万元以上100万元以下罚款，违法所得在100万元以上的，处违法所得5倍以上10倍以下罚款：\n（一）采集、保藏、利用、对外提供我国人类遗传资源未通过伦理审查；\n（二）采集我国人类遗传资源未经人类遗传资源提供者事先知情同意，或者采取隐瞒、误导、欺骗等手段取得人类遗传资源提供者同意；\n（三）采集、保藏、利用、对外提供我国人类遗传资源违反相关技术规范；\n（四）将人类遗传资源信息向外国组织、个人及其设立或者实际控制的机构提供或者开放使用，未向国务院卫生健康主管部门备案或者提交信息备份。\n第四十条 违反本条例规定，有下列情形之一的，由国务院卫生健康主管部门责令改正，给予警告，可以处50万元以下罚款：\n（一）保藏我国人类遗传资源过程中未完整记录并妥善保存人类遗传资源的来源信息和使用信息；\n（二）保藏我国人类遗传资源未提交年度报告；\n（三）开展国际合作科学研究未及时提交合作研究情况报告。\n第四十一条 外国组织、个人及其设立或者实际控制的机构违反本条例规定，在我国境内采集、保藏我国人类遗传资源，利用我国人类遗传资源开展科学研究，或者向境外提供我国人类遗传资源的，由国务院卫生健康主管部门责令停止违法行为，没收违法采集、保藏的人类遗传资源和违法所得，处100万元以上1000万元以下罚款，违法所得在100万元以上的，处违法所得5倍以上10倍以下罚款。\n第四十二条 违反本条例规定，买卖人类遗传资源的，由国务院卫生健康主管部门责令停止违法行为，没收违法采集、保藏的人类遗传资源和违法所得，处100万元以上1000万元以下罚款，违法所得在100万元以上的，处违法所得5倍以上10倍以下罚款。\n第四十三条 对有本条例第三十六条、第三十九条、第四十一条、第四十二条规定违法行为的单位，情节严重的，由国务院卫生健康主管部门或者省、自治区、直辖市人民政府人类遗传资源主管部门依据职责禁止其1至5年内从事采集、保藏、利用、对外提供我国人类遗传资源的活动；情节特别严重的，永久禁止其从事采集、保藏、利用、对外提供我国人类遗传资源的活动。\n对有本条例第三十六条至第三十九条、第四十一条、第四十二条规定违法行为的单位的法定代表人、主要负责人、直接负责的主管人员以及其他责任人员，依法给予处分，并由国务院卫生健康主管部门或者省、自治区、直辖市人民政府人类遗传资源主管部门依据职责没收其违法所得，处50万元以下罚款；情节严重的，禁止其1至5年内从事采集、保藏、利用、对外提供我国人类遗传资源的活动；情节特别严重的，永久禁止其从事采集、保藏、利用、对外提供我国人类遗传资源的活动。\n单位和个人有本条例规定违法行为的，记入信用记录，并依照有关法律、行政法规的规定向社会公示。\n第四十四条 违反本条例规定，侵害他人合法权益的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第四十五条 国务院卫生健康主管部门和省、自治区、直辖市人民政府人类遗传资源主管部门的工作人员违反本条例规定，不履行职责或者滥用职权、玩忽职守、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附 则","text":"第四十六条 人类遗传资源相关信息属于国家秘密的，应当依照《中华人民共和国保守国家秘密法》和国家其他有关保密规定实施保密管理。\n第四十七条 本条例自2019年7月1日起施行。","level":1}]},{"id":"n1270","sections":[{"name":"","text":"不动产登记暂行条例\n（2014年11月24日中华人民共和国国务院令第656号公布 根据2019年3月24日《国务院关于修改部分行政法规的决定》第一次修订 根据2024年3月10日《国务院关于修改和废止部分行政法规的决定》第二次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为整合不动产登记职责，规范登记行为，方便群众申请登记，保护权利人合法权益，根据《中华人民共和国民法典》等法律，制定本条例。\n第二条 本条例所称不动产登记，是指不动产登记机构依法将不动产权利归属和其他法定事项记载于不动产登记簿的行为。\n本条例所称不动产，是指土地、海域以及房屋、林木等定着物。\n第三条 不动产首次登记、变更登记、转移登记、注销登记、更正登记、异议登记、预告登记、查封登记等，适用本条例。\n第四条 国家实行不动产统一登记制度。\n不动产登记遵循严格管理、稳定连续、方便群众的原则。\n不动产权利人已经依法享有的不动产权利，不因登记机构和登记程序的改变而受到影响。\n第五条 下列不动产权利，依照本条例的规定办理登记：\n（一）集体土地所有权；\n（二）房屋等建筑物、构筑物所有权；\n（三）森林、林木所有权；\n（四）耕地、林地、草地等土地承包经营权；\n（五）建设用地使用权；\n（六）宅基地使用权；\n（七）海域使用权；\n（八）地役权；\n（九）抵押权；\n（十）法律规定需要登记的其他不动产权利。\n第六条 国务院自然资源主管部门负责指导、监督全国不动产登记工作。\n县级以上地方人民政府应当确定一个部门为本行政区域的不动产登记机构，负责不动产登记工作，并接受上级人民政府不动产登记主管部门的指导、监督。\n第七条 不动产登记由不动产所在地的县级人民政府不动产登记机构办理；直辖市、设区的市人民政府可以确定本级不动产登记机构统一办理所属各区的不动产登记。\n跨县级行政区域的不动产登记，由所跨县级行政区域的不动产登记机构分别办理。不能分别办理的，由所跨县级行政区域的不动产登记机构协商办理；协商不成的，由共同的上一级人民政府不动产登记主管部门指定办理。\n国务院确定的重点国有林区的森林、林木和林地，国务院批准项目用海、用岛，中央国家机关使用的国有土地等不动产登记，由国务院自然资源主管部门会同有关部门规定。","level":1},{"name":"第二章 不动产登记簿","text":"第八条 不动产以不动产单元为基本单位进行登记。不动产单元具有唯一编码。\n不动产登记机构应当按照国务院自然资源主管部门的规定设立统一的不动产登记簿。\n不动产登记簿应当记载以下事项：\n（一）不动产的坐落、界址、空间界限、面积、用途等自然状况；\n（二）不动产权利的主体、类型、内容、来源、期限、权利变化等权属状况；\n（三）涉及不动产权利限制、提示的事项；\n（四）其他相关事项。\n第九条 不动产登记簿应当采用电子介质，暂不具备条件的，可以采用纸质介质。不动产登记机构应当明确不动产登记簿唯一、合法的介质形式。\n不动产登记簿采用电子介质的，应当定期进行异地备份，并具有唯一、确定的纸质转化形式。\n第十条 不动产登记机构应当依法将各类登记事项准确、完整、清晰地记载于不动产登记簿。任何人不得损毁不动产登记簿，除依法予以更正外不得修改登记事项。\n第十一条 不动产登记工作人员应当具备与不动产登记工作相适应的专业知识和业务能力。\n不动产登记机构应当加强对不动产登记工作人员的管理和专业技术培训。\n第十二条 不动产登记机构应当指定专人负责不动产登记簿的保管，并建立健全相应的安全责任制度。\n采用纸质介质不动产登记簿的，应当配备必要的防盗、防火、防渍、防有害生物等安全保护设施。\n采用电子介质不动产登记簿的，应当配备专门的存储设施，并采取信息网络安全防护措施。\n第十三条 不动产登记簿由不动产登记机构永久保存。不动产登记簿损毁、灭失的，不动产登记机构应当依据原有登记资料予以重建。\n行政区域变更或者不动产登记机构职能调整的，应当及时将不动产登记簿移交相应的不动产登记机构。","level":1},{"name":"第三章 登记程序","text":"第十四条 因买卖、设定抵押权等申请不动产登记的，应当由当事人双方共同申请。\n属于下列情形之一的，可以由当事人单方申请：\n（一）尚未登记的不动产首次申请登记的；\n（二）继承、接受遗赠取得不动产权利的；\n（三）人民法院、仲裁委员会生效的法律文书或者人民政府生效的决定等设立、变更、转让、消灭不动产权利的；\n（四）权利人姓名、名称或者自然状况发生变化，申请变更登记的；\n（五）不动产灭失或者权利人放弃不动产权利，申请注销登记的；\n（六）申请更正登记或者异议登记的；\n（七）法律、行政法规规定可以由当事人单方申请的其他情形。\n第十五条 当事人或者其代理人应当向不动产登记机构申请不动产登记。\n不动产登记机构将申请登记事项记载于不动产登记簿前，申请人可以撤回登记申请。\n第十六条 申请人应当提交下列材料，并对申请材料的真实性负责：\n（一）登记申请书；\n（二）申请人、代理人身份证明材料、授权委托书；\n（三）相关的不动产权属来源证明材料、登记原因证明文件、不动产权属证书；\n（四）不动产界址、空间界限、面积等材料；\n（五）与他人利害关系的说明材料；\n（六）法律、行政法规以及本条例实施细则规定的其他材料。\n不动产登记机构应当在办公场所和门户网站公开申请登记所需材料目录和示范文本等信息。\n第十七条 不动产登记机构收到不动产登记申请材料，应当分别按照下列情况办理：\n（一）属于登记职责范围，申请材料齐全、符合法定形式，或者申请人按照要求提交全部补正申请材料的，应当受理并书面告知申请人；\n（二）申请材料存在可以当场更正的错误的，应当告知申请人当场更正，申请人当场更正后，应当受理并书面告知申请人；\n（三）申请材料不齐全或者不符合法定形式的，应当当场书面告知申请人不予受理并一次性告知需要补正的全部内容；\n（四）申请登记的不动产不属于本机构登记范围的，应当当场书面告知申请人不予受理并告知申请人向有登记权的机构申请。\n不动产登记机构未当场书面告知申请人不予受理的，视为受理。\n第十八条 不动产登记机构受理不动产登记申请的，应当按照下列要求进行查验：\n（一）不动产界址、空间界限、面积等材料与申请登记的不动产状况是否一致；\n（二）有关证明材料、文件与申请登记的内容是否一致；\n（三）登记申请是否违反法律、行政法规规定。\n第十九条 属于下列情形之一的，不动产登记机构可以对申请登记的不动产进行实地查看：\n（一）房屋等建筑物、构筑物所有权首次登记；\n（二）在建建筑物抵押权登记；\n（三）因不动产灭失导致的注销登记；\n（四）不动产登记机构认为需要实地查看的其他情形。\n对可能存在权属争议，或者可能涉及他人利害关系的登记申请，不动产登记机构可以向申请人、利害关系人或者有关单位进行调查。\n不动产登记机构进行实地查看或者调查时，申请人、被调查人应当予以配合。\n第二十条 不动产登记机构应当自受理登记申请之日起30个工作日内办结不动产登记手续，法律另有规定的除外。\n第二十一条 登记事项自记载于不动产登记簿时完成登记。\n不动产登记机构完成登记，应当依法向申请人核发不动产权属证书或者登记证明。\n第二十二条 登记申请有下列情形之一的，不动产登记机构应当不予登记，并书面告知申请人：\n（一）违反法律、行政法规规定的；\n（二）存在尚未解决的权属争议的；\n（三）申请登记的不动产权利超过规定期限的；\n（四）法律、行政法规规定不予登记的其他情形。","level":1},{"name":"第四章 登记信息共享与保护","text":"第二十三条 国务院自然资源主管部门应当会同有关部门建立统一的不动产登记信息管理基础平台。\n各级不动产登记机构登记的信息应当纳入统一的不动产登记信息管理基础平台，确保国家、省、市、县四级登记信息的实时共享。\n第二十四条 不动产登记有关信息与住房城乡建设、农业农村、林业草原等部门审批信息、交易信息等应当实时互通共享。\n不动产登记机构能够通过实时互通共享取得的信息，不得要求不动产登记申请人重复提交。\n第二十五条 自然资源、公安、民政、财政、税务、市场监管、金融、审计、统计等部门应当加强不动产登记有关信息互通共享。\n第二十六条 不动产登记机构、不动产登记信息共享单位及其工作人员应当对不动产登记信息保密；涉及国家秘密的不动产登记信息，应当依法采取必要的安全保密措施。\n第二十七条 权利人、利害关系人可以依法查询、复制不动产登记资料，不动产登记机构应当提供。\n有关国家机关可以依照法律、行政法规的规定查询、复制与调查处理事项有关的不动产登记资料。\n第二十八条 查询不动产登记资料的单位、个人应当向不动产登记机构说明查询目的，不得将查询获得的不动产登记资料用于其他目的；未经权利人同意，不得泄露查询获得的不动产登记资料。","level":1},{"name":"第五章 法律责任","text":"第二十九条 不动产登记机构登记错误给他人造成损害，或者当事人提供虚假材料申请登记给他人造成损害的，依照《中华人民共和国民法典》的规定承担赔偿责任。\n第三十条 不动产登记机构工作人员进行虚假登记，损毁、伪造不动产登记簿，擅自修改登记事项，或者有其他滥用职权、玩忽职守行为的，依法给予处分；给他人造成损害的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第三十一条 伪造、变造不动产权属证书、不动产登记证明，或者买卖、使用伪造、变造的不动产权属证书、不动产登记证明的，由不动产登记机构或者公安机关依法予以收缴；有违法所得的，没收违法所得；给他人造成损害的，依法承担赔偿责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第三十二条 不动产登记机构、不动产登记信息共享单位及其工作人员，查询不动产登记资料的单位或者个人违反国家规定，泄露不动产登记资料、登记信息，或者利用不动产登记资料、登记信息进行不正当活动，给他人造成损害的，依法承担赔偿责任；对有关责任人员依法给予处分；有关责任人员构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附 则","text":"第三十三条 本条例施行前依法颁发的各类不动产权属证书和制作的不动产登记簿继续有效。\n不动产统一登记过渡期内，农村土地承包经营权的登记按照国家有关规定执行。\n第三十四条 本条例实施细则由国务院自然资源主管部门会同有关部门制定。\n第三十五条 本条例自2015年3月1日起施行。本条例施行前公布的行政法规有关不动产登记的规定与本条例规定不一致的，以本条例规定为准。","level":1}]},{"id":"n1271","sections":[{"name":"","text":"外国企业常驻代表机构登记管理条例\n（2010年11月19日中华人民共和国国务院令第584号公布 根据2013年7月18日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2018年9月18日《国务院关于修改部分行政法规的决定》第二次修订 根据2024年3月10日《国务院关于修改和废止部分行政法规的决定》第三次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了规范外国企业常驻代表机构的设立及其业务活动，制定本条例。\n第二条 本条例所称外国企业常驻代表机构（以下简称代表机构），是指外国企业依照本条例规定，在中国境内设立的从事与该外国企业业务有关的非营利性活动的办事机构。代表机构不具有法人资格。\n第三条 代表机构应当遵守中国法律，不得损害中国国家安全和社会公共利益。\n第四条 代表机构设立、变更、终止，应当依照本条例规定办理登记。\n外国企业申请办理代表机构登记，应当对申请文件、材料的真实性负责。\n第五条 省、自治区、直辖市人民政府市场监督管理部门是代表机构的登记和管理机关（以下简称登记机关）。\n登记机关应当与其他有关部门建立信息共享机制，相互提供有关代表机构的信息。\n第六条 代表机构应当于每年3月1日至6月30日向登记机关提交年度报告。年度报告的内容包括外国企业的合法存续情况、代表机构的业务活动开展情况及其经会计师事务所审计的费用收支情况等相关情况。\n第七条 代表机构应当依法设置会计账簿，真实记载外国企业经费拨付和代表机构费用收支情况，并置于代表机构驻在场所。\n代表机构不得使用其他企业、组织或者个人的账户。\n第八条 外国企业委派的首席代表、代表以及代表机构的工作人员应当遵守法律、行政法规关于出入境、居留、就业、纳税、外汇登记等规定；违反规定的，由有关部门依照法律、行政法规的相关规定予以处理。","level":1},{"name":"第二章 登记事项","text":"第九条 代表机构的登记事项包括：代表机构名称、首席代表姓名、业务范围、驻在场所、驻在期限、外国企业名称及其住所。\n第十条 代表机构名称应当由以下部分依次组成：外国企业国籍、外国企业中文名称、驻在城市名称以及“代表处”字样，并不得含有下列内容和文字：\n（一）有损于中国国家安全或者社会公共利益的；\n（二）国际组织名称；\n（三）法律、行政法规或者国务院规定禁止的。\n代表机构应当以登记机关登记的名称从事业务活动。\n第十一条 外国企业应当委派一名首席代表。首席代表在外国企业书面授权范围内，可以代表外国企业签署代表机构登记申请文件。\n外国企业可以根据业务需要，委派1至3名代表。\n第十二条 有下列情形之一的，不得担任首席代表、代表：\n（一）因损害中国国家安全或者社会公共利益，被判处刑罚的；\n（二）因从事损害中国国家安全或者社会公共利益等违法活动，依法被撤销设立登记、吊销登记证或者被有关部门依法责令关闭的代表机构的首席代表、代表，自被撤销、吊销或者责令关闭之日起未逾5年的；\n（三）国务院市场监督管理部门规定的其他情形。\n第十三条 代表机构不得从事营利性活动。\n中国缔结或者参加的国际条约、协定另有规定的，从其规定，但是中国声明保留的条款除外。\n第十四条 代表机构可以从事与外国企业业务有关的下列活动：\n（一）与外国企业产品或者服务有关的市场调查、展示、宣传活动；\n（二）与外国企业产品销售、服务提供、境内采购、境内投资有关的联络活动。\n法律、行政法规或者国务院规定代表机构从事前款规定的业务活动须经批准的，应当取得批准。\n第十五条 代表机构的驻在场所由外国企业自行选择。\n根据国家安全和社会公共利益需要，有关部门可以要求代表机构调整驻在场所，并及时通知登记机关。\n第十六条 代表机构的驻在期限不得超过外国企业的存续期限。\n第十七条 登记机关应当将代表机构登记事项记载于代表机构登记簿，供社会公众查阅、复制。\n第十八条 代表机构应当将登记机关颁发的外国企业常驻代表机构登记证（以下简称登记证）置于代表机构驻在场所的显著位置。\n第十九条 任何单位和个人不得伪造、涂改、出租、出借、转让登记证和首席代表、代表的代表证（以下简称代表证）。\n登记证和代表证遗失或者毁坏的，代表机构应当在指定的媒体上声明作废，申请补领。\n登记机关依法作出准予变更登记、准予注销登记、撤销变更登记、吊销登记证决定的，代表机构原登记证和原首席代表、代表的代表证自动失效。\n第二十条 代表机构设立、变更，外国企业应当在登记机关指定的媒体上向社会公告。\n代表机构注销或者被依法撤销设立登记、吊销登记证的，由登记机关进行公告。\n第二十一条 登记机关对代表机构涉嫌违反本条例的行为进行查处，可以依法行使下列职权：\n（一）向有关的单位和个人调查、了解情况；\n（二）查阅、复制、查封、扣押与违法行为有关的合同、票据、账簿以及其他资料；\n（三）查封、扣押专门用于从事违法行为的工具、设备、原材料、产品（商品）等财物；\n（四）查询从事违法行为的代表机构的账户以及与存款有关的会计凭证、账簿、对账单等。","level":1},{"name":"第三章 设立登记","text":"第二十二条 设立代表机构应当向登记机关申请设立登记。\n第二十三条 外国企业申请设立代表机构，应当向登记机关提交下列文件、材料：\n（一）代表机构设立登记申请书；\n（二）外国企业住所证明和存续2年以上的合法营业证明；\n（三）外国企业章程或者组织协议；\n（四）外国企业对首席代表、代表的任命文件；\n（五）首席代表、代表的身份证明和简历；\n（六）同外国企业有业务往来的金融机构出具的资金信用证明；\n（七）代表机构驻在场所的合法使用证明。\n法律、行政法规或者国务院规定设立代表机构须经批准的，外国企业应当自批准之日起90日内向登记机关申请设立登记，并提交有关批准文件。\n中国缔结或者参加的国际条约、协定规定可以设立从事营利性活动的代表机构的，还应当依照法律、行政法规或者国务院规定提交相应文件。\n第二十四条 登记机关应当自受理申请之日起15日内作出是否准予登记的决定，作出决定前可以根据需要征求有关部门的意见。作出准予登记决定的，应当自作出决定之日起5日内向申请人颁发登记证和代表证；作出不予登记决定的，应当自作出决定之日起5日内向申请人出具登记驳回通知书，说明不予登记的理由。\n登记证签发日期为代表机构成立日期。\n第二十五条 代表机构、首席代表和代表凭登记证、代表证申请办理居留、就业、纳税、外汇登记等有关手续。","level":1},{"name":"第四章 变更登记","text":"第二十六条 代表机构登记事项发生变更，外国企业应当向登记机关申请变更登记。\n第二十七条 变更登记事项的，应当自登记事项发生变更之日起60日内申请变更登记。\n变更登记事项依照法律、行政法规或者国务院规定在登记前须经批准的，应当自批准之日起30日内申请变更登记。\n第二十八条 代表机构驻在期限届满后继续从事业务活动的，外国企业应当在驻在期限届满前60日内向登记机关申请变更登记。\n第二十九条 申请代表机构变更登记，应当提交代表机构变更登记申请书以及国务院市场监督管理部门规定提交的相关文件。\n变更登记事项依照法律、行政法规或者国务院规定在登记前须经批准的，还应当提交有关批准文件。\n第三十条 登记机关应当自受理申请之日起10日内作出是否准予变更登记的决定。作出准予变更登记决定的，应当自作出决定之日起5日内换发登记证和代表证；作出不予变更登记决定的，应当自作出决定之日起5日内向申请人出具变更登记驳回通知书，说明不予变更登记的理由。\n第三十一条 外国企业的有权签字人、企业责任形式、资本（资产）、经营范围以及代表发生变更的，外国企业应当自上述事项发生变更之日起60日内向登记机关备案。","level":1},{"name":"第五章 注销登记","text":"第三十二条 有下列情形之一的，外国企业应当在下列事项发生之日起60日内向登记机关申请注销登记：\n（一）外国企业撤销代表机构；\n（二）代表机构驻在期限届满不再继续从事业务活动；\n（三）外国企业终止；\n（四）代表机构依法被撤销批准或者责令关闭。\n第三十三条 外国企业申请代表机构注销登记，应当向登记机关提交下列文件：\n（一）代表机构注销登记申请书；\n（二）代表机构税务登记注销证明；\n（三）海关出具的相关事宜已清理完结或者该代表机构未办理相关手续的证明；\n（四）国务院市场监督管理部门规定提交的其他文件。\n法律、行政法规或者国务院规定代表机构终止活动须经批准的，还应当提交有关批准文件。\n第三十四条 登记机关应当自受理申请之日起10日内作出是否准予注销登记的决定。作出准予注销决定的，应当自作出决定之日起5日内出具准予注销通知书，收缴登记证和代表证；作出不予注销登记决定的，应当自作出决定之日起5日内向申请人出具注销登记驳回通知书，说明不予注销登记的理由。","level":1},{"name":"第六章 法律责任","text":"第三十五条 未经登记，擅自设立代表机构或者从事代表机构业务活动的，由登记机关责令停止活动，处以5万元以上20万元以下的罚款。\n代表机构违反本条例规定从事营利性活动的，由登记机关责令改正，没收违法所得，没收专门用于从事营利性活动的工具、设备、原材料、产品（商品）等财物，处以5万元以上50万元以下罚款；情节严重的，吊销登记证。\n第三十六条 提交虚假材料或者采取其他欺诈手段隐瞒真实情况，取得代表机构登记或者备案的，由登记机关责令改正，对代表机构处以2万元以上20万元以下的罚款，对直接负责的主管人员和其他直接责任人员处以1000元以上1万元以下的罚款；情节严重的，由登记机关撤销登记或者吊销登记证，缴销代表证。\n代表机构提交的年度报告隐瞒真实情况、弄虚作假的，由登记机关责令改正，对代表机构处以2万元以上20万元以下的罚款；情节严重的，吊销登记证。\n伪造、涂改、出租、出借、转让登记证、代表证的，由登记机关对代表机构处以1万元以上10万元以下的罚款；对直接负责的主管人员和其他直接责任人员处以1000元以上1万元以下的罚款；情节严重的，吊销登记证，缴销代表证。\n第三十七条 代表机构违反本条例第十四条规定从事业务活动以外活动的，由登记机关责令限期改正；逾期未改正的，处以1万元以上10万元以下的罚款；情节严重的，吊销登记证。\n第三十八条 有下列情形之一的，由登记机关责令限期改正，处以1万元以上3万元以下的罚款；逾期未改正的，吊销登记证：\n（一）未依照本条例规定提交年度报告的；\n（二）未按照登记机关登记的名称从事业务活动的；\n（三）未按照中国政府有关部门要求调整驻在场所的；\n（四）未依照本条例规定公告其设立、变更情况的；\n（五）未依照本条例规定办理有关变更登记、注销登记或者备案的。\n第三十九条 代表机构从事危害中国国家安全或者社会公共利益等严重违法活动的，由登记机关吊销登记证。\n代表机构违反本条例规定被撤销设立登记、吊销登记证，或者被中国政府有关部门依法责令关闭的，自被撤销、吊销或者责令关闭之日起5年内，设立该代表机构的外国企业不得在中国境内设立代表机构。\n第四十条 登记机关及其工作人员滥用职权、玩忽职守、徇私舞弊，未依照本条例规定办理登记、查处违法行为，或者支持、包庇、纵容违法行为的，依法给予处分。\n第四十一条 违反本条例规定，构成违反治安管理行为的，依照《中华人民共和国治安管理处罚法》的规定予以处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附 则","text":"第四十二条 本条例所称外国企业，是指依照外国法律在中国境外设立的营利性组织。\n第四十三条 代表机构登记的收费项目依照国务院财政部门、价格主管部门的有关规定执行，代表机构登记的收费标准依照国务院价格主管部门、财政部门的有关规定执行。\n第四十四条 香港特别行政区、澳门特别行政区和台湾地区企业在中国境内设立代表机构的，参照本条例规定进行登记管理。\n第四十五条 本条例自2011年3月1日起施行。1983年3月5日经国务院批准，1983年3月15日原国家工商行政管理局发布的《关于外国企业常驻代表机构登记管理办法》同时废止。","level":1}]},{"id":"n1272","sections":[{"name":"","text":"全国农业普查条例\n（2006年8月23日中华人民共和国国务院令第473号公布 2026年3月20日中华人民共和国国务院令第833号修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了科学、有效地组织实施全国农业普查，保障农业普查数据的真实性、准确性、完整性和及时性，根据《中华人民共和国统计法》，制定本条例。\n第二条 农业普查的目的，是全面掌握我国农业、农村和农民的基本情况，为研究制定经济社会发展战略、规划、政策和科学决策提供依据，并为农业生产经营者和社会公众提供统计信息服务。\n第三条 农业普查工作按照全国统一领导、部门分工协作、地方分级负责、各方共同参与的原则组织实施。\n第四条 国家机关、社会团体以及与农业普查有关的单位和个人，应当依照《中华人民共和国统计法》和本条例的规定，积极参与并密切配合农业普查工作。\n第五条 各级农业普查领导小组办公室（以下简称普查办公室）和普查办公室工作人员、普查指导员、普查员（以下统称普查人员）依法独立行使调查、报告、监督的职权，任何单位和个人不得干涉。\n各地方、各部门、各单位的负责人不得自行修改普查办公室、普查人员依法搜集、整理的农业普查资料，不得以任何方式要求普查办公室、普查人员伪造、篡改农业普查资料，不得明示、暗示下级单位及其人员或者农业普查对象填报虚假农业普查数据，不得对依法履行职责或者拒绝、抵制农业普查违法行为的单位和个人打击报复。\n第六条 报刊、广播、电视、新闻网站等新闻媒体和网络服务提供者，应当采取多种形式，开展农业普查宣传报道。\n第七条 农业普查所需经费，由中央和地方各级人民政府共同负担，并列入相应年度预算，按时拨付，确保足额到位。\n农业普查经费应当统一管理、专款专用、从严控制支出。\n各级财政部门、审计部门依据职责，加强对农业普查经费的预算监督和审计监督。\n第八条 农业普查每10年进行一次，尾数逢6的年份为农业普查年度，标准时点为农业普查年度的12月31日24时。特殊地区的农业普查登记时间经国务院农业普查领导小组办公室批准，可以适当调整。","level":1},{"name":"第二章 农业普查的对象、范围和内容","text":"第九条 农业普查对象是在中华人民共和国境内的下列单位和个人：\n（一）农村住户，包括农村农业生产经营户和其他住户；\n（二）城镇农业生产经营户；\n（三）农业生产经营单位；\n（四）村民委员会；\n（五）乡镇人民政府。\n第十条 农业普查对象应当如实回答普查人员就农业普查有关问题的询问，按时填报农业普查表、提供农业普查所需的资料，不得提供不真实或者不完整的农业普查资料，不得迟报、拒报农业普查资料。\n农业普查对象应当配合县级以上人民政府统计机构依法进行的监督检查，如实反映情况，提供相关证明和资料，不得拒绝、阻碍检查，不得转移、隐匿、篡改、毁弃原始记录和凭证、统计台账、农业普查表、会计资料及其他相关证明和资料。\n要求农业普查对象提供报表、资料，应当坚持必要、规范原则，精简整合填报事项，强化数据共享利用，减轻基层负担。\n第十一条 农业普查行业范围包括：农作物种植业、林业、畜牧业、渔业和农林牧渔辅助性活动。\n第十二条 农业普查内容包括：农业生产条件、农业生产经营活动、农业土地利用、农村居民生活、农村劳动力及就业、乡村产业发展、乡村建设、乡村治理等情况。\n国务院农业普查领导小组办公室可以根据具体情况对前款规定的农业普查内容进行调整。\n第十三条 农业普查采用全面调查的方法。国务院农业普查领导小组办公室可以决定对特定内容采用抽样调查、遥感测量等方法。\n农业普查应当充分利用行政记录、社会大数据等资料。\n第十四条 农业普查执行国家统计标准。\n第十五条 农业普查方案由国务院农业普查领导小组办公室统一制定，报国务院审批。农业普查应当按照农业普查方案的规定执行。\n省级普查办公室可以根据需要增设农业普查附表，报经国务院农业普查领导小组办公室批准后实施。","level":1},{"name":"第三章 农业普查的组织实施","text":"第十六条 国务院设立农业普查领导小组及其办公室。国务院农业普查领导小组负责组织和领导全国农业普查工作。国务院农业普查领导小组办公室设在国家统计局，具体负责农业普查日常工作的组织和协调。国务院农业普查领导小组及其办公室任务完成后自动撤销。\n第十七条 地方各级人民政府设立农业普查领导小组及其办公室，按照国务院农业普查领导小组及其办公室的统一规定和要求，负责本行政区域内农业普查的组织实施工作。国家统计局派出的调查机构作为农业普查领导小组及其办公室的成员单位，参与农业普查的组织实施工作。地方各级农业普查领导小组及其办公室任务完成后自动撤销。\n村民委员会应当在乡镇人民政府的指导下协助做好本区域内的农业普查工作。\n第十八条 县级以上各级人民政府有关部门应当积极参与并密切配合普查办公室开展农业普查工作。\n军队所属单位的农业普查工作，由军队统一组织实施。\n新疆生产建设兵团的农业普查工作，由新疆生产建设兵团农业普查领导小组及其办公室负责组织实施。\n第十九条 农村的农业普查现场登记按普查区进行。普查区以村民委员会管理地域为基础划分，每个普查区可以划分为若干个普查小区。\n城镇的农业普查现场登记，按照农业普查方案的规定进行。\n第二十条 每个普查小区配备一名普查员，负责农业普查的访问登记等工作。每个普查区至少配备一名普查指导员，负责安排、指导和督促检查普查员的工作，也可以直接进行访问登记。\n普查指导员和普查员主要由有较高文化水平的乡村干部、村民小组长和其他当地居民担任。\n普查指导员和普查员应当身体健康、责任心强。\n第二十一条 普查办公室根据工作需要，可以聘用或者按照规定从其他有关单位借调人员从事农业普查工作。有关单位应当积极推荐符合条件的人员从事农业普查工作。\n聘用人员应当由聘用单位支付劳动报酬。借调人员的工资由原单位支付，其福利待遇保持不变。\n农业普查经费中应当对普查指导员、普查员安排适当的工作补助。\n第二十二条 普查办公室应当对普查指导员和普查员进行业务培训，对考核合格的人员颁发全国统一的普查指导员证或者普查员证。\n第二十三条 普查人员进行农业普查时，有权就与农业普查有关的问题询问有关单位和个人，要求有关单位和个人如实提供有关情况和资料并改正不真实、不准确的资料。\n第二十四条 普查人员应当坚持实事求是，恪守职业道德，拒绝、抵制农业普查工作中的违法行为。\n普查办公室、普查人员应当严格执行农业普查方案，如实搜集、报送农业普查资料，不得伪造、篡改农业普查资料，不得以任何方式要求农业普查对象提供不真实的农业普查资料，不得以任何方式要求普查人员或者下级普查办公室伪造、篡改农业普查资料，不得有其他违反本条例规定的行为。\n普查指导员和普查员执行农业普查任务时，应当出示普查指导员证或者普查员证；未出示的，农业普查对象有权拒绝提供有关情况和资料。\n第二十五条 普查员应当依法直接访问农业普查对象，当场进行询问、填报。农业普查表填写完成后，应当由农业普查对象签字或者盖章确认。农业普查对象应当对其签字或者盖章的农业普查资料的真实性负责。\n普查人员应当对其负责登记、审核、录入的农业普查资料与农业普查对象签字或者盖章的农业普查资料的一致性负责。\n普查办公室应当对其加工、整理的农业普查资料的真实性、准确性、完整性负责。","level":1},{"name":"第四章 数据处理和质量控制","text":"第二十六条 农业普查数据处理方案和实施办法，由国务院农业普查领导小组办公室制定。\n普查办公室应当按照数据处理方案和实施办法的规定进行数据处理。\n第二十七条 国务院农业普查领导小组办公室应当建立健全农业普查数据处理系统，并加强日常管理和维护更新，保障数据安全。\n第二十八条 国家建立农业普查数据质量控制制度。\n普查办公室应当按照农业普查数据质量控制制度有关要求，对农业普查实施中的每个环节实行质量控制和检查验收。\n第二十九条 普查人员实行质量控制工作责任制。\n普查人员应当按照农业普查方案的规定对农业普查数据进行审核、复查和验收。\n第三十条 国务院农业普查领导小组办公室制定农业普查事后质量抽查方案，统一组织农业普查事后质量抽查工作。事后质量抽查结果作为评估全国和各地方农业普查数据质量的重要依据。","level":1},{"name":"第五章 数据公布、资料管理和开发应用","text":"第三十一条 国家建立农业普查资料公布制度。\n农业普查汇总资料，除依法予以保密的外，应当及时向社会公布。\n全国农业普查数据和各省、自治区、直辖市的主要农业普查数据，由国务院农业普查领导小组办公室审定并会同国务院有关部门公布。\n地方普查办公室发布农业普查公报，应当报经上一级普查办公室核准。\n第三十二条 普查办公室、普查人员对在农业普查工作中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息，应当予以保密，不得泄露或者向他人非法提供；对在农业普查工作中搜集的能够识别或者推断单个农业普查对象身份的资料，不得对外提供、泄露，不得用于统计以外的目的。\n第三十三条 普查办公室应当按照国家有关规定建立健全农业普查资料的保存、管理制度，做好农业普查资料的保存、管理，并在农业普查工作结束后，及时做好有关农业普查资料的归档和移交。\n有关部门应当依法做好农业普查资料部门间共享和为社会公众提供服务等工作，并对农业普查资料进行开发和应用。\n第三十四条 县级以上各级人民政府统计机构和有关部门可以根据农业普查结果，对有关常规统计的历史数据进行修正，具体办法由国家统计局规定。","level":1},{"name":"第六章 奖励和处罚","text":"第三十五条 对认真执行本条例，忠于职守，坚持原则，做出显著成绩的单位和个人，按照国家有关规定给予奖励。\n第三十六条 地方、部门、单位的负责人有下列行为之一的，依法给予处分，并由县级以上人民政府统计机构予以通报：\n（一）自行修改农业普查资料、编造虚假农业普查数据的；\n（二）要求普查办公室、普查人员伪造、篡改农业普查资料的；\n（三）明示、暗示下级单位及其人员或者农业普查对象填报虚假农业普查数据的；\n（四）对本地方、本部门、本单位发生的农业普查数据严重失实情况和严重农业普查违法行为失察的；\n（五）有其他农业普查造假、弄虚作假行为的。\n对依法履行职责或者拒绝、抵制农业普查违法行为的单位和个人打击报复的，依照前款规定给予处分和予以通报。\n第三十七条 普查办公室有下列行为之一的，由本级人民政府或者上级人民政府统计机构责令改正，予以通报；对负有责任的领导人员和直接责任人员依法给予处分：\n（一）未执行农业普查方案的；\n（二）伪造、篡改农业普查资料的；\n（三）要求农业普查对象提供不真实的农业普查资料的；\n（四）要求普查人员或者下级普查办公室伪造、篡改农业普查资料的。\n普查人员有前款所列行为之一的，责令改正，依法给予处分。\n第三十八条 普查办公室有下列行为之一的，对负有责任的领导人员和直接责任人员依法给予处分：\n（一）违法公布农业普查资料的；\n（二）泄露或者向他人非法提供在农业普查工作中知悉的国家秘密、工作秘密、商业秘密、个人隐私、个人信息的；\n（三）对外提供、泄露在农业普查工作中搜集的能够识别或者推断单个农业普查对象身份的资料的；\n（四）违反国家有关规定，造成农业普查资料毁损、灭失的。\n普查人员有前款所列行为之一的，依法给予处分。\n第三十九条 作为农业普查对象的农业生产经营单位、村民委员会、乡镇人民政府有下列行为之一的，由县级以上人民政府统计机构责令改正，给予警告，可以予以通报；其负有责任的领导人员和直接责任人员属于公职人员的，依法给予处分：\n（一）拒绝或者阻碍普查办公室、普查人员依法进行农业普查的；\n（二）提供不真实或者不完整的农业普查资料的；\n（三）拒报或者经催报后仍未按时提供农业普查资料的；\n（四）拒绝、阻碍监督检查的；\n（五）转移、隐匿、篡改、毁弃或者拒绝提供原始记录和凭证、统计台账、农业普查表、会计资料及其他相关证明和资料的。\n农业生产经营单位有前款所列行为之一的，可以并处10万元以下罚款；情节严重的，并处10万元以上50万元以下罚款。\n农村住户、城镇农业生产经营户有本条第一款所列行为之一的，由县级以上人民政府统计机构责令改正，予以批评教育。\n农业普查对象有本条第一款第（一）、（四）项所列行为之一，构成违反治安管理行为的，由公安机关依法处理。\n第四十条 作为农业普查对象的农业生产经营单位、村民委员会、乡镇人民政府迟报农业普查资料的，由县级以上人民政府统计机构责令改正，给予警告，可以予以通报；其负有责任的领导人员和直接责任人员属于公职人员的，依法给予处分。\n农业生产经营单位迟报农业普查资料的，可以并处5万元以下罚款。\n农村住户、城镇农业生产经营户迟报农业普查资料的，由县级以上人民政府统计机构责令改正，予以批评教育。\n第四十一条 违反本条例规定，造成人身损害或者财产损失的，依法承担民事责任；构成犯罪的，依法追究刑事责任。\n第四十二条 普查办公室应当设立举报电话和信箱，接受社会各界对农业普查违法行为的检举和监督。对检举有功的单位和个人按照国家有关规定给予奖励。","level":1},{"name":"第七章 附 则","text":"第四十三条 街道办事处、居民委员会涉及农业生产经营活动的，分别参照本条例关于乡镇人民政府、村民委员会的规定执行。\n第四十四条 本条例自2026年5月1日起施行。","level":1}]},{"id":"n1273","sections":[{"name":"","text":"中华人民共和国反外国不当域外管辖条例\n第一条 为了维护国家主权、安全、发展利益，保护中国公民、组织合法权益，维护以国际法为基础的国际秩序，根据《中华人民共和国国家安全法》、《中华人民共和国对外关系法》、《中华人民共和国反外国制裁法》等法律，制定本条例。\n第二条 反外国不当域外管辖工作贯彻总体国家安全观，统筹发展和安全，统筹国内国际，维护中国特色社会主义制度，推动构建更加公正合理的全球治理体系。\n第三条 中华人民共和国坚持独立自主的和平外交政策，反对霸权主义和强权政治，反对任何国家以任何借口、任何方式干涉中国内政。\n外国国家违反国际法和国际关系基本准则，实施不当域外管辖措施，危害中国国家主权、安全、发展利益，损害中国公民、组织合法权益的，中国政府有权采取相应的措施。\n第四条 中国政府根据中华人民共和国法律和中华人民共和国缔结或者参加的国际条约，或者按照对等原则，有权对与中国存在适当联系的行为实施域外管辖措施，维护国家主权、安全、发展利益，保护中国公民、组织合法权益。\n中国政府按照前款规定对有关行为有权管辖，外国国家主张对同一行为实施管辖措施的，双方可以在共同遵守国际法和国际关系基本准则的基础上，通过缔结条约或者经外交途径、主管部门协商等解决。\n第五条 国家建立健全应对外国不当域外管辖有关工作机制（以下简称工作机制），统筹协调应对外国不当域外管辖工作。\n国务院有关部门按照职责分工承担应对外国不当域外管辖具体工作。国务院有关部门和其他有关机关应当加强外国不当域外管辖措施识别、应对工作的协同配合和信息共享。\n第六条 国务院法治部门会同其他有关机关开展外国不当域外管辖措施识别工作，可以进行调查和对外磋商等。有关组织、个人可以向国务院法治部门提出开展识别工作的建议。\n开展外国不当域外管辖措施识别工作应当综合考虑下列因素：\n（一）是否违反国际法和国际关系基本准则；\n（二）被外国国家域外管辖的行为与该国的联系是否适当；\n（三）是否危害中国国家主权、安全、发展利益，损害中国公民、组织合法权益；\n（四）其他应当考虑的因素。\n经识别，有关措施构成外国不当域外管辖措施的，国务院法治部门可以予以公告。任何组织、个人不得执行或者协助执行外国不当域外管辖措施。\n中国公民、组织因特殊情况确需执行或者协助执行外国不当域外管辖措施的，应当向国务院法治部门申请并提供相应的事实和理由、需要执行或者协助执行的范围等，按照工作机制决策程序经同意后可以在特定范围内执行或者协助执行有关措施。\n第七条 中国政府可以对有关国家实施不当域外管辖措施行为进行评估，确定风险等级，依法采取外交外事、出境入境、贸易、投资、国际合作、对外援助等方面的反制和限制措施。\n第八条 国务院有关部门按照工作机制决策程序，可以将推动实施或者参与实施外国不当域外管辖措施的外国组织、个人列入恶意实体清单，依照《中华人民共和国反外国制裁法》、《实施〈中华人民共和国反外国制裁法〉的规定》等，决定对其采取下列一种或者几种反制和限制措施，并予以公告：\n（一）不予签发签证、不准入境、注销签证或者限期出境、遣送出境、驱逐出境；\n（二）取消或者限制相关人员在中国境内工作、停留或者居留资格；\n（三）查封、扣押、冻结其在中国境内的动产、不动产和其他各类财产；\n（四）禁止或者限制中国境内的组织、个人向其提供数据、个人信息，与其进行有关交易、合作等活动；\n（五）禁止或者限制其从事与中国有关的进出口活动；\n（六）禁止或者限制其在中国境内投资；\n（七）禁止或者限制其产品、交通运输工具等入境；\n（八）罚款；\n（九）其他必要措施。\n前款规定措施还可以适用于列入恶意实体清单的组织、个人实际控制或者参与设立、运营的组织。\n第九条 被采取反制和限制措施的组织、个人可以向作出采取反制和限制措施决定的国务院有关部门申请暂停、变更或者取消有关反制和限制措施，申请时应当提供其改正行为、采取措施消除行为后果等方面的事实和理由。\n作出采取反制和限制措施决定的国务院有关部门可以根据实际情况组织评估反制和限制措施的实施情况和效果。\n作出采取反制和限制措施决定的国务院有关部门根据评估结果或者根据对相关申请的审查情况，按照工作机制决策程序可以作出暂停、变更或者取消有关反制和限制措施的决定，并予以公告。\n第十条 有关反制和限制措施需要国务院其他部门实施的，作出采取、暂停、变更或者取消反制和限制措施决定的国务院有关部门应当按照工作机制程序，将有关反制和限制措施决定通报负责实施的国务院有关部门。\n收到有关反制和限制措施决定的国务院有关部门，应当按照职责分工实施。\n第十一条 有关组织、个人在特殊情况下确需与被采取反制和限制措施的组织、个人进行被禁止或者限制的相关活动的，应当向作出采取反制和限制措施决定的国务院有关部门申请并提供相应的事实和理由，按照工作机制决策程序经同意后可以与被采取反制和限制措施的组织、个人进行相关活动。\n第十二条 国务院有关部门可以对涉嫌执行或者协助执行外国不当域外管辖措施的组织、个人采取现场检查、查阅和复制有关资料等措施。有关组织、个人应当予以协助、配合，不得拒绝、阻碍。\n第十三条 国务院有关部门可以对执行或者协助执行外国不当域外管辖措施的组织、个人进行约谈、责令改正。\n国务院法治部门按照工作机制决策程序，可以对执行或者协助执行外国不当域外管辖措施的组织、个人作出禁止执行外国不当域外管辖措施的决定（以下称禁执令）。有关组织、个人应当遵守禁执令。\n第十四条 任何组织、个人执行或者协助执行外国不当域外管辖措施，侵害中国公民、组织合法权益的，中国公民、组织可以依法向人民法院提起诉讼，要求停止侵害、赔偿损失。\n第十五条 省级以上人民政府有关部门按照职责分工，为中国公民、组织应对外国不当域外管辖提供指导和服务。\n第十六条 行业协会商会依照法律法规和章程，发挥行业自律和协调作用，引导会员依法合规经营，及时反映行业诉求，为会员提供与应对外国不当域外管辖有关的市场拓展、权益保护、纠纷处理等方面的服务。\n第十七条 拒不执行或者规避执行本条例规定的反制和限制措施，或者违反禁执令的，国务院有关部门可以责令改正，禁止或者限制其从事政府采购、招标投标以及有关货物、技术的进出口或者国际服务贸易等活动，禁止或者限制其从中国境外接收或者向中国境外提供数据、个人信息，禁止或者限制其出境入境、在中国境内停留居留，处以罚款等。\n第十八条 违反本条例规定，构成犯罪的，依法追究刑事责任。\n第十九条 反外国不当域外管辖涉及反腐败、反垄断、反不正当竞争、出口管制、数据安全、司法协助等相关工作，法律法规另有规定的，依照其规定。\n应对外国国家违反国际法和国际关系基本准则，不当禁止或者限制中国公民、组织与第三国（地区）及其公民、组织进行正常的经贸及相关活动的工作，国家另有规定的，依照其规定。\n第二十条 本条例自公布之日起施行。","level":0}]},{"id":"n1274","sections":[{"name":"","text":"社会团体登记管理条例\n（1998年10月25日中华人民共和国国务院令第250号发布 根据2016年2月6日《国务院关于修改部分行政法规的决定》第一次修订 根据2026年3月12日《国务院关于修改〈社会团体登记管理条例〉的决定》第二次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了保障公民的结社自由，维护社会团体的合法权益，加强对社会团体的登记管理，促进社会主义物质文明、精神文明建设，制定本条例。\n第二条 本条例所称社会团体，是指中国公民自愿组成，为实现会员共同意愿，按照其章程开展活动的非营利性社会组织。\n国家机关以外的组织可以作为单位会员加入社会团体。\n第三条 成立社会团体，应当经其业务主管单位审查同意，并依照本条例的规定进行登记。\n社会团体应当具备法人条件。\n下列团体不属于本条例规定登记的范围：\n（一）参加中国人民政治协商会议的人民团体；\n（二）由国务院机构编制管理机关核定，并经国务院批准免于登记的团体；\n（三）机关、团体、企业事业单位内部经本单位批准成立、在本单位内部活动的团体。\n第四条 社会团体必须遵守宪法、法律、法规和国家政策，不得反对宪法确定的基本原则，不得危害国家的统一、安全和民族的团结，不得损害国家利益、社会公共利益以及其他组织和公民的合法权益，不得违背社会道德风尚。\n社会团体不得从事营利性经营活动。\n第五条 国家保护社会团体依照法律、法规及其章程开展活动，任何组织和个人不得非法干涉。\n第六条 国务院民政部门和县级以上地方各级人民政府民政部门是本级人民政府的社会团体登记管理机关（以下简称登记管理机关）。\n国务院有关部门和县级以上地方各级人民政府有关部门、国务院或者县级以上地方各级人民政府授权的组织，是有关行业、学科或者业务范围内社会团体的业务主管单位（以下简称业务主管单位）。\n法律、行政法规对社会团体的监督管理另有规定的，依照有关法律、行政法规的规定执行。","level":1},{"name":"第二章 管 辖","text":"第七条 全国性的社会团体，由国务院的登记管理机关负责登记管理；地方性的社会团体，由所在地人民政府的登记管理机关负责登记管理；跨行政区域的社会团体，由所跨行政区域的共同上一级人民政府的登记管理机关负责登记管理。\n第八条 登记管理机关、业务主管单位与其管辖的社会团体的住所不在一地的，可以委托社会团体住所地的登记管理机关、业务主管单位负责委托范围内的监督管理工作。","level":1},{"name":"第三章 成立登记","text":"第九条 申请成立社会团体，应当经其业务主管单位审查同意，由发起人向登记管理机关申请登记。\n筹备期间不得开展筹备以外的活动。\n第十条 成立社会团体，应当具备下列条件：\n（一）有50个以上的个人会员或者30个以上的单位会员；个人会员、单位会员混合组成的，会员总数不得少于50个；\n（二）有规范的名称和相应的组织机构；\n（三）有固定的住所；\n（四）有与其业务活动相适应的专职工作人员；\n（五）有合法的资产和经费来源，全国性的社会团体有10万元以上活动资金，地方性的社会团体和跨行政区域的社会团体有3万元以上活动资金；\n（六）有独立承担民事责任的能力。\n社会团体的名称应当符合法律、法规的规定，不得违背社会道德风尚。社会团体的名称应当与其业务范围、成员分布、活动地域相一致，准确反映其特征。全国性的社会团体的名称冠以“中国”、“全国”、“中华”等字样的，应当按照国家有关规定经过批准，地方性的社会团体的名称不得冠以“中国”、“全国”、“中华”等字样。\n第十一条 申请登记社会团体，发起人应当向登记管理机关提交下列文件：\n（一）登记申请书；\n（二）业务主管单位的批准文件；\n（三）验资报告、场所使用权证明；\n（四）发起人和拟任负责人的基本情况、身份证明；\n（五）章程草案。\n第十二条 登记管理机关应当自收到本条例第十一条所列全部有效文件之日起60日内，作出准予或者不予登记的决定。准予登记的，发给《社会团体法人登记证书》；不予登记的，应当向发起人说明理由。\n社会团体登记事项包括：名称、住所、宗旨、业务范围、活动地域、法定代表人、活动资金和业务主管单位。\n社会团体的法定代表人，不得同时担任其他社会团体的法定代表人。\n第十三条 有下列情形之一的，登记管理机关不予登记：\n（一）有根据证明申请登记的社会团体的宗旨、业务范围不符合本条例第四条的规定的；\n（二）在同一行政区域内已有业务范围相同或者相似的社会团体，没有必要成立的；\n（三）发起人、拟任负责人正在或者曾经受到剥夺政治权利的刑事处罚，或者不具有完全民事行为能力的；\n（四）在申请登记时弄虚作假的；\n（五）有法律、行政法规禁止的其他情形的。\n第十四条 社会团体的章程应当包括下列事项：\n（一）名称、住所；\n（二）宗旨、业务范围和活动地域；\n（三）会员资格及其权利、义务；\n（四）民主的组织管理制度，执行机构的产生程序；\n（五）负责人的条件和产生、罢免的程序；\n（六）资产管理和使用的原则；\n（七）章程的修改程序；\n（八）终止程序和终止后资产的处理；\n（九）应当由章程规定的其他事项。\n第十五条 依照法律规定，自批准成立之日起即具有法人资格的社会团体，应当自批准成立之日起60日内向登记管理机关提交批准文件，申领《社会团体法人登记证书》。登记管理机关自收到文件之日起30日内发给《社会团体法人登记证书》。\n第十六条 社会团体凭《社会团体法人登记证书》申请刻制印章，开立银行账户。社会团体应当将印章式样和银行账号报登记管理机关备案。\n第十七条 社会团体的分支机构、代表机构是社会团体的组成部分，不具有法人资格，应当按照其所属于的社会团体的章程所规定的宗旨和业务范围，在该社会团体授权的范围内开展活动、发展会员。社会团体的分支机构不得再设立分支机构。\n社会团体不得设立地域性的分支机构。","level":1},{"name":"第四章 变更登记、注销登记","text":"第十八条 社会团体的登记事项需要变更的，应当自业务主管单位审查同意之日起30日内，向登记管理机关申请变更登记。\n社会团体修改章程，应当自业务主管单位审查同意之日起30日内，报登记管理机关核准。\n第十九条 社会团体有下列情形之一的，应当在业务主管单位审查同意后，向登记管理机关申请注销登记：\n（一）完成社会团体章程规定的宗旨的；\n（二）自行解散的；\n（三）分立、合并的；\n（四）由于其他原因终止的。\n有关机关会同登记管理机关可以根据需要明确行业协会商会的行业管理部门。业务主管单位、行业管理部门及有关机关对存在会员或者机构规模过小、业务领域划分过细、功能作用较弱、业务交叉重叠等情形的行业协会商会，可以要求合并；对存在任务已完成、行业调整需要、运转严重失灵、严重扰乱秩序等情形的行业协会商会，可以要求终止。\n第二十条 社会团体在办理注销登记前，应当在业务主管单位或者登记管理机关的指导下，成立清算组织，完成债务处理等清算工作，行业管理部门予以配合。\n社会团体未及时履行清算义务的，业务主管单位、行业管理部门、登记管理机关或者利害关系人可以依法申请人民法院指定有关人员组成清算组进行清算。\n清算期间，社会团体不得从事与清算无关的活动。\n第二十一条 社会团体应当自清算结束之日起15日内向登记管理机关办理注销登记。办理注销登记，应当提交法定代表人签署的注销登记申请书、业务主管单位的审查文件和清算报告书。\n登记管理机关准予注销登记的，发给注销证明文件，收缴该社会团体的登记证书、印章和财务凭证。\n行业协会商会存在本条例第十九条第二款规定情形的，由业务主管单位、行业管理部门或者有关机关制定合并或者终止方案，经登记管理机关会同有关机关审核后，有关行业协会商会应当依照本条例的规定办理变更登记、注销登记；有关行业协会商会难以自主办理的，由业务主管单位、行业管理部门及有关机关向登记管理机关提出变更、注销相关行业协会商会，登记管理机关予以办理。\n第二十二条 社会团体注销后剩余财产的处理，按照国家有关规定办理。\n第二十三条 社会团体成立、注销或者变更名称、住所、法定代表人，由登记管理机关予以公告。","level":1},{"name":"第五章 监督管理","text":"第二十四条 登记管理机关履行下列监督管理职责：\n（一）负责社会团体的成立、变更、注销的登记；\n（二）对社会团体实施年度检查；\n（三）对社会团体违反本条例的问题进行监督检查，对社会团体违反本条例的行为给予行政处罚。\n第二十五条 业务主管单位履行下列监督管理职责：\n（一）负责社会团体成立登记、变更登记、注销登记前的审查；\n（二）监督、指导社会团体遵守宪法、法律、法规和国家政策，依据其章程开展活动；\n（三）负责社会团体年度检查的初审；\n（四）协助登记管理机关和其他有关部门查处社会团体的违法行为；\n（五）会同有关机关指导社会团体的清算事宜。\n业务主管单位履行前款规定的职责，不得向社会团体收取费用。\n第二十六条 社会团体的资产来源必须合法，任何单位和个人不得侵占、私分或者挪用社会团体的资产。\n社会团体的经费，以及开展章程规定的活动按照国家有关规定所取得的合法收入，必须用于章程规定的业务活动，不得在会员中分配。\n社会团体接受捐赠、资助，必须符合章程规定的宗旨和业务范围，必须根据与捐赠人、资助人约定的期限、方式和合法用途使用。社会团体应当向业务主管单位报告接受、使用捐赠、资助的有关情况，并应当将有关情况以适当方式向社会公布。\n社会团体专职工作人员的工资和保险福利待遇，参照国家对事业单位的有关规定执行。\n第二十七条 社会团体必须执行国家规定的财务管理制度，接受财政部门的监督；资产来源属于国家拨款或者社会捐赠、资助的，还应当接受审计机关的监督。\n社会团体在换届或者更换法定代表人之前，登记管理机关、业务主管单位应当组织对其进行财务审计。\n第二十八条 社会团体应当于每年3月31日前向业务主管单位报送上一年度的工作报告，经业务主管单位初审同意后，于5月31日前报送登记管理机关，接受年度检查。工作报告的内容包括：本社会团体遵守法律法规和国家政策的情况、依照本条例履行登记手续的情况、按照章程开展活动的情况、人员和机构变动的情况以及财务管理的情况。\n对于依照本条例第十五条的规定发给《社会团体法人登记证书》的社会团体，登记管理机关对其应当简化年度检查的内容。","level":1},{"name":"第六章 罚 则","text":"第二十九条 社会团体在申请登记时弄虚作假，骗取登记的，或者自取得《社会团体法人登记证书》之日起1年未开展活动的，由登记管理机关予以撤销登记。\n第三十条 社会团体有下列情形之一的，由登记管理机关给予警告，责令改正，可以限期停止活动，并可以责令撤换直接负责的主管人员；情节严重的，吊销登记证书；构成犯罪的，依法追究刑事责任：\n（一）涂改、出租、出借《社会团体法人登记证书》，或者出租、出借社会团体印章的；\n（二）超出章程规定的宗旨和业务范围进行活动的；\n（三）拒不接受或者不按照规定接受监督检查的；\n（四）内部管理不力导致运转失灵的；\n（五）不按照规定办理变更登记、注销登记的；\n（六）违反规定设立分支机构、代表机构，或者对分支机构、代表机构疏于管理，造成严重后果的；\n（七）从事营利性的经营活动的；\n（八）侵占、私分、挪用社会团体资产或者所接受的捐赠、资助的；\n（九）违反国家有关规定收取费用、筹集资金或者接受、使用捐赠、资助的。\n前款规定的行为有违法经营额或者违法所得的，予以没收，可以并处违法经营额1倍以上3倍以下或者违法所得3倍以上5倍以下的罚款。\n第三十一条 社会团体的活动违反其他法律、法规和国家有关规定的，由有关国家机关依法处理；有关国家机关认为依法应当吊销登记证书的，由登记管理机关吊销登记证书。\n第三十二条 筹备期间开展筹备以外的活动，或者未经登记，擅自以社会团体名义进行活动，以及被撤销登记的社会团体继续以社会团体名义进行活动的，由登记管理机关予以取缔，没收非法财产；构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予治安管理处罚。\n第三十三条 社会团体被责令限期停止活动的，由登记管理机关封存《社会团体法人登记证书》、印章和财务凭证。\n社会团体被撤销登记、吊销登记证书的，由登记管理机关收缴《社会团体法人登记证书》和印章。\n第三十四条 登记管理机关、业务主管单位、行业管理部门及有关机关的工作人员滥用职权、徇私舞弊、玩忽职守构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。","level":1},{"name":"第七章 附 则","text":"第三十五条 《社会团体法人登记证书》的式样由国务院民政部门制定。\n对社会团体进行年度检查不得收取费用。\n第三十六条 本条例施行前已经成立的社会团体，应当自本条例施行之日起1年内依照本条例有关规定申请重新登记。\n第三十七条 本条例自发布之日起施行。1989年10月25日国务院发布的《社会团体登记管理条例》同时废止。","level":1}]},{"id":"n1275","sections":[{"name":"","text":"中华人民共和国行政复议法实施条例\n（2007年5月29日中华人民共和国国务院令第499号公布 2026年4月29日中华人民共和国国务院令第836号修订）","level":0},{"name":"第一章 总 则","text":"第一条 根据《中华人民共和国行政复议法》（以下简称行政复议法），制定本条例。\n第二条 行政复议机关应当对行政行为的合法性、适当性进行全面审查，保护公民、法人和其他组织的合法权益，监督和保障行政机关依法行使职权，推动行政争议实质性化解，促进从源头上预防和减少行政争议。\n第三条 各级行政复议机关应当认真履行行政复议职责，领导并支持本机关行政复议机构依法办理行政复议事项，依照有关规定配备、充实、调剂专职行政复议人员，保证行政复议机构的办案能力与工作任务相适应。\n第四条 行政复议机构依照行政复议法和本条例的规定，履行下列职责：\n（一）受理行政复议申请；\n（二）组织开展行政复议调解；\n（三）审理行政复议案件，拟定行政复议决定；\n（四）办理行政复议法第五十六条、第五十七条规定的附带审查事项；\n（五）办理行政复议法第七十二条规定的行政赔偿等事项；\n（六）按照职责权限，指导、监督下级行政复议机构依法履行行政复议职责；\n（七）按照职责权限，督促被申请人、其他有关行政机关依法履行行政复议决定书、调解书、意见书；\n（八）办理行政复议案件统计、行政复议决定抄告事项；\n（九）研究行政复议工作中发现的问题，及时向有关机关提出改进建议，重大问题及时向行政复议机关报告；\n（十）法律、法规规定的其他事项。\n第五条 行政复议人员应当具备与履行行政复议职责相适应的政治、业务素质和道德品行。\n第六条 行政复议机关应当加强行政复议调解工作，支持和保障行政复议机构依法开展调解工作，有关行政机关应当予以配合。\n第七条 行政复议机关应当加强行政复议工作规范化建设，提升行政复议工作流程、保障等规范化水平。具体规范由国务院行政复议机构会同国务院有关部门制定。\n第八条 国务院行政复议机构通过统一的行政复议信息化平台，为公民、法人或者其他组织申请、参加行政复议提供便利，提高行政复议工作质效。\n行政复议活动通过信息网络平台在线进行的，与线下行政复议活动具有同等法律效力。","level":1},{"name":"第二章 行政复议申请","text":"","level":1},{"name":"第一节 行政复议范围","text":"第九条 行政复议法第十一条第十五项规定的行政复议范围包括下列情形：\n（一）对行政机关作出的列入严重失信主体名单决定或者失信惩戒措施不服；\n（二）对教育行政部门就学校开除学籍和退学处理决定作出的申诉处理决定不服；\n（三）对学位授予单位不受理学位申请、不授予学位或者撤销学位行为不服；\n（四）对行政机关在公务员或者参照公务员法管理的工作人员录用工作中对报考者违纪违规行为作出的处理决定不服；\n（五）认为行政机关的其他行政行为侵犯其合法权益。\n第十条 行政复议法第十一条第十三项规定的行政协议包括下列协议：\n（一）政府特许经营协议；\n（二）土地、房屋等征收征用补偿协议；\n（三）政府投资的保障性住房的租赁、买卖等协议；\n（四）医疗保障服务协议；\n（五）其他行政协议。","level":2},{"name":"第二节 行政复议参加人","text":"第十一条 行政复议法和本条例所称的近亲属，包括配偶、父母、子女、兄弟姐妹、祖父母、外祖父母、孙子女、外孙子女和其他具有扶养、赡养关系的亲属。\n第十二条 个体工商户申请行政复议的，以营业执照上登记的经营者为申请人。\n农村承包经营户申请行政复议的，以土地承包经营权证等证书上记载的人、在承包合同上签字的人或者农村承包经营户内全体成员推选的成员代表为申请人。\n第十三条 合伙企业申请行政复议的，应当以依法登记的企业为申请人，由执行合伙事务的合伙人代表该企业参加行政复议；其他合伙组织申请行政复议的，由全体合伙人共同申请行政复议。\n前款规定以外的不具备法人资格的其他组织申请行政复议的，由该组织的主要负责人代表该组织参加行政复议；没有主要负责人的，由共同推选的成员代表该组织参加行政复议。\n第十四条 公司股东会、董事会认为行政机关作出的行政行为侵犯公司合法权益的，可以以公司的名义申请行政复议。\n第十五条 农村集体经济组织或者依法代行农村集体经济组织职能的村民委员会、村民小组认为行政机关作出的行政行为侵犯农村集体经济组织合法权益的，可以以自己的名义申请行政复议。\n农村集体经济组织或者依法代行农村集体经济组织职能的村民委员会、村民小组不申请行政复议的，半数以上的农村集体经济组织成员可以以农村集体经济组织、村民委员会或者村民小组的名义申请行政复议。\n第十六条 业主委员会认为行政机关作出的行政行为侵犯业主共有利益的，可以以自己的名义申请行政复议。\n业主委员会不申请行政复议或者未成立业主委员会的，专有部分占建筑物总面积过半数或者占总户数过半数的业主可以以自己的名义申请行政复议。\n第十七条 同一行政复议案件申请人超过10人的，推选2至5名代表人参加行政复议。\n申请人推选代表人，应当向行政复议机关提交由全体申请人签名、盖章或者按指印的推选书。\n第三人超过10人的，可以依照前两款的规定推选代表人。\n第十八条 行政复议法第十七条第一款规定的其他代理人，包括申请人或者第三人的近亲属、工作人员等。\n被申请人应当指定1至2名工作人员作为代理人参加行政复议，不得仅委托律师担任代理人。\n第十九条 符合法律援助条件的行政复议申请人申请法律援助的，应当向行政复议机构所在地或者行政争议发生地的法律援助机构提出申请。\n第二十条 行政机关与法律、法规、规章授权的组织以共同的名义作出同一行政行为的，共同作出行政行为的行政机关和法律、法规、规章授权的组织为共同被申请人。\n行政机关与其他组织以共同名义作出同一行政行为的，行政机关为被申请人，其他组织可以作为第三人参加行政复议。\n第二十一条 行政机关设立的派出机构、内设机构或者其他组织，未经法律、法规、规章授权，对外以自己名义作出行政行为的，该行政机关为被申请人。\n第二十二条 法律、法规、规章授权的组织根据授权作出行政行为的，该组织为被申请人。","level":2},{"name":"第三节 申请的提出","text":"第二十三条 行政复议法第二十条第一款规定的行政复议申请期限的计算，依照下列规定办理：\n（一）当场作出行政行为的，自行政行为作出之日起计算；\n（二）载明行政行为的法律文书直接送达的，自受送达人签收或者拒绝签收之日起计算；\n（三）载明行政行为的法律文书邮寄送达的，自受送达人在邮件签收单上签收之日起计算；没有邮件签收单的，自受送达人在送达回执上签名之日或者邮政机构记载的受送达人签收之日起计算；\n（四）载明行政行为的法律文书以电子方式送达的，自法律文书到达受送达人指定的特定系统之日起计算，法律、行政法规另有规定的除外；\n（五）行政行为依法通过公告形式告知受送达人的，自公告规定的期限届满之日起计算；\n（六）行政机关作出行政行为时未告知公民、法人或者其他组织，事后补充告知的，自该公民、法人或者其他组织收到行政机关补充告知的通知之日起计算。\n被申请人能够证明公民、法人或者其他组织知道或者应当知道行政行为的，自证据材料证明其知道或者应当知道行政行为之日起计算。\n第二十四条 公民、法人或者其他组织依照行政复议法第十一条第三项、第十一项、第十二项的规定申请行政机关履行法定职责，行政机关未履行的，行政复议申请期限依照下列规定计算：\n（一）有履行期限规定的，自履行期限届满之日起计算；\n（二）没有履行期限规定的，自行政机关收到申请满60日起计算。\n公民、法人或者其他组织在紧急情况下请求行政机关履行保护人身权、财产权的法定职责，行政机关不履行的，行政复议申请期限不受前款规定的限制。\n第二十五条 行政机关作出的行政行为对公民、法人或者其他组织的权利、义务可能产生不利影响的，应当告知其申请行政复议的权利、行政复议机关和行政复议申请期限。\n第二十六条 行政机关未依照行政复议法第二十三条规定告知公民、法人或者其他组织先向行政复议机关申请行政复议，公民、法人或者其他组织未经行政复议直接向人民法院提起行政诉讼的，自公民、法人或者其他组织提起行政诉讼之日至人民法院驳回起诉裁定送达之日的期间不计入行政复议申请期限。\n第二十七条 公民、法人或者其他组织书面申请行政复议的，应当在行政复议申请书中载明下列事项，签名、盖章或者按指印，并提交身份证明材料：\n（一）申请人的基本情况，包括公民的姓名、性别、身份证号码、住所、送达地址、联系方式；法人或者其他组织的名称、统一社会信用代码、住所、送达地址、联系方式和法定代表人或者主要负责人的姓名、职务；\n（二）被申请人的名称；\n（三）行政复议请求、申请行政复议的主要事实和理由；\n（四）申请行政复议的日期。\n由法定代理人或者委托代理人代为申请行政复议的，应当在行政复议申请书中写明法定代理人或者委托代理人的基本情况，并提交法定代理人或者委托代理人的身份证明和代理权限证明等材料。\n第二十八条 申请人通过行政复议机关指定的互联网渠道申请行政复议的，行政复议申请材料到达特定系统之日，为行政复议机关收到行政复议申请之日。\n申请人通过互联网渠道提交的申请材料符合法定要求的，行政复议机关不得要求另行提供纸质材料。\n第二十九条 申请人提出行政复议申请时错列被申请人的，行政复议机构应当告知申请人变更被申请人。申请人不同意变更或者变更后所列被申请人仍不符合规定的，行政复议机关决定不予受理并说明理由。\n第三十条 行政复议法第二十三条第一款第三项规定的行政机关未履行法定职责，是指申请人向行政机关申请履行相应法定职责，该行政机关存在行政复议法第十一条第三项、第十一项、第十二项、第十四项规定的在法定期限内未受理、受理后不予答复或者不履行相应法定职责的情形。\n行政机关明确答复不予受理、明示拒绝履行、不完全履行的，不属于行政复议法第二十三条第一款第三项规定的行政机关未履行法定职责情形。\n第三十一条 对行政机关认为申请公开的政府信息属于《中华人民共和国政府信息公开条例》第十四条、第十五条、第十六条规定的情形，决定全部或者部分不予公开的行为不服的，应当依照行政复议法第二十三条的规定先向行政复议机关申请行政复议，对行政复议决定不服的，可以再依法向人民法院提起行政诉讼。","level":2},{"name":"第四节 行政复议管辖","text":"第三十二条 对两个以上国务院部门共同作出的行政行为不服的，依照行政复议法第二十五条的规定，可以向其中任何一个国务院部门申请行政复议，由作出行政行为的国务院部门共同作出行政复议决定。\n对海关、金融、外汇管理等实行垂直领导的行政机关、税务机关、国家安全机关与其他行政机关共同作出的行政行为不服的，可以向其中一个有管辖权的行政复议机关申请行政复议，由有管辖权的行政复议机关共同作出行政复议决定。\n第三十三条 对行政机关设立的内设机构经法律、法规、规章授权，以自己名义作出的行政行为不服的，向设立该机构的行政机关申请行政复议；该行政机关不具有行政复议职责的，向对该行政机关有管辖权的行政复议机关申请行政复议。","level":2},{"name":"第三章 行政复议受理","text":"第三十四条 公民、法人或者其他组织认为行政机关的行政行为侵犯其合法权益提出行政复议申请，除不符合行政复议法和本条例规定的受理条件的，行政复议机关必须受理。\n第三十五条 行政复议法第三十条第一款第二项规定的申请人与被申请行政复议的行政行为有利害关系包括下列情形：\n（一）行政行为涉及申请人相邻权的；\n（二）行政行为影响申请人公平参与竞争的；\n（三）撤销或者变更行政行为侵犯申请人合法权益的；\n（四）申请人为维护自身合法权益向具有处理职责的行政机关申请查处违法行为，行政机关作出或者未作出处理的；\n（五）其他与行政行为有利害关系的情形。\n第三十六条 公民、法人或者其他组织就下列事项申请行政复议的，行政复议机关不予受理：\n（一）公安、国家安全、刑罚执行等机关办理刑事案件与执行刑罚的行为；\n（二）行政机关实施的行政指导行为；\n（三）行政机关为作出行政行为而实施的论证、请示、咨询等过程性行为；\n（四）上级行政机关对下级行政机关的执法监督、督促履责等行为；\n（五）行政机关对信访事项作出的登记、受理、交办、转送、复查、复核等行为。\n第三十七条 行政复议申请有下列情形之一，行政复议机关已经受理的，应当决定驳回行政复议申请：\n（一）行政复议请求明显缺乏事实和法律依据，经释明后申请人仍然坚持申请行政复议；\n（二）申请人所请求履行的法定职责或者给付义务明显不属于行政机关权限范围；\n（三）申请人提出的行政复议申请所涉及行政行为的法律效力已经被人民法院作出生效裁判、调解书确认。\n申请人没有新的事实和理由，就同一事项再次申请行政复议的，行政复议机关告知申请人不再处理，并记录在案。\n第三十八条 作出行政处罚决定的行政机关收到申请人依照行政复议法第三十二条规定提交的行政复议申请后，认为行政处罚决定违法或者不当，需要自行纠正的，应当自收到行政复议申请之日起5个工作日内按照法定程序，采取撤销、变更行政处罚决定等方式予以纠正，并将有关情况告知申请人和行政复议机关。\n行政机关自行纠正后，申请人仍坚持对原行政处罚决定申请行政复议的，行政机关应当告知申请人向有管辖权的行政复议机关申请行政复议。申请人向行政机关提交行政复议申请之日至行政机关将有关情况告知申请人之日的期间不计入行政复议申请期限。","level":1},{"name":"第四章 行政复议审理","text":"","level":1},{"name":"第一节 一般规定","text":"第三十九条 行政复议机关审理行政复议案件，应当由2名以上行政复议人员参加。适用简易程序的，可以由1名行政复议人员审理。\n第四十条 上级行政复议机关对下级行政复议机关管辖的行政复议案件，认为属于下列情形之一的，可以决定提级审理：\n（一）涉及重大社会公共利益或者有重大影响；\n（二）属于新类型案件，且案情重大、疑难、复杂；\n（三）具有法律适用指导意义；\n（四）确有必要提级审理的其他情形。\n下级行政复议机关对本机关管辖的行政复议案件，认为符合前款规定情形，需要由上级行政复议机关审理的，可以报请上级行政复议机关决定，报请提级审理期间不计入行政复议案件办理期限。\n上级行政复议机关决定提级审理的，应当通知下级行政复议机关于5个工作日内移送案件材料，并书面告知当事人。行政复议审理期限自上级行政复议机关收到案件材料之日起重新计算。\n第四十一条 被申请人提交书面答复时，应当就行政行为合法性、适当性和申请人的行政复议请求说明相关事实和理由。\n第四十二条 依照行政复议法第二十四条第二款、第二十五条第一项的规定申请原级行政复议的案件，由原承办行政行为有关事项的部门或者机构提出书面答复，并提交作出行政行为的证据、依据和其他有关材料。\n第四十三条 因同一行政行为或者同类行政行为发生的行政复议案件，有下列情形之一的，行政复议机关可以决定合并审理：\n（一）两个以上行政机关分别对同一事实作出行政行为，公民、法人或者其他组织不服，向同一行政复议机关申请行政复议；\n（二）行政机关就同一事实对多个公民、法人或者其他组织分别作出行政行为，公民、法人或者其他组织不服，分别向同一行政复议机关申请行政复议；\n（三）在行政复议期间，被申请人对申请人作出新的行政行为，申请人不服，向同一行政复议机关申请行政复议；\n（四）行政复议机关认为可以合并审理的其他情形。\n决定合并审理的案件，行政复议机关可以合并作出行政复议决定。","level":2},{"name":"第二节 行政复议证据","text":"第四十四条 行政复议机构认为有必要的，可以就案件相关事实当面询问当事人和其他有关人员。\n第四十五条 行政复议期间需要现场勘验的，有关单位、人员应当予以配合，现场勘验所用时间不计入行政复议审理期限。\n第四十六条 行政复议期间涉及专门事项需要鉴定的，当事人可以申请行政复议机构委托鉴定机构进行鉴定。行政复议机构审查同意的，组织当事人协商确定具备相应资格的鉴定机构；协商不成的，由行政复议机构指定。鉴定费用由当事人承担。鉴定所用时间不计入行政复议审理期限。\n第四十七条 被申请人有证据证明其在行政程序中依法要求申请人或者第三人提供证据，申请人或者第三人无正当理由未予提供，但在行政复议程序中提供的证据，行政复议机关不予采纳。\n第四十八条 当事人在调解过程中对协商条件、方案等所作的认可，不得在其后行政复议案件审理过程中作为对其不利的证据。\n第四十九条 行政复议机关应当为申请人、第三人及其委托代理人查阅、复制有关材料提供必要条件。","level":2},{"name":"第三节 行政复议审理程序","text":"第五十条 县级以上地方人民政府行政复议委员会由本级人民政府有关部门、专家、学者等共同组成，可设主任、副主任，由本级人民政府、本级行政复议机构负责人等担任。\n国务院部门可以根据行政复议工作实际情况设立行政复议委员会。\n第五十一条 行政复议委员会通过召开行政复议委员会全体会议、案件咨询会议等形式履行相关职责。\n第五十二条 提请行政复议委员会提出咨询意见的行政复议案件，行政复议机构报请行政复议机关签发行政复议决定时，应当附具行政复议委员会咨询意见，并对行政复议委员会咨询意见的采纳情况作出说明；不采纳行政复议委员会咨询意见的，应当说明理由。\n第五十三条 申请人在对行政行为提出行政复议申请时尚不知道该行政行为所依据的规范性文件的，可以在行政复议机关作出行政复议决定前向行政复议机关提出对该规范性文件的附带审查申请。\n行政复议法第五十六条、第五十七条规定的期限，自行政复议中止之日起计算。\n第五十四条 行政复议法第五十九条规定的规范性文件或者依据的相关条款超越权限或者违反上位法包括下列情形：\n（一）超越制定机关的法定职权或者超越法律、法规、规章的授权范围；\n（二）与法律、法规、规章等上位法的规定相抵触；\n（三）没有法律、法规、规章依据，违法增加公民、法人和其他组织义务或者减损公民、法人和其他组织合法权益；\n（四）其他违反法律、法规、规章规定的情形。","level":2},{"name":"第五章 行政复议决定","text":"第五十五条 行政复议法第六十三条第一款第一项规定的内容不适当包括下列情形：\n（一）违背行政管理目的；\n（二）超过必要限度；\n（三）对相同情况的当事人不平等对待；\n（四）其他不适当的情形。\n第五十六条 行政复议法第六十三条第一款第二项规定的未正确适用依据包括下列情形：\n（一）错误适用依据具体条款；\n（二）应当适用法律位阶更高的依据，而适用法律位阶较低的依据；\n（三）应当适用特殊规定，而适用一般规定；\n（四）应当适用多个依据，而只适用部分依据；\n（五）未明确适用依据；\n（六）其他未正确适用依据的情形。\n第五十七条 行政复议法第六十四条第一款第三项规定的适用的依据不合法包括下列情形：\n（一）适用的依据尚未生效；\n（二）适用的依据超越制定主体权限；\n（三）适用的依据违反上位法的规定；\n（四）其他适用的依据不合法的情形。\n行政行为适用的依据不合法，但有合法依据可以适用且符合行政复议法第六十三条规定的情形的，行政复议机关可以作出变更决定。\n第五十八条 行政复议机关依照行政复议法第六十四条第一款的规定责令被申请人重新作出行政行为的，被申请人应当在法律、法规、规章规定的期限内重新作出行政行为；法律、法规、规章未规定期限的，重新作出行政行为的期限为60日。\n公民、法人或者其他组织对被申请人重新作出的行政行为不服的，可以依法申请行政复议或者提起行政诉讼。\n行政机关违反行政复议法第六十四条第二款的规定，以同一事实和理由重新作出与原行政行为相同或者基本相同的行政行为，行政复议机关应当决定撤销或者部分撤销该行政行为，并责令被申请人在一定期限内重新作出行政行为。\n第五十九条 行政复议法第六十五条第一款第二项规定的程序轻微违法包括对申请人依法享有的陈述、申辩等重要程序性权利不产生实际影响的下列情形：\n（一）处理期限轻微违法；\n（二）通知、送达等程序轻微违法；\n（三）其他程序轻微违法的情形。\n第六十条 行政复议法第六十七条规定的重大且明显违法包括下列情形：\n（一）行政行为实施主体不具有行政主体资格；\n（二）增加义务或者减损权利的行政行为没有法律、法规、规章依据；\n（三）行政行为的内容客观上不可能实施；\n（四）其他重大且明显违法的情形。\n第六十一条 有下列情形之一的，行政复议机关应当决定驳回申请人的行政复议请求：\n（一）申请人申请确认行政行为无效，行政复议机关受理后发现该行政行为不属于无效情形，经释明，申请人拒绝变更行政复议请求；\n（二）申请人认为被申请人不履行法定职责申请行政复议，行政复议机关受理后发现被申请人因不可抗力等正当事由客观上无法履行法定职责；\n（三）被申请行政复议的行政行为依法应予变更，但是变更对申请人更为不利。\n前款第三项情形中，第三人提出相反请求的除外。\n第六十二条 行政复议机关审理行政协议复议案件，根据行政复议法第七十一条规定的情形，作出如下决定：\n（一）责令被申请人依法订立行政协议；\n（二）责令被申请人依法履行或者按照行政协议约定履行义务；\n（三）撤销被申请人变更、解除行政协议的行政行为，或者确认该行政行为违法；\n（四）撤销、解除行政协议；\n（五）责令被申请人采取补救措施、赔偿损失或者依法给予合理补偿。\n第六十三条 行政复议机关审理行政赔偿复议案件，对于应当赔偿且能够确定赔偿方式的，应当作出具有明确赔偿内容的行政复议决定。\n行政机关作出的行政赔偿决定确定的赔偿数额确有错误的，行政复议机关可以作出变更决定。\n第六十四条 有下列情形之一的，行政复议机关决定驳回申请人行政赔偿请求：\n（一）申请人主张的损害没有事实根据；\n（二）申请人主张的损害与违法行政行为没有因果关系；\n（三）申请人的损失已经通过行政补偿等其他途径获得救济；\n（四）被申请人自行纠正原违法行政行为的同时已经消除相应损害结果；\n（五）申请人请求行政赔偿的理由不能成立的其他情形。\n第六十五条 行政复议机关作出行政复议决定后，申请人以外的公民、法人或者其他组织就同一行政行为或者同样行政行为申请行政复议且符合受理条件的，行政复议机关可以在受理后根据发生法律效力的行政复议决定的内容，直接作出行政复议决定。\n前款规定的同样行政行为是指同一行政机关就同一事实对多个当事人分别作出的行政行为。","level":1},{"name":"第六章 行政复议指导和监督","text":"第六十六条 县级以上地方各级人民政府应当建立健全行政复议工作责任制，支持和保障行政复议机构依法履行职责，将行政复议工作纳入本级政府目标责任制。\n县级以上地方各级人民政府行政复议机构应当加强对行政复议工作的统计分析，定期向本级人民政府提交行政复议工作报告。\n第六十七条 县级以上地方各级人民政府应当按照职责权限，通过定期组织检查、抽查等方式，对下级人民政府行政复议工作进行检查，并及时反馈检查结果。重大事项及时按照有关规定请示报告。\n第六十八条 行政复议机关应当采取有效措施，支持和保障行政复议人员依法履职办案。\n第六十九条 行政复议机构在行政复议工作中发现法律、法规、规章、规范性文件实施中带有普遍性的问题，可以制作行政复议建议书，向有关机关提出完善制度和改进行政执法的建议。\n第七十条 各级行政复议机构应当定期对行政复议人员进行政治、理论和业务培训，提高行政复议人员的能力素质。","level":1},{"name":"第七章 法律责任","text":"第七十一条 被申请人在规定期限内未按照行政复议决定的要求重新作出行政行为，或者违反规定重新作出行政行为的，依照行政复议法第八十三条的规定追究法律责任。\n第七十二条 对行政复议人员及其近亲属实施报复陷害、侮辱诽谤、暴力侵害、威胁恐吓、滋事骚扰等违法行为的，依法给予处分、治安管理处罚；构成犯罪的，依法追究刑事责任。\n第七十三条 加强行政复议与监察监督的贯通协同，健全信息共享和线索移送机制。","level":1},{"name":"第八章 附 则","text":"第七十四条 公民、法人或者其他组织对行政机关作出的驳回商标申请、驳回专利申请等行为不服申请行政复议的，依照《中华人民共和国商标法》、《中华人民共和国专利法》的有关规定提出复审请求。\n第七十五条 公民、法人或者其他组织对海警机构的行政行为不服的，依法向上一级海警机构申请行政复议。\n第七十六条 行政复议机关审理行政复议案件，参照国务院行政复议机构发布的行政复议指导性案例。\n第七十七条 本条例自2026年7月1日起施行。","level":1}]},{"id":"n1276","sections":[{"name":"","text":"行政法规制定程序条例\n（2001年11月16日中华人民共和国国务院令第321号公布 根据2017年12月22日《国务院关于修改〈行政法规制定程序条例〉的决定》修订 2026年5月15日中华人民共和国国务院令第838号第二次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了规范行政法规制定程序，保证行政法规质量，根据宪法、立法法和国务院组织法的有关规定，制定本条例。\n第二条 行政法规的立项、起草、审查、决定、公布、解释，适用本条例。\n第三条 制定行政法规，应当坚持中国共产党的领导，贯彻落实党的路线方针政策和决策部署。\n制定行政法规，应当符合宪法和法律的规定，遵循立法法确定的指导思想和原则。\n第四条 制定政治方面法律的配套行政法规，应当按照有关规定及时报告党中央。\n制定经济、文化、社会、生态文明等方面重大体制和重大政策调整的重要行政法规，应当将行政法规草案或者行政法规草案涉及的重大问题按照有关规定及时报告党中央。\n第五条 制定行政法规，应当完整准确全面贯彻新发展理念，统筹发展和安全，注重立法与改革、发展、稳定相协同，注重保障和促进社会公平正义，优化法治化营商环境，服务高质量发展和高水平对外开放，建设法治政府，推进国家治理体系和治理能力现代化。\n第六条 制定行政法规，应当坚持科学立法、民主立法、依法立法，增强立法的系统性、整体性、协同性、时效性。\n第七条 制定行政法规，应当适应改革需要，引导、推动、规范、保障相关改革。\n第八条 对党和国家工作大局急需、人民群众迫切期盼，调整范围单一、有关方面没有较大争议的行政法规，应当快速响应，优化工作方式，加快相关立法工作。\n第九条 行政法规应当备而不繁，逻辑严密，条文明确、具体，用语准确、简洁，具有可操作性。","level":1},{"name":"第二章 立 项","text":"第十条 国务院于每年年初编制本年度的立法工作计划。\n国务院法治部门根据国家总体工作部署，拟订国务院年度立法工作计划，报党中央、国务院批准后向社会公布。\n第十一条 国务院有关部门认为需要制定行政法规的，应当于国务院编制年度立法工作计划前，向国务院报请立项。\n国务院有关部门应当贯彻落实党中央、国务院决策部署，报送实践所需、立法时机成熟的立项申请。\n国务院法治部门应当向社会公开征集行政法规制定项目建议。\n第十二条 国务院有关部门报送行政法规立项申请，应当说明依据的党的路线方针政策和决策部署、立法项目的必要性和可行性、所要解决的主要问题、拟确立的主要制度及预期实施效果、有关风险评估及防范应对措施、已开展的工作情况等。\n第十三条 国务院法治部门拟订国务院年度立法工作计划时，应当结合立法项目的成熟程度、紧迫程度，突出重点领域、新兴领域、涉外领域，统筹兼顾，加强评估论证。\n列入国务院年度立法工作计划的行政法规项目应当符合下列要求：\n（一）贯彻落实党的路线方针政策和决策部署，适应改革、发展、稳定的需要；\n（二）有关的改革实践经验基本成熟，立法时机成熟；\n（三）所要解决的问题属于国务院职权范围并需要国务院制定行政法规的事项，全国人民代表大会及其常务委员会授权国务院制定行政法规的事项，或者为执行法律的规定需要制定行政法规的事项；\n（四）拟列入当年完成审查的立法项目的，还应当已经向国务院报送行政法规草案送审稿（以下简称送审稿），且有关方面对送审稿规定的主要制度没有较大争议。\n第十四条 承担起草任务的国务院有关部门应当严格贯彻执行立法工作计划，抓紧工作，按照要求向国务院报送送审稿；报送国务院前，应当送国务院法治部门进行前置评估。国务院法治部门应当提出前置评估意见。起草部门应当认真研究处理，并在报送国务院的材料中对前置评估意见研究处理情况作出说明。\n国务院法治部门应当及时跟踪了解国务院各部门落实国务院年度立法工作计划的情况，加强组织协调和督促指导，统筹推进立法工作计划落实。\n国务院年度立法工作计划在执行中可以根据实际情况予以调整。\n第十五条 国务院有关部门起草的拟报请国务院批准印发的文件涉及立法项目的，应当征求国务院法治部门意见。","level":1},{"name":"第三章 起 草","text":"第十六条 行政法规由国务院组织起草。国务院年度立法工作计划确定行政法规由国务院的一个部门或者几个部门具体负责起草工作，也可以确定由国务院法治部门起草或者组织起草。\n第十七条 起草行政法规，应当符合本条例第三条至第七条的规定，并符合下列要求：\n（一）弘扬社会主义核心价值观，铸牢中华民族共同体意识；\n（二）体现全面深化改革精神，科学规范行政行为，保障政府履行经济调节、市场监管、社会管理、公共服务、生态环境保护等职能；\n（三）符合优化协同高效的原则，相同或者相近的职能规定由一个行政机关承担，简化行政管理手续；\n（四）切实保障公民、法人和其他组织的合法权益，在规定其应当履行的义务的同时，应当规定其相应的权利和保障权利实现的途径；\n（五）体现行政机关的职权与责任相统一的原则，在赋予有关行政机关必要的职权的同时，应当规定其行使职权的条件、程序和应承担的责任；\n（六）坚持问题导向，遵循经济社会发展规律。\n第十八条 起草行政法规，应当坚持和发展全过程人民民主，拓展人民群众有序参与立法途径。起草部门应当通过多种方式深入调查研究，总结实践经验，广泛听取有关机关、组织和公民的意见。起草与经营主体生产经营活动密切相关的行政法规，应当听取有关企业和行业协会商会的意见。听取意见可以采取召开座谈会、论证会、听证会等多种形式。\n起草行政法规，涉及人民群众普遍关注的热点难点问题和经济社会发展遇到的突出矛盾，减损公民、法人和其他组织权利或者增加其义务，对人民群众有重要影响等重大利益调整事项的，应当进行论证咨询。\n起草行政法规，起草部门应当将行政法规草案及其说明等向社会公布，征求意见；但是，涉及国家安全，或者遇有紧急情形等，经国务院决定不公布的除外。向社会公布征求意见的期限一般不少于30日。\n起草专业性较强的行政法规，起草部门可以吸收相关领域的专家参与起草工作，或者委托有关专家、教学科研单位、社会组织起草。\n第十九条 起草行政法规，起草部门应当就涉及其他部门的职责或者与其他部门关系紧密的规定，与有关部门充分协商，涉及部门职责分工、行政许可、财政支持、税收优惠政策的，应当征得机构编制、财政、税务等相关部门同意。\n起草部门应当加强立法时机、立法预期实施效果等的评估，并与宏观政策取向保持一致，注重为基层减负。\n第二十条 起草行政法规，起草部门应当对涉及有关管理体制、政策等需要国务院决策的重大问题提出解决方案，报国务院决定。\n第二十一条 起草部门向国务院报送的送审稿，应当由起草部门主要负责人签发。\n起草行政法规，涉及几个部门共同职责需要共同起草的，应当共同起草，达成一致意见后联合报送送审稿。几个部门共同起草的送审稿，应当由该几个部门主要负责人共同签发。\n第二十二条 起草部门将送审稿报送国务院审查时，应当一并报送送审稿的说明和有关材料。修改行政法规的，还应当报送修改前后的对照文本。\n送审稿的说明应当包括以下内容：立法的必要性、可行性，主要思路，确立的主要制度；征求有关机关、组织和公民意见的情况，各方面对送审稿主要问题的不同意见及其协调处理情况；拟设定、取消或者调整行政许可、行政强制措施的情况；风险评估及防范应对措施等。\n有关材料主要包括：依据的党的路线方针政策和决策部署；所规范领域的实际情况和相关数据，实践中存在的主要问题，与有关行政法规协调和衔接情况；拟设定、取消或者调整行政许可、行政强制措施的论证材料；有关评估报告；调研报告、考察报告、国内外的有关立法资料等。","level":1},{"name":"第四章 审 查","text":"第二十三条 报送国务院的送审稿，由国务院法治部门负责审查。国务院法治部门应当完善政府立法审查制度，提高审查质效。\n国务院法治部门主要从以下方面对送审稿进行审查：\n（一）是否严格贯彻落实党的路线方针政策和决策部署，是否符合宪法和法律的规定，是否遵循立法法确定的指导思想和原则；\n（二）是否符合本条例第十七条的要求；\n（三）是否与有关行政法规协调、衔接；\n（四）是否正确处理有关机关、组织和公民对送审稿主要问题的意见；\n（五）其他需要审查的内容。\n第二十四条 送审稿有下列情形之一的，国务院法治部门可以缓办或者退回，并书面告知起草部门：\n（一）制定行政法规的基本条件尚不成熟或者发生重大变化的；\n（二）有关部门对送审稿规定的主要制度存在较大争议的；\n（三）起草部门未就涉及部门职责分工、行政许可、财政支持、税收优惠政策的规定征得机构编制、财政、税务等相关部门同意的；\n（四）未按照本条例有关规定公开征求意见的；\n（五）报送送审稿等材料不符合本条例第十四条、第二十条至第二十二条规定的。\n第二十五条 国务院法治部门应当将送审稿或者送审稿涉及的主要问题发送国务院有关部门、地方人民政府、有关组织和专家等各方面征求意见。国务院有关部门、地方人民政府应当在规定期限内反馈书面意见，并加盖本单位或者本单位办公厅（室）印章。国务院法治部门认为送审稿中涉及合宪性问题的，应当征求全国人民代表大会常务委员会有关工作机构意见。\n国务院法治部门可以将送审稿或者修改稿及其说明等向社会公布，征求意见。向社会公布征求意见的期限一般不少于30日。\n第二十六条 国务院法治部门应当就送审稿涉及的主要问题，深入基层进行实地调查研究，听取基层有关机关、组织和公民的意见。\n第二十七条 送审稿涉及重大利益调整的，国务院法治部门应当进行论证咨询，广泛听取有关方面的意见。论证咨询可以采取座谈会、论证会、听证会、委托研究等多种形式。\n送审稿涉及重大利益调整或者存在重大意见分歧，对公民、法人或者其他组织的权利义务有较大影响，人民群众普遍关注的，国务院法治部门可以举行听证会，听取有关机关、组织和公民的意见。\n第二十八条 国务院有关部门对送审稿涉及的主要制度、政策、管理体制、权限分工等有不同意见的，国务院法治部门应当进行协调，力求达成一致意见。对有较大争议的重要立法事项，国务院法治部门可以委托有关专家、教学科研单位、社会组织进行评估。\n经过充分协调不能达成一致意见的，国务院法治部门、起草部门应当将争议的主要问题、有关部门的意见以及国务院法治部门的意见及时报国务院领导协调，或者报国务院决定。\n第二十九条 国务院法治部门应当认真研究各方面的意见，与起草部门协商后，对送审稿进行修改，形成行政法规草案和对草案的说明。\n第三十条 行政法规草案由国务院法治部门主要负责人提出提请国务院常务会议审议的建议；对调整范围单一、各方面意见一致或者依据法律制定的配套行政法规草案，可以采取传批方式，由国务院法治部门直接提请国务院审批。","level":1},{"name":"第五章 决定与公布","text":"第三十一条 行政法规草案由国务院常务会议审议，或者由国务院审批。\n国务院常务会议审议行政法规草案时，由国务院法治部门或者起草部门作说明。\n第三十二条 国务院法治部门应当根据国务院对行政法规草案的审议意见，对行政法规草案进行修改，形成草案修改稿，报请总理签署国务院令公布施行。\n签署公布行政法规的国务院令载明该行政法规的施行日期。\n第三十三条 行政法规签署公布后，及时在国务院公报和中国政府法制信息网以及在全国范围内发行的报纸上刊载。国务院法治部门应当及时汇编出版行政法规的国家正式版本，并纳入国家行政法规库。\n在国务院公报上刊登的行政法规文本为标准文本。\n第三十四条 行政法规应当自公布之日起30日后施行；但是，涉及国家安全、外汇汇率、货币政策的确定以及公布后不立即施行将有碍行政法规施行的，可以自公布之日起施行。\n第三十五条 行政法规在公布后的30日内由国务院办公厅报全国人民代表大会常务委员会备案。","level":1},{"name":"第六章 行政法规解释","text":"第三十六条 行政法规有下列情形之一的，由国务院解释：\n（一）行政法规的规定需要进一步明确具体含义的；\n（二）行政法规制定后出现新的情况，需要明确适用行政法规依据的。\n国务院法治部门研究拟订行政法规解释草案，报国务院同意后，由国务院公布或者由国务院授权国务院有关部门公布。\n行政法规的解释与行政法规具有同等效力。\n第三十七条 国务院各部门和省、自治区、直辖市人民政府可以向国务院提出行政法规解释要求。\n第三十八条 对属于行政工作中具体应用行政法规的问题，省、自治区、直辖市人民政府法治部门以及国务院有关部门法治机构请求国务院法治部门解释的，国务院法治部门可以研究答复；其中涉及重大问题的，由国务院法治部门提出意见，报国务院同意后答复。","level":1},{"name":"第七章 其他规定","text":"第三十九条 行政法规的名称一般称“条例”，也可以称“规定”、“办法”等。国务院根据全国人民代表大会及其常务委员会的授权决定制定的行政法规，称“暂行条例”或者“暂行规定”。\n国务院各部门和地方人民政府制定的规章不得称“条例”。\n第四十条 行政法规根据内容需要，可以分章、节、条、款、项、目。章、节、条的序号用中文数字依次表述，款不编序号，项的序号用中文数字加括号依次表述，目的序号用阿拉伯数字依次表述。\n第四十一条 行政法规明确要求对专门事项作出配套的具体规定的，国务院有关部门应当自行政法规施行之日起1年内作出规定；行政法规对配套的具体规定制定期限另有规定的，从其规定。国务院有关部门未能在期限内作出配套的具体规定的，应当向国务院说明情况。\n第四十二条 国务院可以根据经济社会发展、全面深化改革需要，就行政管理等领域的特定事项，决定授权在规定期限和范围内暂时调整或者暂时停止适用行政法规的部分规定。\n国务院有关部门应当会同相关地方人民政府对行政法规暂时调整或者暂时停止适用情况及时进行评估论证。对实践证明可行、需要修改有关行政法规的，按立法程序办理；对实践证明不宜调整、需要恢复施行行政法规有关规定的，由国务院有关部门报请国务院决定。\n第四十三条 国务院法治部门应当根据全面深化改革、经济社会发展需要以及上位法规定，报国务院同意后及时组织开展行政法规清理工作。国务院有关部门可以根据工作需要，向国务院法治部门提出行政法规清理建议。\n对不适应全面深化改革和经济社会发展要求、不符合上位法规定的行政法规，应当及时修改或者废止。\n第四十四条 国务院法治部门或者国务院有关部门可以组织对有关行政法规或者行政法规中的有关规定进行立法后评估，并把评估结果作为修改、废止有关行政法规的重要参考。\n第四十五条 行政法规的修改、废止程序适用本条例的有关规定。\n行政法规修改的，应当公布新的行政法规文本。\n行政法规废止的，除由法律、其他行政法规规定废止该行政法规的以外，由总理签署国务院令予以公布。\n第四十六条 行政法规的外文正式译本和民族语言文本，由国务院法治部门审定。\n第四十七条 拟订国务院提请全国人民代表大会或者全国人民代表大会常务委员会审议的法律草案，参照本条例的有关规定办理。","level":1},{"name":"第八章 附 则","text":"第四十八条 本条例自2026年7月1日起施行。","level":1}]},{"id":"n1277","sections":[{"name":"","text":"国务院关于对外投资的规定\n第一条 为了推进高水平对外开放，促进对外投资高质量发展，有效实施对外投资管理，保护投资者及其对外投资合法权益，维护国家主权、安全、发展利益，根据《中华人民共和国对外关系法》、《中华人民共和国对外贸易法》等法律，制定本规定。\n第二条 中华人民共和国境内（以下简称中国境内）投资者对外投资，适用本规定。\n本规定所称对外投资即境外投资，是指投资者以投入资产、权益或者提供融资、担保等方式，直接或者间接获得其他国家（地区）的企业、资产等所有权、控制权、经营管理权以及其他相关权益的活动。\n本规定所称投资者，包括中国境内的企业、其他组织和居民个人。\n第三条 对外投资工作坚持对外开放的基本国策，贯彻总体国家安全观，统筹发展和安全，统筹国内国际，健全对外投资管理服务体系，提升对外投资质量与水平，促进开放合作、互利共赢。\n第四条 国家主动对接国际高标准经济贸易规则，推进高质量共建“一带一路”，推进多双边投资合作机制建设，积极参与国际投资规则制定，推动产业链供应链国际合作，反对单边主义和保护主义，推动建设开放型世界经济。\n第五条 国家支持投资者按照市场化原则开展对外投资活动，积极参与国际合作竞争。投资者依法享有对外投资自主权，自主决策、自担风险、自负盈亏。\n投资者开展对外投资及其相关活动，应当遵守法律法规和国际惯例，尊重当地习俗和文化传统，遵守商业道德，诚实守信、公平竞争，履行社会责任，维护国家形象，不得妨害市场竞争秩序、破坏生态环境、损害劳动者合法权益，不得危害中国国家安全、损害国家利益和社会公共利益。\n第六条 国家健全海外综合服务体系，促进贸易投资一体化，完善公共平台与服务，统筹外事、法律、财税、金融、经贸、物流、出境入境、海关、贸促等领域服务资源，为投资者提供服务保障。\n省级以上人民政府及其有关部门提升公共服务能力和水平，为投资者提供法律法规、政策措施、投资指南、知识产权、风险防范应对、权益保护等方面的公共产品和服务。\n第七条 支持咨询评估、法律服务、会计审计、信用评级、调解仲裁、知识产权等专业服务机构拓展海外服务网络，提高国际化服务能力和水平，为投资者及其对外投资提供高质量专业服务。\n有关专业服务机构应当遵循诚实守信、勤勉尽责、独立客观的原则，建立有效的风险控制和内部控制制度，配备具有相应专业能力的从业人员，依法开展有关服务活动。\n第八条 银行业金融机构应当立足职能定位，遵循市场化、法治化、商业可持续和风险可控原则，在业务范围内为投资者对外投资提供融资等金融服务。鼓励政策性保险机构为投资者对外投资提供海外投资保险等服务。\n第九条 有关行业协会商会应当依照法律、法规和章程，加强行业自律，提升服务投资者及其对外投资的能力和水平，及时反映行业诉求。\n行业协会商会、贸易投资促进组织按照章程提供与对外投资有关的信息咨询、市场拓展、经贸交流、权益保护、纠纷处理等方面的服务。\n第十条 国家健全对外投资管理体系，完善调控措施，分类分级实施全过程监管，加强风险防控，提高对外投资的科学性、安全性，推动投资便利化和有效防范风险相结合。\n第十一条 国务院投资主管部门、商务主管部门会同国务院其他有关部门根据国民经济和社会发展需要、有关国家（地区）投资环境变化和风险程度等，制定、调整和实施对外投资政策，明确鼓励、限制、禁止的对外投资，加强对外投资监管，指导、监督投资者规范投资经营行为。\n第十二条 投资者开展对外投资活动依法需要履行核准备案、信息报告、跨境资金登记等手续的，应当依照国家有关规定办理，如实提交有关材料，并配合有关主管部门的监督检查。\n第十三条 投资者开展对外投资活动，不得出口、使用国家禁止出口的货物、技术、服务及相关数据，或者未经许可出口、使用国家限制出口的货物、技术、服务及相关数据；不得以跨境派遣技术人员、组织人员赴其他国家（地区）工作、跨境提供技术指导、安排人员跨境培训等方式向其他国家（地区）转移国家禁止出口的货物、技术、服务及相关数据，或者未经许可向其他国家（地区）转移国家限制出口的货物、技术、服务及相关数据。\n第十四条 对外投资涉及资金汇兑、货物与技术进出口、跨境服务贸易、跨境数据流动、人员出境入境的管理以及经营者集中审查、出口管制、网络安全监管、税收征收管理、国有资产监管等，依照有关法律、行政法规和国家有关规定执行。\n第十五条 国家健全境外投资安全审查制度，国务院投资主管部门、商务主管部门会同国务院其他有关部门对影响或者可能影响国家安全的境外投资及相关资产、权益等的转让、处分进行安全审查。有关组织、个人应当予以协助、配合，不得拒绝、阻碍，并应当遵守境外投资安全审查决定。\n第十六条 投资者及其在其他国家（地区）投资的企业应当完善治理结构，建立健全合规经营、内部控制、安全生产、突发事件处置等制度，加强风险识别和防范处置，投入必要的人员、资金、设备等资源，保障其员工和资产安全。\n第十七条 投资者应当规范投资经营行为，不得损害其他投资者的商业信誉、商品声誉，侵犯他人商业秘密，没有正当理由低价倾销商品，通过贿赂、欺诈等手段牟取不正当利益，扰乱对外投资市场秩序。\n第十八条 国务院有关部门加强对外投资监测预警和风险评估，及时发布有关国家（地区）安全状况，提示投资风险，指导和帮助投资者做好安全风险防范，维护国家海外利益和投资者合法权益。\n第十九条 中华人民共和国根据缔结或者参加的国际条约、协定，或者按照平等互惠原则，与其他国家（地区）、国际组织等开展执法领域合作与交流，保护在其他国家（地区）的投资者及其投资的企业、项目所属员工和资产等的安全以及有关组织、个人的正当权益。\n国家积极商签多双边贸易投资协定等国际经贸协定，提高对外投资保护水平，促进投资自由化便利化。\n第二十条 国家依法为在其他国家（地区）投资的中国公民、组织及其在该国家（地区）投资的企业、项目所属中国籍员工提供领事保护与协助，维护其正当权益。\n投资目的国家（地区）发生战争、武装冲突、暴乱、严重自然灾害、重大事故灾难、重大传染病疫情、恐怖袭击等重大突发事件，在该国家（地区）的投资者及其投资的企业、项目所属中国籍员工因人身财产安全受到威胁需要帮助的，驻外外交机构应当及时核实情况，敦促有关国家（地区）采取有效措施保护中国公民、组织的人身财产安全，并根据相关情形提供协助；中国政府作出相应避险安排的，有关组织、个人应当予以配合。\n第二十一条 鼓励投资者通过协商、调解、仲裁、诉讼等多种方式化解对外投资有关矛盾纠纷，维护自身合法权益。\n第二十二条 中国境内组织、个人参与对外投资相关仲裁、诉讼或者受到境外司法、执法机构相关调查，需要向境外提供证据或者相关材料的，应当遵守保守国家秘密、数据安全、个人信息保护、技术出口管理、出口管制、司法协助等法律、行政法规和国家有关规定。依法须经主管机关准许的，应当履行相关法律程序。\n第二十三条 投资者在投资目的国家（地区）遭遇与贸易有关的投资壁垒或者其他投资经营障碍的，国务院商务主管部门可以自行或者会同国务院其他有关部门组织开展调查，有关组织、个人应当予以协助、配合。根据调查结果，国务院有关部门可以采取调整有关国别投资政策，禁止或者限制有关货物、技术进出口或者国际服务贸易等措施。\n第二十四条 任何国家（地区）、国际组织违反国际法和国际关系基本准则，在投资经营等方面对中华人民共和国采取歧视性禁止、限制或者其他类似措施，中国政府及其有关部门可以根据实际情况采取相应的措施，保护投资者及其对外投资的安全和正当权益，保护国家的海外利益不受威胁和侵害。\n国务院有关部门可以依照《中华人民共和国反外国制裁法》、《实施〈中华人民共和国反外国制裁法〉的规定》等，决定将直接或者间接参与制定、决定、实施前款规定的歧视性禁止、限制或者其他类似措施的组织、个人列入反制清单，采取相应的措施。\n第二十五条 外国组织、个人危害中国国家主权、安全、发展利益，违反正常的市场交易原则中断与中国企业、其他组织或者个人的正常交易，或者对投资者及其对外投资采取歧视性措施，不合理剥夺或者限制投资者及其对外投资正当权益的，国务院有关部门可以采取禁止或者限制其从事与我国有关的进出口活动，禁止或者限制其在中国境内投资，禁止或者限制中国境内的组织、个人与其进行有关交易、合作等活动，禁止或者限制相关人员、产品、交通运输工具等入境，取消或者限制相关人员在中国境内工作、停留或者居留资格等措施。有关措施可以适用于外国组织、个人实际控制或者参与设立、运营的组织。\n第二十六条 公职人员对在履行对外投资管理服务相关职责中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息等应当依法予以保密，不得泄露或者非法向他人提供。\n第二十七条 投资者投资国家禁止的对外投资的，由国务院投资主管部门、商务主管部门按照职责分工责令停止该投资活动，限期处分股份、资产，没收违法所得；拒不执行的，处投资额5‰以上10‰以下的罚款；对直接负责的主管人员和其他直接责任人员处5万元以上10万元以下的罚款。\n投资者未按规定履行境外投资核准备案手续，或者以提交虚假材料、隐瞒真实信息等方式申请有关核准备案的，由核准备案机关责令改正，没收违法所得，处投资额1‰以上5‰以下的罚款；拒不改正的，责令其停止该投资活动，限期处分股份、资产，处投资额5‰以上10‰以下的罚款；对直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款。\n投资者以贿赂、欺骗等不正当手段获得境外投资核准备案的，由核准备案机关撤销核准备案文件，没收违法所得，处投资额1‰以上5‰以下的罚款；已经投资的，责令其停止该投资活动，限期处分股份、资产，处投资额5‰以上10‰以下的罚款；对直接负责的主管人员和其他直接责任人员处2万元以上5万元以下的罚款。\n自前三款规定的处罚决定生效之日起，有关主管部门可以在3年内不受理违法行为人提出的核准备案申请，或者禁止其在1年以上3年以下的期限内从事对外投资活动。\n第二十八条 违反本规定第十五条规定，拒不配合境外投资安全审查，提供虚假材料或者隐瞒有关信息，或者不遵守境外投资安全审查决定的，由国务院有关部门责令改正，没收违法所得，处以罚款；危害国家安全的，责令其采取必要措施消除对国家安全的影响，可以禁止其在1年以上3年以下的期限内从事对外投资活动；已经投资的，可以责令其停止该投资活动，限期处分股份、资产。\n第二十九条 投资者违反本规定第十七条规定的，国务院投资主管部门、商务主管部门按照职责分工可以责令限期改正；造成危害后果的，可以禁止其在1年以上3年以下的期限内从事对外投资活动。\n第三十条 投资者开展对外投资活动，违反本规定，造成人身损害、财产损失的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n投资者开展对外投资活动，违反其他法律、法规的，由有权机关责令改正，依法予以处理。\n第三十一条 公职人员在对外投资工作中滥用职权、玩忽职守、徇私舞弊，或者泄露、非法向他人提供所知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息的，依法给予处分；构成犯罪的，依法追究刑事责任。\n第三十二条 对投资者在香港特别行政区、澳门特别行政区、台湾地区投资的管理，参照本规定执行；法律、行政法规或者国务院另有规定的，依照其规定。\n第三十三条 对投资者以自有资金、募集资金及其他受托资金在中国境外金融市场投资的管理，依照本规定和国家其他有关规定执行。\n对投资者以对外投资获得的资产、权益等在中国境外再投资的管理，依照本规定和国家其他有关规定执行。\n中国境内居民个人等对外投资具体管理办法，由国务院投资主管部门、商务主管部门制定。\n第三十四条 本规定自2026年7月1日起施行。","level":0}]},{"id":"n1278","sections":[{"name":"","text":"中华人民共和国矿产资源法实施条例","level":0},{"name":"第一章 总 则","text":"第一条 根据《中华人民共和国矿产资源法》（以下简称矿产资源法），制定本条例。\n第二条 国家促进矿产资源合理开发利用，加强矿产资源和生态环境保护，推动矿业高质量发展，保障矿产资源安全。\n第三条 矿产资源目录的确定和调整，由国务院自然资源主管部门会同国务院发展改革部门提出，报国务院批准后公布。\n矿产资源目录包括矿产资源矿种和分类。\n第四条 国家加大对基础性地质调查工作的投入力度，加强基础性地质调查队伍建设，鼓励社会力量依法有序参与基础性地质调查，提升基础性地质调查工作质效。\n第五条 国家完善财政、金融、土地、生态环境、产业、进出口等方面政策措施，健全战略性矿产资源探产供储销全链条统筹和衔接体系，加大对战略性矿产资源勘查、开采、加工、贸易、储备等的支持力度，推进战略性矿产资源产业优化升级，提升矿产资源安全保障水平。\n战略性矿产资源目录的确定和调整，由国务院自然资源主管部门会同国务院有关部门研究提出，报国务院批准后实施。确定和调整战略性矿产资源目录，应当统筹考虑下列因素，对相关矿产资源开展评估：\n（一）对国民经济和社会发展、国家安全的重要程度；\n（二）国内资源禀赋情况、紧缺程度以及对外依存度；\n（三）相关产业链供应链的韧性和安全水平；\n（四）其他需要考虑的因素。\n对国务院确定的特定战略性矿产资源，按照法律、行政法规和国家有关规定实行规划管控、总量调控、限定开采主体等保护性开采措施。\n第六条 依照矿产资源法第九条规定编制并经批准的矿产资源相关规划应当依法公布。开展地质调查以及矿产资源勘查、开采、保护和矿区生态修复等活动，应当符合矿产资源相关规划。\n县级以上人民政府自然资源主管部门可以根据实际需要，会同有关部门就特定领域、特定区域的矿产资源或者特定矿种的勘查、开采、保护和矿区生态修复等编制相关规划，相关信息应当纳入国土空间规划实施监督信息系统。\n第七条 国家坚持平等互利、合作共赢的方针，通过多种途径和方式积极促进矿产资源领域国际投资、贸易、技术等合作，维护产业链供应链安全稳定。\n开展海外矿产资源开发利用，应当维护国家利益和社会公共利益，遵守我国法律、法规以及所在国家或者地区的相关法律，信守合同，尊重当地习俗和文化传统，注重生态环境保护和安全生产，加强安全风险防范，并按照规定办理相关手续，依法接受我国相关部门和驻外外交机构的管理和监督。","level":1},{"name":"第二章 矿业权","text":"第八条 矿业权应当通过招标、拍卖、挂牌等竞争性方式出让；对紧缺程度高、资源储量规模中型以上的战略性矿产资源，或者对勘查开采技术、生态环境保护有特殊要求的勘查区块，优先通过招标方式出让探矿权。\n有下列情形之一的，可以通过协议方式出让矿业权：\n（一）依照法律、行政法规或者国务院规定，相关矿产资源需由特定主体勘查、开采；\n（二）为保障矿山安全生产或者矿业权合理设置等，需要在登记的开采区域深部、上部继续开采矿产资源或者在其周边进一步开采零星分散矿产资源；\n（三）同一矿业权人在其登记的相邻勘查、开采区域之间无法单独设置矿业权的夹缝区域勘查、开采矿产资源；\n（四）法律、行政法规或者国务院规定的其他情形。\n为保障国家矿产资源安全，急需开采战略性矿产资源的，经国务院同意，可以由省级以上人民政府自然资源主管部门直接授予采矿权。\n第九条 县级以上人民政府自然资源主管部门按照规定权限组织矿业权出让。\n下列矿产资源由国务院自然资源主管部门或者其授权的省、自治区、直辖市人民政府自然资源主管部门组织矿业权出让：\n（一）战略性矿产资源；\n（二）跨省、自治区、直辖市的矿产资源；\n（三）我国领海及管辖的其他海域的矿产资源。\n前款规定以外的矿产资源的矿业权出让权限，由省、自治区、直辖市人民政府规定。\n同一矿种的探矿权、采矿权出让实行同级管理。矿业权出让涉及多个矿种的，出让权限按照主矿种确定；难以确定主矿种的，按照出让权限最高的矿种确定。\n第十条 县级以上人民政府自然资源主管部门应当根据矿产资源相关规划和矿产资源供需形势等，加强对矿业权出让工作的统筹安排，对符合出让条件的及时安排出让。\n矿业权出让前，出让矿业权的自然资源主管部门（以下称矿业权出让部门）应当进行核查，确保拟出让的勘查、开采区域符合国土空间规划管控要求。\n探矿权出让以经纬度划分的区块为基本单位。\n除符合规定的情形外，新设采矿权范围不得与已设采矿权垂直投影范围重叠，可集中开发的同一矿体不得设立2个以上采矿权。\n第十一条 对向县级以上人民政府自然资源主管部门提供可设立探矿权的区块来源的单位和个人，按照国家有关规定给予适当奖励或者补偿；参与该区块探矿权竞争性出让的，同等条件下优先取得探矿权。\n第十二条 通过竞争性方式出让矿业权的，矿业权出让部门应当提前在其门户网站、公共资源交易平台等公告拟出让矿业权的基本情况、出让方式、竞争规则、保证金收取、风险提示、受让人的技术能力等条件及其权利义务等事项。公告期限不少于30个工作日。\n国务院自然资源主管部门、县级以上地方人民政府及其自然资源主管部门应当创造和维护公平、有序的市场竞争环境，保障各类主体依法平等参与矿业权竞争性出让。\n第十三条 出让矿业权的，矿业权出让部门应当与依法确定的受让人以书面形式签订矿业权出让合同。\n矿业权出让合同签订后，因矿业权出让部门核查有误等导致矿业权不符合国土空间规划管控要求，无法进行勘查或者开采的，受让人有权解除合同。合同解除后，矿业权出让部门应当返还矿业权出让收益；造成受让人财产损失的，应当依法赔偿。\n第十四条 矿业权受让人应当按照国家有关规定和出让合同约定按时足额缴纳矿业权出让收益、矿业权占用费等有关费用。矿业权有关费用征收的具体办法由国务院财政部门会同国务院自然资源主管部门、国务院税务主管部门制定，报国务院批准后执行。\n有下列情形之一的，可以减收或者免收矿业权出让收益：\n（一）勘查、开采低品位、难选冶矿产资源；\n（二）对矿产资源实行综合开发利用成效显著；\n（三）依法组织实施矿产资源应急性开采；\n（四）国务院规定的其他情形。\n未按时足额缴纳矿业权出让收益的，应当按照国家有关规定和出让合同约定支付违约金。\n第十五条 探矿权的期限为5年，期限届满可以续期，续期最多不超过3次，每次期限为5年。对石油、天然气以及国务院自然资源主管部门确定的其他战略性矿产资源，经国务院自然资源主管部门同意，可以根据实际情况增加续期次数。\n采矿权的期限结合矿产资源储量和矿山建设规模确定，最长不超过30年。确定采矿权期限的具体办法由国务院自然资源主管部门制定。采矿权期限届满，登记的开采区域内仍有可供开采的矿产资源的，可以续期。\n矿业权期限届满前，因保障国家矿产资源安全等公共利益需要，原矿业权出让部门可以依法收回矿业权；矿业权被收回的，应当依法给予公平、合理的补偿。\n第十六条 申请矿业权续期的，矿业权人应当在矿业权期限届满前6个月至3个月内向原矿业权出让部门提出申请。原矿业权出让部门应当在矿业权期限届满前作出是否准予续期的决定。\n第十七条 办理探矿权续期时，应当按照国务院自然资源主管部门规定的比例核减勘查区域面积。但是，已经探明矿产资源或者符合国务院自然资源主管部门规定情形的勘查区域，不计入核减面积计算基数。\n因生态环境保护、基础设施建设等公共利益需要，或者因自然灾害等不可抗力导致已设立探矿权的部分勘查区域无法继续勘查的，可以按照规定凭相关证明文件抵扣需核减的面积。\n第十八条 探矿权人依照矿产资源法第二十五条规定申请将其探矿权转为采矿权的，应当在探矿权期限内向原矿业权出让部门提出申请，并提交矿产资源储量报告（以下简称储量报告）等材料。原矿业权出让部门应当与该探矿权人签订采矿权出让合同，设立采矿权，但有下列情形之一的除外：\n（一）所探明矿产资源按照国家有关规定需由该探矿权人以外的特定主体开采；\n（二）所探明矿产资源未达到有关产业政策规定的储量规模或者产能要求；\n（三）所探明矿产资源因公共利益需要不能转为采矿权，或者因不可抗力等特殊情形已不具备开采条件；\n（四）法律、行政法规规定的其他情形。\n第十九条 矿业权可以依法转让。但是，有下列情形之一的，矿业权不得转让：\n（一）以协议出让方式取得矿业权，持有不满5年；\n（二）矿业权依法被查封；\n（三）矿业权权属不明确或者存在争议；\n（四）矿业权出让合同约定矿业权不得转让；\n（五）国家规定不得转让的其他情形。\n依照本条例第八条第三款规定由省级以上人民政府自然资源主管部门直接授予的采矿权，未经原授予采矿权的自然资源主管部门同意，不得转让。\n因股权转让等导致实际控制人变更的，矿业权人应当向原矿业权出让部门报告。\n第二十条 矿业权转让的，受让人应当具备该矿业权出让时要求的受让人的技术能力等条件。\n第二十一条 矿业权转让的，转让人、受让人应当以书面形式签订矿业权转让合同，明确双方的权利和义务。矿业权转让合同应当对矿区生态修复义务履行有关事项作出明确约定。\n矿业权转让后的期限为该矿业权的剩余期限。\n第二十二条 矿业权设立、变更、转让、抵押和消灭的，应当依法办理登记。\n第二十三条 矿产资源法第二十八条第一项所称国家出资勘查矿产资源，是指由中央财政或者地方财政出资，为保障国家矿产资源安全而开展的矿产资源勘查。国家出资勘查矿产资源的，凭项目任务书开展地质勘查工作，无需取得探矿权。\n采矿权人在登记的开采区域内为开采活动需要进行勘查，以及在登记的开采区域深部、上部进行勘查的，无需取得探矿权。\n第二十四条 建设项目施工单位在批准的作业区域和建设工期内，因施工需要采挖只能用作普通建筑材料的砂、石、黏土，无需取得采矿权。采挖的砂、石、黏土的处置应当遵守所在地省、自治区、直辖市的有关规定，不得自行处置（建设项目施工自用除外）。\n前款所称批准的作业区域，不包括建设项目施工临时用地区域。","level":1},{"name":"第三章 矿产资源勘查、开采","text":"第二十五条 国务院自然资源主管部门会同国务院有关部门建立健全基础性地质调查技术标准和规范体系。\n从事基础性地质调查工作的单位应当严格执行有关技术标准和规范，对调查成果的质量负责。县级以上人民政府自然资源主管部门应当加强对基础性地质调查成果质量的监督。\n任何单位和个人不得阻挠、妨碍依法开展的基础性地质调查工作。\n第二十六条 省级以上人民政府自然资源主管部门应当加强基础性地质调查成果发布管理，按照规定权限统一发布基础性地质调查成果信息；信息发布前应当依法进行保密审查，不得发布涉及国家秘密、工作秘密、商业秘密的成果数据。\n第二十七条 省级以上人民政府自然资源主管部门应当为建设单位提供建设项目占地范围内矿产资源分布和矿业权设置情况查询服务。\n建设项目确需压覆已经设置矿业权的矿产资源，对矿业权人正常勘查、开采活动造成直接影响的，建设单位应当在压覆前与矿业权人协商，并依法给予矿业权人公平、合理的补偿。因矿产资源被压覆依法需要办理矿业权变更登记或者注销登记的，矿业权人应当依法办理。\n建设项目确需压覆战略性矿产资源的，应当经国务院自然资源主管部门或者其授权的省、自治区、直辖市人民政府自然资源主管部门批准。经依法批准的国土空间规划确定的城镇开发边界内的建设项目确需压覆战略性矿产资源的，有关审批应当根据实际情况予以简化。\n经科学评估，建设项目压覆矿产资源但不直接影响正常勘查、开采活动的，可以不作为压覆矿产资源处理。\n第二十八条 矿业权人进行矿产资源勘查、开采作业前，应当分别编制勘查方案、开采方案，报原矿业权出让部门批准，取得勘查许可证、采矿许可证；未取得相应许可证的，不得进行勘查、开采作业。\n编制勘查方案，应当根据勘查矿种和范围、勘查相关标准和技术规范，以及绿色勘查等勘查工作要求，明确勘查区域，合理选择勘查工作方法，并对勘查活动结束后的清理恢复等作出安排。\n编制开采方案，应当根据开采矿种和范围、资源赋存情况、开采技术规范，以及矿产资源合理开发利用、绿色矿山建设等开采工作要求，合理选择开采方式、开采顺序、开采方法，并对空间使用以及资源综合开采、综合利用的保障措施等作出安排。\n综合开采矿产资源的，应当结合储量报告和开采方案，根据开采实际合理确定并登记开采矿种。\n第二十九条 申请勘查许可证、采矿许可证的，应当向原矿业权出让部门提交申请书、矿业权证书，以及相应的勘查方案或者开采方案等材料。原矿业权出让部门应当自受理申请之日起15个工作日内作出是否批准的决定。予以批准的，核发勘查许可证、采矿许可证；不予批准的，书面通知申请人并说明理由。\n原矿业权出让部门受理申请后，可以组织专家对勘查方案、开采方案进行评审，并在10个工作日内出具评审意见。评审所需时间不计算在许可审查期限内，费用不得由矿业权人承担。\n勘查许可证、采矿许可证期限届满日期与探矿权、采矿权期限届满日期一致。\n原矿业权出让部门核发采矿许可证后，应当及时通知开采区域有关地方人民政府组织落实采矿权勘界工作。\n第三十条 矿业权人可以在办理矿业权登记时一并申请办理勘查许可证、采矿许可证。\n矿业权转让的，受让人应当重新申请勘查许可证、采矿许可证。\n第三十一条 勘查许可证、采矿许可证具体管理办法由国务院自然资源主管部门制定。\n第三十二条 矿业权人应当按照经批准的勘查方案、开采方案进行勘查、开采作业。\n勘查的主要工作方法发生变化的，探矿权人应当调整勘查方案，报原矿业权出让部门批准。\n开采方式发生重大变化或者开采的主矿种发生变化的，采矿权人应当调整开采方案，报原矿业权出让部门批准并重新核发采矿许可证。\n第三十三条 矿业权人进行矿产资源勘查、开采作业前，应当依法办理建设项目核准（备案）、用地用海、生态环境、安全生产等方面相关手续；涉及军用土地的，还应当经军队团级以上单位按照中央军事委员会的相关规定报经批准。\n采矿权人编制矿山开发项目可行性研究报告、矿山初步设计（油气田开发方案）等，应当与开采方案相衔接。\n第三十四条 自然保护地范围内可以依法开展符合管控要求的基础性地质调查、战略性矿产资源远景调查和规定范围内的战略性矿产资源勘查、开采等活动，具体管理办法由国务院自然资源主管部门、林业草原主管部门制定。\n第三十五条 矿产资源法第三十四条第一款所称矿业用地，包括矿产资源勘查用地和矿产资源开采用地。\n矿产资源勘查用地包括勘查作业使用的土地，以及为满足勘查作业需要搭建或者修建生活用房、工棚、运输便道等使用的土地。\n矿产资源开采用地包括采掘矿产资源等采矿作业使用的土地，以及为满足采矿作业需要堆放采出的矿石、废石、废渣，修建工业厂房、井巷工程、尾矿库、配套的选矿厂、生活服务设施、交通运输设施等使用的土地。\n县级以上人民政府应当依法保障矿产资源勘查、开采用地的合理需求。\n第三十六条 矿业权人可以依法通过划拨、出让、租赁、作价出资等方式使用国有土地，也可以依法通过出让、出租等方式取得集体经营性建设用地使用权。\n开采矿产资源使用国有土地和集体经营性建设用地，可以通过协议方式出让。\n第三十七条 勘查矿产资源可以依照土地管理法律、行政法规的规定临时使用土地。\n露天开采战略性矿产资源占用土地，经科学论证，具备边开采、边复垦条件的，矿业权人报省级以上人民政府自然资源主管部门批准后，可以临时使用土地；涉及使用林地草地的，有关自然资源主管部门应当征求同级林业草原主管部门意见。临时使用土地应当分区、分期审批，原则上每期不超过五年。矿业权人未按照规定履行土地复垦等矿区生态修复义务的，有关自然资源主管部门不得批准其新的临时用地。\n第三十八条 石油、天然气等矿产资源勘查过程中发现可供开采的石油、天然气等矿产资源的，探矿权人完成试油（气）作业，向原矿业权出让部门提交探采合一计划后，可以进行开采，并按照规定向有关能源主管部门履行备案手续。\n探矿权人依照前款规定开采石油、天然气等矿产资源的，应当在国务院自然资源主管部门规定的期限内，向原矿业权出让部门申请将其探矿权转为采矿权，依法办理采矿权登记，并取得采矿许可证。\n第三十九条 国务院自然资源主管部门会同国务院有关部门完善绿色矿山政策、标准规范，健全绿色矿山名录并实行动态管理。矿业权人应当加强绿色矿山规划、建设、运营和管理，推动矿山企业绿色发展。\n第四十条 国务院自然资源主管部门会同国务院有关部门组织制定矿产资源开采回采率、选矿回收率、综合利用率有关国家标准。\n采矿权人应当从技术、设备、管理等方面采取有效措施，确保矿产资源开采回采率、选矿回收率、综合利用率达到有关国家标准的要求。\n国家制定和完善相关激励性政策措施，促进提高矿产资源开采回采率、选矿回收率、综合利用率。\n第四十一条 县级以上人民政府自然资源主管部门应当会同有关部门加强矿产资源综合开采、综合利用先进适用技术、工艺、设备的推广应用，鼓励、引导采矿权人开展技术、工艺升级和设备更新，推进矿产资源综合利用产业化发展。\n第四十二条 国家建立矿产资源储量管理制度，加强对矿产资源储量及其变动情况的调查、核实、统计、评估等，为编制矿产资源相关规划、促进矿产资源合理开发利用、加强矿产资源保护等提供依据。\n国家定期组织开展矿产资源潜力评价和开发利用现状调查，加强对矿产资源储量和矿业权价值及相关权益的评估管理。\n第四十三条 矿业权人经过勘查工作查明可供开采的矿产资源或者在开采期间发现矿产资源储量发生重大变化的，应当编制储量报告并报送原矿业权出让部门。储量报告应当包括矿产资源的空间分布、种类、数量、质量和矿床工业指标论证等内容，并对矿石加工选冶技术性能、开采技术条件、开发经济意义等情况作出说明。\n原矿业权出让部门应当对矿业权人报送的储量报告进行审核，并可以根据审核工作需要组织有关单位对储量报告进行技术评估。经审核的储量报告可以作为矿产资源储量统计和监督管理等的依据。\n矿业权人应当对其报送的储量报告的真实性负责，不得弄虚作假。\n第四十四条 采矿权人应当按照规定开展矿产资源储量监测，建立健全矿产资源储量台账，定期向原矿业权出让部门报告矿产资源储量变化情况和开发利用情况。\n第四十五条 矿山闭坑的，采矿权人应当按照国家有关规定将闭坑地质报告报送县级以上地方人民政府自然资源主管部门，并汇交有关地质资料。","level":1},{"name":"第四章 矿区生态修复","text":"第四十六条 县级以上地方人民政府自然资源主管部门应当会同有关部门对本行政区域内因开采矿产资源导致的地质环境破坏、土地损毁、植被退化等生态破坏情况进行调查评价，明确矿区生态修复的重点区域、目标任务。\n第四十七条 采矿权人是矿区生态修复的责任人。采矿权人应当协同实施矿区生态修复与污染防治。\n采矿权转让的，除国家另有规定或者矿业权出让、转让合同另有约定外，由受让人履行矿区生态修复义务。转让人在采矿权转让过程中对矿区生态修复事项弄虚作假的，其生态修复义务不因采矿权转让而免除。\n第四十八条 对历史遗留的废弃矿区，由所在地县级以上地方人民政府自然资源主管部门确认矿区生态修复责任人；责任人灭失或者无法确认的，由所在地县级以上地方人民政府组织开展矿区生态修复，并协同开展污染治理。\n国务院自然资源主管部门等有关部门可以制定专项政策，支持地方人民政府对历史遗留的废弃矿区开展生态修复。县级以上地方人民政府依法可以通过多种方式拓宽矿区生态修复资金渠道。\n第四十九条 国家完善政策措施，鼓励社会资本依法参与矿区生态修复，维护参与矿区生态修复的社会资本的合法权益。\n国家充分发挥市场机制在矿区生态修复中的作用，推进矿区生态修复市场化发展。\n第五十条 开采矿产资源前，采矿权人应当依照法律、法规和国务院自然资源主管部门的规定以及矿业权出让合同编制矿区生态修复方案，随开采方案报原矿业权出让部门批准。矿区生态修复方案应当明确生态修复的目标任务、工程布局、技术措施、时序安排、经费概算、保障措施等内容；涉及尾矿库的，还应当明确尾矿库修复的专门措施。\n编制矿区生态修复方案，应当依照矿产资源法第四十六条第二款的规定，在矿区涉及的有关范围内公示征求意见，并专门听取有关单位和个人的意见。采矿权人应当在矿区生态修复方案报批时对公示征求意见和专门听取意见的情况作出说明。\n采矿权人对矿区生态修复方案作出调整的，应当按照国务院自然资源主管部门的规定报原矿业权出让部门备案；依据本条例第三十二条第三款的规定调整开采方案的，应当重新编制矿区生态修复方案并随开采方案报原矿业权出让部门批准。\n已经按照规定编制矿区生态修复方案的，不再编制土地复垦方案。\n第五十一条 矿区生态修复能够边开采、边修复或者分区、分期修复的，采矿权人应当根据矿山开采设计和工艺流程、开采进度、采矿用地范围和类型、安全生产条件以及土地损毁和生态破坏等情况，合理划分修复单元、安排修复时序，及时开展生态修复；不能边开采、边修复或者分区、分期修复的，应当在矿山闭坑前或者闭坑后的2年内完成生态修复，但开采放射性矿产资源的矿区生态修复时限可以根据实际需要确定。\n第五十二条 采矿权人按照矿区生态修复方案完成生态修复后，应当及时向矿区所在地县级以上地方人民政府自然资源主管部门申请验收；分区、分期完成生态修复的，应当分区、分期申请验收。\n县级以上地方人民政府自然资源主管部门会同生态环境主管部门等有关部门组织矿区生态修复验收。验收合格的，应当向采矿权人出具验收合格确认书；验收不合格的，应当向采矿权人出具书面整改意见，由采矿权人整改完成后重新申请验收。\n第五十三条 矿区生态修复费用由采矿权人按年度提取，除法律另有规定外，矿区生态修复费用不得被查封、冻结或者划拨。","level":1},{"name":"第五章 矿产资源储备和应急","text":"第五十四条 国家按照政府主导、社会共建、多元互补、高效协同的原则，构建产品储备、产能储备和产地储备相结合的战略性矿产资源储备体系，科学合理确定储备结构、规模和布局并动态调整，发挥储备的战略保障、宏观调控和应对急需等功能。\n国家完善战略性矿产资源储备监管体系，加快储备设施建设，提高储备运营主体专业化水平，加强储备信息化建设，持续提升战略性矿产资源储备综合效能。县级以上人民政府应当根据需要，将战略性矿产资源储备纳入国民经济和社会发展相关规划、国土空间规划，并在安排重大项目建设方面给予支持。\n第五十五条 国务院发展改革部门统筹协调国家矿产品储备工作，定期拟订储备规划和总量计划，动态调整储备品种规模；国务院粮食和物资储备部门组织实施中央政府矿产品储备的收储、轮换和日常管理；国务院能源主管部门按照职责负责能源储备相关工作。县级以上地方人民政府按照国家有关规定，结合本地实际开展矿产品储备。\n有关企业应当按照国家有关规定做好矿产品储备工作。国家完善政策措施，支持企业开展矿产品储备。\n战略性矿产资源产品储备管理部门、承储单位应当加强战略性矿产品资产管理，并按照规定报送矿产品储备管理情况。\n第五十六条 能源战略性矿产资源产能储备的具体办法，由国务院能源主管部门会同国务院有关部门制定；其他战略性矿产资源产能储备的具体办法由国务院工业和信息化主管部门会同国务院有关部门制定。\n开采战略性矿产资源的采矿权人应当按照国家有关规定，结合矿山生产能力、外部运输条件、安全生产状况等情况，编制产能储备建设方案，落实产能储备责任，合理规划生产能力，确保应急增产需要。\n第五十七条 战略性矿产资源产地储备应当遵循科学评估、合理布局、分级管理、动态调整的原则，结合国家矿产资源开发利用和安全保障等相关规划，统筹资源禀赋、开发利用技术条件、国内外供需状况、生态区位等因素，合理确定储备规模、布局等，并对储备地开展必要的补充勘查，提升应急开采能力，与产品储备、产能储备有机衔接，形成梯次供应能力。\n国务院自然资源主管部门牵头组织全国战略性矿产资源产地储备工作，研究提出产地储备矿种、规模、布局意见，组织开展产地储备摸底调查、评估论证和储备勘查，划定战略性矿产资源储备地，加强产地储备监测和保护监督。省、自治区、直辖市人民政府自然资源主管部门协助开展产地储备相关工作，按照属地管理职责组织开展保护监督工作。鼓励企业积极参与产地储备工作。\n战略性矿产资源产地储备期限应当与矿产资源相关规划相衔接，原则上不少于5年。储备期限届满后，国务院自然资源主管部门应当会同国务院有关部门组织评估论证，确定是否延长储备期限，根据需要适时开展产地储备调整、动用。\n纳入产地储备的战略性矿产资源，未经国务院自然资源主管部门批准，不得开采或者压覆。\n第五十八条 国务院发展改革、工业和信息化、自然资源、粮食和物资储备、矿山安全监察等有关部门应当建立健全矿产资源供应安全预测预警工作体系，加强矿产资源供应安全相关数据信息共享和应用，对矿产品供求变化、价格波动以及安全风险状况等开展综合监测、分析、评估，及时进行预测预警。\n第五十九条 矿产资源法第五十五条第一款第六项所称其他必要措施，包括但不限于直接组织矿产资源开采、加工、运输、供应，征用相关矿产品、矿产品储备设施、交通运输工具，按照供应保障顺序组织实施矿产资源或者矿产品供应。","level":1},{"name":"第六章 监督管理","text":"第六十条 县级以上人民政府自然资源主管部门和其他有关部门应当按照职责分工，加强对矿产资源勘查、开采和矿区生态修复等活动的监督检查，依法及时查处违法行为。\n县级以上人民政府自然资源主管部门和其他有关部门在监督检查中应当加强协调配合，能够联合检查的实行联合检查，鼓励通过非现场检查、使用非接触式技术手段开展监督检查。\n第六十一条 自然资源主管部门和其他有关部门及其工作人员对监督管理过程中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息依法负有保密义务。\n前款所称商业秘密，包括但不限于矿产资源储量和矿业权人的勘查成果、重大发现、核心技术方案。商业秘密不得向第三方泄露，法律另有规定或者矿业权人书面同意的除外。\n第六十二条 国务院自然资源主管部门按照科学合理、体现差异、简便易行的原则，建立矿产资源开发利用水平评估指标体系，并加强对评估指标运用的指导。\n县级以上人民政府自然资源主管部门应当根据矿产资源开发利用水平评估指标，加强对本行政区域内矿产资源勘查、开采情况的汇总、分析并定期进行评估，提出节约集约开发利用矿产资源等方面的改进措施。采矿权人和有关矿山企业应当配合自然资源主管部门的评估工作，落实相关改进措施。\n第六十三条 国务院自然资源主管部门推动提升矿产资源监督管理信息化水平，通过全国矿产资源监督管理信息系统开展监管和服务，并与国务院有关部门加强信息共享。\n第六十四条 国务院自然资源主管部门根据从事矿产资源勘查单位的规模、技术能力、人才装备、信用状况等，对其实行备案和分级分类监管，引导矿产资源勘查市场规模化发展，提升专业化水平。\n第六十五条 矿业权人之间对勘查、开采区域发生争议时，由当事人协商解决。当事人协商不成的，由矿产资源所在地县级以上地方人民政府根据依法核定的勘查、开采区域处理；跨行政区域的勘查、开采区域争议，由共同的上一级人民政府处理。\n第六十六条 国家自然资源督察机构根据国务院的授权，对省、自治区、直辖市人民政府矿产资源开发利用和监督管理情况进行督察。\n国家自然资源督察机构进行督察时，有权向与督察事项有关的单位和个人了解督察事项有关情况，有关单位和个人应当支持、协助督察机构工作。","level":1},{"name":"第七章 法律责任","text":"第六十七条 阻挠、妨碍依法开展的基础性地质调查工作的，由县级以上人民政府自然资源主管部门责令改正，给予警告或者通报批评；拒不改正的，对单位处2万元以上10万元以下的罚款，对个人处1万元以上5万元以下的罚款。\n第六十八条 矿业权人未定期报送矿产资源储量变化情况和开发利用情况，或者在矿山闭坑后未报送闭坑地质报告的，由县级以上人民政府自然资源主管部门责令改正，处2万元以上10万元以下的罚款；情节严重的，处10万元以上50万元以下的罚款。\n第六十九条 矿产资源法第六十三条、第六十四条、第六十六条、第六十七条、第六十八条规定的违法行为所涉矿产资源属于战略性矿产资源的，应当从重处罚。\n第七十条 矿业权人未按照规定缴纳矿业权占用费的，征收机关可以责令限期缴纳，逾期不缴纳的，可以处应缴矿业权占用费3倍以下的罚款。\n第七十一条 建设项目施工单位自行处置因施工需要采挖的砂、石、黏土的，由县级以上人民政府自然资源主管部门责令改正，处自行处置的矿产品市场价值3倍以上5倍以下的罚款；自行处置的矿产品市场价值不足10万元的，处10万元以上30万元以下的罚款。\n第七十二条 未经批准开采纳入产地储备的战略性矿产资源的，依照矿产资源法第六十四条的规定从重处罚。\n第七十三条 违反本条例规定，造成他人人身财产损害或者生态环境损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附 则","text":"第七十四条 外商投资勘查、开采矿产资源，应当符合外商投资准入负面清单的规定。\n外商投资勘查、开采矿产资源，影响或者可能影响国家安全的，依照国家有关规定进行安全审查。\n第七十五条 矿产资源及相关货物、技术、服务的进出口，应当遵守有关对外贸易、进出口管理法律、行政法规的规定；属于出口管制物项的，还应当遵守出口管制法律、行政法规的规定。\n第七十六条 任何国家、地区和国际组织采取或者协助、支持采取歧视性的禁止、限制或者其他类似措施，危害中华人民共和国矿产资源及相关产业链供应链安全的，国务院有关部门可以根据实际情况采取必要的反制措施。\n第七十七条 国家对铀（钍）矿等放射性矿产资源的勘查、开采和保护等另有规定的，依照其规定。\n第七十八条 2025年7月1日前依法核发的勘查许可证、采矿许可证，在有效期内继续有效。\n第七十九条 本条例自2026年6月15日起施行。《矿产资源监督管理暂行办法》、《矿产资源补偿费征收管理规定》、《中华人民共和国矿产资源法实施细则》、《矿产资源勘查区块登记管理办法》、《矿产资源开采登记管理办法》、《探矿权采矿权转让管理办法》同时废止。","level":1}]},{"id":"n1279","sections":[{"name":"","text":"国务院关于产业链供应链安全的规定\n第一条 为了防范产业链供应链安全风险，提升产业链供应链韧性和安全水平，维护经济社会稳定和国家安全，根据《中华人民共和国国家安全法》、《中华人民共和国对外关系法》、《中华人民共和国反外国制裁法》、《中华人民共和国对外贸易法》等法律，制定本规定。\n第二条 产业链供应链安全工作贯彻总体国家安全观，统筹发展和安全，统筹国内国际，推进高水平对外开放，促进全球产业链供应链稳定畅通。\n第三条 国家建立健全产业链供应链安全工作机制，统筹协调产业链供应链安全工作。\n国务院外交、发展改革、工业和信息化、公安、国家安全、法治、财政、自然资源、交通运输、农业农村、商务、金融管理、海关、市场监督管理、网信等部门按照职责分工，负责承担产业链供应链安全工作。国务院有关部门加强产业链供应链安全工作协同配合。\n省、自治区、直辖市人民政府在国家统筹协调下，负责与本行政区域有关的产业链供应链安全工作。\n第四条 国家引导产业链供应链合理有序布局，推进产业链供应链数字化、智能化，提升产业链供应链安全可控水平，促进产业链供应链高质量发展。\n鼓励支持企业开拓多元化供应渠道，开展产业链供应链合作，公平参与市场竞争，提升防范产业链供应链安全风险水平。\n第五条 国家坚持平等互利、合作共赢原则，加强产业链供应链领域国际合作，积极参与产业链供应链有关国际规则制定。\n第六条 国务院有关部门和省、自治区、直辖市人民政府在有关规划制定过程中，应当充分考虑可能对产业链供应链安全产生的影响。\n第七条 国家加强关键领域产业链供应链安全保障。国务院有关部门制定关键领域清单并实行动态调整，维护关键领域的原材料、技术、设备、产品等的生产与流通稳定、持续运行。\n第八条 国务院有关部门推动关键领域产业链供应链信息共享，强化信息平台支撑，引导行业、企业间加强关键领域产业链供应链信息互联互通，并采取有效措施保障数据安全。\n第九条 国家建立健全关键领域产业链供应链安全风险监测预警制度。国务院有关部门对关键领域的原材料、技术、设备、产品等供给渠道稳定情况及其对经济社会稳定和国家安全的影响等，组织开展评估监测，识别产业链供应链安全风险，及时发布预警信息。\n企业、行业协会商会等发现影响产业链供应链安全情形的，可以向县级以上人民政府有关部门报告。\n第十条 国家建立健全关键领域产业链供应链安全风险防范制度。国务院有关部门组织开展关键领域实物储备和能力储备，加大技术、设备、产品研发力度，提升关键领域产业链供应链抗风险能力。\n国务院有关部门和地方人民政府应当结合本行业、本地区特点，有针对性地采取产业链供应链安全风险防范措施。\n第十一条 国家建立健全关键领域产业链供应链安全应急管理制度，国务院有关部门制定应急工作预案。出现影响关键领域产业链供应链安全情形，危及经济社会稳定和国家安全的，经国务院或者国务院授权的部门决定，可以采取紧急调度、动用储备以及组织生产、运输、供应等应急处置措施。法律、行政法规另有规定的，依照其规定。\n国务院有关部门和地方人民政府应当按照职责权限实施应急处置措施，并在有关情形消除后及时终止实施。有关组织、个人应当配合应急处置措施的实施。\n第十二条 鼓励、引导社会资金投入，支持关键领域科学技术研发、核心技术攻关，促进科技成果转化。\n企业、科研机构等应当完善风险防控体系，实现核心技术及相关信息系统、数据的安全可控。有关部门应当加强指导和培训。\n第十三条 任何组织、个人违反我国法律、行政法规、部门规章和国家有关规定，在我国境内开展与产业链供应链相关的调查等信息收集活动的，有关部门依法采取相应处理措施。\n第十四条 外国国家、地区和国际组织违反国际法和国际关系基本准则，在产业链供应链方面对我国采取歧视性禁止、限制或者其他类似措施，实施或者协助实施损害我国产业链供应链安全行为的，国务院有关部门有权对有关措施或者行为开展产业链供应链安全调查。\n国务院有关部门按程序可以采取相应措施，包括但不限于禁止或者限制有关货物、技术进出口或者国际服务贸易，收取特别费用等。\n国务院有关部门可以依照《中华人民共和国反外国制裁法》、《实施〈中华人民共和国反外国制裁法〉的规定》等，决定将直接或者间接参与制定、决定、实施本条第一款规定的措施或者行为的组织、个人列入反制清单，采取反制措施。\n第十五条 外国组织、个人违反正常的市场交易原则，中断与我国公民、组织的正常交易，对我国公民、组织采取歧视性措施或者实施其他行为，对我国产业链供应链安全造成实质损害或者产生实质损害威胁的，国务院有关部门有权开展产业链供应链安全调查。\n调查可以采取询问有关当事人，查阅或者复制相关文件、资料以及其他必要的方式，有关当事人应当配合调查。调查期间，当事人可以陈述、申辩。\n根据调查结果，国务院有关部门可以对外国组织、个人采取禁止或者限制其从事与我国有关的进出口活动，禁止或者限制其在我国境内投资，禁止或者限制我国境内的组织、个人与其进行有关交易、合作等活动，禁止或者限制相关人员、交通运输工具等入境，取消或者限制相关人员在我国境内工作、停留或者居留资格等措施。有关措施可以适用于外国组织、个人实际控制或者参与设立、运营的组织。\n第十六条 我国境内的组织、个人应当执行国务院有关部门依照第十四条、第十五条规定采取的措施。\n对违反前款规定的组织、个人，国务院有关部门有权责令改正，禁止或者限制其从事政府采购、招标投标以及有关的货物、技术进出口或者国际服务贸易等活动，禁止或者限制其从境外接收或者向境外提供数据、个人信息，禁止或者限制其出境、在我国境内停留居留等。\n第十七条 鼓励、支持律师事务所、公证机构等专业服务机构为我国公民、组织提供与产业链供应链安全有关的法律服务。\n第十八条 本规定自公布之日起施行。","level":0}]},{"id":"n1280","sections":[{"name":"","text":"退役军人就业创业促进条例","level":0},{"name":"第一章 总 则","text":"第一条 为了促进退役军人就业创业，发挥退役军人人力资源作用，维护退役军人合法权益，让军人成为全社会尊崇的职业，根据《中华人民共和国退役军人保障法》、《中华人民共和国就业促进法》等有关法律，制定本条例。\n第二条 退役军人就业创业工作坚持中国共产党的领导，坚持普惠与优待叠加的原则，采取政府推动、市场引导、社会支持相结合的方式，鼓励和扶持退役军人就业创业。\n第三条 引导退役军人树立正确的择业观念，通过教育培训、就业支持、创业扶持等措施，促进退役军人高质量充分就业。\n第四条 国家将退役军人就业创业工作纳入有关规划。\n各级人民政府应当加强对退役军人就业创业的指导和服务，推动机关、群团组织、企业事业单位等各负其责、密切配合，形成支持退役军人就业创业的合力。\n第五条 国务院退役军人工作主管部门、人力资源社会保障部门以及中央和国家机关其他有关部门按照职责分工做好退役军人就业创业工作。\n县级以上地方人民政府退役军人工作主管部门应当加强对退役军人就业创业的宣传、组织、协调等工作。地方各级有关机关应当在各自职责范围内做好退役军人就业创业工作。\n第六条 尊重、关爱退役军人是全社会的共同责任。国家鼓励和引导企业、社会组织、个人等社会力量依法为退役军人就业创业提供支持和帮助。\n第七条 退役军人在就业创业活动中应当模范遵守宪法和法律法规，保守军事秘密，践行社会主义核心价值观，积极参加社会主义现代化建设。\n第八条 国家依法对退役军人就业创业给予经费支持，标准应当与经济社会发展水平和财力状况相适应。","level":1},{"name":"第二章 教育培训","text":"第九条 国家采取措施加强对退役军人的教育培训，帮助退役军人完善知识结构，提高思想政治水平、职业技能水平和综合职业素养，提升就业创业能力。\n第十条 国家鼓励退役军人接受学历教育，提升学历层次，增强就业创业发展潜力。\n国家鼓励退役军人接受职业学校教育，提升技术技能，增强职业综合素质和行动能力。\n第十一条 军人入伍前已被普通高等学校录取或者是正在普通高等学校就学的学生，服现役期间保留入学资格或者学籍，退役后2年内允许入学或者复学，可以按照国家有关规定转入本校其他专业学习。\n第十二条 退役军人参加国家教育考试的，按照国家有关规定享受优待政策。\n退役军人在接受学历教育时，按照国家有关规定享受学费和助学金资助等国家教育资助政策。\n县级以上地方人民政府兵役机关、退役军人工作主管部门按照职责分工负责对退役军人考生和复学学生的政策宣传、身份审核工作，教育行政部门负责资助资格审核工作。\n鼓励各地出台政策支持退役军人参加高等教育自学考试和各类高等学校举办的高等学历继续教育。\n第十三条 鼓励普通高等学校、职业院校（含技工院校）等针对退役军人特点，优化人才培养方案。\n第十四条 退役军人培训工作应当以提高就业质量为导向，紧密围绕社会需求，适应科技创新和产业发展趋势，为退役军人提供有特色、精细化、针对性强的培训服务。\n第十五条 县级以上地方人民政府退役军人工作主管部门根据驻地部队需要，协助开展职业技能储备培训和离队前教育。\n第十六条 军人退出现役后，退役军人工作主管部门和其他负责退役军人安置工作的部门应当区分不同安置方式的退役军人，组织适应性培训。培训应当使用适合退役军人特点的教材，培训时长不得少于国家规定的时长。\n第十七条 符合条件的退役军人参加职业技能培训的，按照规定享受职业技能培训补贴等相应扶持政策。\n安置地人民政府退役军人工作主管部门应当根据未达到法定退休年龄的自主就业退役军士和义务兵的就业需求，组织其免费参加职业技能培训，或者在其参加职业技能培训后在安置地标准内给予培训补贴。\n第十八条 自主就业的退役军士和义务兵原则上在安置地参加职业技能培训。经安置地人民政府退役军人工作主管部门批准，在安置地以外地区参加职业技能培训的，培训结束并经安置地人民政府退役军人工作主管部门审核同意后，在安置地标准内给予培训补贴。\n第十九条 省级人民政府退役军人工作主管部门负责统筹本行政区域内退役军人职业技能培训工作，明确总体计划、管理机制、发展方向等，可以根据实际情况会同有关部门制定公布职业技能培训项目参考目录，结合实际组织实施示范培训。\n设区的市级人民政府退役军人工作主管部门及其授权的县级人民政府退役军人工作主管部门负责本行政区域内退役军人职业技能培训的具体组织实施，结合本地区产业发展和急需紧缺职业需要，综合考虑自主就业的退役军士和义务兵就业需求，会同有关部门制定公布职业技能培训项目参考目录。\n组织实施职业技能培训的地方人民政府退役军人工作主管部门按照规定从普通高等学校、职业院校（含技工院校）、专业培训机构中确定承训机构，签订承训合同，公告承训机构信息，并动态更新。涉及政府采购的，应当严格执行政府采购有关规定。\n第二十条 承训机构应当建立健全教学管理制度、学员管理制度、安全管理制度，组织学员参加职业能力评价，推荐就业岗位。\n鼓励承训机构共享优质培训资源。\n第二十一条 省级人民政府退役军人工作主管部门会同有关部门对承训机构加强动态管理，建立以学员满意度、职业技能评价、培训后就业情况等为主要指标的培训质量评价标准，定期对培训质量进行检查，提高职业技能培训质量和水平。\n第二十二条 鼓励公共实训基地主动承接退役军人职业技能培训项目，面向退役军人就业需求和市场需求设置有针对性的培训课程。\n第二十三条 国家推行终身职业技能培训制度，将退役军人职业技能培训纳入终身职业技能培训政策和组织实施体系。\n国务院退役军人工作主管部门完善网络课程体系，为退役军人提供便捷化网络学习服务。\n鼓励用人单位定期组织招用的退役军人参加岗位技能提升和知识更新培训。\n第二十四条 发挥普通高等学校、职业院校（含技工院校）等教学资源优势，加强校内培训服务，支持退役军人学生在获得学历证书的同时，经考试考核合格取得相应的职业资格证书或者职业技能等级证书。\n第二十五条 退役军人服现役期间取得的技能人员职业资格证书，作为其退出现役后从事相应职业（工种）的合法凭证，在全国范围内通用。","level":1},{"name":"第三章 就业支持","text":"第二十六条 国家支持退役军人多渠道就业，引导退役军人发挥自身优势投身社会主义现代化建设。\n第二十七条 自主就业的退役军士和义务兵入伍前是机关、群团组织、事业单位或者国有企业人员的，退出现役后可以选择复职复工，其工资、福利待遇不得低于本单位同等条件人员的平均水平。\n第二十八条 机关、群团组织、事业单位和国有企业在招录或者招聘人员时，对退役军人的年龄和学历条件可以适当放宽，同等条件下优先招录、招聘退役军人。国有企业招聘人员时，可以根据需要设置一定比例的岗位招聘退役军人。\n鼓励和引导前款规定以外的其他用人单位在招用人员时，同等条件下优先招用退役军人。\n用人单位招用退役军人符合国家规定的，依法享受税收优惠等政策。\n第二十九条 各地应当设置一定数量的基层公务员职位，面向服现役满5年的高校毕业生退役军人招考。\n服现役满5年的高校毕业生退役军人可以报考面向服务基层项目人员定向考录的职位，同服务基层项目人员共享公务员定向考录计划。\n各级有关机关在组织开展选调生工作时，应当注重选调有服役经历的符合条件的优秀大学生。\n第三十条 艰苦边远地区县乡事业单位可以按照有关规定对退役军人进行专项招聘，并增加工作实绩在组织考察中的权重。\n促进符合条件的优秀退役军人到中小学任教。各地在制定中小学教师招聘计划时，可以面向退役军人单列计划。\n各地应当注重从优秀退役军人中选聘党的基层组织、社区和村专职工作人员。\n各级退役军人工作主管部门直属事业单位、乡镇（街道）退役军人服务站应当优先招聘符合条件的退役军人。\n第三十一条 国家综合性消防救援队伍招录消防员时，应当设置一定比例的计划专项招录退役军士和义务兵。\n招聘警务辅助人员时，同等条件下应当优先招聘退役军人。\n军队文职人员岗位、国防教育机构岗位等应当优先选用符合条件的退役军人。\n第三十二条 退役军官在军队团和相当于团以下单位工作的经历，退役军士和义务兵服现役的经历，视为基层工作经历。\n退役军人服现役年限计算为工龄，退役后与所在单位工作年限累计计算，享受国家和所在单位规定的与工龄有关的相应待遇。\n第三十三条 县级以上地方人民政府退役军人工作主管部门应当会同有关部门开展退役军人就业推荐、职业指导，定期组织退役军人招聘活动，开展形式多样的岗位推介，为退役军人就业搭建平台。\n公共人力资源服务机构应当免费为退役军人提供职业介绍、职业指导等服务。\n第三十四条 地方各级人民政府应当将符合就业困难人员认定条件的退役军人纳入就业援助范围，优先提供帮扶。","level":1},{"name":"第四章 创业扶持","text":"第三十五条 鼓励和支持有条件、有意愿的退役军人创业，带动更多就业。\n第三十六条 退役军人从事个体经营，依法享受税收优惠等政策。\n第三十七条 退役军人创业，可以按照国家有关规定申请创业担保贷款，并享受贷款贴息等融资优惠政策。\n金融机构应当按照市场化原则，依法依规提供符合退役军人创业需求的金融产品和服务，扩大退役军人信贷服务覆盖面。\n鼓励社会资本设立退役军人创业基金，拓宽退役军人融资渠道。\n第三十八条 县级以上地方人民政府投资建设或者与社会共建的创业基地（园区）等可以通过开辟专区等形式，优先为退役军人创业提供服务。\n有条件的地区可以建立退役军人创业载体，为退役军人创业提供经营场地、投资融资、项目对接等方面的优先、优惠服务。\n第三十九条 县级以上地方人民政府应当支持引导有创业意愿和培训需求的退役军人参加创业培训。\n鼓励县级以上地方人民政府退役军人工作主管部门建立退役军人创业服务团队，发挥创业指导、吸纳退役军人就业、企业互助发展等方面作用。\n第四十条 国务院部门、县级以上地方人民政府及其部门设立的政务服务机构、公共服务机构等应当设置退役军人窗口或者绿色通道，为退役军人创业提供登记注册、税费办理、补贴申领等服务。\n第四十一条 鼓励退役军人围绕新技术、新产业、新业态以及国家重点扶持领域创业创新。支持退役军人创办的符合条件的中小企业参与科技型中小企业评价。\n县级以上人民政府退役军人工作主管部门应当采取多种举措促进退役军人创业创新赛事活动优秀项目成果转化。\n第四十二条 县级以上人民政府退役军人工作主管部门应当引导退役军人用好各项创业扶持优惠政策。","level":1},{"name":"第五章 法律责任","text":"第四十三条 退役军人工作主管部门及其工作人员有下列行为之一的，由其上级主管部门责令改正；对负有责任的领导人员和直接责任人员依法给予处分：\n（一）在退役军人就业创业工作中出具虚假文件的；\n（二）挪用、截留、私分退役军人就业创业工作等经费的；\n（三）在退役军人就业创业工作中利用职务之便为自己或者他人谋取私利的；\n（四）在退役军人就业创业工作中失职渎职的；\n（五）有其他违反法律法规行为的。\n第四十四条 其他负责退役军人就业创业有关工作的部门及其工作人员违反本条例规定的，由其上级主管部门责令改正；对负有责任的领导人员和直接责任人员依法给予处分。\n第四十五条 退役军人弄虚作假骗取相关待遇的，由有关主管部门取消待遇，追缴非法所得，并由其所在单位或者有关部门依法给予处分。\n第四十六条 违反本条例规定，构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附 则","text":"第四十七条 中国人民武装警察部队依法退出现役的警官、警士和义务兵等人员，适用本条例。\n第四十八条 本条例自2026年8月1日起施行。","level":1}]},{"id":"n1281","sections":[{"name":"","text":"国务院关于出境入境管理的规定\n第一条 为了规范出境入境管理，保障出境入境人员的合法权益，维护国家主权、安全、发展利益，根据《中华人民共和国出境入境管理法》等法律，制定本规定。\n第二条 国家建立和完善中国公民出境安全风险防范制度。\n国务院外交、文化和旅游主管部门以及驻外外交机构应当根据有关国家和地区战争或者武装冲突、社会治安、自然灾害、事故灾难、传染病疫情等安全形势，及时公开发布国外安全提醒和旅游目的地安全风险提示。\n中国公民应当关注国外安全提醒和旅游目的地安全风险提示，避免前往及驻留高风险国家或者地区。\n移民管理机构在受理、审批中国公民出境入境证件申请和实施出境边防检查时，应当根据国务院有关主管部门的通知，提醒准备前往高风险国家或者地区的中国公民谨慎前往或者密切关注当地安全形势，提高警惕、加强防范、注意安全。其中，对准备前往风险等级为最高级别或者严重危及人身安全案件突发高发的国家或者地区的中国公民，必要时应当劝阻其前往。\n第三条 出境入境人员申请出境入境、停留居留的事由应当真实、合法。\n移民管理机构、签证机关在核实出境入境人员的身份、申请事由时，可以询问相关情况，要求其出示、提供有关文件、资料、电子数据等信息，出境入境人员应当予以配合。\n单位或者个人为出境入境人员出具邀请函件或者其他申请材料的，应当对邀请内容和证明事项的真实性负责，并配合移民管理机构、签证机关核实有关信息。\n出境入境人员提供虚假材料、作出虚假陈述的，移民管理机构、签证机关有权决定不予签发出境入境证件或者不准其出境、入境。\n第四条 中国公民因骗取出境入境证件、非法出境入境受到行政拘留处罚的，移民管理机构可以根据违法情形和预防违法犯罪的需要，决定自处罚执行完毕之日起6个月至3年以内不准其出境。\n中国公民在境外从事违法犯罪活动，危害国家安全和利益的，可以由国务院有关主管部门，或者经驻外外交机构等核实后由其境内住所地省级人民政府决定自回国之日起6个月至3年以内不准其出境。\n中国公民违反出口管制、技术进出口管理等规定，可能危害国家产业安全、技术安全的，国务院商务等有关主管部门可以决定不准其出境。\n第五条 外国人在境外申请办理中国签证或者在口岸申请入境时提供虚假材料、作出虚假陈述的，移民管理机构、签证机关可以决定1年至5年以内不准其入境。\n外国人因妨害国（边）境管理受到刑事处罚，或者因骗取出境入境证件、非法出境入境受到行政处罚的，移民管理机构可以根据违法情形和预防违法犯罪的需要，决定自处罚执行完毕之日起1年至5年以内不准其入境。法律另有规定的，从其规定。\n外国人被列入反制清单、不可靠实体清单、恶意实体清单或者被采取反制和限制措施等，需要依法采取不予签发出境入境证件或者不准入境等相关措施的，由移民管理机构、签证机关按照职责实施。\n第六条 对依法决定不准出境的人员，决定机关应当按照规定及时通知移民管理机构执行，并向当事人书面告知不准出境的事实、理由、依据和救济途径；有可能影响国家安全、刑事案件侦查等情形的，可以不告知当事人。\n移民管理机构执行不准出境决定时，应当按照决定机关通知的内容告知当事人。\n第七条 国家对接受出境入境人员委托从事出境入境政策咨询、证件代办、手续办理等中介服务的机构和人员实行备案管理。\n从事出境入境中介服务的机构，应当自设立之日起15日内向所在地移民管理机构备案。从事出境入境中介服务的人员，应当由所在机构办理备案手续。本规定施行前已经从事出境入境中介服务的，应当在本规定施行之日起90日内办理备案手续。\n从事出境入境中介服务的机构和人员备案管理的具体办法，由国家移民管理部门会同国务院市场监督管理等主管部门制定。\n第八条 从事出境入境中介服务的机构，应当具备下列条件：\n（一）依法设立；\n（二）法定代表人或者负责人没有因故意犯罪受过刑事处罚；\n（三）有具备出境入境有关法律法规政策等专业知识的工作人员和与所从事中介服务活动相适应的资金、场所；\n（四）直接为出境入境人员提供中介服务的工作人员没有因危害国家安全、公共安全或者妨害国（边）境管理的故意犯罪受过刑事处罚；\n（五）有健全的管理制度，包括人员管理、教育培训、资料保存、数据安全、合规管理等。\n从事出境中介服务的，还应当已经与境外有关服务机构建立合作关系或者签署有效的合作意向书。\n境外企业、机构不得在中国境内提供出境入境中介服务。\n第九条 移民管理机构应当会同同级外事、教育、司法行政、人力资源社会保障、商务、文化和旅游、市场监督管理等有关主管部门建立和完善监管制度，按照职责分工加强对从事出境入境中介服务的机构符合条件情况、经营活动等的监督管理，依法公布相关违法信息和不良记录。\n有关主管部门及其工作人员对履行职责过程中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息，应当依法予以保密。\n第十条 从事出境入境中介服务的机构不得有下列行为：\n（一）发布虚假信息，或者通过夸大宣传、误导性宣传等方式招徕服务对象；\n（二）提供或者协助提供虚假材料，协助他人违规办理签证、停留居留证件、护照等出境入境证件或者手续；\n（三）泄露、出售、非法提供在中介服务活动中知悉的商业秘密、个人隐私或者个人信息；\n（四）超出备案范围从事出境入境中介服务；\n（五）组织或者协助他人从事跨境违法犯罪活动；\n（六）危害国家安全、利益或者扰乱出境入境管理秩序的其他行为。\n公职人员、军队人员等委托从事出境入境中介服务的机构违规办理外国国籍、境外永久居留资格、境外居留证件或者其他出境入境证件、手续的，从事出境入境中介服务的机构不得办理，并及时向监察机关等报告。\n第十一条 通过提供虚假材料、作出虚假陈述等方式弄虚作假骗取签证、停留居留证件、护照等出境入境证件的，由移民管理机构依照《中华人民共和国出境入境管理法》、《中华人民共和国护照法》的规定予以处罚。\n个人为他人申请出境入境、停留居留出具虚假邀请函件或者其他申请材料的，由移民管理机构处5000元以上1万元以下罚款；有违法所得的，没收违法所得。单位有前述行为的，处1万元以上5万元以下罚款；有违法所得的，没收违法所得；对直接负责的主管人员和其他直接责任人员处5000元以上1万元以下罚款。法律另有规定的，从其规定。\n第十二条 从事出境入境中介服务的机构违反本规定第七条、第八条规定的，由移民管理机构责令限期改正；拒不改正的，处5000元以上1万元以下罚款，并通报有关主管部门责令暂停相关业务或者停业整顿；情节严重的，处1万元以上5万元以下罚款，并通报有关主管部门吊销相关业务许可证或者吊销营业执照。\n个人违反本规定从事出境入境中介服务的，由移民管理机构责令停止违法行为；有违法所得的，没收违法所得；情节严重的，可以并处5000元以下罚款。\n第十三条 从事出境入境中介服务的机构违反本规定第十条规定，扰乱出境入境管理秩序的，由移民管理机构责令限期改正；有违法所得的，没收违法所得；违法所得2万元以上的，并处违法所得1倍以上5倍以下罚款；没有违法所得或者违法所得不足2万元的，并处2万元以上5万元以下罚款；拒不改正或者情节严重的，通报有关主管部门责令暂停相关业务、停业整顿、吊销相关业务许可证或者吊销营业执照；对直接负责的主管人员和其他直接责任人员处1万元以上5万元以下罚款。法律另有规定的，从其规定。\n第十四条 县级以上地方人民政府公安机关出入境管理机构依照本规定处超过5000元罚款、没收违法所得的行政处罚，由其所属的公安机关决定。\n第十五条 国务院有关主管部门应当加强在出境入境人员合法权益保障、中国公民出境安全风险防范、出境入境中介服务管理等方面的工作协同。\n第十六条 移民管理机构应当畅通对违反出境入境管理行为的举报渠道，依法及时处理有关举报。对不属于本单位职责的举报，应当及时移送有关单位依法处理。\n第十七条 违反本规定，构成犯罪的，依法追究刑事责任。\n第十八条 本规定所称移民管理机构，是指国家移民管理部门和出入境边防检查机关、县级以上地方人民政府公安机关出入境管理机构。\n本规定所称签证机关，是指驻外签证机关和口岸签证机关。\n第十九条 本规定自2026年9月15日起施行。","level":0}]},{"id":"n1282","sections":[{"name":"","text":"集成电路布图设计保护条例\n（2001年4月2日中华人民共和国国务院令第300号公布 2026年7月23日中华人民共和国国务院令第842号修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了保护集成电路布图设计专有权，鼓励集成电路技术创新，促进科学技术发展，制定本条例。\n第二条 集成电路布图设计保护工作应当贯彻党和国家知识产权战略部署，提升我国集成电路布图设计创造、运用、保护、管理和服务水平。\n第三条 本条例下列用语的含义：\n（一）集成电路，是指以半导体材料为基片，将至少有一个是有源元件的两个以上元件和部分或者全部互连线路集成在基片之中或者基片之上，以执行某种电子功能的中间产品或者最终产品；\n（二）集成电路布图设计（以下简称布图设计），是指集成电路中至少有一个是有源元件的两个以上元件和部分或者全部互连线路的三维配置，或者为制造集成电路而准备的上述三维配置；\n（三）布图设计权利人，是指依照本条例的规定，对布图设计享有专有权的自然人、法人或者非法人组织；\n（四）复制，是指重复制作布图设计或者含有该布图设计的集成电路的行为；\n（五）商业利用，是指为商业目的进口、销售或者以其他方式提供受保护的布图设计、含有该布图设计的集成电路或者含有该集成电路的物品的行为。\n对集成光子、量子等功能的集成电路的布图设计，可以依照本条例的规定予以保护。\n第四条 中国自然人、法人或者非法人组织创作的布图设计，依照本条例享有布图设计专有权。\n外国人、外国企业或者外国其他组织创作的布图设计首先在中国境内投入商业利用的，依照本条例享有布图设计专有权。\n外国人、外国企业或者外国其他组织创作的布图设计，其创作者所属国同中国签订有关布图设计保护协议或者与中国共同参加有关布图设计保护国际条约的，依照本条例享有布图设计专有权。\n第五条 申请布图设计登记或者办理其他布图设计事务，可以自行办理，也可以委托依法设立的专利代理机构办理。\n在中国没有经常居所或者营业所的外国人、外国企业或者外国其他组织在中国申请布图设计登记和办理其他布图设计事务的，应当委托依法设立的专利代理机构办理。\n专利代理机构应当遵守法律、行政法规，按照被代理人的委托办理布图设计登记申请或者其他布图设计事务；对被代理人布图设计中未公开的内容，负有保密责任。\n第六条 受保护的布图设计应当具有独创性，即该布图设计是创作者自己的智力劳动成果，并且在其创作时该布图设计在布图设计创作者和集成电路制造者中不是公认的常规设计。\n受保护的由常规设计组成的布图设计，其组合作为整体应当符合前款规定的条件。\n第七条 本条例对布图设计的保护，不延及思想、处理过程、操作方法或者数学概念等。\n第八条 国务院知识产权行政部门负责全国的布图设计专有权有关管理工作。\n第九条 申请布图设计登记和行使布图设计专有权应当遵循诚实信用原则。不得滥用布图设计专有权损害国家利益、社会公共利益或者他人合法权益。\n滥用布图设计专有权，排除或者限制竞争，构成垄断行为的，依照《中华人民共和国反垄断法》处理。\n第十条 国务院知识产权行政部门应当会同有关部门采取措施，加强布图设计公共服务，促进布图设计运用。","level":1},{"name":"第二章 布图设计专有权","text":"第十一条 布图设计权利人享有下列专有权：\n（一）对受保护的布图设计的全部或者其中任何具有独创性的部分进行复制；\n（二）将受保护的布图设计、含有该布图设计的集成电路或者含有该集成电路的物品投入商业利用。\n第十二条 布图设计专有权经国务院知识产权行政部门登记产生。\n未经登记的布图设计不受本条例保护。\n第十三条 布图设计专有权属于布图设计创作者，本条例另有规定的除外。\n由法人或者非法人组织主持，依据法人或者非法人组织的意志而创作，并由法人或者非法人组织承担责任的布图设计，该法人或者非法人组织是创作者。\n由自然人创作的布图设计，该自然人是创作者。\n第十四条 两个以上自然人、法人或者非法人组织合作创作的布图设计，其专有权的归属由合作者约定；未作约定或者约定不明的，其专有权由合作者共同享有。\n第十五条 受委托创作的布图设计，其专有权的归属由委托人和受托人双方约定；未作约定或者约定不明的，其专有权由受托人享有。\n第十六条 属于本条例第十三条第二款规定情形的，法人或者非法人组织应当依照《中华人民共和国促进科技成果转化法》和国家有关规定，对符合条件的人员给予合理的奖励和报酬。\n第十七条 布图设计专有权的保护期为10年，自布图设计登记申请之日或者在世界任何地方首次投入商业利用之日起计算，以较前日期为准。但是，无论是否登记或者投入商业利用，布图设计自创作完成之日起15年后，不再受本条例保护。\n第十八条 布图设计专有权属于自然人的，该自然人死亡后，其专有权在本条例规定的保护期内依法转移。\n布图设计专有权属于法人或者非法人组织的，法人或者非法人组织变更、终止后，其专有权在本条例规定的保护期内由承继其权利、义务的法人或者非法人组织享有；没有承继其权利、义务的法人或者非法人组织的，不再受本条例保护。","level":1},{"name":"第三章 布图设计的登记","text":"第十九条 国务院知识产权行政部门负责布图设计登记工作，受理布图设计登记申请。\n第二十条 提出布图设计登记申请应当以真实创作活动为基础，不得弄虚作假。\n第二十一条 申请登记的布图设计涉及国家安全或者重大利益，需要保密的，按照国家有关规定办理。\n第二十二条 申请布图设计登记，应当提交：\n（一）布图设计登记申请表；\n（二）布图设计的复制件或者图样；\n（三）布图设计的独创性声明；\n（四）国务院知识产权行政部门规定的其他材料。\n布图设计已投入商业利用的，申请布图设计登记应当提交含有该布图设计的集成电路样品。\n第二十三条 申请人提交的复制件或者图样应当包含布图设计的必要信息，能够清楚地显示该布图设计具有独创性的部分。\n第二十四条 独创性声明应当指明布图设计具有独创性的设计区域、设计要点以及相应功能。\n布图设计作为整体具有独创性的，应当在独创性声明中具体说明。\n第二十五条 国务院知识产权行政部门收到本条例第二十二条规定的布图设计登记申请文件之日为申请日。申请文件是邮寄的，以寄出的邮戳日为申请日。\n第二十六条 布图设计自其在世界任何地方首次商业利用之日起2年内，未向国务院知识产权行政部门提出登记申请的，国务院知识产权行政部门不再予以登记。\n第二十七条 国务院知识产权行政部门对布图设计登记申请进行初步审查，认为申请登记的布图设计明显不符合本条例第三条第一款第一项、第二项或者第七条、第二十条、第二十三条、第二十四条的规定的，应当通知申请人，要求其在指定期限内陈述意见或者补正；申请人期满未答复的，其申请视为撤回。申请人陈述意见或者补正后，国务院知识产权行政部门仍然认为不符合本条例规定的，应当予以驳回。\n第二十八条 布图设计登记申请经初步审查，未发现驳回理由的，由国务院知识产权行政部门予以登记，发给登记证明文件，并予以公告。\n第二十九条 布图设计登记申请人对国务院知识产权行政部门驳回其登记申请的决定不服的，可以自收到通知之日起3个月内，向国务院知识产权行政部门请求复审。国务院知识产权行政部门复审后，作出决定，并通知布图设计登记申请人。布图设计登记申请人对国务院知识产权行政部门的复审决定仍不服的，可以依法向人民法院起诉。\n第三十条 布图设计获准登记后，国务院知识产权行政部门发现该登记不符合本条例规定的，应当予以撤销，通知布图设计权利人，并予以登记和公告。\n任何人发现该登记不符合本条例规定的，可以请求国务院知识产权行政部门撤销布图设计登记。国务院知识产权行政部门对撤销布图设计登记的请求应当及时审查和作出决定，并通知请求人和布图设计权利人。撤销布图设计登记的决定，由国务院知识产权行政部门登记和公告。\n前两款所称不符合本条例规定，是指不符合本条例第三条第一款第一项、第二项或者第四条、第六条、第七条、第十七条、第二十条、第二十三条、第二十四条、第二十六条的规定。\n布图设计权利人和请求人对国务院知识产权行政部门的审查决定不服的，可以依法向人民法院起诉。\n第三十一条 布图设计登记被撤销的，该布图设计专有权视为自始即不存在。\n第三十二条 国务院知识产权行政部门的工作人员及有关人员对布图设计登记中未公开的内容负有保密责任。\n第三十三条 当事人因不可抗拒的事由延误本条例规定的期限或者国务院知识产权行政部门指定的期限，导致其权利丧失的，自障碍消除之日起2个月内且自期限届满之日起2年内，可以向国务院知识产权行政部门说明理由并附具有关证明文件，请求恢复其权利。\n除前款规定的情形外，当事人因其他正当理由延误本条例规定的期限或者国务院知识产权行政部门指定的期限，导致其权利丧失的，可以自收到国务院知识产权行政部门的通知之日起2个月内向国务院知识产权行政部门说明理由，请求恢复其权利；但是，延误复审请求期限的，可以自复审请求期限届满之日起2个月内向国务院知识产权行政部门请求恢复其权利。\n当事人请求延长国务院知识产权行政部门指定的期限的，应当在期限届满前，向国务院知识产权行政部门说明理由并办理有关手续。\n本条第一款和第二款的规定不适用本条例第十七条、第二十六条规定的期限。","level":1},{"name":"第四章 布图设计专有权的行使","text":"第三十四条 受保护的布图设计以登记的布图设计的复制件或者图样所显示的为准，独创性声明可以用于解释布图设计的独创性。\n第三十五条 布图设计权利人可以将其专有权转让或者许可他人使用其布图设计。\n中国自然人、法人或者非法人组织向外国人、外国企业或者外国其他组织转让布图设计专有权的，应当依照有关法律、行政法规和国家有关规定办理手续。\n转让布图设计专有权的，当事人应当订立书面合同，并向国务院知识产权行政部门登记，由国务院知识产权行政部门予以公告。布图设计专有权的转让自登记之日起生效。\n许可他人使用其布图设计的，当事人应当订立书面合同，并自合同生效之日起3个月内向国务院知识产权行政部门备案。\n以布图设计专有权出质的，由出质人和质权人共同向国务院知识产权行政部门办理出质登记，由国务院知识产权行政部门予以公告。\n第三十六条 布图设计专有权的共有人对权利的行使有约定的，从其约定。没有约定的，共有人可以单独使用或者以普通许可方式许可他人使用该布图设计；许可他人使用该布图设计的，收取的使用费应当在共有人之间分配。\n除前款规定的情形外，行使共有的布图设计专有权应当取得全体共有人的同意。\n第三十七条 下列行为可以不经布图设计权利人许可，不向其支付使用费：\n（一）为个人目的或者仅为评价、分析、研究、教学等目的而复制受保护的布图设计的；\n（二）在依据前项评价、分析受保护的布图设计的基础上，创作出具有独创性的布图设计的；\n（三）对自己独立创作的与他人相同的布图设计进行复制或者将其投入商业利用的。\n第三十八条 受保护的布图设计、含有该布图设计的集成电路或者含有该集成电路的物品，由布图设计权利人或者经其许可投放市场后，他人再次商业利用的，可以不经布图设计权利人许可，并不向其支付使用费。\n第三十九条 在国家出现紧急状态或者非常情况时，或者为了公共利益的目的，或者经人民法院、反垄断执法机构依法认定布图设计权利人有垄断行为而需要给予补救时，国务院知识产权行政部门可以给予使用其布图设计的非自愿许可。\n第四十条 国务院知识产权行政部门作出给予使用布图设计非自愿许可的决定，应当及时通知布图设计权利人。\n给予使用布图设计非自愿许可的决定，应当根据非自愿许可的理由，规定使用的范围和时间，其范围应当限于为公共目的非商业性使用，或者限于经人民法院、反垄断执法机构依法认定布图设计权利人有垄断行为而需要给予的补救。\n非自愿许可的理由消除并不再发生时，国务院知识产权行政部门应当根据布图设计权利人的请求，经审查后作出终止使用布图设计非自愿许可的决定。\n第四十一条 取得使用布图设计非自愿许可的自然人、法人或者非法人组织不享有独占的使用权，并且无权允许他人使用。\n第四十二条 取得使用布图设计非自愿许可的自然人、法人或者非法人组织应当向布图设计权利人支付合理的使用费，其数额由双方协商；双方不能达成协议的，由国务院知识产权行政部门作出行政裁决。\n第四十三条 布图设计权利人对国务院知识产权行政部门关于使用布图设计非自愿许可的决定不服的，布图设计权利人和取得非自愿许可的自然人、法人或者非法人组织对国务院知识产权行政部门关于布图设计非自愿许可使用费的行政裁决不服的，可以依法向人民法院起诉。","level":1},{"name":"第五章 法律责任","text":"第四十四条 除本条例另有规定的外，未经布图设计权利人许可，有下列行为之一的，行为人应当立即停止侵权行为，并承担赔偿责任：\n（一）复制受保护的布图设计的全部或者其中任何具有独创性的部分的；\n（二）为商业目的进口、销售或者以其他方式提供受保护的布图设计、含有该布图设计的集成电路或者含有该集成电路的物品的。\n第四十五条 未经布图设计权利人许可，使用其布图设计，即侵犯其布图设计专有权，引起纠纷的，由当事人协商解决；不愿协商或者协商不成的，布图设计权利人或者利害关系人可以向人民法院起诉，也可以请求国务院知识产权行政部门处理。国务院知识产权行政部门处理时，认定侵权行为成立的，可以责令侵权人立即停止侵权行为，没收、销毁侵权产品或者物品。当事人不服的，可以依法向人民法院起诉；侵权人期满不起诉又不停止侵权行为的，国务院知识产权行政部门可以请求人民法院强制执行。应当事人的请求，国务院知识产权行政部门可以就侵犯布图设计专有权的赔偿数额进行调解；调解不成的，当事人可以依法向人民法院起诉。\n第四十六条 侵犯布图设计专有权的赔偿数额按照权利人因被侵权所受到的实际损失或者侵权人因侵权所获得的利益确定；权利人的损失或者侵权人获得的利益难以确定的，参照该布图设计许可使用费的倍数合理确定。对故意侵犯布图设计专有权，情节严重的，可以在按照上述方法确定数额的1倍以上5倍以下确定赔偿数额。\n赔偿数额还应当包括权利人为制止侵权行为所支付的合理开支。\n第四十七条 在获得含有受保护的布图设计的集成电路或者含有该集成电路的物品时，不知道也没有合理理由应当知道其中含有非法复制的布图设计，而将其投入商业利用的，不视为侵权。\n前款行为人得到其中含有非法复制的布图设计的明确通知后，可以继续将现有的存货或者此前的订货投入商业利用，但应当向布图设计权利人支付合理的使用费。\n第四十八条 专利代理机构泄露被代理人布图设计中未公开的内容的，依照《专利代理条例》第二十五条规定给予处罚。\n国务院知识产权行政部门的工作人员及有关人员泄露布图设计登记中未公开的内容的，依法给予处分；涉及泄露国家秘密、侵犯商业秘密的，依照有关法律、行政法规的规定承担法律责任。\n第四十九条 从事布图设计专有权管理工作的国家机关工作人员玩忽职守、滥用职权、徇私舞弊的，依法给予处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附 则","text":"第五十条 布图设计登记公告后，公众可以请求查阅该布图设计登记簿或者请求国务院知识产权行政部门提供该登记簿的副本。公众也可以请求查阅该布图设计的复制件或者图样的纸件。\n除诉讼或者行政处理程序等国家机关依法履职需要外，任何人不得查阅或者复制布图设计的复制件或者图样的电子版本。\n第五十一条 申请布图设计登记和办理其他手续，应当按照规定缴纳费用。\n第五十二条 本条例规定的各种期限开始的当日不计算在期限内，自下一日开始计算。期限以年或者月计算的，以其最后一月的相应日为期限届满日；该月无相应日的，以该月最后一日为期限届满日；期限届满日是法定休假日的，以休假日后的第一个工作日为期限届满日。\n第五十三条 任何国家或者地区在集成电路布图设计保护方面对中华人民共和国采取歧视性的禁止、限制或者其他类似措施的，中华人民共和国可以根据实际情况对有关国家或者地区采取相应的措施。\n第五十四条 本条例自2026年10月15日起施行。","level":1}]},{"id":"n1283","sections":[{"name":"","text":"电力安全事故应急处置和调查处理条例\n（2011年7月7日中华人民共和国国务院令第599号公布 2026年8月30日中华人民共和国国务院令第845号修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强电力安全事故应急处置工作，规范电力安全事故调查处理，控制、减轻和消除电力安全事故损害，保障电力系统安全稳定运行和电力可靠供应，制定本条例。\n第二条 本条例所称电力安全事故，是指电力生产或者电网运行过程中发生的影响电力系统安全稳定运行或者影响电力正常供应的事故。\n第三条 根据电力安全事故（以下简称事故）影响电力系统安全稳定运行或者影响电力正常供应的程度，事故分为特别重大事故、重大事故、较大事故和一般事故。事故等级划分标准由本条例附表列示。事故等级划分标准的部分项目需要调整的，由国务院能源主管部门提出方案，报国务院批准。\n由单一输电线路或者单一变电站供电的区域，因该单一输电线路或者单一变电站故障导致电网减供负荷或者造成供电用户停电的事故等级划分标准，由国务院能源主管部门另行制定，报国务院批准。\n第四条 国务院能源主管部门应当加强电力安全监督管理，依法建立健全事故应急处置和调查处理的各项制度，组织或者参与事故调查处理。\n国务院能源主管部门和国务院其他有关部门、地方人民政府及其有关部门按照国家规定的权限和程序，组织、协调、参与事故应急处置工作。\n第五条 电力企业、电力用户以及其他并入电网运行的主体（以下简称其他并网主体），应当遵守电力安全管理规定，服从统一调度，严格执行有关标准和技术规范，在电力系统的规划、建设、运行等环节落实事故预防措施，加强事故隐患排查，防止和避免事故发生。\n电力调度机构应当严格依照相关法律、行政法规和国务院能源主管部门的规定开展电网运行控制。\n县级以上地方人民政府有关部门确定的重要电力用户，应当按照国务院能源主管部门的规定配置自备应急电源，并加强安全使用管理。\n第六条 事故发生后，有关单位和个人应当按照规定及时、准确报告事故情况，开展应急处置工作，防止事故扩大，减轻事故损害。电力企业以及其他并网主体应当尽快恢复电力生产、电网运行和电力正常供应。\n有关人民政府及其有关部门应当为事故应急处置提供必要的支持和保障。\n第七条 任何单位和个人不得阻挠和干涉对事故的报告、应急处置和依法调查处理。","level":1},{"name":"第二章 事故报告","text":"第八条 事故发生后，事故现场有关人员应当立即向发电厂、变电（换流）站运行值班人员，电力调度机构值班人员或者本单位现场负责人报告。有关人员接到报告后，应当立即向上一级电力调度机构和本单位负责人报告。本单位负责人接到报告后应当立即向国务院能源主管部门设在当地的派出机构（以下称派出能源监管机构）、县级以上人民政府应急管理部门报告。热电厂事故影响热力正常供应的，还应当向供热管理部门报告；事故涉及水电厂（站）大坝安全的，还应当同时向有管辖权的水行政主管部门或者流域管理机构报告。\n省、自治区、直辖市级以上电力调度机构对调度管辖范围内发生的事故，应当立即向国务院能源主管部门或者派出能源监管机构报告。\n事故发生单位、电力调度机构及其有关人员不得迟报或者瞒报、谎报事故情况。\n第九条 派出能源监管机构接到事故报告后，应当立即核实有关情况，向国务院能源主管部门报告；事故造成供电用户停电的，应当同时通报事故发生地县级以上地方人民政府。\n对特别重大事故、重大事故，国务院能源主管部门接到事故报告后应当立即报告国务院，并通报国务院应急管理部门等有关部门。\n第十条 事故报告应当包括下列内容：\n（一）事故发生的时间、地点（区域）、事故发生单位以及事故简要经过；\n（二）已知的电力设备、设施损坏情况，停运的发电设备数量、电网减供负荷或者发电设备减少出力的数值、停电范围；\n（三）事故原因的初步判断；\n（四）事故发生后采取的措施、电网运行方式、发电设备运行状况以及事故控制情况；\n（五）其他应当报告的情况。\n事故报告可以先行报告已知情况，后续再报告详细情况。事故报告后出现新情况的，应当及时补报。\n第十一条 事故发生后，有关单位和人员应当妥善保护事故现场以及工作日志、工作票、操作票等相关材料，及时保存故障录波图、电力调度数据、发电设备运行数据和输变电设备运行数据等相关资料，并在事故调查组成立后将相关材料、资料移交事故调查组。\n因抢救人员或者采取恢复电力生产、电网运行和电力供应等紧急措施，需要改变事故现场、移动电力设备的，应当作出标记、绘制现场简图，妥善保存重要痕迹、物证，并作出书面记录。\n任何单位和个人不得故意破坏事故现场，不得伪造、隐匿或者毁灭相关证据。","level":1},{"name":"第三章 事故应急处置","text":"第十二条 电力企业应当按照国家有关规定，制定本单位事故应急救援预案，并定期组织演练。事故应急救援预案应当报派出能源监管机构备案，并抄报所在地县级以上地方人民政府应急管理部门。\n国务院能源主管部门、派出能源监管机构应当指导电力企业加强事故应急救援体系建设，保障物资、装备等投入。\n第十三条 事故发生后，有关电力企业、电力用户以及其他并网主体应当立即采取相应的紧急处置措施，控制事故范围，防止发生电网系统性崩溃和瓦解；事故危及人身和设备安全的，相关运行值班人员可以按照有关规定，立即采取停运发电设备和输变电设备等紧急处置措施。\n事故造成电力设备、设施损坏的，有关电力企业以及其他并网主体应当立即组织抢修。\n第十四条 根据事故的具体情况，电力调度机构可以发布开启或者停运发电设备、调整发电设备有功和无功出力、调整电网运行方式、调整调度计划等电力调度命令，电力企业、电力用户以及其他并网主体应当执行。\n事故可能导致破坏电力系统稳定和电网大面积停电的，电力调度机构有权决定采取拉限负荷、解列电网、解列发电设备等必要措施。\n事故造成某一区域电力系统全部停止运行的，电力调度机构应当立即确定恢复供电方案，必要时启动系统内具备独立启动和孤网运行能力的发电设备，或者调度外来电源，尽快恢复电力系统运行。\n第十五条 恢复电网运行和电力供应，应当优先保证重要发电厂厂用电源、重要输变电设备、电力主干网架的恢复，优先恢复重要电力用户、重要城市、重点地区的电力供应。\n第十六条 国务院能源主管部门依照《中华人民共和国突发事件应对法》和《国家突发事件总体应急预案》，组织编制国家大面积停电事件应急预案，报国务院批准。\n地方人民政府应当依照法律、行政法规和国家大面积停电事件应急预案，组织制定本行政区域大面积停电事件应急预案。\n大面积停电事件应急预案应当对应急组织指挥体系及职责，应急处置的各项措施，以及人员、资金、物资、技术、通信等应急保障作出具体规定。\n第十七条 事故造成大面积停电的，国务院能源主管部门和国务院其他有关部门、有关地方人民政府及其有关部门、电力企业以及其他并网主体应当按照大面积停电事件应急预案等规定，启动应急响应，成立应急指挥机构，尽快恢复电网运行和电力供应，防止各种次生灾害的发生。\n第十八条 事故造成大面积停电的，地方人民政府及有关部门应当立即组织开展下列应急处置工作：\n（一）加强对停电地区关系国计民生、国家安全和公共安全的重点单位的安全保卫，防范破坏社会秩序的行为，维护社会稳定；\n（二）及时排除因停电发生的各种险情；\n（三）事故造成重大人员伤亡或者需要紧急转移、安置受困人员的，及时组织实施救治、转移、安置工作；\n（四）加强停电地区道路交通指挥和疏导，做好铁路、民航运输以及通信保障工作；\n（五）组织应急物资的紧急生产和调用，保证电网恢复运行所需物资和居民基本生活资料的供给。\n第十九条 事故造成重要电力用户供电中断的，重要电力用户应当按照有关技术要求迅速启动自备应急电源；启动自备应急电源无效的，电网企业应当提供必要的支援和保障。\n事故造成地铁、机场、高层建筑、商场、影剧院、体育场馆等人员聚集场所停电的，应当迅速启用应急照明，组织人员有序疏散。\n第二十条 应急指挥机构、国务院能源主管部门或者派出能源监管机构应当按照有关规定，统一、准确、及时发布有关事故影响范围、处置工作进度、预计恢复供电时间等信息。","level":1},{"name":"第四章 事故调查处理","text":"第二十一条 特别重大事故由国务院或者国务院授权的部门组织事故调查组进行调查。\n重大事故由国务院能源主管部门组织事故调查组进行调查。\n较大事故、一般事故由派出能源监管机构组织事故调查组进行调查。国务院能源主管部门认为必要的，可以组织事故调查组对较大事故进行调查。\n未造成供电用户停电的一般事故，派出能源监管机构也可以委托事故发生单位调查处理。\n第二十二条 根据事故的具体情况，事故调查组由有关人民政府及其能源、应急管理部门和其他负有安全生产监督管理职责的部门、消防救援机构派人组成，邀请公安机关、人民检察院等单位派人参加。事故调查组应当及时向监察机关通报事故情况，并邀请监察机关介入事故调查。\n根据事故调查工作的需要，事故调查组可以聘请有关专家协助调查。\n事故调查组组长由组织事故调查组的机关指定。\n第二十三条 事故调查组应当按照国家有关规定开展事故调查，并在下列期限内向组织事故调查组的机关提交事故调查报告：\n（一）特别重大事故和重大事故的调查期限为60日；特殊情况下，经组织事故调查组的机关批准，可以适当延长，但延长的期限不得超过60日。\n（二）较大事故和一般事故的调查期限为45日；特殊情况下，经组织事故调查组的机关批准，可以适当延长，但延长的期限不得超过45日。\n事故调查期限自事故发生之日起计算。\n第二十四条 事故调查报告应当包括下列内容：\n（一）事故涉及单位基本情况和事故发生及处置经过；\n（二）事故造成的直接经济损失和事故对电网运行、电力正常供应的影响情况；\n（三）事故发生的原因和事故性质；\n（四）事故应急处置和恢复电力生产、电网运行的情况；\n（五）事故责任认定、对事故责任单位的处理建议、应当追责问责的公职人员建议名单和对其他责任人员的处理建议；\n（六）事故防范和整改措施。\n事故调查报告应当附具有关证据材料和技术分析报告。事故调查组成员应当在事故调查报告上签字。\n第二十五条 事故调查报告报经组织事故调查组的机关批复同意，事故调查工作即告结束；委托事故发生单位调查的一般事故，事故调查报告应当报经派出能源监管机构批复同意。事故调查报告应当依法及时向社会公布。\n有关机关应当依法对事故责任单位和有关责任人员进行处罚，对负有事故责任的公职人员给予处分。\n事故责任单位应当对本单位负有事故责任的人员进行处理，并将处理结果及时报组织事故调查组的机关。\n第二十六条 事故责任单位和有关人员应当认真吸取事故教训，落实事故防范和整改措施，防止事故再次发生。\n国务院能源主管部门或者派出能源监管机构应当在事故调查报告批复后一年内，组织对事故防范和整改措施落实情况进行评估，并及时向社会公开评估结果。","level":1},{"name":"第五章 法律责任","text":"第二十七条 事故发生单位主要负责人有下列行为之一的，由国务院能源主管部门或者派出能源监管机构处其上一年年收入60%至100%的罚款；属于公职人员的，并依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）不立即组织事故处置的；\n（二）迟报事故的；\n（三）在事故调查处理期间擅离职守的。\n第二十八条 事故发生单位及其有关人员有下列行为之一的，由国务院能源主管部门或者派出能源监管机构对事故发生单位处100万元以上500万元以下的罚款；对主要负责人、直接负责的主管人员和其他直接责任人员处其上一年年收入60%至100%的罚款，属于公职人员的，并依法给予处分；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任：\n（一）谎报或者瞒报事故的；\n（二）伪造或者故意破坏事故现场的；\n（三）转移、隐匿资金、财产，或者销毁有关证据、资料的；\n（四）拒绝接受调查或者拒绝提供有关情况和资料的；\n（五）在事故调查中作伪证或者指使他人作伪证的；\n（六）事故发生后逃匿的。\n第二十九条 对事故责任单位，由国务院能源主管部门或者派出能源监管机构依照下列规定处以罚款：\n（一）发生一般事故的，处30万元以上100万元以下的罚款；\n（二）发生较大事故的，处100万元以上200万元以下的罚款；\n（三）发生重大事故的，处200万元以上1000万元以下的罚款；\n（四）发生特别重大事故的，处1000万元以上2000万元以下的罚款。\n事故情节特别严重、影响特别恶劣的，国务院能源主管部门或者派出能源监管机构可以按照前款罚款数额的2倍以上5倍以下对事故责任单位处以罚款。\n第三十条 事故责任单位主要负责人未依法履行安全生产管理职责，导致事故发生的，由国务院能源主管部门或者派出能源监管机构依照下列规定处以罚款；属于公职人员的，并依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）发生一般事故的，处其上一年年收入40%的罚款；\n（二）发生较大事故的，处其上一年年收入60%的罚款；\n（三）发生重大事故的，处其上一年年收入80%的罚款；\n（四）发生特别重大事故的，处其上一年年收入100%的罚款。\n事故责任单位其他负责人和安全生产管理人员未依法履行安全生产管理职责，导致事故发生的，由国务院能源主管部门或者派出能源监管机构处其上一年年收入20%至50%的罚款。\n第三十一条 事故发生单位主要负责人依照本条例规定受到撤职及以上处分或者刑事处罚的，自受处分之日或者刑罚执行完毕之日起5年内，不得担任任何生产经营单位主要负责人。\n第三十二条 国务院能源主管部门或者派出能源监管机构、有关地方人民政府以及其他负有安全生产监督管理职责的部门有下列行为之一的，对负有责任的领导人员和直接责任人员依法给予处分；负有责任的领导人员和直接责任人员构成犯罪的，依法追究刑事责任：\n（一）不立即组织事故处置的；\n（二）迟报或者瞒报、谎报事故的；\n（三）阻碍、干涉事故调查工作的；\n（四）在事故调查中作伪证或者指使他人作伪证的。\n第三十三条 电力调度机构有下列行为之一的，对负有责任的领导人员和直接责任人员依法给予处分；负有责任的领导人员和直接责任人员构成犯罪的，依法追究刑事责任：\n（一）未及时开展事故处置，造成事故扩大的；\n（二）未及时采取措施恢复供电的；\n（三）迟报或者瞒报、谎报事故的；\n（四）不配合事故调查，拒绝提供有关情况和资料，作伪证或者指使他人作伪证，销毁有关证据、资料的。\n第三十四条 参与事故调查的人员在事故调查中有下列行为之一的，依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）对事故调查工作不负责任，致使事故调查工作有重大疏漏的；\n（二）包庇、袒护负有事故责任的人员或者借机打击报复的。","level":1},{"name":"第六章 附 则","text":"第三十五条 发生本条例规定的事故，同时造成人员伤亡或者直接经济损失，依照本条例确定的事故等级与依照《生产安全事故报告和调查处理条例》确定的事故等级不相同的，按事故等级较高者确定事故等级，依照本条例的规定调查处理；事故造成人员伤亡，构成《生产安全事故报告和调查处理条例》规定的重大事故或者特别重大事故的，依照《生产安全事故报告和调查处理条例》的规定调查处理。\n电力生产或者电网运行过程中发生发电设备或者输变电设备损坏，造成直接经济损失的事故，未影响电力系统安全稳定运行以及电力正常供应的，由国务院能源主管部门或者派出能源监管机构依照《生产安全事故报告和调查处理条例》的规定组成事故调查组对重大事故、较大事故、一般事故进行调查处理。\n第三十六条 本条例对事故报告和调查处理未作规定的，适用《生产安全事故报告和调查处理条例》等有关法律、行政法规的规定。\n第三十七条 核电厂核事故的应急处置和调查处理，依照《核电厂核事故应急管理条例》的规定执行。\n第三十八条 本条例自2027年1月1日起施行。\n附件：电力安全事故等级划分标准\n附件\n电力安全事故等级划分标准\n-155575601345判定项判定项-3556010795-8235951633220事故等级事故等级\t造成电网减供负荷的比例\t造成供电用户停电的比例\t发电厂或者变电站因安全故障造成的影响和持续时间\t发电设备减少出力导致电力系统备用容量下降的后果\t发电设备因安全故障停运的时间和后果\n特别重大事故\t区域性电网，减供负荷30%以上省、自治区电网，负荷50000兆瓦以上的，减供负荷30%以上；负荷11000兆瓦以上50000兆瓦以下的，减供负荷40%以上直辖市电网，减供负荷50%以上省、自治区人民政府所在地城市电网，负荷4500兆瓦以上的，减供负荷60%以上\t直辖市电网，60%以上供电用户停电省、自治区人民政府所在地城市电网，负荷4500兆瓦以上的，70%以上供电用户停电\n重大事故\t区域性电网，减供负荷10%以上30%以下省、自治区电网，负荷50000兆瓦以上的，减供负荷13%以上30%以下；负荷11000兆瓦以上50000兆瓦以下的，减供负荷16%以上40%以下；负荷5000兆瓦以上11000兆瓦以下的，减供负荷50%以上直辖市电网，减供负荷20%以上50%以下省、自治区人民政府所在地城市电网，负荷4500兆瓦以上的，减供负荷40%以上60%以下；负荷4500兆瓦以下的，减供负荷40%以上其他设区的市级行政区域电网，负荷1300兆瓦以上的，减供负荷60%以上\t直辖市电网，30%以上60%以下供电用户停电省、自治区人民政府所在地城市电网，负荷4500兆瓦以上的，50%以上70%以下供电用户停电；负荷4500兆瓦以下的，50%以上供电用户停电其他设区的市级行政区域电网，负荷1300兆瓦以上的，70%以上供电用户停电\n较大事故\t区域性电网，减供负荷7%以上10%以下省、自治区电网，负荷50000兆瓦以上的，减供负荷10%以上13%以下；负荷11000兆瓦以上50000兆瓦以下的，减供负荷12%以上16%以下；负荷5000兆瓦以上11000兆瓦以下的，减供负荷20%以上50%以下；负荷5000兆瓦以下的，减供负荷40%以上直辖市电网，减供负荷10%以上20%以下省、自治区人民政府所在地城市电网，减供负荷20%以上40%以下其他设区的市级行政区域电网，负荷1300兆瓦以上的，减供负荷40%以上60%以下；负荷1300兆瓦以下的，减供负荷40%以上县级市电网，负荷220兆瓦以上的，减供负荷60%以上\t直辖市电网，15%以上30%以下供电用户停电省、自治区人民政府所在地城市电网，30%以上50%以下供电用户停电其他设区的市级行政区域电网，负荷1300兆瓦以上的，50%以上70%以下供电用户停电；负荷1300兆瓦以下的，50%以上供电用户停电县级市电网，负荷220兆瓦以上的，70%以上供电用户停电 发电设备涉网性能不符合技术要求，造成省、自治区、直辖市电网，负荷50000兆瓦以上的，减少出力达到电网负荷10%以上；负荷11000兆瓦以上50000兆瓦以下的，减少出力达到电网负荷11%以上；负荷5000兆瓦以上11000兆瓦以下的，减少出力达到电网负荷15%以上；负荷5000兆瓦以下的，减少出力达到电网负荷30%以上\t发电设备因安全故障停止运行超过行业标准规定的大修时间两周，并导致电网减供负荷\n一般事故\t区域性电网，减供负荷4%以上7%以下省、自治区电网，负荷50000兆瓦以上的，减供负荷5%以上10%以下；负荷11000兆瓦以上50000兆瓦以下的，减供负荷6%以上12%以下；负荷5000兆瓦以上11000兆瓦以下的，减供负荷10%以上20%以下；负荷5000兆瓦以下的，减供负荷25%以上40%以下直辖市电网，减供负荷5%以上10%以省、自治区人民政府所在地城市电网，减供负荷10%以上20%以下其他设区的市级行政区域电网，减供负荷20%以上40%以下县级市电网，负荷220兆瓦以上的，减供负荷40%以上60%以下；负荷220兆瓦以下的，减供负荷40%以上其他县级行政区域电网，负荷180兆瓦以上的，减供负荷70%以上\t直辖市电网10%以上15%以下供电用户停电省、自治区人民政府所在地城市电网，15%以上30%以下供电用户停电其他设区的市级行政区域电网，30%以上50%以下供电用户停电县级市电网负荷220兆瓦以上的，50%以上70%以下供电用户停电；负荷220兆瓦以下的，50%以上供电用户停电其他县级行政区域电网，负荷180兆瓦以上的，80%以上供电用户停电\t发电厂或者220千伏以上变电站因安全故障导致周边其他发电厂并网点或变电站的220千伏以上运行母线电压偏离系统标称电压15%以上，持续时间1.5小时以上。\t发电设备涉网性能不符合技术要求，造成省、自治区、直辖市电网，负荷50000兆瓦以上的，减少出力达到电网负荷2%以上10%以下；负荷11000兆瓦以上50000兆瓦以下的，减少出力达到电网负荷3%以上11%以下；负荷5000兆瓦以上11000兆瓦以下的，减少出力达到电网负荷9%以上15%以下；负荷5000兆瓦以下的，减少出力达到电网负荷9%以上30%以下因自身安全故障，发电设备单次减少出力3000兆瓦以上，其中新能源发电设备单次减少出力1000兆瓦以上\t发电设备因安全故障停止运行超过行业标准规定的小修时间两周，并导致电网减供负荷发电设备备用期间擅自检修，造成电力调度机构调用发电设备失败，并导致电网减供负荷\n注：1.符合本表所列情形之一的，即构成相应等级的电力安全事故。\n2.本表中所称的“以上”包括本数，“以下”不包括本数。\n3.本表下列用语的含义：\n（1）电网负荷，是指电力调度机构统一调度的电网在事故发生起始时刻的实际负荷；\n（2）电网减供负荷，是指电力调度机构统一调度的电网在事故发生期间的实际负荷最大减少量；\n（3）涉网性能，是指发电设备所具备的有功/无功控制、频率电压响应、故障扰动耐受等涉及电网安全稳定运行的能力。\n4.其他事项：\n（1）在国家标准、行业标准规定范围内的电压、频率波动期间，电力用户出于自身设备安全考虑主动脱离电网的负荷不纳入电网减供负荷统计；\n（2）负荷占所在市级或者县级行政区域负荷10%以上，且通过单一输电线路或者单一变电站供电的电力用户，因其自身设备安全故障、设备不满足标准等原因，在电网发生单一故障扰动后仅造成该用户负荷损失的，不纳入电网减供负荷统计。","level":1}]},{"id":"n1284","sections":[{"name":"","text":"城市绿化条例\n（1992年6月22日中华人民共和国国务院令第100号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2017年3月1日《国务院关于修改和废止部分行政法规的决定》第二次修订 根据2026年1月30日《国务院关于修改和废止部分行政法规的决定》第三次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了促进城市绿化事业的发展，改善生态环境，美化生活环境，增进人民身心健康，制定本条例。\n第二条 本条例适用于在城市规划区内种植和养护树木花草等城市绿化的规划、建设、保护和管理。\n第三条 城市人民政府应当把城市绿化建设纳入国民经济和社会发展计划。\n第四条 国家鼓励和加强城市绿化的科学研究，推广先进技术，提高城市绿化的科学技术和艺术水平。\n第五条 城市中的单位和有劳动能力的公民，应当依照国家有关规定履行植树或者其他绿化义务。\n第六条 对在城市绿化工作中成绩显著的单位和个人，由人民政府给予表彰和奖励。\n第七条 国务院设立全国绿化委员会，统一组织领导全国城乡绿化工作，其办公室设在国务院林业行政主管部门。\n国务院城市建设行政主管部门和国务院林业行政主管部门等，按照国务院规定的职权划分，负责全国城市绿化工作。\n地方绿化管理体制，由省、自治区、直辖市人民政府根据本地实际情况规定。\n城市人民政府城市绿化行政主管部门主管本行政区域内城市规划区的城市绿化工作。\n在城市规划区内，有关法律、法规规定由林业行政主管部门等管理的绿化工作，依照有关法律、法规执行。","level":1},{"name":"第二章 规划和建设","text":"第八条 城市人民政府应当组织城市规划行政主管部门和城市绿化行政主管部门等共同编制城市绿化规划，并纳入城市总体规划。\n第九条 城市绿化规划应当从实际出发，根据城市发展需要，合理安排同城市人口和城市面积相适应的城市绿化用地面积。\n城市人均公共绿地面积和绿化覆盖率等规划指标，由国务院城市建设行政主管部门根据不同城市的性质、规模和自然条件等实际情况规定。\n第十条 城市绿化规划应当根据当地的特点，利用原有的地形、地貌、水体、植被和历史文化遗址等自然、人文条件，以方便群众为原则，合理设置公共绿地、居住区绿地、防护绿地、生产绿地和风景林地等。\n第十一条 城市绿化工程的设计，应当委托持有相应资格证书的设计单位承担。\n工程建设项目的附属绿化工程设计方案，按照基本建设程序审批时，必须有城市人民政府城市绿化行政主管部门参加审查。\n建设单位必须按照批准的设计方案进行施工。设计方案确需改变时，须经原批准机关审批。\n第十二条 城市绿化工程的设计，应当借鉴国内外先进经验，体现民族风格和地方特色。城市公共绿地和居住区绿地的建设，应当以植物造景为主，选用适合当地自然条件的树木花草，并适当配置泉、石、雕塑等景物。\n第十三条 城市绿化规划应当因地制宜地规划不同类型的防护绿地。各有关单位应当依照国家有关规定，负责本单位管界内防护绿地的绿化建设。\n第十四条 单位附属绿地的绿化规划和建设，由该单位自行负责，城市人民政府城市绿化行政主管部门应当监督检查，并给予技术指导。\n第十五条 城市苗圃、草圃、花圃等生产绿地的建设，应当适应城市绿化建设的需要。\n第十六条 城市新建、扩建、改建工程项目和开发住宅区项目，需要绿化的，其基本建设投资中应当包括配套的绿化建设投资，并统一安排绿化工程施工，在规定的期限内完成绿化任务。","level":1},{"name":"第三章 保护和管理","text":"第十七条 城市的公共绿地、风景林地、防护绿地、行道树及干道绿化带的绿化，由城市人民政府城市绿化行政主管部门管理；各单位管界内的防护绿地的绿化，由该单位按照国家有关规定管理；单位自建的公园和单位附属绿地的绿化，由该单位管理；居住区绿地的绿化，由城市人民政府城市绿化行政主管部门根据实际情况确定的单位管理；城市苗圃、草圃和花圃等，由其经营单位管理。\n第十八条 任何单位和个人都不得擅自改变城市绿化规划用地性质或者破坏绿化规划用地的地形、地貌、水体和植被。\n第十九条 任何单位和个人都不得擅自占用城市绿化用地；占用的城市绿化用地，应当限期归还。\n因建设或者其他特殊需要临时占用城市绿化用地，须经城市人民政府城市绿化行政主管部门同意，并按照有关规定办理临时用地手续。\n第二十条 任何单位和个人都不得损坏城市树木花草和绿化设施。\n砍伐城市树木，必须经城市人民政府城市绿化行政主管部门批准，并按照国家有关规定补植树木或者采取其他补救措施。\n第二十一条 在城市的公共绿地内开设商业、服务摊点的，应当持市场监督管理部门批准的营业执照，在公共绿地管理单位指定的地点从事经营活动，并遵守公共绿地和市场监督管理的规定。\n第二十二条 城市的绿地管理单位，应当建立、健全管理制度，保持树木花草繁茂及绿化设施完好。\n第二十三条 为保证管线的安全使用需要修剪树木时，应当按照兼顾管线安全使用和树木正常生长的原则进行修剪。承担修剪费用的办法，由城市人民政府规定。\n因不可抗力致使树木倾斜危及管线安全时，管线管理单位可以先行扶正或者砍伐树木，但是，应当及时报告城市人民政府城市绿化行政主管部门和绿地管理单位。\n第二十四条 城市古树名木的保护，依照《古树名木保护条例》的规定执行。","level":1},{"name":"第四章 罚 则","text":"第二十五条 工程建设项目的附属绿化工程设计方案，未经批准或者未按照批准的设计方案施工的，由城市人民政府城市绿化行政主管部门责令停止施工、限期改正或者采取其他补救措施。\n第二十六条 违反本条例规定，有下列行为之一的，由城市人民政府城市绿化行政主管部门或者其授权的单位责令停止侵害，可以并处罚款；造成损失的，应当负赔偿责任；应当给予治安管理处罚的，依照《中华人民共和国治安管理处罚法》的有关规定处罚；构成犯罪的，依法追究刑事责任：\n（一）损坏城市树木花草的；\n（二）擅自砍伐城市树木的；\n（三）损坏城市绿化设施的。\n第二十七条 未经同意擅自占用城市绿化用地的，由城市人民政府城市绿化行政主管部门责令限期退还、恢复原状，可以并处罚款；造成损失的，应当负赔偿责任。\n第二十八条 对不服从公共绿地管理单位管理的商业、服务摊点，由城市人民政府城市绿化行政主管部门或者其授权的单位给予警告，可以并处罚款；情节严重的，可以提请市场监督管理部门吊销营业执照。\n第二十九条 对违反本条例的直接责任人员或者单位负责人，可以由其所在单位或者上级主管机关依法给予处分；构成犯罪的，依法追究刑事责任。\n第三十条 城市人民政府城市绿化行政主管部门和城市绿地管理单位的工作人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管机关依法给予处分；构成犯罪的，依法追究刑事责任。\n第三十一条 当事人对行政处罚决定不服的，可以依法申请行政复议，也可以依法提起行政诉讼。当事人逾期不申请行政复议或者不向人民法院起诉又不履行行政处罚决定的，由作出行政处罚决定的机关申请人民法院强制执行。\n对治安管理处罚不服的，依照《中华人民共和国治安管理处罚法》的规定执行。","level":1},{"name":"第五章 附 则","text":"第三十二条 省、自治区、直辖市人民政府可以依照本条例制定实施办法。\n第三十三条 本条例自1992年8月1日起施行。","level":1}]},{"id":"n1285","sections":[{"name":"","text":"水库大坝安全管理条例\n（1991年3月22日中华人民共和国国务院令第77号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2018年3月19日《国务院关于修改和废止部分行政法规的决定》第二次修订 根据2026年1月30日《国务院关于修改和废止部分行政法规的决定》第三次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为加强水库大坝安全管理，保障人民生命财产和社会主义建设的安全，根据《中华人民共和国水法》，制定本条例。\n第二条 本条例适用于中华人民共和国境内坝高15米以上或者库容100万立方米以上的水库大坝（以下简称大坝）。大坝包括永久性挡水建筑物以及与其配合运用的泄洪、输水和过船建筑物等。\n坝高15米以下、10米以上或者库容100万立方米以下、10万立方米以上，对重要城镇、交通干线、重要军事设施、工矿区安全有潜在危险的大坝，其安全管理参照本条例执行。\n第三条 国务院水行政主管部门会同国务院有关主管部门对全国的大坝安全实施监督。县级以上地方人民政府水行政主管部门会同有关主管部门对本行政区域内的大坝安全实施监督。\n各级水利、能源、建设、交通、农业等有关部门，是其所管辖的大坝的主管部门。\n第四条 各级人民政府及其大坝主管部门对其所管辖的大坝的安全实行行政领导负责制。\n第五条 大坝的建设和管理应当贯彻安全第一的方针。\n第六条 任何单位和个人都有保护大坝安全的义务。","level":1},{"name":"第二章 大坝建设","text":"第七条 兴建大坝必须符合由国务院水行政主管部门会同有关大坝主管部门制定的大坝安全技术标准。\n第八条 兴建大坝必须进行工程设计。大坝的工程设计必须由具有相应资格证书的单位承担。\n大坝的工程设计应当包括工程观测、通信、动力、照明、交通、消防等管理设施的设计。\n第九条 大坝施工必须由具有相应资格证书的单位承担。大坝施工单位必须按照施工承包合同规定的设计文件、图纸要求和有关技术标准进行施工。\n建设单位和设计单位应当派驻代表，对施工质量进行监督检查。质量不符合设计要求的，必须返工或者采取补救措施。\n第十条 兴建大坝时，建设单位应当按照批准的设计，提请县级以上人民政府依照国家规定划定管理和保护范围，树立标志。\n已建大坝尚未划定管理和保护范围的，大坝主管部门应当根据安全管理的需要，提请县级以上人民政府划定。\n第十一条 大坝开工后，大坝主管部门应当组建大坝管理单位，由其按照工程基本建设验收规程参与质量检查以及大坝分部、分项验收和蓄水验收工作。\n大坝竣工后，建设单位应当申请大坝主管部门组织验收。","level":1},{"name":"第三章 大坝管理","text":"第十二条 大坝及其设施受国家保护，任何单位和个人不得侵占、毁坏。大坝管理单位应当加强大坝的安全保卫工作。\n第十三条 禁止在大坝管理和保护范围内进行爆破、打井、采石、采矿、挖沙、取土、修坟等危害大坝安全的活动。\n第十四条 非大坝管理人员不得操作大坝的泄洪闸门、输水闸门以及其他设施，大坝管理人员操作时应当遵守有关的规章制度。禁止任何单位和个人干扰大坝的正常管理工作。\n第十五条 禁止在大坝的集水区域内乱伐林木、陡坡开荒等导致水库淤积的活动。禁止在库区内围垦和进行采石、取土等危及山体的活动。\n第十六条 大坝坝顶确需兼做公路的，须经科学论证和县级以上地方人民政府大坝主管部门批准，并采取相应的安全维护措施。\n第十七条 禁止在坝体修建码头、渠道、堆放杂物、晾晒粮草。在大坝管理和保护范围内修建码头、鱼塘的，须经大坝主管部门批准，并与坝脚和泄水、输水建筑物保持一定距离，不得影响大坝安全、工程管理和抢险工作。\n第十八条 大坝主管部门应当配备具有相应业务水平的大坝安全管理人员。\n大坝管理单位应当建立、健全安全管理规章制度。\n第十九条 大坝管理单位必须按照有关技术标准，对大坝进行安全监测和检查；对监测资料应当及时整理分析，随时掌握大坝运行状况。发现异常现象和不安全因素时，大坝管理单位应当立即报告大坝主管部门，及时采取措施。\n第二十条 大坝管理单位必须做好大坝的养护修理工作，保证大坝和闸门启闭设备完好。\n第二十一条 大坝的运行，必须在保证安全的前提下，发挥综合效益。大坝管理单位应当根据批准的计划和大坝主管部门的指令进行水库的调度运用。\n在汛期，综合利用的水库，其调度运用必须服从防汛指挥机构的统一指挥；以发电为主的水库，其汛限水位以上的防洪库容及其洪水调度运用，必须服从防汛指挥机构的统一指挥。\n任何单位和个人不得非法干预水库的调度运用。\n第二十二条 大坝主管部门应当建立大坝定期安全检查、鉴定制度。\n汛前、汛后，以及暴风、暴雨、特大洪水或者强烈地震发生后，大坝主管部门应当组织对其所管辖的大坝的安全进行检查。\n第二十三条 大坝主管部门对其所管辖的大坝应当按期注册登记，建立技术档案。大坝注册登记办法由国务院水行政主管部门会同有关主管部门制定。\n第二十四条 大坝管理单位和有关部门应当做好防汛抢险物料的准备和气象水情预报，并保证水情传递、报警以及大坝管理单位与大坝主管部门、上级防汛指挥机构之间联系通畅。\n第二十五条 大坝出现险情征兆时，大坝管理单位应当立即报告大坝主管部门和上级防汛指挥机构，并采取抢救措施；有垮坝危险时，应当采取一切措施向预计的垮坝淹没地区发出警报，做好转移工作。","level":1},{"name":"第四章 险坝处理","text":"第二十六条 对尚未达到设计洪水标准、抗震设防标准或者有严重质量缺陷的险坝，大坝主管部门应当组织有关单位进行分类，采取除险加固等措施，或者废弃重建。\n在险坝加固前，大坝管理单位应当制定保坝应急措施；经论证必须改变原设计运行方式的，应当报请大坝主管部门审批。\n第二十七条 大坝主管部门应当对其所管辖的需要加固的险坝制定加固计划，限期消除危险；有关人民政府应当优先安排所需资金和物料。\n险坝加固必须由具有相应设计资格证书的单位作出加固设计，经审批后组织实施。险坝加固竣工后，由大坝主管部门组织验收。\n第二十八条 大坝主管部门应当组织有关单位，对险坝可能出现的垮坝方式、淹没范围作出预估，并制定应急方案，报防汛指挥机构批准。","level":1},{"name":"第五章 罚 则","text":"第二十九条 违反本条例规定，有下列行为之一的，由大坝主管部门责令其停止违法行为，赔偿损失，采取补救措施，可以并处罚款；应当给予治安管理处罚的，由公安机关依照《中华人民共和国治安管理处罚法》的规定处罚；构成犯罪的，依法追究刑事责任：\n（一）毁坏大坝或者其观测、通信、动力、照明、交通、消防等管理设施的；\n（二）在大坝管理和保护范围内进行爆破、打井、采石、采矿、取土、挖沙、修坟等危害大坝安全活动的；\n（三）擅自操作大坝的泄洪闸门、输水闸门以及其他设施，破坏大坝正常运行的；\n（四）在库区内围垦的；\n（五）在坝体修建码头、渠道或者堆放杂物、晾晒粮草的；\n（六）擅自在大坝管理和保护范围内修建码头、鱼塘的。\n第三十条 盗窃或者抢夺大坝工程设施、器材的，依照刑法规定追究刑事责任。\n第三十一条 由于勘测设计失误、施工质量低劣、调度运用不当以及滥用职权，玩忽职守，导致大坝事故的，由其所在单位或者上级主管机关对责任人员依法给予处分；构成犯罪的，依法追究刑事责任。\n第三十二条 当事人对行政处罚决定不服的，可以依法申请行政复议，也可以依法提起行政诉讼。当事人逾期不申请行政复议或者不向人民法院起诉又不履行行政处罚决定的，由作出行政处罚决定的机关申请人民法院强制执行。\n对治安管理处罚不服的，依照《中华人民共和国治安管理处罚法》的规定办理。","level":1},{"name":"第六章 附 则","text":"第三十三条 国务院有关部门和各省、自治区、直辖市人民政府可以根据本条例制定实施细则。\n第三十四条 本条例自发布之日起施行。","level":1}]},{"id":"n1286","sections":[{"name":"","text":"中华人民共和国注册建筑师条例\n（1995年9月23日中华人民共和国国务院令第184号发布 根据2019年4月23日《国务院关于修改部分行政法规的决定》第一次修订 根据2026年1月30日《国务院关于修改和废止部分行政法规的决定》第二次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强对注册建筑师的管理，提高建筑设计质量与水平，保障公民生命和财产安全，维护社会公共利益，制定本条例。\n第二条 本条例所称注册建筑师，是指依法取得注册建筑师证书并从事房屋建筑设计及相关业务的人员。\n注册建筑师分为一级注册建筑师和二级注册建筑师。\n第三条 注册建筑师的考试、注册和执业，适用本条例。\n第四条 国务院建设行政主管部门、人事行政主管部门和省、自治区、直辖市人民政府建设行政主管部门、人事行政主管部门依照本条例的规定对注册建筑师的考试、注册和执业实施指导和监督。\n第五条 全国注册建筑师管理委员会和省、自治区、直辖市注册建筑师管理委员会，依照本条例的规定负责注册建筑师的考试和注册的具体工作。\n全国注册建筑师管理委员会由国务院建设行政主管部门、人事行政主管部门、其他有关行政主管部门的代表和建筑设计专家组成。\n省、自治区、直辖市注册建筑师管理委员会由省、自治区、直辖市建设行政主管部门、人事行政主管部门、其他有关行政主管部门的代表和建筑设计专家组成。\n第六条 注册建筑师可以组建注册建筑师协会，维护会员的合法权益。","level":1},{"name":"第二章 考试和注册","text":"第七条 国家实行注册建筑师全国统一考试制度。注册建筑师全国统一考试办法，由国务院建设行政主管部门会同国务院人事行政主管部门商国务院其他有关行政主管部门共同制定，由全国注册建筑师管理委员会组织实施。\n第八条 符合下列条件之一的，可以申请参加一级注册建筑师考试：\n（一）取得建筑学硕士以上学位或者相近专业工学博士学位，并从事建筑设计或者相关业务2年以上的；\n（二）取得建筑学学士学位或者相近专业工学硕士学位，并从事建筑设计或者相关业务3年以上的；\n（三）具有建筑学专业大学本科毕业学历并从事建筑设计或者相关业务5年以上的，或者具有建筑学相近专业大学本科毕业学历并从事建筑设计或者相关业务7年以上的；\n（四）取得高级工程师技术职称并从事建筑设计或者相关业务3年以上的，或者取得工程师技术职称并从事建筑设计或者相关业务5年以上的；\n（五）不具有前四项规定的条件，但设计成绩突出，经全国注册建筑师管理委员会认定达到前四项规定的专业水平的。\n前款第三项至第五项规定的人员应当取得学士学位。\n第九条 符合下列条件之一的，可以申请参加二级注册建筑师考试：\n（一）具有建筑学或者相近专业大学本科毕业以上学历，从事建筑设计或者相关业务2年以上的；\n（二）具有建筑设计技术专业或者相近专业大专毕业以上学历，并从事建筑设计或者相关业务3年以上的；\n（三）具有建筑设计技术专业4年制中专毕业学历，并从事建筑设计或者相关业务5年以上的；\n（四）具有建筑设计技术相近专业中专毕业学历，并从事建筑设计或者相关业务7年以上的；\n（五）取得助理工程师以上技术职称，并从事建筑设计或者相关业务3年以上的。\n第十条 本条例施行前已取得高级、中级技术职称的建筑设计人员，经所在单位推荐，可以按照注册建筑师全国统一考试办法的规定，免予部分科目的考试。\n第十一条 注册建筑师考试合格，取得相应的注册建筑师资格的，可以申请注册。\n第十二条 一级注册建筑师的注册，由全国注册建筑师管理委员会负责；二级注册建筑师的注册，由省、自治区、直辖市注册建筑师管理委员会负责。\n第十三条 有下列情形之一的，不予注册：\n（一）不具有完全民事行为能力的；\n（二）因受刑事处罚，自刑罚执行完毕之日起至申请注册之日止不满5年的；\n（三）因在建筑设计或者相关业务中犯有错误受行政处罚或者撤职以上处分，自处罚、处分决定之日起至申请注册之日止不满2年的；\n（四）受吊销注册建筑师证书的行政处罚，自处罚决定之日起至申请注册之日止不满5年的；\n（五）有国务院规定不予注册的其他情形的。\n第十四条 全国注册建筑师管理委员会和省、自治区、直辖市注册建筑师管理委员会依照本条例第十三条的规定，决定不予注册的，应当自决定之日起15日内书面通知申请人；申请人有异议的，可以依法申请行政复议，也可以依法提起行政诉讼。\n第十五条 全国注册建筑师管理委员会应当将准予注册的一级注册建筑师名单报国务院建设行政主管部门备案；省、自治区、直辖市注册建筑师管理委员会应当将准予注册的二级注册建筑师名单报省、自治区、直辖市人民政府建设行政主管部门备案。\n国务院建设行政主管部门或者省、自治区、直辖市人民政府建设行政主管部门发现有关注册建筑师管理委员会的注册不符合本条例规定的，应当通知有关注册建筑师管理委员会撤销注册，收回注册建筑师证书。\n第十六条 准予注册的申请人，分别由全国注册建筑师管理委员会和省、自治区、直辖市注册建筑师管理委员会核发由国务院建设行政主管部门统一制作的一级注册建筑师证书或者二级注册建筑师证书。\n第十七条 注册建筑师注册的有效期为2年。有效期届满需要继续注册的，应当在期满前30日内办理注册手续。\n第十八条 已取得注册建筑师证书的人员，除本条例第十五条第二款规定的情形外，注册后有下列情形之一的，由准予注册的全国注册建筑师管理委员会或者省、自治区、直辖市注册建筑师管理委员会撤销注册，收回注册建筑师证书：\n（一）完全丧失民事行为能力的；\n（二）受刑事处罚的；\n（三）因在建筑设计或者相关业务中犯有错误，受到行政处罚或者撤职以上处分的；\n（四）自行停止注册建筑师业务满2年的。\n被撤销注册的当事人对撤销注册、收回注册建筑师证书有异议的，可以依法申请行政复议，也可以依法提起行政诉讼。\n第十九条 被撤销注册的人员可以依照本条例的规定重新注册。","level":1},{"name":"第三章 执 业","text":"第二十条 注册建筑师的执业范围：\n（一）建筑设计；\n（二）建筑设计技术咨询；\n（三）建筑物调查与鉴定；\n（四）对本人主持设计的项目进行施工指导和监督；\n（五）国务院建设行政主管部门规定的其他业务。\n第二十一条 注册建筑师执行业务，应当加入建筑设计单位。\n建筑设计单位的资质等级及其业务范围，由国务院建设行政主管部门规定。\n第二十二条 一级注册建筑师的执业范围不受建筑规模和工程复杂程度的限制。二级注册建筑师的执业范围不得超越国家规定的建筑规模和工程复杂程度。\n第二十三条 注册建筑师执行业务，由建筑设计单位统一接受委托并统一收费。\n第二十四条 因设计质量造成的经济损失，由建筑设计单位承担赔偿责任；建筑设计单位有权向签字的注册建筑师追偿。","level":1},{"name":"第四章 权利和义务","text":"第二十五条 注册建筑师有权以注册建筑师的名义执行注册建筑师业务。\n非注册建筑师不得以注册建筑师的名义执行注册建筑师业务。二级注册建筑师不得以一级注册建筑师的名义执行业务，也不得超越国家规定的二级注册建筑师的执业范围执行业务。\n第二十六条 国家规定的一定跨度、跨径和高度以上的房屋建筑，应当由注册建筑师进行设计。\n第二十七条 任何单位和个人修改注册建筑师的设计图纸，应当征得该注册建筑师同意；但是，因特殊情况不能征得该注册建筑师同意的除外。\n第二十八条 注册建筑师应当履行下列义务：\n（一）遵守法律、法规和职业道德，维护社会公共利益；\n（二）保证建筑设计的质量，并在其负责的设计图纸上签字；\n（三）保守在执业中知悉的单位和个人的秘密；\n（四）不得同时受聘于二个以上建筑设计单位执行业务；\n（五）不得准许他人以本人名义执行业务。","level":1},{"name":"第五章 法律责任","text":"第二十九条 以不正当手段取得注册建筑师考试合格资格或者注册建筑师证书的，由全国注册建筑师管理委员会或者省、自治区、直辖市注册建筑师管理委员会取消考试合格资格或者吊销注册建筑师证书；对负有直接责任的主管人员和其他直接责任人员，依法给予处分。\n第三十条 未经注册擅自以注册建筑师名义从事注册建筑师业务的，由县级以上人民政府建设行政主管部门责令停止违法活动，没收违法所得，并可以处以违法所得5倍以下的罚款；造成损失的，应当承担赔偿责任。\n第三十一条 注册建筑师违反本条例规定，有下列行为之一的，由县级以上人民政府建设行政主管部门责令停止违法活动，没收违法所得，并可以处以违法所得5倍以下的罚款；情节严重的，可以责令停止执行业务或者由全国注册建筑师管理委员会或者省、自治区、直辖市注册建筑师管理委员会吊销注册建筑师证书：\n（一）以个人名义承接注册建筑师业务、收取费用的；\n（二）同时受聘于二个以上建筑设计单位执行业务的；\n（三）在建筑设计或者相关业务中侵犯他人合法权益的；\n（四）准许他人以本人名义执行业务的；\n（五）二级注册建筑师以一级注册建筑师的名义执行业务或者超越国家规定的执业范围执行业务的。\n第三十二条 因建筑设计质量不合格发生重大责任事故，造成重大损失的，对该建筑设计负有直接责任的注册建筑师，由县级以上人民政府建设行政主管部门责令停止执行业务；情节严重的，由全国注册建筑师管理委员会或者省、自治区、直辖市注册建筑师管理委员会吊销注册建筑师证书。\n第三十三条 违反本条例规定，未经注册建筑师同意擅自修改其设计图纸的，由县级以上人民政府建设行政主管部门责令纠正；造成损失的，应当承担赔偿责任。\n第三十四条 违反本条例规定，构成犯罪的，依法追究刑事责任。","level":1},{"name":"第六章 附 则","text":"第三十五条 本条例所称建筑设计单位，包括专门从事建筑设计的工程设计单位和其他从事建筑设计的工程设计单位。\n第三十六条 外国人申请参加中国注册建筑师全国统一考试和注册以及外国建筑师申请在中国境内执行注册建筑师业务，按照对等原则办理。\n第三十七条 本条例自发布之日起施行。","level":1}]},{"id":"n1287","sections":[{"name":"","text":"城镇排水与污水处理条例\n（2013年10月2日中华人民共和国国务院令第641号公布 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强对城镇排水与污水处理的管理，保障城镇排水与污水处理设施安全运行，防治城镇水污染和内涝灾害，保障公民生命、财产安全和公共安全，保护环境，制定本条例。\n第二条 城镇排水与污水处理的规划，城镇排水与污水处理设施的建设、维护与保护，向城镇排水设施排水与污水处理，以及城镇内涝防治，适用本条例。\n第三条 县级以上人民政府应当加强对城镇排水与污水处理工作的领导，并将城镇排水与污水处理工作纳入国民经济和社会发展规划。\n第四条 城镇排水与污水处理应当遵循尊重自然、统筹规划、配套建设、保障安全、综合利用的原则。\n第五条 国务院住房城乡建设主管部门指导监督全国城镇排水与污水处理工作。\n县级以上地方人民政府城镇排水与污水处理主管部门（以下称城镇排水主管部门）负责本行政区域内城镇排水与污水处理的监督管理工作。\n县级以上人民政府其他有关部门依照本条例和其他有关法律、法规的规定，在各自的职责范围内负责城镇排水与污水处理监督管理的相关工作。\n第六条 国家鼓励采取特许经营、政府购买服务等多种形式，吸引社会资金参与投资、建设和运营城镇排水与污水处理设施。\n县级以上人民政府鼓励、支持城镇排水与污水处理科学技术研究，推广应用先进适用的技术、工艺、设备和材料，促进污水的再生利用和污泥、雨水的资源化利用，提高城镇排水与污水处理能力。","level":1},{"name":"第二章 规划与建设","text":"第七条 国务院住房城乡建设主管部门会同国务院有关部门，编制全国的城镇排水与污水处理规划，明确全国城镇排水与污水处理的中长期发展目标、发展战略、布局、任务以及保障措施等。\n城镇排水主管部门会同有关部门，根据当地经济社会发展水平以及地理、气候特征，编制本行政区域的城镇排水与污水处理规划，明确排水与污水处理目标与标准，排水量与排水模式，污水处理与再生利用、污泥处理处置要求，排涝措施，城镇排水与污水处理设施的规模、布局、建设时序和建设用地以及保障措施等；易发生内涝的城市、镇，还应当编制城镇内涝防治专项规划，并纳入本行政区域的城镇排水与污水处理规划。\n第八条 城镇排水与污水处理规划的编制，应当依据国民经济和社会发展规划、城乡规划、土地利用总体规划、水污染防治规划和防洪规划，并与城镇开发建设、道路、绿地、水系等专项规划相衔接。\n城镇内涝防治专项规划的编制，应当根据城镇人口与规模、降雨规律、暴雨内涝风险等因素，合理确定内涝防治目标和要求，充分利用自然生态系统，提高雨水滞渗、调蓄和排放能力。\n第九条 城镇排水主管部门应当将编制的城镇排水与污水处理规划报本级人民政府批准后组织实施，并报上一级人民政府城镇排水主管部门备案。\n城镇排水与污水处理规划一经批准公布，应当严格执行；因经济社会发展确需修改的，应当按照原审批程序报送审批。\n第十条 县级以上地方人民政府应当根据城镇排水与污水处理规划的要求，加大对城镇排水与污水处理设施建设和维护的投入。\n第十一条 城乡规划和城镇排水与污水处理规划确定的城镇排水与污水处理设施建设用地，不得擅自改变用途。\n第十二条 县级以上地方人民政府应当按照先规划后建设的原则，依据城镇排水与污水处理规划，合理确定城镇排水与污水处理设施建设标准，统筹安排管网、泵站、污水处理厂以及污泥处理处置、再生水利用、雨水调蓄和排放等排水与污水处理设施建设和改造。\n城镇新区的开发和建设，应当按照城镇排水与污水处理规划确定的建设时序，优先安排排水与污水处理设施建设；未建或者已建但未达到国家有关标准的，应当按照年度改造计划进行改造，提高城镇排水与污水处理能力。\n第十三条 县级以上地方人民政府应当按照城镇排涝要求，结合城镇用地性质和条件，加强雨水管网、泵站以及雨水调蓄、超标雨水径流排放等设施建设和改造。\n新建、改建、扩建市政基础设施工程应当配套建设雨水收集利用设施，增加绿地、砂石地面、可渗透路面和自然地面对雨水的滞渗能力，利用建筑物、停车场、广场、道路等建设雨水收集利用设施，削减雨水径流，提高城镇内涝防治能力。\n新区建设与旧城区改建，应当按照城镇排水与污水处理规划确定的雨水径流控制要求建设相关设施。\n第十四条 城镇排水与污水处理规划范围内的城镇排水与污水处理设施建设项目以及需要与城镇排水与污水处理设施相连接的新建、改建、扩建建设工程，城乡规划主管部门在依法核发建设用地规划许可证时，应当征求城镇排水主管部门的意见。城镇排水主管部门应当就排水设计方案是否符合城镇排水与污水处理规划和相关标准提出意见。\n建设单位应当按照排水设计方案建设连接管网等设施；未建设连接管网等设施的，不得投入使用。城镇排水主管部门或者其委托的专门机构应当加强指导和监督。\n第十五条 城镇排水与污水处理设施建设工程竣工后，建设单位应当依法组织竣工验收。竣工验收合格的，方可交付使用，并自竣工验收合格之日起15日内，将竣工验收报告及相关资料报城镇排水主管部门备案。\n第十六条 城镇排水与污水处理设施竣工验收合格后，由城镇排水主管部门通过招标投标、委托等方式确定符合条件的设施维护运营单位负责管理。特许经营合同、委托运营合同涉及污染物削减和污水处理运营服务费的，城镇排水主管部门应当征求环境保护主管部门、价格主管部门的意见。国家鼓励实施城镇污水处理特许经营制度。具体办法由国务院住房城乡建设主管部门会同国务院有关部门制定。\n城镇排水与污水处理设施维护运营单位应当具备下列条件：\n（一）有法人资格；\n（二）有与从事城镇排水与污水处理设施维护运营活动相适应的资金和设备；\n（三）有完善的运行管理和安全管理制度；\n（四）技术负责人和关键岗位人员经专业培训并考核合格；\n（五）有相应的良好业绩和维护运营经验；\n（六）法律、法规规定的其他条件。","level":1},{"name":"第三章 排 水","text":"第十七条 县级以上地方人民政府应当根据当地降雨规律和暴雨内涝风险情况，结合气象、水文资料，建立排水设施地理信息系统，加强雨水排放管理，提高城镇内涝防治水平。\n县级以上地方人民政府应当组织有关部门、单位采取相应的预防治理措施，建立城镇内涝防治预警、会商、联动机制，发挥河道行洪能力和水库、洼淀、湖泊调蓄洪水的功能，加强对城镇排水设施的管理和河道防护、整治，因地制宜地采取定期清淤疏浚等措施，确保雨水排放畅通，共同做好城镇内涝防治工作。\n第十八条 城镇排水主管部门应当按照城镇内涝防治专项规划的要求，确定雨水收集利用设施建设标准，明确雨水的排水分区和排水出路，合理控制雨水径流。\n第十九条 除干旱地区外，新区建设应当实行雨水、污水分流；对实行雨水、污水合流的地区，应当按照城镇排水与污水处理规划要求，进行雨水、污水分流改造。雨水、污水分流改造可以结合旧城区改建和道路建设同时进行。\n在雨水、污水分流地区，新区建设和旧城区改建不得将雨水管网、污水管网相互混接。\n在有条件的地区，应当逐步推进初期雨水收集与处理，合理确定截流倍数，通过设置初期雨水贮存池、建设截流干管等方式，加强对初期雨水的排放调控和污染防治。\n第二十条 城镇排水设施覆盖范围内的排水单位和个人，应当按照国家有关规定将污水排入城镇排水设施。\n在雨水、污水分流地区，不得将污水排入雨水管网。\n第二十一条 从事工业、建筑、餐饮、医疗等活动的企业事业单位、个体工商户（以下称排水户）向城镇排水设施排放污水的，应当向城镇排水主管部门申请领取污水排入排水管网许可证。城镇排水主管部门应当按照国家有关标准，重点对影响城镇排水与污水处理设施安全运行的事项进行审查。\n排水户应当按照污水排入排水管网许可证的要求排放污水。\n第二十二条 排水户申请领取污水排入排水管网许可证应当具备下列条件：\n（一）排放口的设置符合城镇排水与污水处理规划的要求；\n（二）按照国家有关规定建设相应的预处理设施和水质、水量检测设施；\n（三）排放的污水符合国家或者地方规定的有关排放标准；\n（四）法律、法规规定的其他条件。\n符合前款规定条件的，由城镇排水主管部门核发污水排入排水管网许可证；具体办法由国务院住房城乡建设主管部门制定。\n第二十三条 城镇排水主管部门应当加强对排放口设置以及预处理设施和水质、水量检测设施建设的指导和监督；对不符合规划要求或者国家有关规定的，应当要求排水户采取措施，限期整改。\n第二十四条 城镇排水主管部门委托的排水监测机构，应当对排水户排放污水的水质和水量进行监测，并建立排水监测档案。排水户应当接受监测，如实提供有关资料。\n实行排污许可重点管理的排水户安装的水污染物排放自动监测设备，应当与环境保护主管部门的监控设备联网。环境保护主管部门应当将监测数据与城镇排水主管部门共享。\n第二十五条 因城镇排水设施维护或者检修可能对排水造成影响的，城镇排水设施维护运营单位应当提前24小时通知相关排水户；可能对排水造成严重影响的，应当事先向城镇排水主管部门报告，采取应急处理措施，并向社会公告。\n第二十六条 设置于机动车道路上的窨井，应当按照国家有关规定进行建设，保证其承载力和稳定性等符合相关要求。\n排水管网窨井盖应当具备防坠落和防盗窃功能，满足结构强度要求。\n第二十七条 城镇排水主管部门应当按照国家有关规定建立城镇排涝风险评估制度和灾害后评估制度，在汛前对城镇排水设施进行全面检查，对发现的问题，责成有关单位限期处理，并加强城镇广场、立交桥下、地下构筑物、棚户区等易涝点的治理，强化排涝措施，增加必要的强制排水设施和装备。\n城镇排水设施维护运营单位应当按照防汛要求，对城镇排水设施进行全面检查、维护、清疏，确保设施安全运行。\n在汛期，有管辖权的人民政府防汛指挥机构应当加强对易涝点的巡查，发现险情，立即采取措施。有关单位和个人在汛期应当服从有管辖权的人民政府防汛指挥机构的统一调度指挥或者监督。","level":1},{"name":"第四章 污水处理","text":"第二十八条 城镇排水主管部门应当与城镇污水处理设施维护运营单位签订维护运营合同，明确双方权利义务。\n城镇污水处理设施维护运营单位应当依照法律、法规和有关规定以及维护运营合同进行维护运营，定期向社会公开有关维护运营信息，并接受相关部门和社会公众的监督。\n第二十九条 城镇污水处理设施维护运营单位应当保证出水水质符合国家和地方规定的排放标准，不得排放不达标污水。\n城镇污水处理设施维护运营单位应当按照国家有关规定检测进出水水质，向城镇排水主管部门、环境保护主管部门报送污水处理水质和水量、主要污染物削减量等信息，并按照有关规定和维护运营合同，向城镇排水主管部门报送生产运营成本等信息。\n城镇污水处理设施维护运营单位应当按照国家有关规定向价格主管部门提交相关成本信息。\n城镇排水主管部门核定城镇污水处理运营成本，应当考虑主要污染物削减情况。\n第三十条 城镇污水处理设施维护运营单位或者污泥处理处置单位应当安全处理处置污泥，保证处理处置后的污泥符合国家有关标准，对产生的污泥以及处理处置后的污泥去向、用途、用量等进行跟踪、记录，并向城镇排水主管部门、环境保护主管部门报告。任何单位和个人不得擅自倾倒、堆放、丢弃、抛撒、遗撒或者焚烧污泥。\n第三十一条 城镇污水处理设施维护运营单位不得擅自停运城镇污水处理设施，因检修等原因需要停运或者部分停运城镇污水处理设施的，应当在90个工作日前向城镇排水主管部门、环境保护主管部门报告。\n城镇污水处理设施维护运营单位在出现进水水质和水量发生重大变化可能导致出水水质超标，或者发生影响城镇污水处理设施安全运行的突发情况时，应当立即采取应急处理措施，并向城镇排水主管部门、环境保护主管部门报告。\n城镇排水主管部门或者环境保护主管部门接到报告后，应当及时核查处理。\n第三十二条 排水单位和个人应当按照国家有关规定缴纳污水处理费。\n向城镇污水处理设施排放污水、缴纳污水处理费的，不再缴纳排污费。\n排水监测机构接受城镇排水主管部门委托从事有关监测活动，不得向城镇污水处理设施维护运营单位和排水户收取任何费用。\n第三十三条 污水处理费应当纳入地方财政预算管理，专项用于城镇污水处理设施的建设、运行和污泥处理处置，不得挪作他用。污水处理费的收费标准不应低于城镇污水处理设施正常运营的成本。因特殊原因，收取的污水处理费不足以支付城镇污水处理设施正常运营的成本的，地方人民政府给予补贴。\n污水处理费的收取、使用情况应当向社会公开。\n第三十四条 县级以上地方人民政府环境保护主管部门应当依法对城镇污水处理设施的出水水质和水量进行监督检查。\n城镇排水主管部门应当对城镇污水处理设施运营情况进行监督和考核，并将监督考核情况向社会公布。有关单位和个人应当予以配合。\n城镇污水处理设施维护运营单位应当为进出水在线监测系统的安全运行提供保障条件。\n第三十五条 城镇排水主管部门应当根据城镇污水处理设施维护运营单位履行维护运营合同的情况以及环境保护主管部门对城镇污水处理设施出水水质和水量的监督检查结果，核定城镇污水处理设施运营服务费。地方人民政府有关部门应当及时、足额拨付城镇污水处理设施运营服务费。\n第三十六条 城镇排水主管部门在监督考核中，发现城镇污水处理设施维护运营单位存在未依照法律、法规和有关规定以及维护运营合同进行维护运营，擅自停运或者部分停运城镇污水处理设施，或者其他无法安全运行等情形的，应当要求城镇污水处理设施维护运营单位采取措施，限期整改；逾期不整改的，或者整改后仍无法安全运行的，城镇排水主管部门可以终止维护运营合同。\n城镇排水主管部门终止与城镇污水处理设施维护运营单位签订的维护运营合同的，应当采取有效措施保障城镇污水处理设施的安全运行。\n第三十七条 国家鼓励城镇污水处理再生利用，工业生产、城市绿化、道路清扫、车辆冲洗、建筑施工以及生态景观等，应当优先使用再生水。\n县级以上地方人民政府应当根据当地水资源和水环境状况，合理确定再生水利用的规模，制定促进再生水利用的保障措施。\n再生水纳入水资源统一配置，县级以上地方人民政府水行政主管部门应当依法加强指导。","level":1},{"name":"第五章 设施维护与保护","text":"第三十八条 城镇排水与污水处理设施维护运营单位应当建立健全安全生产管理制度，加强对窨井盖等城镇排水与污水处理设施的日常巡查、维修和养护，保障设施安全运行。\n从事管网维护、应急排水、井下及有限空间作业的，设施维护运营单位应当安排专门人员进行现场安全管理，设置醒目警示标志，采取有效措施避免人员坠落、车辆陷落，并及时复原窨井盖，确保操作规程的遵守和安全措施的落实。相关特种作业人员，应当按照国家有关规定取得相应的资格证书。\n第三十九条 县级以上地方人民政府应当根据实际情况，依法组织编制城镇排水与污水处理应急预案，统筹安排应对突发事件以及城镇排涝所必需的物资。\n城镇排水与污水处理设施维护运营单位应当制定本单位的应急预案，配备必要的抢险装备、器材，并定期组织演练。\n第四十条 排水户因发生事故或者其他突发事件，排放的污水可能危及城镇排水与污水处理设施安全运行的，应当立即采取措施消除危害，并及时向城镇排水主管部门和环境保护主管部门等有关部门报告。\n城镇排水与污水处理安全事故或者突发事件发生后，设施维护运营单位应当立即启动本单位应急预案，采取防护措施、组织抢修，并及时向城镇排水主管部门和有关部门报告。\n第四十一条 城镇排水主管部门应当会同有关部门，按照国家有关规定划定城镇排水与污水处理设施保护范围，并向社会公布。\n在保护范围内，有关单位从事爆破、钻探、打桩、顶进、挖掘、取土等可能影响城镇排水与污水处理设施安全的活动的，应当与设施维护运营单位等共同制定设施保护方案，并采取相应的安全防护措施。\n第四十二条 禁止从事下列危及城镇排水与污水处理设施安全的活动：\n（一）损毁、盗窃城镇排水与污水处理设施；\n（二）穿凿、堵塞城镇排水与污水处理设施；\n（三）向城镇排水与污水处理设施排放、倾倒剧毒、易燃易爆、腐蚀性废液和废渣；\n（四）向城镇排水与污水处理设施倾倒垃圾、渣土、施工泥浆等废弃物；\n（五）建设占压城镇排水与污水处理设施的建筑物、构筑物或者其他设施；\n（六）其他危及城镇排水与污水处理设施安全的活动。\n第四十三条 新建、改建、扩建建设工程，不得影响城镇排水与污水处理设施安全。\n建设工程开工前，建设单位应当查明工程建设范围内地下城镇排水与污水处理设施的相关情况。城镇排水主管部门及其他相关部门和单位应当及时提供相关资料。\n建设工程施工范围内有排水管网等城镇排水与污水处理设施的，建设单位应当与施工单位、设施维护运营单位共同制定设施保护方案，并采取相应的安全保护措施。\n因工程建设需要拆除、改动城镇排水与污水处理设施的，建设单位应当制定拆除、改动方案，报城镇排水主管部门审核，并承担重建、改建和采取临时措施的费用。\n第四十四条 县级以上人民政府城镇排水主管部门应当会同有关部门，加强对城镇排水与污水处理设施运行维护和保护情况的监督检查，并将检查情况及结果向社会公开。实施监督检查时，有权采取下列措施：\n（一）进入现场进行检查、监测；\n（二）查阅、复制有关文件和资料；\n（三）要求被监督检查的单位和个人就有关问题作出说明。\n被监督检查的单位和个人应当予以配合，不得妨碍和阻挠依法进行的监督检查活动。\n第四十五条 审计机关应当加强对城镇排水与污水处理设施建设、运营、维护和保护等资金筹集、管理和使用情况的监督，并公布审计结果。","level":1},{"name":"第六章 法律责任","text":"第四十六条 违反本条例规定，县级以上地方人民政府及其城镇排水主管部门和其他有关部门，不依法作出行政许可或者办理批准文件的，发现违法行为或者接到对违法行为的举报不予查处的，或者有其他未依照本条例履行职责的行为的，对直接负责的主管人员和其他直接责任人员依法给予处分；直接负责的主管人员和其他直接责任人员的行为构成犯罪的，依法追究刑事责任。\n违反本条例规定，核发污水排入排水管网许可证、排污许可证后不实施监督检查的，对核发许可证的部门及其工作人员依照前款规定处理。\n第四十七条 违反本条例规定，城镇排水主管部门对不符合法定条件的排水户核发污水排入排水管网许可证的，或者对符合法定条件的排水户不予核发污水排入排水管网许可证的，对直接负责的主管人员和其他直接责任人员依法给予处分；直接负责的主管人员和其他直接责任人员的行为构成犯罪的，依法追究刑事责任。\n第四十八条 违反本条例规定，在雨水、污水分流地区，建设单位、施工单位将雨水管网、污水管网相互混接的，由城镇排水主管部门责令改正，处5万元以上10万元以下的罚款；造成损失的，依法承担赔偿责任。\n第四十九条 违反本条例规定，城镇排水与污水处理设施覆盖范围内的排水单位和个人，未按照国家有关规定将污水排入城镇排水设施，或者在雨水、污水分流地区将污水排入雨水管网的，由城镇排水主管部门责令改正，给予警告；逾期不改正或者造成严重后果的，对单位处10万元以上20万元以下罚款，对个人处2万元以上10万元以下罚款；造成损失的，依法承担赔偿责任。\n第五十条 违反本条例规定，排水户未取得污水排入排水管网许可证向城镇排水设施排放污水的，由城镇排水主管部门责令停止违法行为，限期采取治理措施，补办污水排入排水管网许可证，可以处50万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。\n违反本条例规定，排水户不按照污水排入排水管网许可证的要求排放污水的，由城镇排水主管部门责令停止违法行为，限期改正，可以处5万元以下罚款；造成严重后果的，吊销污水排入排水管网许可证，并处5万元以上50万元以下罚款，可以向社会予以通报；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第五十一条 违反本条例规定，因城镇排水设施维护或者检修可能对排水造成影响或者严重影响，城镇排水设施维护运营单位未提前通知相关排水户的，或者未事先向城镇排水主管部门报告，采取应急处理措施的，或者未按照防汛要求对城镇排水设施进行全面检查、维护、清疏，影响汛期排水畅通的，由城镇排水主管部门责令改正，给予警告；逾期不改正或者造成严重后果的，处10万元以上20万元以下罚款；造成损失的，依法承担赔偿责任。\n第五十二条 违反本条例规定，城镇污水处理设施维护运营单位未按照国家有关规定检测进出水水质的，或者未报送污水处理水质和水量、主要污染物削减量等信息和生产运营成本等信息的，由城镇排水主管部门责令改正，可以处5万元以下罚款；造成损失的，依法承担赔偿责任。\n违反本条例规定，城镇污水处理设施维护运营单位擅自停运城镇污水处理设施，未按照规定事先报告或者采取应急处理措施的，由城镇排水主管部门责令改正，给予警告；逾期不改正或者造成严重后果的，处10万元以上50万元以下罚款；造成损失的，依法承担赔偿责任。\n第五十三条 违反本条例规定，城镇污水处理设施维护运营单位或者污泥处理处置单位对产生的污泥以及处理处置后的污泥的去向、用途、用量等未进行跟踪、记录的，或者处理处置后的污泥不符合国家有关标准的，由城镇排水主管部门责令限期采取治理措施，给予警告；造成严重后果的，处10万元以上20万元以下罚款；逾期不采取治理措施的，城镇排水主管部门可以指定有治理能力的单位代为治理，所需费用由当事人承担；造成损失的，依法承担赔偿责任。\n违反本条例规定，擅自倾倒、堆放、丢弃、抛撒、遗撒或者焚烧污泥的，由城镇排水主管部门责令停止违法行为，采取治理措施消除污染，没收违法所得，并处20万元以上200万元以下的罚款；对直接负责的主管人员和其他直接责任人员处2万元以上10万元以下的罚款；情节严重的，责令限制生产、停产整治；造成严重后果的，处200万元以上500万元以下的罚款；拒不采取治理措施的，指定有治理能力的单位代为治理，所需费用由违法者承担。\n第五十四条 违反本条例规定，排水单位或者个人不缴纳污水处理费的，由城镇排水主管部门责令限期缴纳，逾期拒不缴纳的，处应缴纳污水处理费数额1倍以上3倍以下罚款。\n第五十五条 违反本条例规定，城镇排水与污水处理设施维护运营单位有下列情形之一的，由城镇排水主管部门责令改正，给予警告；逾期不改正或者造成严重后果的，处10万元以上50万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任：\n（一）未按照国家有关规定履行日常巡查、维修和养护责任，保障设施安全运行的；\n（二）未及时采取防护措施、组织事故抢修的；\n（三）因巡查、维护不到位，导致窨井盖丢失、损毁，造成人员伤亡和财产损失的。\n第五十六条 违反本条例规定，从事危及城镇排水与污水处理设施安全的活动的，由城镇排水主管部门责令停止违法行为，限期恢复原状或者采取其他补救措施，给予警告；逾期不采取补救措施或者造成严重后果的，对单位处10万元以上30万元以下罚款，对个人处2万元以上10万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。\n第五十七条 违反本条例规定，有关单位未与施工单位、设施维护运营单位等共同制定设施保护方案，并采取相应的安全防护措施的，由城镇排水主管部门责令改正，处2万元以上5万元以下罚款；造成严重后果的，处5万元以上10万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。\n违反本条例规定，擅自拆除、改动城镇排水与污水处理设施的，由城镇排水主管部门责令改正，恢复原状或者采取其他补救措施，处5万元以上10万元以下罚款；造成严重后果的，处10万元以上30万元以下罚款；造成损失的，依法承担赔偿责任；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附 则","text":"第五十八条 依照《中华人民共和国生态环境法典》的规定，排水户需要取得排污许可证的，由环境保护主管部门核发；违反《中华人民共和国生态环境法典》的规定排放污水的，由环境保护主管部门处罚。\n第五十九条 本条例自2014年1月1日起施行。","level":1}]},{"id":"n1288","sections":[{"name":"","text":"黄河水量调度条例\n（2006年7月24日中华人民共和国国务院令第472号公布 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》修订）","level":0},{"name":"第一章 总 则","text":"第一条 为加强黄河水量的统一调度，实现黄河水资源的可持续利用，促进黄河流域及相关地区经济社会发展和生态环境的改善，根据《中华人民共和国水法》，制定本条例。\n第二条 黄河流域的青海省、四川省、甘肃省、宁夏回族自治区、内蒙古自治区、陕西省、山西省、河南省、山东省，以及国务院批准取用黄河水的河北省、天津市（以下称十一省区市）的黄河水量调度和管理，适用本条例。\n第三条 国家对黄河水量实行统一调度，遵循总量控制、断面流量控制、分级管理、分级负责的原则。\n实施黄河水量调度，应当首先满足城乡居民生活用水的需要，合理安排农业、工业、生态环境用水，防止黄河断流。\n第四条 黄河水量调度计划、调度方案和调度指令的执行，实行地方人民政府行政首长负责制和黄河水利委员会及其所属管理机构以及水库主管部门或者单位主要领导负责制。\n第五条 国务院水行政主管部门和国务院发展改革主管部门负责组织、协调、监督、指导黄河水量调度工作。\n黄河水利委员会依照本条例的规定负责黄河水量调度的组织实施和监督检查工作。\n有关县级以上地方人民政府水行政主管部门和黄河水利委员会所属管理机构，依照本条例的规定负责所辖范围内黄河水量调度的实施和监督检查工作。\n第六条 在黄河水量调度工作中做出显著成绩的单位和个人，由有关县级以上人民政府或者有关部门给予奖励。","level":1},{"name":"第二章 水量分配","text":"第七条 黄河水量分配方案，由黄河水利委员会商十一省区市人民政府制订，经国务院发展改革主管部门和国务院水行政主管部门审查，报国务院批准。\n国务院批准的黄河水量分配方案，是黄河水量调度的依据，有关地方人民政府和黄河水利委员会及其所属管理机构必须执行。\n第八条 制订黄河水量分配方案，应当遵循下列原则：\n（一）依据流域规划和水中长期供求规划；\n（二）坚持计划用水、节约用水；\n（三）充分考虑黄河流域水资源条件，取用水现状、供需情况及发展趋势，发挥黄河水资源的综合效益；\n（四）统筹兼顾生活、生产、生态环境用水；\n（五）正确处理上下游、左右岸的关系；\n（六）科学确定河道输沙入海水量和可供水量。\n前款所称可供水量，是指在黄河流域干、支流多年平均天然年径流量中，除必需的河道输沙入海水量外，可供城乡居民生活、农业、工业及河道外生态环境用水的最大水量。\n第九条 黄河水量分配方案需要调整的，应当由黄河水利委员会商十一省区市人民政府提出方案，经国务院发展改革主管部门和国务院水行政主管部门审查，报国务院批准。","level":1},{"name":"第三章 水量调度","text":"第十条 黄河水量调度实行年度水量调度计划与月、旬水量调度方案和实时调度指令相结合的调度方式。\n黄河水量调度年度为当年7月1日至次年6月30日。\n第十一条 黄河干、支流的年度和月用水计划建议与水库运行计划建议，由十一省区市人民政府水行政主管部门和河南、山东黄河河务局以及水库管理单位，按照调度管理权限和规定的时间向黄河水利委员会申报。河南、山东黄河河务局申报黄河干流的用水计划建议时，应当商河南省、山东省人民政府水行政主管部门。\n第十二条 年度水量调度计划由黄河水利委员会商十一省区市人民政府水行政主管部门和河南、山东黄河河务局以及水库管理单位制订，报国务院水行政主管部门批准并下达，同时抄送国务院发展改革主管部门。\n经批准的年度水量调度计划，是确定月、旬水量调度方案和年度黄河干、支流用水量控制指标的依据。年度水量调度计划应当纳入本级国民经济和社会发展年度计划。\n第十三条 年度水量调度计划，应当依据经批准的黄河水量分配方案和年度预测来水量、水库蓄水量，按照同比例丰增枯减、多年调节水库蓄丰补枯的原则，在综合平衡申报的年度用水计划建议和水库运行计划建议的基础上制订。\n第十四条 黄河水利委员会应当根据经批准的年度水量调度计划和申报的月用水计划建议、水库运行计划建议，制订并下达月水量调度方案；用水高峰时，应当根据需要制订并下达旬水量调度方案。\n第十五条 黄河水利委员会根据实时水情、雨情、旱情、墒情、水库蓄水量及用水情况，可以对已下达的月、旬水量调度方案作出调整，下达实时调度指令。\n第十六条 青海省、四川省、甘肃省、宁夏回族自治区、内蒙古自治区、陕西省、山西省境内黄河干、支流的水量，分别由各省级人民政府水行政主管部门负责调度；河南省、山东省境内黄河干流的水量，分别由河南、山东黄河河务局负责调度，支流的水量，分别由河南省、山东省人民政府水行政主管部门负责调度；调入河北省、天津市的黄河水量，分别由河北省、天津市人民政府水行政主管部门负责调度。\n市、县级人民政府水行政主管部门和黄河水利委员会所属管理机构，负责所辖范围内分配水量的调度。\n实施黄河水量调度，必须遵守经批准的年度水量调度计划和下达的月、旬水量调度方案以及实时调度指令。\n第十七条 龙羊峡、刘家峡、万家寨、三门峡、小浪底、西霞院、故县、东平湖等水库，由黄河水利委员会组织实施水量调度，下达月、旬水量调度方案及实时调度指令；必要时，黄河水利委员会可以对大峡、沙坡头、青铜峡、三盛公、陆浑等水库组织实施水量调度，下达实时调度指令。\n水库主管部门或者单位具体负责实施所辖水库的水量调度，并按照水量调度指令做好发电计划的安排。\n第十八条 黄河水量调度实行水文断面流量控制。黄河干流水文断面的流量控制指标，由黄河水利委员会规定；重要支流水文断面及其流量控制指标，由黄河水利委员会会同黄河流域有关省、自治区人民政府水行政主管部门规定。\n青海省、甘肃省、宁夏回族自治区、内蒙古自治区、河南省、山东省人民政府，分别负责并确保循化、下河沿、石嘴山、头道拐、高村、利津水文断面的下泄流量符合规定的控制指标；陕西省和山西省人民政府共同负责并确保潼关水文断面的下泄流量符合规定的控制指标。\n龙羊峡、刘家峡、万家寨、三门峡、小浪底水库的主管部门或者单位，分别负责并确保贵德、小川、万家寨、三门峡、小浪底水文断面的出库流量符合规定的控制指标。\n第十九条 黄河干、支流省际或者重要控制断面和出库流量控制断面的下泄流量以国家设立的水文站监测数据为依据。对水文监测数据有争议的，以黄河水利委员会确认的水文监测数据为准。\n第二十条 需要在年度水量调度计划外使用其他省、自治区、直辖市计划内水量分配指标的，应当向黄河水利委员会提出申请，由黄河水利委员会组织有关各方在协商一致的基础上提出方案，报国务院水行政主管部门批准后组织实施。","level":1},{"name":"第四章 应急调度","text":"第二十一条 出现严重干旱、省际或者重要控制断面流量降至预警流量、水库运行故障、重大水污染事故等情况，可能造成供水危机、黄河断流时，黄河水利委员会应当组织实施应急调度。\n第二十二条 黄河水利委员会应当商十一省区市人民政府以及水库主管部门或者单位，制订旱情紧急情况下的水量调度预案，经国务院水行政主管部门审查，报国务院或者国务院授权的部门批准。\n第二十三条 十一省区市人民政府水行政主管部门和河南、山东黄河河务局以及水库管理单位，应当根据经批准的旱情紧急情况下的水量调度预案，制订实施方案，并抄送黄河水利委员会。\n第二十四条 出现旱情紧急情况时，经国务院水行政主管部门同意，由黄河水利委员会组织实施旱情紧急情况下的水量调度预案，并及时调整取水及水库出库流量控制指标；必要时，可以对黄河流域有关省、自治区主要取水口实行直接调度。\n县级以上地方人民政府、水库管理单位应当按照旱情紧急情况下的水量调度预案及其实施方案，合理安排用水计划，确保省际或者重要控制断面和出库流量控制断面的下泄流量符合规定的控制指标。\n第二十五条 出现旱情紧急情况时，十一省区市人民政府水行政主管部门和河南、山东黄河河务局以及水库管理单位，应当每日向黄河水利委员会报送取（退）水及水库蓄（泄）水情况。\n第二十六条 出现省际或者重要控制断面流量降至预警流量、水库运行故障以及重大水污染事故等情况时，黄河水利委员会及其所属管理机构、有关省级人民政府及其水行政主管部门和环境保护主管部门以及水库管理单位，应当根据需要，按照规定的权限和职责，及时采取压减取水量直至关闭取水口、实施水库应急泄流方案、加强水文监测、对排污企业实行限产或者停产等处置措施，有关部门和单位必须服从。\n省际或者重要控制断面的预警流量，由黄河水利委员会确定。\n第二十七条 实施应急调度，需要动用水库死库容的，由黄河水利委员会商有关水库主管部门或者单位，制订动用水库死库容的水量调度方案，经国务院水行政主管部门审查，报国务院或者国务院授权的部门批准实施。","level":1},{"name":"第五章 监督管理","text":"第二十八条 黄河水利委员会及其所属管理机构和县级以上地方人民政府水行政主管部门应当加强对所辖范围内水量调度执行情况的监督检查。\n第二十九条 十一省区市人民政府水行政主管部门和河南、山东黄河河务局，应当按照国务院水行政主管部门规定的时间，向黄河水利委员会报送所辖范围内取（退）水量报表。\n第三十条 黄河水量调度文书格式，由黄河水利委员会编制、公布，并报国务院水行政主管部门备案。\n第三十一条 黄河水利委员会应当定期将黄河水量调度执行情况向十一省区市人民政府水行政主管部门以及水库主管部门或者单位通报，并及时向社会公告。\n第三十二条 黄河水利委员会及其所属管理机构、县级以上地方人民政府水行政主管部门，应当在各自的职责范围内实施巡回监督检查，在用水高峰时对主要取（退）水口实施重点监督检查，在特殊情况下对有关河段、水库、主要取（退）水口进行驻守监督检查；发现重点污染物排放总量超过控制指标或者水体严重污染时，应当及时通报有关人民政府环境保护主管部门。\n第三十三条 黄河水利委员会及其所属管理机构、县级以上地方人民政府水行政主管部门实施监督检查时，有权采取下列措施：\n（一）要求被检查单位提供有关文件和资料，进行查阅或者复制；\n（二）要求被检查单位就执行本条例的有关问题进行说明；\n（三）进入被检查单位生产场所进行现场检查；\n（四）对取（退）水量进行现场监测；\n（五）责令被检查单位纠正违反本条例的行为。\n第三十四条 监督检查人员在履行监督检查职责时，应当向被检查单位或者个人出示执法证件，被检查单位或者个人应当接受和配合监督检查工作，不得拒绝或者妨碍监督检查人员依法执行公务。","level":1},{"name":"第六章 法律责任","text":"第三十五条 违反本条例规定，有下列行为之一的，对负有责任的主管人员和其他直接责任人员，由其上级主管部门、单位或者监察机关依法给予处分：\n（一）不制订年度水量调度计划的；\n（二）不及时下达月、旬水量调度方案的；\n（三）不制订旱情紧急情况下的水量调度预案及其实施方案和动用水库死库容水量调度方案的。\n第三十六条 违反本条例规定，有下列行为之一的，对负有责任的主管人员和其他直接责任人员，由其上级主管部门、单位或者监察机关依法给予处分；造成严重后果，构成犯罪的，依法追究刑事责任：\n（一）不执行年度水量调度计划和下达的月、旬水量调度方案以及实时调度指令的；\n（二）不执行旱情紧急情况下的水量调度预案及其实施方案、水量调度应急处置措施和动用水库死库容水量调度方案的；\n（三）不履行监督检查职责或者发现违法行为不予查处的；\n（四）其他滥用职权、玩忽职守等违法行为。\n第三十七条 省际或者重要控制断面下泄流量不符合规定的控制指标的，由黄河水利委员会予以通报，责令限期改正；逾期不改正的，按照控制断面下泄流量的缺水量，在下一调度时段加倍扣除；对控制断面下游水量调度产生严重影响或者造成其他严重后果的，本年度不再新增该省、自治区的取水工程项目。对负有责任的主管人员和其他直接责任人员，由其上级主管部门、单位或者监察机关依法给予处分。\n第三十八条 水库出库流量控制断面的下泄流量不符合规定的控制指标，对控制断面下游水量调度产生严重影响的，对负有责任的主管人员和其他直接责任人员，由其上级主管部门、单位或者监察机关依法给予处分。\n第三十九条 违反本条例规定，有关用水单位或者水库管理单位有下列行为之一的，由县级以上地方人民政府水行政主管部门或者黄河水利委员会及其所属管理机构按照管理权限，责令停止违法行为，给予警告，限期采取补救措施，并处2万元以上10万元以下罚款；对负有责任的主管人员和其他直接责任人员，由其上级主管部门、单位或者监察机关依法给予处分：\n（一）虚假填报或者篡改上报的水文监测数据、取用水量数据或者水库运行情况等资料的；\n（二）水库管理单位不执行水量调度方案和实时调度指令的；\n（三）超计划取用水的。\n第四十条 违反本条例规定，有下列行为之一的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任：\n（一）妨碍、阻挠监督检查人员或者取用水工程管理人员依法执行公务的；\n（二）在水量调度中煽动群众闹事的。","level":1},{"name":"第七章 附 则","text":"第四十一条 黄河水量调度中，有关用水计划建议和水库运行计划建议申报时间，年度水量调度计划制订、下达时间，月、旬水量调度方案下达时间，取（退）水水量报表报送时间等，由国务院水行政主管部门规定。\n第四十二条 在黄河水量调度中涉及水资源保护、防洪、防凌和水污染防治的，依照《中华人民共和国生态环境法典》、《中华人民共和国黄河保护法》、《中华人民共和国水法》和《中华人民共和国防洪法》的有关规定执行。\n第四十三条 本条例自2006年8月1日起施行。","level":1}]},{"id":"n1289","sections":[{"name":"","text":"民用建筑节能条例\n（2008年8月1日中华人民共和国国务院令第530号公布 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强民用建筑节能管理，降低民用建筑使用过程中的能源消耗，提高能源利用效率，制定本条例。\n第二条 本条例所称民用建筑节能，是指在保证民用建筑使用功能和室内热环境质量的前提下，降低其使用过程中能源消耗的活动。\n本条例所称民用建筑，是指居住建筑、国家机关办公建筑和商业、服务业、教育、卫生等其他公共建筑。\n第三条 各级人民政府应当加强对民用建筑节能工作的领导，积极培育民用建筑节能服务市场，健全民用建筑节能服务体系，推动民用建筑节能技术的开发应用，做好民用建筑节能知识的宣传教育工作。\n第四条 国家鼓励和扶持在新建建筑和既有建筑节能改造中采用太阳能、地热能等可再生能源。\n在具备太阳能利用条件的地区，有关地方人民政府及其部门应当采取有效措施，鼓励和扶持单位、个人安装使用太阳能热水系统、照明系统、供热系统、采暖制冷系统等太阳能利用系统。\n第五条 国务院建设主管部门负责全国民用建筑节能的监督管理工作。县级以上地方人民政府建设主管部门负责本行政区域民用建筑节能的监督管理工作。\n县级以上人民政府有关部门应当依照本条例的规定以及本级人民政府规定的职责分工，负责民用建筑节能的有关工作。\n第六条 国务院建设主管部门应当在国家节能中长期专项规划指导下，编制全国民用建筑节能规划，并与相关规划相衔接。\n县级以上地方人民政府建设主管部门应当组织编制本行政区域的民用建筑节能规划，报本级人民政府批准后实施。\n第七条 国家建立健全民用建筑节能标准体系。国家民用建筑节能标准由国务院建设主管部门负责组织制定，并依照法定程序发布。\n国家鼓励制定、采用优于国家民用建筑节能标准的地方民用建筑节能标准。\n第八条 县级以上人民政府应当安排民用建筑节能资金，用于支持民用建筑节能的科学技术研究和标准制定、既有建筑围护结构和供热系统的节能改造、可再生能源的应用，以及民用建筑节能示范工程、节能项目的推广。\n政府引导金融机构对既有建筑节能改造、可再生能源的应用，以及民用建筑节能示范工程等项目提供支持。\n民用建筑节能项目依法享受税收优惠。\n第九条 国家积极推进供热体制改革，完善供热价格形成机制，鼓励发展集中供热，逐步实行按照用热量收费制度。\n第十条 对在民用建筑节能工作中做出显著成绩的单位和个人，按照国家有关规定给予表彰和奖励。","level":1},{"name":"第二章 新建建筑节能","text":"第十一条 国家推广使用民用建筑节能的新技术、新工艺、新材料和新设备，限制使用或者禁止使用能源消耗高的技术、工艺、材料和设备。国务院节能工作主管部门、建设主管部门应当制定、公布并及时更新推广使用、限制使用、禁止使用目录。\n国家限制进口或者禁止进口能源消耗高的技术、材料和设备。\n建设单位、设计单位、施工单位不得在建筑活动中使用列入禁止使用目录的技术、工艺、材料和设备。\n第十二条 编制城市详细规划、镇详细规划，应当按照民用建筑节能的要求，确定建筑的布局、形状和朝向。\n城乡规划主管部门依法对民用建筑进行规划审查，应当就设计方案是否符合民用建筑节能强制性标准征求同级建设主管部门的意见；建设主管部门应当自收到征求意见材料之日起10日内提出意见。征求意见时间不计算在规划许可的期限内。\n对不符合民用建筑节能强制性标准的，不得颁发建设工程规划许可证。\n第十三条 施工图设计文件审查机构应当按照民用建筑节能强制性标准对施工图设计文件进行审查；经审查不符合民用建筑节能强制性标准的，县级以上地方人民政府建设主管部门不得颁发施工许可证。\n第十四条 建设单位不得明示或者暗示设计单位、施工单位违反民用建筑节能强制性标准进行设计、施工，不得明示或者暗示施工单位使用不符合施工图设计文件要求的墙体材料、保温材料、门窗、采暖制冷系统和照明设备。\n按照合同约定由建设单位采购墙体材料、保温材料、门窗、采暖制冷系统和照明设备的，建设单位应当保证其符合施工图设计文件要求。\n第十五条 设计单位、施工单位、工程监理单位及其注册执业人员，应当按照民用建筑节能强制性标准进行设计、施工、监理。\n第十六条 施工单位应当对进入施工现场的墙体材料、保温材料、门窗、采暖制冷系统和照明设备进行查验；不符合施工图设计文件要求的，不得使用。\n工程监理单位发现施工单位不按照民用建筑节能强制性标准施工的，应当要求施工单位改正；施工单位拒不改正的，工程监理单位应当及时报告建设单位，并向有关主管部门报告。\n墙体、屋面的保温工程施工时，监理工程师应当按照工程监理规范的要求，采取旁站、巡视和平行检验等形式实施监理。\n未经监理工程师签字，墙体材料、保温材料、门窗、采暖制冷系统和照明设备不得在建筑上使用或者安装，施工单位不得进行下一道工序的施工。\n第十七条 建设单位组织竣工验收，应当对民用建筑是否符合民用建筑节能强制性标准进行查验；对不符合民用建筑节能强制性标准的，不得出具竣工验收合格报告。\n第十八条 实行集中供热的建筑应当安装供热系统调控装置、用热计量装置和室内温度调控装置；公共建筑还应当安装用电分项计量装置。居住建筑安装的用热计量装置应当满足分户计量的要求。\n计量装置应当依法检定合格。\n第十九条 建筑的公共走廊、楼梯等部位，应当安装、使用节能灯具和电气控制装置。\n第二十条 对具备可再生能源利用条件的建筑，建设单位应当选择合适的可再生能源，用于采暖、制冷、照明和热水供应等；设计单位应当按照有关可再生能源利用的标准进行设计。\n建设可再生能源利用设施，应当与建筑主体工程同步设计、同步施工、同步验收。\n第二十一条 国家机关办公建筑和大型公共建筑的所有权人应当对建筑的能源利用效率进行测评和标识，并按照国家有关规定将测评结果予以公示，接受社会监督。\n国家机关办公建筑应当安装、使用节能设备。\n本条例所称大型公共建筑，是指单体建筑面积2万平方米以上的公共建筑。\n第二十二条 房地产开发企业销售商品房，应当向购买人明示所售商品房的能源消耗指标、节能措施和保护要求、保温工程保修期等信息，并在商品房买卖合同和住宅质量保证书、住宅使用说明书中载明。\n第二十三条 在正常使用条件下，保温工程的最低保修期限为5年。保温工程的保修期，自竣工验收合格之日起计算。\n保温工程在保修范围和保修期内发生质量问题的，施工单位应当履行保修义务，并对造成的损失依法承担赔偿责任。","level":1},{"name":"第三章 既有建筑节能","text":"第二十四条 既有建筑节能改造应当根据当地经济、社会发展水平和地理气候条件等实际情况，有计划、分步骤地实施分类改造。\n本条例所称既有建筑节能改造，是指对不符合民用建筑节能强制性标准的既有建筑的围护结构、供热系统、采暖制冷系统、照明设备和热水供应设施等实施节能改造的活动。\n第二十五条 县级以上地方人民政府建设主管部门应当对本行政区域内既有建筑的建设年代、结构形式、用能系统、能源消耗指标、寿命周期等组织调查统计和分析，制定既有建筑节能改造计划，明确节能改造的目标、范围和要求，报本级人民政府批准后组织实施。\n中央国家机关既有建筑的节能改造，由有关管理机关事务工作的机构制定节能改造计划，并组织实施。\n第二十六条 国家机关办公建筑、政府投资和以政府投资为主的公共建筑的节能改造，应当制定节能改造方案，经充分论证，并按照国家有关规定办理相关审批手续方可进行。\n各级人民政府及其有关部门、单位不得违反国家有关规定和标准，以节能改造的名义对前款规定的既有建筑进行扩建、改建。\n第二十七条 居住建筑和本条例第二十六条规定以外的其他公共建筑不符合民用建筑节能强制性标准的，在尊重建筑所有权人意愿的基础上，可以结合扩建、改建，逐步实施节能改造。\n第二十八条 实施既有建筑节能改造，应当符合民用建筑节能强制性标准，优先采用遮阳、改善通风等低成本改造措施。\n既有建筑围护结构的改造和供热系统的改造，应当同步进行。\n第二十九条 对实行集中供热的建筑进行节能改造，应当安装供热系统调控装置和用热计量装置；对公共建筑进行节能改造，还应当安装室内温度调控装置和用电分项计量装置。\n第三十条 国家机关办公建筑的节能改造费用，由县级以上人民政府纳入本级财政预算。\n居住建筑和教育、科学、文化、卫生、体育等公益事业使用的公共建筑节能改造费用，由政府、建筑所有权人共同负担。\n国家鼓励社会资金投资既有建筑节能改造。","level":1},{"name":"第四章 建筑用能系统运行节能","text":"第三十一条 建筑所有权人或者使用权人应当保证建筑用能系统的正常运行，不得人为损坏建筑围护结构和用能系统。\n国家机关办公建筑和大型公共建筑的所有权人或者使用权人应当建立健全民用建筑节能管理制度和操作规程，对建筑用能系统进行监测、维护，并定期将分项用电量报县级以上地方人民政府建设主管部门。\n第三十二条 县级以上地方人民政府节能工作主管部门应当会同同级建设主管部门确定本行政区域内公共建筑重点用电单位及其年度用电限额。\n县级以上地方人民政府建设主管部门应当对本行政区域内国家机关办公建筑和公共建筑用电情况进行调查统计和评价分析。国家机关办公建筑和大型公共建筑采暖、制冷、照明的能源消耗情况应当依照法律、行政法规和国家其他有关规定向社会公布。\n国家机关办公建筑和公共建筑的所有权人或者使用权人应当对县级以上地方人民政府建设主管部门的调查统计工作予以配合。\n第三十三条 供热单位应当建立健全相关制度，加强对专业技术人员的教育和培训。\n供热单位应当改进技术装备，实施计量管理，并对供热系统进行监测、维护，提高供热系统的效率，保证供热系统的运行符合民用建筑节能强制性标准。\n第三十四条 县级以上地方人民政府建设主管部门应当对本行政区域内供热单位的能源消耗情况进行调查统计和分析，并制定供热单位能源消耗指标；对超过能源消耗指标的，应当要求供热单位制定相应的改进措施，并监督实施。","level":1},{"name":"第五章 法律责任","text":"第三十五条 违反本条例规定，县级以上人民政府有关部门有下列行为之一的，对负有责任的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）对设计方案不符合民用建筑节能强制性标准的民用建筑项目颁发建设工程规划许可证的；\n（二）对不符合民用建筑节能强制性标准的设计方案出具合格意见的；\n（三）对施工图设计文件不符合民用建筑节能强制性标准的民用建筑项目颁发施工许可证的；\n（四）不依法履行监督管理职责的其他行为。\n第三十六条 违反本条例规定，各级人民政府及其有关部门、单位违反国家有关规定和标准，以节能改造的名义对既有建筑进行扩建、改建的，对负有责任的主管人员和其他直接责任人员，依法给予处分。\n第三十七条 违反本条例规定，建设单位有下列行为之一的，由县级以上地方人民政府建设主管部门责令改正，处20万元以上50万元以下的罚款：\n（一）明示或者暗示设计单位、施工单位违反民用建筑节能强制性标准进行设计、施工的；\n（二）明示或者暗示施工单位使用不符合施工图设计文件要求的墙体材料、保温材料、门窗、采暖制冷系统和照明设备的；\n（三）采购不符合施工图设计文件要求的墙体材料、保温材料、门窗、采暖制冷系统和照明设备的。\n违反本条例规定，建设单位、设计单位、施工单位使用国家有关目录、名录中禁止或者淘汰的技术、工艺、材料、设备的，由县级以上人民政府建设主管部门责令改正，没收违法所得，并处货值金额1倍以上5倍以下的罚款；情节严重的，报经有批准权的人民政府批准，责令停业、关闭。\n第三十八条 违反本条例规定，建设单位对不符合民用建筑节能强制性标准的民用建筑项目出具竣工验收合格报告的，由县级以上地方人民政府建设主管部门责令改正，处民用建筑项目合同价款2%以上4%以下的罚款；造成损失的，依法承担赔偿责任。\n第三十九条 违反本条例规定，设计单位未按照民用建筑节能强制性标准进行设计的，由县级以上地方人民政府建设主管部门责令改正，处10万元以上30万元以下的罚款；情节严重的，由颁发资质证书的部门责令停业整顿，降低资质等级或者吊销资质证书；造成损失的，依法承担赔偿责任。\n第四十条 违反本条例规定，施工单位未按照民用建筑节能强制性标准进行施工的，由县级以上地方人民政府建设主管部门责令改正，处民用建筑项目合同价款2%以上4%以下的罚款；情节严重的，由颁发资质证书的部门责令停业整顿，降低资质等级或者吊销资质证书；造成损失的，依法承担赔偿责任。\n第四十一条 违反本条例规定，施工单位有下列行为之一的，由县级以上地方人民政府建设主管部门责令改正，处10万元以上20万元以下的罚款；情节严重的，由颁发资质证书的部门责令停业整顿，降低资质等级或者吊销资质证书；造成损失的，依法承担赔偿责任：\n（一）未对进入施工现场的墙体材料、保温材料、门窗、采暖制冷系统和照明设备进行查验的；\n（二）使用不符合施工图设计文件要求的墙体材料、保温材料、门窗、采暖制冷系统和照明设备的。\n第四十二条 违反本条例规定，工程监理单位有下列行为之一的，由县级以上地方人民政府建设主管部门责令限期改正；逾期未改正的，处10万元以上30万元以下的罚款；情节严重的，由颁发资质证书的部门责令停业整顿，降低资质等级或者吊销资质证书；造成损失的，依法承担赔偿责任：\n（一）未按照民用建筑节能强制性标准实施监理的；\n（二）墙体、屋面的保温工程施工时，未采取旁站、巡视和平行检验等形式实施监理的。\n对不符合施工图设计文件要求的墙体材料、保温材料、门窗、采暖制冷系统和照明设备，按照符合施工图设计文件要求签字的，依照《建设工程质量管理条例》第六十七条的规定处罚。\n第四十三条 违反本条例规定，房地产开发企业销售商品房，未向购买人明示所售商品房的能源消耗指标、节能措施和保护要求、保温工程保修期等信息，或者向购买人明示的所售商品房能源消耗指标与实际能源消耗不符的，依法承担民事责任；由县级以上地方人民政府建设主管部门责令限期改正；逾期未改正的，处交付使用的房屋销售总额2%以下的罚款；情节严重的，由颁发资质证书的部门降低资质等级或者吊销资质证书。\n第四十四条 违反本条例规定，注册执业人员未执行民用建筑节能强制性标准的，由县级以上人民政府建设主管部门责令停止执业3个月以上1年以下；情节严重的，由颁发资格证书的部门吊销执业资格证书，5年内不予注册。","level":1},{"name":"第六章 附 则","text":"第四十五条 本条例自2008年10月1日起施行。","level":1}]},{"id":"n1290","sections":[{"name":"","text":"消耗臭氧层物质管理条例\n（2010年4月8日中华人民共和国国务院令第573号公布 根据2018年3月19日《国务院关于修改和废止部分行政法规的决定》第一次修订 根据2023年12月29日《国务院关于修改〈消耗臭氧层物质管理条例〉的决定》第二次修订 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》第三次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强对消耗臭氧层物质的管理，履行《保护臭氧层维也纳公约》和《关于消耗臭氧层物质的蒙特利尔议定书》规定的义务，保护臭氧层和生态环境，保障人体健康，根据《中华人民共和国生态环境法典》，制定本条例。\n第二条 本条例所称消耗臭氧层物质，是指列入《中国受控消耗臭氧层物质清单》的化学品。\n《中国受控消耗臭氧层物质清单》由国务院生态环境主管部门会同国务院有关部门制定、调整和公布。\n第三条 在中华人民共和国境内从事消耗臭氧层物质的生产、销售、使用和进出口等活动，适用本条例。\n前款所称生产，是指制造消耗臭氧层物质的活动。前款所称使用，是指利用消耗臭氧层物质进行的生产经营等活动，不包括使用含消耗臭氧层物质的产品的活动。\n第四条 消耗臭氧层物质的管理工作应当坚持中国共产党的领导，贯彻党和国家路线方针政策和决策部署。\n国务院生态环境主管部门统一负责全国消耗臭氧层物质的监督管理工作。\n国务院商务主管部门、海关总署等有关部门依照本条例的规定和各自的职责负责消耗臭氧层物质的有关监督管理工作。\n地方人民政府生态环境主管部门和商务等有关部门依照本条例的规定和各自的职责负责本行政区域消耗臭氧层物质的有关监督管理工作。\n第五条 国家逐步削减并最终淘汰作为制冷剂、发泡剂、灭火剂、溶剂、清洗剂、加工助剂、杀虫剂、气雾剂、膨胀剂等用途的消耗臭氧层物质。\n禁止将国家已经淘汰的消耗臭氧层物质用于前款规定的用途。\n国务院生态环境主管部门会同国务院有关部门拟订《中国履行〈关于消耗臭氧层物质的蒙特利尔议定书〉国家方案》（以下简称国家方案），报国务院批准后实施。\n第六条 国务院生态环境主管部门根据国家方案和消耗臭氧层物质淘汰进展情况，会同国务院有关部门确定并公布限制或者禁止新建、改建、扩建生产、使用消耗臭氧层物质建设项目的类别，制定并公布限制或者禁止生产、使用、进出口消耗臭氧层物质的名录。\n因特殊用途确需生产、使用前款规定禁止生产、使用的消耗臭氧层物质的，按照《关于消耗臭氧层物质的蒙特利尔议定书》有关允许用于特殊用途的规定，由国务院生态环境主管部门会同国务院有关部门批准。\n第七条 国家对消耗臭氧层物质的生产、使用、进出口实行总量控制和配额管理。国务院生态环境主管部门根据国家方案和消耗臭氧层物质淘汰进展情况，商国务院有关部门确定国家消耗臭氧层物质的年度生产、使用和进出口配额总量，并予以公告。\n第八条 国家鼓励、支持消耗臭氧层物质替代品和替代技术的科学研究、技术开发和推广应用。\n国务院生态环境主管部门会同国务院有关部门制定、调整和公布《中国消耗臭氧层物质替代品推荐名录》。\n开发、生产、使用消耗臭氧层物质替代品，应当符合国家产业政策，并按照国家有关规定享受优惠政策。对在消耗臭氧层物质淘汰工作中做出突出成绩的单位和个人，按照国家有关规定给予奖励。\n第九条 任何单位和个人对违反本条例规定的行为，有权向生态环境主管部门或者其他有关部门举报。接到举报的部门应当及时调查处理，并为举报人保密；经调查情况属实的，对举报人给予奖励。","level":1},{"name":"第二章 生产、销售和使用","text":"第十条 消耗臭氧层物质的生产、使用单位，应当依照本条例的规定申请领取生产或者使用配额许可证。但是，使用单位有下列情形之一的，不需要申请领取使用配额许可证：\n（一）维修单位为了维修制冷设备、制冷系统或者灭火系统使用消耗臭氧层物质的；\n（二）实验室为了实验分析少量使用消耗臭氧层物质的；\n（三）海关为了防止有害生物传入传出使用消耗臭氧层物质实施检疫的；\n（四）国务院生态环境主管部门规定的不需要申请领取使用配额许可证的其他情形。\n第十一条 消耗臭氧层物质的生产、使用单位除具备法律、行政法规规定的条件外，还应当具备下列条件：\n（一）有合法生产或者使用相应消耗臭氧层物质的业绩；\n（二）有生产或者使用相应消耗臭氧层物质的场所、设施、设备和专业技术人员；\n（三）有经验收合格的环境保护设施；\n（四）有健全完善的生产经营管理制度。\n将消耗臭氧层物质用于本条例第六条规定的特殊用途的单位，不适用前款第（一）项的规定。\n第十二条 消耗臭氧层物质的生产、使用单位应当于每年10月31日前向国务院生态环境主管部门书面申请下一年度的生产配额或者使用配额，并提交其符合本条例第十一条规定条件的证明材料。\n国务院生态环境主管部门根据国家消耗臭氧层物质的年度生产、使用配额总量和申请单位生产、使用相应消耗臭氧层物质的业绩情况，核定申请单位下一年度的生产配额或者使用配额，并于每年12月20日前完成审查，符合条件的，核发下一年度的生产或者使用配额许可证，予以公告，并抄送国务院有关部门和申请单位所在地省、自治区、直辖市人民政府生态环境主管部门；不符合条件的，书面通知申请单位并说明理由。\n第十三条 消耗臭氧层物质的生产或者使用配额许可证应当载明下列内容：\n（一）生产或者使用单位的名称、地址、法定代表人或者负责人；\n（二）准予生产或者使用的消耗臭氧层物质的品种、用途及其数量；\n（三）有效期限；\n（四）发证机关、发证日期和证书编号。\n第十四条 消耗臭氧层物质的生产、使用单位需要调整其配额的，应当向国务院生态环境主管部门申请办理配额变更手续。\n国务院生态环境主管部门应当依照本条例第十一条、第十二条规定的条件和依据进行审查，并在受理申请之日起20个工作日内完成审查，符合条件的，对申请单位的配额进行调整，并予以公告；不符合条件的，书面通知申请单位并说明理由。\n第十五条 消耗臭氧层物质的生产单位不得超出生产配额许可证规定的品种、数量、期限生产消耗臭氧层物质，不得超出生产配额许可证规定的用途生产、销售消耗臭氧层物质。\n禁止无生产配额许可证生产消耗臭氧层物质。\n第十六条 依照本条例规定领取使用配额许可证的单位，不得超出使用配额许可证规定的品种、用途、数量、期限使用消耗臭氧层物质。\n除本条例第十条规定的不需要申请领取使用配额许可证的情形外，禁止无使用配额许可证使用消耗臭氧层物质。\n第十七条 下列单位应当按照国务院生态环境主管部门的规定办理备案手续：\n（一）消耗臭氧层物质的销售单位；\n（二）从事含消耗臭氧层物质的制冷设备、制冷系统或者灭火系统的维修、报废处理等经营活动的单位；\n（三）从事消耗臭氧层物质回收、再生利用或者销毁等经营活动的单位；\n（四）国务院生态环境主管部门规定的不需要申请领取使用配额许可证的消耗臭氧层物质的使用单位。\n前款第（一）项、第（二）项、第（四）项规定的单位向所在地设区的市级人民政府生态环境主管部门备案，第（三）项规定的单位向所在地省、自治区、直辖市人民政府生态环境主管部门备案。\n第十八条 除依照本条例规定进出口外，消耗臭氧层物质的购买和销售行为只能在符合本条例规定的消耗臭氧层物质的生产、销售和使用单位之间进行。\n第十九条 消耗臭氧层物质的生产、使用单位，应当按照国务院生态环境主管部门的规定采取必要的措施，防止或者减少消耗臭氧层物质的泄漏和排放。\n从事含消耗臭氧层物质的制冷设备、制冷系统或者灭火系统的维修、报废处理等经营活动的单位，应当按照国务院生态环境主管部门的规定对消耗臭氧层物质进行回收、循环利用或者交由从事消耗臭氧层物质回收、再生利用、销毁等经营活动的单位进行无害化处置。\n从事消耗臭氧层物质回收、再生利用、销毁等经营活动的单位，以及生产过程中附带产生消耗臭氧层物质的单位，应当按照国务院生态环境主管部门的规定对消耗臭氧层物质进行无害化处置，不得直接排放。\n第二十条 从事消耗臭氧层物质的生产、销售、使用、回收、再生利用、销毁等经营活动的单位，以及从事含消耗臭氧层物质的制冷设备、制冷系统或者灭火系统的维修、报废处理等经营活动的单位，应当完整保存有关生产经营活动的原始资料至少3年，并按照国务院生态环境主管部门的规定报送相关数据。\n生产、使用消耗臭氧层物质数量较大，以及生产过程中附带产生消耗臭氧层物质数量较大的单位，应当安装自动监测设备，与生态环境主管部门的监控设备联网，并保证监测设备正常运行，确保监测数据的真实性和准确性。具体办法由国务院生态环境主管部门规定。","level":1},{"name":"第三章 进出口","text":"第二十一条 国家对进出口消耗臭氧层物质予以控制，并实行名录管理。国务院生态环境主管部门会同国务院商务主管部门、海关总署制定、调整和公布《中国进出口受控消耗臭氧层物质名录》。\n进出口列入《中国进出口受控消耗臭氧层物质名录》的消耗臭氧层物质的单位，应当依照本条例的规定向国家消耗臭氧层物质进出口管理机构申请进出口配额，领取进出口审批单，并提交拟进出口的消耗臭氧层物质的品种、数量、来源、用途等情况的材料。\n第二十二条 国家消耗臭氧层物质进出口管理机构应当自受理申请之日起20个工作日内完成审查，作出是否批准的决定。予以批准的，向申请单位核发进出口审批单；未予批准的，书面通知申请单位并说明理由。\n进出口审批单的有效期最长为90日，不得超期或者跨年度使用。\n第二十三条 取得消耗臭氧层物质进出口审批单的单位，应当按照国务院商务主管部门的规定申请领取进出口许可证，持进出口许可证向海关办理通关手续。列入必须实施检验的进出口商品目录的消耗臭氧层物质，由海关依法实施检验。\n消耗臭氧层物质在中华人民共和国境内的海关特殊监管区域、保税监管场所与境外之间进出的，进出口单位应当依照本条例的规定申请领取进出口审批单、进出口许可证；消耗臭氧层物质在中华人民共和国境内的海关特殊监管区域、保税监管场所与境内其他区域之间进出的，或者在上述海关特殊监管区域、保税监管场所之间进出的，不需要申请领取进出口审批单、进出口许可证。","level":1},{"name":"第四章 监督检查","text":"第二十四条 生态环境主管部门和其他有关部门，依照本条例的规定和各自的职责对消耗臭氧层物质的生产、销售、使用和进出口等活动进行监督检查。\n第二十五条 生态环境主管部门和其他有关部门进行监督检查，有权采取下列措施：\n（一）要求被检查单位提供有关资料；\n（二）要求被检查单位就执行本条例规定的有关情况作出说明；\n（三）进入被检查单位的生产、经营、储存场所进行调查和取证；\n（四）责令被检查单位停止违反本条例规定的行为，履行法定义务；\n（五）扣押、查封违法生产、销售、使用、进出口的消耗臭氧层物质及其生产设备、设施、原料及产品。\n被检查单位应当予以配合，如实反映情况，提供必要资料，不得拒绝和阻碍。\n第二十六条 生态环境主管部门和其他有关部门进行监督检查，监督检查人员不得少于2人，并应当出示有效的行政执法证件。\n生态环境主管部门和其他有关部门的工作人员，对监督检查中知悉的商业秘密负有保密义务。\n第二十七条 国务院生态环境主管部门应当建立健全消耗臭氧层物质的数据信息管理系统，收集、汇总和发布消耗臭氧层物质的生产、使用、进出口等数据信息。\n地方人民政府生态环境主管部门应当将监督检查中发现的违反本条例规定的行为及处理情况逐级上报至国务院生态环境主管部门。\n县级以上地方人民政府其他有关部门应当将监督检查中发现的违反本条例规定的行为及处理情况逐级上报至国务院有关部门，国务院有关部门应当及时抄送国务院生态环境主管部门。\n第二十八条 地方人民政府生态环境主管部门或者其他有关部门对违反本条例规定的行为不查处的，其上级主管部门有权责令其依法查处或者直接进行查处。","level":1},{"name":"第五章 法律责任","text":"第二十九条 负有消耗臭氧层物质监督管理职责的部门及其工作人员有下列行为之一的，对直接负责的主管人员和其他直接责任人员，依法给予处分；直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任：\n（一）违反本条例规定核发消耗臭氧层物质生产、使用配额许可证的；\n（二）违反本条例规定核发消耗臭氧层物质进出口审批单或者进出口许可证的；\n（三）对发现的违反本条例的行为不依法查处的；\n（四）在办理消耗臭氧层物质生产、使用、进出口等行政许可以及实施监督检查的过程中，索取、收受他人财物或者谋取其他利益的；\n（五）有其他徇私舞弊、滥用职权、玩忽职守行为的。\n第三十条 无生产配额许可证生产消耗臭氧层物质的，由所在地生态环境主管部门责令停止违法行为，没收用于违法生产消耗臭氧层物质的原料、违法生产的消耗臭氧层物质和违法所得，拆除、销毁用于违法生产消耗臭氧层物质的设备、设施，并处100万元以上500万元以下的罚款。\n第三十一条 依照本条例规定应当申请领取使用配额许可证的单位无使用配额许可证使用消耗臭氧层物质，或者违反本条例规定将已淘汰的消耗臭氧层物质用于制冷剂、发泡剂、灭火剂、溶剂、清洗剂、加工助剂、杀虫剂、气雾剂、膨胀剂等用途的，由所在地生态环境主管部门责令停止违法行为，没收违法使用的消耗臭氧层物质、违法使用消耗臭氧层物质生产的产品和违法所得，并处20万元以上50万元以下的罚款；情节严重的，并处50万元以上100万元以下的罚款，拆除、销毁用于违法使用消耗臭氧层物质的设备、设施。\n第三十二条 消耗臭氧层物质的生产、使用单位有下列行为之一的，由所在地省、自治区、直辖市人民政府生态环境主管部门责令停止违法行为，没收违法生产、使用的消耗臭氧层物质、违法使用消耗臭氧层物质生产的产品和违法所得，并处10万元以上50万元以下的罚款，报国务院生态环境主管部门核减其生产、使用配额数量；情节严重的，并处50万元以上100万元以下的罚款，报国务院生态环境主管部门吊销其生产、使用配额许可证：\n（一）超出生产配额许可证规定的品种、数量、期限生产消耗臭氧层物质的；\n（二）超出生产配额许可证规定的用途生产或者销售消耗臭氧层物质的；\n（三）超出使用配额许可证规定的品种、数量、用途、期限使用消耗臭氧层物质的。\n第三十三条 消耗臭氧层物质的生产、销售、使用单位向不符合本条例规定的单位销售或者购买消耗臭氧层物质的，由所在地生态环境主管部门责令改正，没收违法销售或者购买的消耗臭氧层物质和违法所得，处以所销售或者购买的消耗臭氧层物质市场总价3倍的罚款；对取得生产、使用配额许可证的单位，报国务院生态环境主管部门核减其生产、使用配额数量。\n第三十四条 消耗臭氧层物质的生产、使用单位未按照规定采取必要的措施防止或者减少消耗臭氧层物质的泄漏和排放的，由所在地生态环境主管部门责令改正，处5万元以上10万元以下的罚款；拒不改正的，处10万元以上50万元以下的罚款，报国务院生态环境主管部门核减其生产、使用配额数量。\n第三十五条 从事含消耗臭氧层物质的制冷设备、制冷系统或者灭火系统的维修、报废处理等经营活动的单位，未按照规定对消耗臭氧层物质进行回收、循环利用或者交由从事消耗臭氧层物质回收、再生利用、销毁等经营活动的单位进行无害化处置的，由所在地生态环境主管部门责令改正，处5万元以上20万元以下的罚款；拒不改正的，责令停产整治或者停业整治。\n第三十六条 从事消耗臭氧层物质回收、再生利用、销毁等经营活动的单位，以及生产过程中附带产生消耗臭氧层物质的单位，未按照规定对消耗臭氧层物质进行无害化处置而直接排放的，由所在地生态环境主管部门责令改正，处10万元以上50万元以下的罚款；拒不改正的，责令停产整治或者停业整治。\n第三十七条 从事消耗臭氧层物质生产、销售、使用、进出口、回收、再生利用、销毁等经营活动的单位，以及从事含消耗臭氧层物质的制冷设备、制冷系统或者灭火系统的维修、报废处理等经营活动的单位有下列行为之一的，由所在地生态环境主管部门责令改正，处5000元以上2万元以下的罚款：\n（一）依照本条例规定应当向生态环境主管部门备案而未备案的；\n（二）未按照规定完整保存有关生产经营活动的原始资料的；\n（三）未按时申报或者谎报、瞒报有关经营活动的数据资料的；\n（四）未按照监督检查人员的要求提供必要的资料的。\n第三十八条 生产、使用消耗臭氧层物质数量较大，以及生产过程中附带产生消耗臭氧层物质数量较大的单位，未按照规定安装自动监测设备并与生态环境主管部门的监控设备联网，或者未保证监测设备正常运行导致监测数据不真实、不准确的，由所在地生态环境主管部门责令改正，处2万元以上20万元以下的罚款；拒不改正的，责令停产整治或者停业整治。\n第三十九条 进出口单位无进出口许可证或者超出进出口许可证的规定进出口消耗臭氧层物质的，由海关依照有关法律、行政法规的规定予以处罚；构成犯罪的，依法追究刑事责任。\n以欺骗、贿赂等不正当手段取得消耗臭氧层物质进出口配额、进出口审批单、进出口许可证的，由国家消耗臭氧层物质进出口管理机构、国务院商务主管部门依据职责撤销其进出口配额、进出口审批单、进出口许可证，3年内不得再次申请，并由所在地生态环境主管部门处10万元以上50万元以下的罚款。\n第四十条 拒绝、阻碍生态环境主管部门或者其他有关部门的监督检查，或者在接受监督检查时弄虚作假的，由监督检查部门责令改正，处5万元以上20万元以下的罚款；对直接负责的主管人员和其他直接责任人员，处5000元以上5万元以下的罚款；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第四十一条 因违反本条例规定受到行政处罚的，按照国家有关规定记入信用记录，并向社会公布。","level":1},{"name":"第六章 附 则","text":"第四十二条 本条例自2010年6月1日起施行。","level":1}]},{"id":"n1291","sections":[{"name":"","text":"住房公积金管理条例\n（1999年4月3日中华人民共和国国务院令第262号发布 根据2002年3月24日《国务院关于修改〈住房公积金管理条例〉的决定》第一次修订 根据2019年3月24日《国务院关于修改部分行政法规的决定》第二次修订 根据2026年8月10日《国务院关于修改〈住房公积金管理条例〉的决定》第三次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强对住房公积金的管理，维护住房公积金所有者的合法权益，更好满足多样化住房消费需求，促进城镇住房建设，提高城镇居民的居住水平，制定本条例。\n第二条 本条例适用于中华人民共和国境内住房公积金的缴存、提取、使用、管理和监督。\n本条例所称住房公积金，是指国家机关、国有企业、城镇集体企业、外商投资企业、城镇私营企业及其他城镇企业、事业单位、民办非企业单位、社会团体（以下统称单位）及其在职职工缴存的长期住房储金。\n第三条 职工个人缴存的住房公积金和职工所在单位为职工缴存的住房公积金，属于职工个人所有。\n第四条 住房公积金的管理实行住房公积金管理委员会决策、住房公积金管理中心运作、银行专户存储、财政监督的原则。\n第五条 住房公积金应当依照本条例的规定提取和使用，任何单位和个人不得挪作他用。\n第六条 住房公积金的存、贷利率由国务院决定。\n第七条 国务院住房城乡建设主管部门会同国务院财政部门、中国人民银行、国务院银行业监督管理机构拟定住房公积金政策，并监督执行。\n省、自治区人民政府住房城乡建设主管部门会同同级财政部门以及中国人民银行分支机构、国务院银行业监督管理机构派出机构，负责本行政区域内住房公积金管理法规、政策执行情况的监督。","level":1},{"name":"第二章 机构及其职责","text":"第八条 直辖市和省、自治区人民政府所在地的市以及其他设区的市（地、州、盟），应当设立住房公积金管理委员会，作为住房公积金管理的决策机构。住房公积金管理委员会的成员中，人民政府负责人和住房城乡建设、财政、人民银行、银行业监督管理机构等有关部门负责人以及有关专家占1/3，工会代表和职工代表占1/3，单位代表占1/3。\n住房公积金管理委员会主任应当由具有社会公信力的人士担任。\n第九条 住房公积金管理委员会在住房公积金管理方面履行下列职责：\n（一）依据有关法律、法规和政策，制定和调整住房公积金的具体管理措施，并监督实施；\n（二）根据本条例第十八条的规定，拟订住房公积金的具体缴存比例；\n（三）确定住房公积金的最高贷款额度；\n（四）审批住房公积金归集、使用计划；\n（五）审议住房公积金增值收益分配方案；\n（六）审批住房公积金归集、使用计划执行情况的报告；\n（七）审批住房公积金呆账核销申请。\n第十条 直辖市和省、自治区人民政府所在地的市以及其他设区的市（地、州、盟）应当按照精简、效能的原则，设立一个住房公积金管理中心，负责住房公积金的管理运作。县（市）不设立住房公积金管理中心。\n前款规定的住房公积金管理中心可以在有条件的县（市）设立分支机构。住房公积金管理中心与其分支机构应当实行统一的规章制度，进行统一核算。\n住房公积金管理中心是直属城市人民政府的不以营利为目的的独立的事业单位。\n第十一条 住房公积金管理中心履行下列职责：\n（一）编制、执行住房公积金的归集、使用计划；\n（二）负责记载职工住房公积金的缴存、提取、使用等情况；\n（三）负责住房公积金的核算；\n（四）审批住房公积金的提取、使用；\n（五）负责住房公积金的保值和归还；\n（六）编制住房公积金归集、使用计划执行情况的报告；\n（七）承办住房公积金管理委员会决定的其他事项。\n第十二条 住房公积金管理委员会应当按照中国人民银行、国务院银行业监督管理机构的有关规定，指定受委托办理住房公积金金融业务的商业银行（以下简称受委托银行）；住房公积金管理中心应当委托受委托银行办理住房公积金贷款、结算等金融业务和住房公积金账户的设立、缴存、归还等手续。\n住房公积金管理中心应当与受委托银行签订委托合同。","level":1},{"name":"第三章 缴 存","text":"第十三条 住房公积金管理中心应当在受委托银行设立住房公积金专户。\n单位应当向住房公积金管理中心办理住房公积金缴存登记，并为本单位职工办理住房公积金账户设立手续。每个职工只能有一个住房公积金账户。\n住房公积金管理中心应当建立职工住房公积金明细账，记载职工个人住房公积金的缴存、提取等情况。\n第十四条 新设立的单位应当自设立之日起30日内向住房公积金管理中心办理住房公积金缴存登记，并自登记之日起20日内，为本单位职工办理住房公积金账户设立手续。\n单位合并、分立、撤销、解散或者破产的，应当自发生上述情况之日起30日内由原单位或者清算组织向住房公积金管理中心办理变更登记或者注销登记，并自办妥变更登记或者注销登记之日起20日内，为本单位职工办理住房公积金账户转移或者封存手续。\n第十五条 单位录用职工的，应当自录用之日起30日内向住房公积金管理中心办理缴存登记，并办理职工住房公积金账户的设立或者转移手续。\n单位与职工终止劳动关系的，单位应当自劳动关系终止之日起30日内向住房公积金管理中心办理变更登记，并办理职工住房公积金账户转移或者封存手续。\n第十六条 职工住房公积金的月缴存额为职工本人上一年度月平均工资乘以职工住房公积金缴存比例。\n单位为职工缴存的住房公积金的月缴存额为职工本人上一年度月平均工资乘以单位住房公积金缴存比例。\n第十七条 新参加工作的职工从参加工作的第二个月开始缴存住房公积金，月缴存额为职工本人当月工资乘以职工住房公积金缴存比例。\n单位新调入的职工从调入单位发放工资之日起缴存住房公积金，月缴存额为职工本人当月工资乘以职工住房公积金缴存比例。\n第十八条 职工和单位住房公积金的缴存比例均不得低于职工上一年度月平均工资的5％，不得高于国家规定的最高缴存比例。具体缴存比例由住房公积金管理委员会拟订，经本级人民政府审核后，报省、自治区、直辖市人民政府批准。\n第十九条 职工个人缴存的住房公积金，由所在单位每月从其工资中代扣代缴。\n单位应当于每月发放职工工资之日起5日内将单位缴存的和为职工代缴的住房公积金汇缴到住房公积金专户内，由受委托银行计入职工住房公积金账户。\n第二十条 单位应当按时、足额缴存住房公积金，不得逾期缴存或者少缴。\n对缴存住房公积金确有困难的单位，经本单位职工代表大会或者工会讨论通过，并经住房公积金管理中心审核，报住房公积金管理委员会批准后，可以降低缴存比例或者缓缴；待单位经济效益好转后，再提高缴存比例或者补缴缓缴。\n第二十一条 住房公积金自存入职工住房公积金账户之日起按照国家规定的利率计息。\n第二十二条 住房公积金管理中心应当为缴存住房公积金的职工发放缴存住房公积金的有效凭证。\n第二十三条 单位为职工缴存的住房公积金，按照规定计入有关成本费用，国家机关、事业单位在预算中列支。","level":1},{"name":"第四章 提取和使用","text":"第二十四条 职工有下列情形之一的，可以提取职工住房公积金账户内的存储余额：\n（一）支付房租的；\n（二）购买、建造、翻建、大修自住住房的；\n（三）偿还购房贷款本息的；\n（四）装修自住住房的；\n（五）支付自住住房物业费的；\n（六）离休、退休的；\n（七）完全丧失劳动能力，并与单位终止劳动关系的；\n（八）出境定居的；\n（九）国务院批准的其他住房消费情形。\n依照前款第六、七、八项规定提取职工住房公积金的，可以同时注销职工住房公积金账户。\n职工死亡或者被宣告死亡的，职工的继承人、受遗赠人可以提取职工住房公积金账户内的存储余额；无继承人也无受遗赠人的，职工住房公积金账户内的存储余额纳入住房公积金的增值收益。\n第二十五条 职工申请提取住房公积金的，住房公积金管理中心应当自受理申请之日起3日内作出准予提取或者不准提取的决定，并通知申请人；准予提取的，由受委托银行办理支付手续。\n第二十六条 缴存住房公积金的职工，在购买、建造、翻建、大修自住住房时，可以向住房公积金管理中心申请住房公积金贷款。\n住房公积金管理中心应当自受理申请之日起10日内作出准予贷款或者不准贷款的决定，并通知申请人；准予贷款的，由受委托银行办理贷款手续。\n住房公积金贷款的风险，由住房公积金管理中心承担。\n第二十七条 申请人申请住房公积金贷款的，应当提供担保。\n第二十八条 住房公积金管理中心在保证住房公积金提取和贷款的前提下，经住房公积金管理委员会批准，可以将住房公积金用于购买国债和政策性金融债。\n住房公积金管理中心不得向他人提供担保。\n第二十九条 住房公积金的增值收益应当存入住房公积金管理中心在受委托银行开立的住房公积金增值收益专户，主要用于建立住房公积金贷款的风险准备金、住房公积金管理中心的管理费用和建设、筹集、运维公共租赁住房以及房屋全生命周期安全管理等住房领域相关公共支出的补充资金。\n第三十条 住房公积金管理中心的管理费用，由住房公积金管理中心按照规定的标准编制全年预算支出总额，报本级人民政府财政部门批准后，从住房公积金增值收益中上交本级财政，由本级财政拨付。\n住房公积金管理中心的管理费用标准，由省、自治区、直辖市人民政府住房城乡建设主管部门会同同级财政部门按照国家规定的事业单位费用标准制定。\n第三十一条 国务院住房城乡建设主管部门和省、自治区人民政府住房城乡建设主管部门以及住房公积金管理中心应当加强数字化、智能化建设，提升住房公积金管理服务效能，实现住房公积金缴存记录等全国范围内互信互认，推动住房公积金转移接续、异地贷款等业务便捷高效办理。","level":1},{"name":"第五章 监 督","text":"第三十二条 地方有关人民政府财政部门应当加强对本行政区域内住房公积金归集、提取和使用情况的监督，并向本级人民政府的住房公积金管理委员会通报。\n住房公积金管理中心在编制住房公积金归集、使用计划时，应当征求财政部门的意见。\n住房公积金管理委员会在审批住房公积金归集、使用计划和计划执行情况的报告时，必须有财政部门参加。\n第三十三条 住房公积金管理中心编制的住房公积金年度预算、决算，应当经财政部门审核后，提交住房公积金管理委员会审议。\n住房公积金管理中心应当每年定期向财政部门、住房城乡建设主管部门和住房公积金管理委员会报送财务报告，并将财务报告向社会公布。\n第三十四条 住房公积金管理中心应当依法接受审计部门的审计监督。\n第三十五条 住房公积金管理中心应当督促单位按时履行下列义务：\n（一）住房公积金的缴存登记或者变更、注销登记；\n（二）住房公积金账户的设立、转移或者封存；\n（三）足额缴存住房公积金。\n职工有权督促单位按时履行前款规定的义务。\n第三十六条 住房公积金管理中心应当督促受委托银行及时办理委托合同约定的业务。\n受委托银行应当按照委托合同的约定，定期向住房公积金管理中心提供有关的业务资料。\n第三十七条 职工、单位有权查询本人、本单位住房公积金的缴存、提取情况，住房公积金管理中心、受委托银行不得拒绝。\n职工、单位对住房公积金账户内的存储余额有异议的，可以申请受委托银行复核；对复核结果有异议的，可以申请住房公积金管理中心重新复核。受委托银行、住房公积金管理中心应当自收到申请之日起5日内给予书面答复。\n职工有权揭发、检举、控告挪用住房公积金的行为。\n第三十八条 国务院住房城乡建设主管部门应当确定住房公积金领域公共信用信息，住房公积金管理中心应当建立全面完整准确的信用记录，纳入全国信用信息共享平台。","level":1},{"name":"第六章 罚 则","text":"第三十九条 违反本条例的规定，单位不办理住房公积金缴存登记或者不为本单位职工办理住房公积金账户设立手续的，由住房公积金管理中心责令限期办理；逾期不办理的，处5万元以上30万元以下的罚款。\n第四十条 违反本条例的规定，单位逾期不缴或者少缴住房公积金的，由住房公积金管理中心责令限期缴存；逾期仍不缴存的，可以申请人民法院强制执行。\n第四十一条 以欺诈、伪造证明材料或者其他手段违法提取住房公积金的，由住房公积金管理中心责令限期退回违法提取的住房公积金，3年内不得提取住房公积金或者使用住房公积金贷款。\n以欺诈、伪造证明材料或者其他手段违法获得住房公积金贷款的，由住房公积金管理中心责令限期返还贷款资金，5年内不得提取住房公积金或者使用住房公积金贷款。\n第四十二条 住房公积金管理委员会违反本条例规定审批住房公积金使用计划的，由国务院住房城乡建设主管部门会同国务院财政部门或者由省、自治区人民政府住房城乡建设主管部门会同同级财政部门，依据管理职权责令限期改正。\n第四十三条 住房公积金管理中心违反本条例规定，有下列行为之一的，由国务院住房城乡建设主管部门或者省、自治区人民政府住房城乡建设主管部门依据管理职权，责令限期改正；对负有责任的主管人员和其他直接责任人员，依法给予处分：\n（一）未按照规定设立住房公积金专户的；\n（二）未按照规定审批职工提取、使用住房公积金的；\n（三）未按照规定使用住房公积金增值收益的；\n（四）委托住房公积金管理委员会指定的银行以外的机构办理住房公积金金融业务的；\n（五）未建立职工住房公积金明细账的；\n（六）未为缴存住房公积金的职工发放缴存住房公积金的有效凭证的；\n（七）未经批准用住房公积金购买国债、政策性金融债的；\n（八）未督促单位按时履行住房公积金的缴存登记等义务的。\n第四十四条 违反本条例规定，挪用住房公积金的，由国务院住房城乡建设主管部门或者省、自治区人民政府住房城乡建设主管部门依据管理职权，追回挪用的住房公积金，没收违法所得；对挪用或者批准挪用住房公积金的人民政府负责人和政府有关部门负责人以及住房公积金管理中心负有责任的主管人员和其他直接责任人员，依照刑法关于挪用公款罪或者其他罪的规定，依法追究刑事责任；尚不够刑事处罚的，依法给予处分。\n第四十五条 住房公积金管理中心违反财政法规的，由财政部门依法给予行政处罚。\n第四十六条 违反本条例规定，住房公积金管理中心向他人提供担保的，对直接负责的主管人员和其他直接责任人员依法给予处分。\n第四十七条 国家机关工作人员在住房公积金监督管理工作中滥用职权、玩忽职守、徇私舞弊，构成犯罪的，依法追究刑事责任；尚不构成犯罪的，依法给予处分。","level":1},{"name":"第七章 附 则","text":"第四十八条 住房公积金财务管理和会计核算的办法，由国务院财政部门商国务院住房城乡建设主管部门制定。\n第四十九条 个体工商户、非全日制从业人员以及其他灵活就业人员，可以自愿缴存住房公积金，按照规定享受相应的政策支持。具体办法由设区的市级以上地方人民政府制定。\n国务院住房城乡建设主管部门等有关部门应当加强对灵活就业人员缴存住房公积金工作的指导。\n第五十条 本条例自发布之日起施行。","level":1}]},{"id":"n1292","sections":[{"name":"","text":"森林病虫害防治条例\n（1989年12月18日中华人民共和国国务院令第46号发布 根据2026年1月30日《国务院关于修改和废止部分行政法规的决定》修订）","level":0},{"name":"第一章 总 则","text":"第一条 为有效防治森林病虫害，保护森林资源，促进林业发展，维护自然生态平衡，根据《中华人民共和国森林法》有关规定，制定本条例。\n第二条 本条例所称森林病虫害防治，是指对森林、林木、林木种苗及木材、竹材的病害和虫害的预防和除治。\n第三条 森林病虫害防治实行“预防为主，综合治理”的方针。\n第四条 森林病虫害防治实行“谁经营、谁防治”的责任制度。\n地方各级人民政府应当制定措施和制度，加强对森林病虫害防治工作的领导。\n第五条 国务院林业主管部门主管全国森林病虫害防治工作。\n县级以上地方各级人民政府林业主管部门主管本行政区域内的森林病虫害防治工作，其所属的森林病虫害防治机构负责森林病虫害防治的具体组织工作。\n区、乡林业工作站负责组织本区、乡的森林病虫害防治工作。\n第六条 国家鼓励和支持森林病虫害防治科学研究，推广和应用先进技术，提高科学防治水平。","level":1},{"name":"第二章 森林病虫害的预防","text":"第七条 森林经营单位和个人在森林的经营活动中应当遵守下列规定：\n（一）植树造林应当适地适树，提倡营造混交林，合理搭配树种，依照国家规定选用林木良种；造林设计方案必须有森林病虫害防治措施；\n（二）禁止使用带有危险性病虫害的林木种苗进行育苗或者造林；\n（三）对幼龄林和中龄林应当及时进行抚育管理，清除已经感染病虫害的林木；\n（四）有计划地实行封山育林，改变纯林生态环境；\n（五）及时清理火烧迹地，伐除受害严重的过火林木；\n（六）采伐后的林木应当及时运出伐区并清理现场。\n第八条 各级人民政府林业主管部门应当有计划地组织建立无检疫对象的林木种苗基地。各级森林病虫害防治机构应当依法对林木种苗和木材、竹材进行产地和调运检疫；发现新传入的危险性病虫害，应当及时采取严密封锁、扑灭措施，不得将危险性病虫害传出。\n各口岸动植物检疫机构，应当按照国家有关进出境动植物检疫的法律规定，加强进境林木种苗和木材、竹材的检疫工作，防止境外森林病虫害传入。\n第九条 各级人民政府林业主管部门应当组织和监督森林经营单位和个人，采取有效措施，保护好林内各种有益生物，并有计划地进行繁殖和培养，发挥生物防治作用。\n第十条 国务院林业主管部门和省、自治区、直辖市人民政府林业主管部门的森林病虫害防治机构，应当综合分析各地测报数据，定期分别发布全国和本行政区域的森林病虫害中、长期趋势预报，并提出防治方案。\n县、市、自治州人民政府林业主管部门或者其所属的森林病虫害防治机构，应当综合分析基层单位测报数据，发布当地森林病虫害短、中期预报，并提出防治方案。\n全民所有的森林和林木，由国营林业局、国营林场或者其他经营单位组织森林病虫害情况调查。\n集体和个人所有的森林和林木，由区、乡林业工作站或者县森林病虫害防治机构组织森林病虫害情况调查。\n各调查单位应当按照规定向上一级林业主管部门或者其森林病虫害防治机构报告森林病虫害的调查情况。\n第十一条 国务院林业主管部门负责制定主要森林病虫害的测报对象及测报办法；省、自治区、直辖市人民政府林业主管部门可以根据本行政区域的情况作出补充规定，并报国务院林业主管部门备案。\n国务院林业主管部门和省、自治区、直辖市人民政府林业主管部门的森林病虫害防治机构可以在不同地区根据实际需要建立中心测报点，对测报对象进行调查与监测。\n第十二条 地方各级人民政府林业主管部门应当对经常发生森林病虫害的地区，实施以营林措施为主，生物、化学和物理防治相结合的综合治理措施，逐步改变森林生态环境，提高森林抗御自然灾害的能力。\n第十三条 各级人民政府林业主管部门可以根据森林病虫害防治的实际需要，建设下列设施：\n（一）药剂、器械及其储备仓库；\n（二）临时简易机场；\n（三）测报试验室、检疫检验室、检疫隔离试种苗圃；\n（四）林木种苗及木材熏蒸除害设施。","level":1},{"name":"第三章 森林病虫害的除治","text":"第十四条 发现严重森林病虫害的单位和个人，应当及时向当地人民政府或者林业主管部门报告。\n当地人民政府或者林业主管部门接到报告后，应当及时组织除治，同时报告所在省、自治区、直辖市人民政府林业主管部门。\n发生大面积暴发性或者危险性森林病虫害时，省、自治区、直辖市人民政府林业主管部门应当及时报告国务院林业主管部门。\n第十五条 发生暴发性或者危险性的森林病虫害时，当地人民政府应当根据实际需要，组织有关部门建立森林病虫害防治临时指挥机构，负责制定紧急除治措施，协调解决工作中的重大问题。\n第十六条 县级以上地方人民政府或者其林业主管部门应当制定除治森林病虫害的实施计划，并组织好交界地区的联防联治，对除治情况定期检查。\n第十七条 施药必须遵守有关规定，防止环境污染，保证人畜安全，减少杀伤有益生物。\n使用航空器施药时，当地人民政府林业主管部门应当事先进行调查设计，做好地面准备工作；林业、民航、气象部门应当密切配合，保证作业质量。\n第十八条 发生严重森林病虫害时，所需的防治药剂、器械、油料等，商业、供销、物资、石油化工等部门应当优先供应，铁路、交通、民航部门应当优先承运，民航部门应当优先安排航空器施药。\n第十九条 森林病虫害防治费用，全民所有的森林和林木，依照国家有关规定，分别从育林基金、木竹销售收入、多种经营收入和事业费中解决；集体和个人所有的森林和林木，由经营者负担，地方各级人民政府可以给予适当扶持。\n对暂时没有经济收入的森林、林木和长期没有经济收入的防护林、水源林、特种用途林的森林经营单位和个人，其所需的森林病虫害防治费用由地方各级人民政府给予适当扶持。\n发生大面积暴发性或者危险性病虫害，森林经营单位或者个人确实无力负担全部防治费用的，各级人民政府应当给予补助。\n第二十条 国家在重点林区逐步实行森林病虫害保险制度，具体办法由中国人民保险公司会同国务院林业主管部门制定。","level":1},{"name":"第四章 奖励和惩罚","text":"第二十一条 有下列成绩之一的单位和个人，由人民政府或者林业主管部门给予奖励：\n（一）严格执行森林病虫害防治法规，预防和除治措施得力，在本地区或者经营区域内，连续五年没有发生森林病虫害的；\n（二）预报病情、虫情及时准确，并提出防治森林病虫害的合理化建议，被有关部门采纳，获得显著效益的；\n（三）在森林病虫害防治科学研究中取得成果或者在应用推广科研成果中获得重大效益的；\n（四）在林业基层单位连续从事森林病虫害防治工作满十年，工作成绩较好的；\n（五）在森林病虫害防治工作中有其他显著成绩的。\n第二十二条 有下列行为之一的，责令限期除治、赔偿损失，可以并处一百元至二千元的罚款：\n（一）用带有危险性病虫害的林木种苗进行育苗或者造林的；\n（二）发生森林病虫害不除治或者除治不力，造成森林病虫害蔓延成灾的；\n（三）隐瞒或者虚报森林病虫害情况，造成森林病虫害蔓延成灾的。\n第二十三条 违反植物检疫法规调运林木种苗或者木材的，除依照植物检疫法规处罚外，并可处五十元至二千元的罚款。\n第二十四条 有本条例第二十二条、第二十三条规定行为的责任人员或者在森林病虫害防治工作中有失职行为的国家工作人员，由其所在单位或者上级机关依法给予处分；构成犯罪的，由司法机关依法追究刑事责任。\n第二十五条 被责令限期除治森林病虫害者不除治的，林业主管部门或者其授权的单位可以代为除治，由被责令限期除治者承担全部防治费用。\n代为除治森林病虫害的工作，不因被责令限期除治者申请复议或者起诉而停止执行。\n第二十六条 本条例规定的行政处罚，由县级以上人民政府林业主管部门或者其委托的单位决定。\n当事人对行政处罚决定不服的，可以依法申请行政复议，也可以依法提起行政诉讼。当事人逾期不申请行政复议或者不起诉又不履行行政处罚决定的，由作出行政处罚决定的机关申请人民法院强制执行。","level":1},{"name":"第五章 附 则","text":"第二十七条 省、自治区、直辖市人民政府可以根据本条例结合本地实际情况，制定实施办法。\n第二十八条 城市园林管理部门管理的森林和林木，其病虫害防治工作由城市园林管理部门参照本条例执行。\n第二十九条 本条例自发布之日起施行。","level":1}]},{"id":"n1293","sections":[{"name":"","text":"中华人民共和国河道管理条例\n（1988年6月10日中华人民共和国国务院令第3号发布 根据2011年1月8日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2017年3月1日《国务院关于修改和废止部分行政法规的决定》第二次修订 根据2017年10月7日《国务院关于修改部分行政法规的决定》第三次修订 根据2018年3月19日《国务院关于修改和废止部分行政法规的决定》第四次修订 根据2026年1月30日《国务院关于修改和废止部分行政法规的决定》第五次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为加强河道管理，保障防洪安全，发挥江河湖泊的综合效益，根据《中华人民共和国水法》，制定本条例。\n第二条 本条例适用于中华人民共和国领域内的河道（包括湖泊、人工水道、行洪区、蓄洪区、滞洪区）。\n河道内的航道，同时适用《中华人民共和国航道管理条例》。\n第三条 开发利用江河湖泊水资源和防治水害，应当全面规划、统筹兼顾、综合利用、讲求效益，服从防洪的总体安排，促进各项事业的发展。\n第四条 国务院水利行政主管部门是全国河道的主管机关。\n各省、自治区、直辖市的水利行政主管部门是该行政区域的河道主管机关。\n第五条 国家对河道实行按水系统一管理和分级管理相结合的原则。\n长江、黄河、淮河、海河、珠江、松花江、辽河等大江大河的主要河段，跨省、自治区、直辖市的重要河段，省、自治区、直辖市之间的边界河道以及国境边界河道，由国家授权的江河流域管理机构实施管理，或者由上述江河所在省、自治区、直辖市的河道主管机关根据流域统一规划实施管理。其他河道由省、自治区、直辖市或者市、县的河道主管机关实施管理。\n第六条 河道划分等级。河道等级标准由国务院水利行政主管部门制定。\n第七条 河道防汛和清障工作实行地方人民政府行政首长负责制。\n第八条 各级人民政府河道主管机关以及河道监理人员，必须按照国家法律、法规，加强河道管理，执行供水计划和防洪调度命令，维护水工程和人民生命财产安全。\n第九条 一切单位和个人都有保护河道堤防安全和参加防汛抢险的义务。","level":1},{"name":"第二章 河道整治与建设","text":"第十条 河道的整治与建设，应当服从流域综合规划，符合国家规定的防洪标准、通航标准和其他有关技术要求，维护堤防安全，保持河势稳定和行洪、航运通畅。\n第十一条 修建开发水利、防治水害、整治河道的各类工程和跨河、穿河、穿堤、临河的桥梁、码头、道路、渡口、管道、缆线等建筑物及设施，建设单位必须按照河道管理权限，将工程建设方案报送河道主管机关审查同意。未经河道主管机关审查同意的，建设单位不得开工建设。\n建设项目经批准后，建设单位应当将施工安排告知河道主管机关。\n第十二条 修建桥梁、码头和其他设施，必须按照国家规定的防洪标准所确定的河宽进行，不得缩窄行洪通道。\n桥梁和栈桥的梁底必须高于设计洪水位，并按照防洪和航运的要求，留有一定的超高。设计洪水位由河道主管机关根据防洪规划确定。\n跨越河道的管道、线路的净空高度必须符合防洪和航运的要求。\n第十三条 交通部门进行航道整治，应当符合防洪安全要求，并事先征求河道主管机关对有关设计和计划的意见。\n水利部门进行河道整治，涉及航道的，应当兼顾航运的需要，并事先征求交通部门对有关设计和计划的意见。\n在国家规定可以流放竹木的河流和重要的渔业水域进行河道、航道整治，建设单位应当兼顾竹木水运和渔业发展的需要，并事先将有关设计和计划送同级林业、渔业主管部门征求意见。\n第十四条 堤防上已修建的涵闸、泵站和埋设的穿堤管道、缆线等建筑物及设施，河道主管机关应当定期检查，对不符合工程安全要求的，限期改建。\n在堤防上新建前款所指建筑物及设施，应当服从河道主管机关的安全管理。\n第十五条 确需利用堤顶或者戗台兼做公路的，须经县级以上地方人民政府河道主管机关批准。堤身和堤顶公路的管理和维护办法，由河道主管机关商交通部门制定。\n第十六条 城镇建设和发展不得占用河道滩地。城镇规划的临河界限，由河道主管机关会同城镇规划等有关部门确定。沿河城镇在编制和审查城镇规划时，应当事先征求河道主管机关的意见。\n第十七条 河道岸线的利用和建设，应当服从河道整治规划和航道整治规划。计划部门在审批利用河道岸线的建设项目时，应当事先征求河道主管机关的意见。\n河道岸线的界限，由河道主管机关会同交通等有关部门报县级以上地方人民政府划定。\n第十八条 河道清淤和加固堤防取土以及按照防洪规划进行河道整治需要占用的土地，由当地人民政府调剂解决。\n因修建水库、整治河道所增加的可利用土地，属于国家所有，可以由县级以上人民政府用于移民安置和河道整治工程。\n第十九条 省、自治区、直辖市以河道为边界的，在河道两岸外侧各10公里之内，以及跨省、自治区、直辖市的河道，未经有关各方达成协议或者国务院水利行政主管部门批准，禁止单方面修建排水、阻水、引水、蓄水工程以及河道整治工程。","level":1},{"name":"第三章 河道保护","text":"第二十条 有堤防的河道，其管理范围为两岸堤防之间的水域、沙洲、滩地（包括可耕地）、行洪区，两岸堤防及护堤地。\n无堤防的河道，其管理范围根据历史最高洪水位或者设计洪水位确定。\n河道的具体管理范围，由县级以上地方人民政府负责划定。\n第二十一条 在河道管理范围内，水域和土地的利用应当符合江河行洪、输水和航运的要求；滩地的利用，应当由河道主管机关会同土地管理等有关部门制定规划，报县级以上地方人民政府批准后实施。\n第二十二条 禁止损毁堤防、护岸、闸坝等水工程建筑物和防汛设施、水文监测和测量设施、河岸地质监测设施以及通信照明等设施。\n在防汛抢险期间，无关人员和车辆不得上堤。\n因降雨雪等造成堤顶泥泞期间，禁止车辆通行，但防汛抢险车辆除外。\n第二十三条 禁止非管理人员操作河道上的涵闸闸门，禁止任何组织和个人干扰河道管理单位的正常工作。\n第二十四条 在河道管理范围内，禁止修建围堤、阻水渠道、阻水道路；种植高秆农作物、芦苇、杞柳、荻柴和树木（堤防防护林除外）；设置拦河渔具；弃置矿渣、石渣、煤灰、泥土、垃圾等。\n在堤防和护堤地，禁止建房、放牧、开渠、打井、挖窖、葬坟、晒粮、存放物料、开采地下资源、进行考古发掘以及开展集市贸易活动。\n第二十五条 在河道管理范围内进行下列活动，必须报经河道主管机关批准；涉及其他部门的，由河道主管机关会同有关部门批准：\n（一）采砂、取土、淘金、弃置砂石或者淤泥；\n（二）爆破、钻探、挖筑鱼塘；\n（三）在河道滩地存放物料、修建厂房或者其他建筑设施；\n（四）在河道滩地开采地下资源及进行考古发掘。\n第二十六条 根据堤防的重要程度、堤基土质条件等，河道主管机关报经县级以上人民政府批准，可以在河道管理范围的相连地域划定堤防安全保护区。在堤防安全保护区内，禁止进行打井、钻探、爆破、挖筑鱼塘、采石、取土等危害堤防安全的活动。\n第二十七条 禁止围湖造田。已经围垦的，应当按照国家规定的防洪标准进行治理，逐步退田还湖。湖泊的开发利用规划必须经河道主管机关审查同意。\n禁止围垦河流，确需围垦的，必须经过科学论证，并经省级以上人民政府批准。\n第二十八条 加强河道滩地、堤防和河岸的水土保持工作，防止水土流失、河道淤积。\n第二十九条 江河的故道、旧堤、原有工程设施等，不得擅自填堵、占用或者拆毁。\n第三十条 护堤护岸林木，由河道管理单位组织营造和管理，其他任何单位和个人不得侵占、砍伐或者破坏。\n河道管理单位对护堤护岸林木进行抚育和更新性质的采伐及用于防汛抢险的采伐，根据国家有关规定免交育林基金。\n第三十一条 在为保证堤岸安全需要限制航速的河段，河道主管机关应当会同交通部门设立限制航速的标志，通行的船舶不得超速行驶。\n在汛期，船舶的行驶和停靠必须遵守防汛指挥部的规定。\n第三十二条 山区河道有山体滑坡、崩岸、泥石流等自然灾害的河段，河道主管机关应当会同地质、交通等部门加强监测。在上述河段，禁止从事开山采石、采矿、开荒等危及山体稳定的活动。\n第三十三条 在河道中流放竹木，不得影响行洪、航运和水工程安全，并服从当地河道主管机关的安全管理。\n在汛期，河道主管机关有权对河道上的竹木和其他漂流物进行紧急处置。\n第三十四条 向河道、湖泊排污的排污口的设置和扩大，排污单位在向环境保护部门申报之前，应当征得河道主管机关的同意。\n第三十五条 在河道管理范围内，禁止堆放、倾倒、掩埋、排放污染水体的物体。禁止在河道内清洗装贮过油类或者有毒污染物的车辆、容器。\n河道主管机关应当开展河道水质监测工作，协同环境保护部门对水污染防治实施监督管理。","level":1},{"name":"第四章 河道清障","text":"第三十六条 对河道管理范围内的阻水障碍物，按照“谁设障，谁清除”的原则，由河道主管机关提出清障计划和实施方案，由防汛指挥部责令设障者在规定的期限内清除。逾期不清除的，由防汛指挥部组织强行清除，并由设障者负担全部清障费用。\n第三十七条 对壅水、阻水严重的桥梁、引道、码头和其他跨河工程设施，根据国家规定的防洪标准，由河道主管机关提出意见并报经人民政府批准，责成原建设单位在规定的期限内改建或者拆除。汛期影响防洪安全的，必须服从防汛指挥部的紧急处理决定。","level":1},{"name":"第五章 经 费","text":"第三十八条 河道堤防的防汛岁修费，按照分级管理的原则，分别由中央财政和地方财政负担，列入中央和地方年度财政预算。\n第三十九条 受益范围明确的堤防、护岸、水闸、圩垸、海塘和排涝工程设施，河道主管机关可以向受益的工商企业等单位和农户收取河道工程修建维护管理费，其标准应当根据工程修建和维护管理费用确定。收费的具体标准和计收办法由省、自治区、直辖市人民政府制定。\n第四十条 在河道管理范围内采砂、取土、淘金，必须按照经批准的范围和作业方式进行，并向河道主管机关缴纳管理费。收费的标准和计收办法由国务院水利行政主管部门会同国务院财政主管部门制定。\n第四十一条 任何单位和个人，凡对堤防、护岸和其他水工程设施造成损坏或者造成河道淤积的，由责任者负责修复、清淤或者承担维修费用。\n第四十二条 河道主管机关收取的各项费用，用于河道堤防工程的建设、管理、维修和设施的更新改造。结余资金可以连年结转使用，任何部门不得截取或者挪用。\n第四十三条 河道两岸的城镇和农村，当地县级以上人民政府可以在汛期组织堤防保护区域内的单位和个人义务出工，对河道堤防工程进行维修和加固。","level":1},{"name":"第六章 罚 则","text":"第四十四条 违反本条例规定，有下列行为之一的，县级以上地方人民政府河道主管机关除责令其纠正违法行为、采取补救措施外，可以并处警告、罚款、没收非法所得；对有关责任人员，由其所在单位或者上级主管机关依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）在河道管理范围内弃置、堆放阻碍行洪物体的；种植阻碍行洪的林木或者高秆植物的；修建围堤、阻水渠道、阻水道路的；\n（二）在堤防、护堤地建房、放牧、开渠、打井、挖窖、葬坟、晒粮、存放物料、开采地下资源、进行考古发掘以及开展集市贸易活动的；\n（三）未经批准或者不按照国家规定的防洪标准、工程安全标准整治河道或者修建水工程建筑物和其他设施的；\n（四）未经批准或者不按照河道主管机关的规定在河道管理范围内采砂、取土、淘金、弃置砂石或者淤泥、爆破、钻探、挖筑鱼塘的；\n（五）未经批准在河道滩地存放物料、修建厂房或者其他建筑设施，以及开采地下资源或者进行考古发掘的；\n（六）违反本条例第二十七条的规定，围垦湖泊、河流的；\n（七）擅自砍伐护堤护岸林木的；\n（八）汛期违反防汛指挥部的规定或者指令的。\n第四十五条 违反本条例规定，有下列行为之一的，县级以上地方人民政府河道主管机关除责令其纠正违法行为、赔偿损失、采取补救措施外，可以并处警告、罚款；应当给予治安管理处罚的，按照《中华人民共和国治安管理处罚法》的规定处罚；构成犯罪的，依法追究刑事责任：\n（一）损毁堤防、护岸、闸坝、水工程建筑物，损毁防汛设施、水文监测和测量设施、河岸地质监测设施以及通信照明等设施；\n（二）在堤防安全保护区内进行打井、钻探、爆破、挖筑鱼塘、采石、取土等危害堤防安全的活动的；\n（三）非管理人员操作河道上的涵闸闸门或者干扰河道管理单位正常工作的。\n第四十六条 当事人对行政处罚决定不服的，可以依法申请行政复议，也可以依法提起行政诉讼。当事人逾期不申请行政复议或者不向人民法院起诉又不履行行政处罚决定的，由作出行政处罚决定的机关申请人民法院强制执行。对治安管理处罚决定不服的，按照《中华人民共和国治安管理处罚法》的规定办理。\n第四十七条 对违反本条例规定，造成国家、集体、个人经济损失的，受害方可以请求县级以上河道主管机关处理。受害方也可以直接向人民法院起诉。\n当事人对河道主管机关的处理决定不服的，可以在接到通知之日起，15日内向人民法院起诉。\n第四十八条 河道主管机关的工作人员以及河道监理人员玩忽职守、滥用职权、徇私舞弊的，由其所在单位或者上级主管机关依法给予处分；对公共财产、国家和人民利益造成重大损失的，依法追究刑事责任。","level":1},{"name":"第七章 附 则","text":"第四十九条 各省、自治区、直辖市人民政府，可以根据本条例的规定，结合本地区的实际情况，制定实施办法。\n第五十条 本条例自发布之日起施行。","level":1}]},{"id":"n1294","sections":[{"name":"","text":"病原微生物实验室生物安全管理条例\n（2004年11月12日中华人民共和国国务院令第424号公布 根据2016年2月6日《国务院关于修改部分行政法规的决定》第一次修订 根据2018年3月19日《国务院关于修改和废止部分行政法规的决定》第二次修订 根据2024年12月6日《国务院关于修改和废止部分行政法规的决定》第三次修订 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》第四次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强病原微生物实验室（以下称实验室）生物安全管理，保护实验室工作人员和公众的健康，制定本条例。\n第二条 对中华人民共和国境内的实验室及其从事实验活动的生物安全管理，适用本条例。\n本条例所称病原微生物，是指能够使人或者动物致病的微生物。\n本条例所称实验活动，是指实验室从事与病原微生物菌（毒）种、样本有关的研究、教学、检测、诊断等活动。\n第三条 国务院卫生主管部门主管与人体健康有关的实验室及其实验活动的生物安全监督工作。\n国务院兽医主管部门主管与动物有关的实验室及其实验活动的生物安全监督工作。\n国务院其他有关部门在各自职责范围内负责实验室及其实验活动的生物安全管理工作。\n县级以上地方人民政府及其有关部门在各自职责范围内负责实验室及其实验活动的生物安全管理工作。\n第四条 国家对病原微生物实行分类管理，对实验室实行分级管理。\n第五条 国家实行统一的实验室生物安全标准。实验室应当符合国家标准和要求。\n第六条 实验室的设立单位及其主管部门负责实验室日常活动的管理，承担建立健全安全管理制度，检查、维护实验设施、设备，控制实验室感染的职责。","level":1},{"name":"第二章 病原微生物的分类和管理","text":"第七条 国家根据病原微生物的传染性、感染后对个体或者群体的危害程度，将病原微生物分为四类：\n第一类病原微生物，是指能够引起人类或者动物非常严重疾病的微生物，以及我国尚未发现或者已经宣布消灭的微生物。\n第二类病原微生物，是指能够引起人类或者动物严重疾病，比较容易直接或者间接在人与人、动物与人、动物与动物间传播的微生物。\n第三类病原微生物，是指能够引起人类或者动物疾病，但一般情况下对人、动物或者环境不构成严重危害，传播风险有限，实验室感染后很少引起严重疾病，并且具备有效治疗和预防措施的微生物。\n第四类病原微生物，是指在通常情况下不会引起人类或者动物疾病的微生物。\n第一类、第二类病原微生物统称为高致病性病原微生物。\n第八条 人间传染的病原微生物目录由国务院卫生主管部门商国务院有关部门后制定、调整并予以公布；动物间传染的病原微生物目录由国务院兽医主管部门商国务院有关部门后制定、调整并予以公布。\n第九条 采集病原微生物样本应当具备下列条件：\n（一）具有与采集病原微生物样本所需要的生物安全防护水平相适应的设备；\n（二）具有掌握相关专业知识和操作技能的工作人员；\n（三）具有有效的防止病原微生物扩散和感染的措施；\n（四）具有保证病原微生物样本质量的技术方法和手段。\n采集高致病性病原微生物样本的工作人员在采集过程中应当防止病原微生物扩散和感染，并对样本的来源、采集过程和方法等作详细记录。\n第十条 运输高致病性病原微生物菌（毒）种或者样本，应当通过陆路运输；没有陆路通道，必须经水路运输的，可以通过水路运输；紧急情况下或者需要将高致病性病原微生物菌（毒）种或者样本运往国外的，可以通过民用航空运输。\n第十一条 运输高致病性病原微生物菌（毒）种或者样本，应当具备下列条件：\n（一）运输目的、高致病性病原微生物的用途和接收单位符合国务院卫生主管部门或者兽医主管部门的规定；\n（二）高致病性病原微生物菌（毒）种或者样本的容器应当密封，容器或者包装材料还应当符合防水、防破损、防外泄、耐高（低）温、耐高压的要求；\n（三）容器或者包装材料上应当印有国务院卫生主管部门或者兽医主管部门规定的生物危险标识、警告用语和提示用语。\n运输高致病性病原微生物菌（毒）种或者样本，应当经省级以上人民政府卫生主管部门或者兽医主管部门批准。在省、自治区、直辖市行政区域内运输的，由省、自治区、直辖市人民政府卫生主管部门或者兽医主管部门批准；需要跨省、自治区、直辖市运输或者运往国外的，由出发地的省、自治区、直辖市人民政府卫生主管部门或者兽医主管部门进行初审后，分别报国务院卫生主管部门或者兽医主管部门批准。\n出入境检验检疫机构在检验检疫过程中需要运输病原微生物样本的，由国务院出入境检验检疫部门批准，并同时向国务院卫生主管部门或者兽医主管部门通报。\n通过民用航空运输高致病性病原微生物菌（毒）种或者样本的，除依照本条第二款、第三款规定取得批准外，还应当经国务院民用航空主管部门批准。\n有关主管部门应当对申请人提交的关于运输高致病性病原微生物菌（毒）种或者样本的申请材料进行审查，对符合本条第一款规定条件的，应当即时批准。\n第十二条 运输高致病性病原微生物菌（毒）种或者样本，应当由不少于2人的专人护送，并采取相应的防护措施。\n有关单位或者个人不得通过公共电（汽）车和城市铁路运输病原微生物菌（毒）种或者样本。\n第十三条 需要通过铁路、公路、民用航空等公共交通工具运输高致病性病原微生物菌（毒）种或者样本的，承运单位应当凭本条例第十一条规定的批准文件予以运输。\n承运单位应当与护送人共同采取措施，确保所运输的高致病性病原微生物菌（毒）种或者样本的安全，严防发生被盗、被抢、丢失、泄漏事件。\n第十四条 国务院卫生主管部门或者兽医主管部门指定的菌（毒）种保藏中心或者专业实验室（以下称保藏机构），承担集中储存病原微生物菌（毒）种和样本的任务。\n保藏机构应当依照国务院卫生主管部门或者兽医主管部门的规定，储存实验室送交的病原微生物菌（毒）种和样本，并向实验室提供病原微生物菌（毒）种和样本。\n保藏机构应当制定严格的安全保管制度，作好病原微生物菌（毒）种和样本进出和储存的记录，建立档案制度，并指定专人负责。对高致病性病原微生物菌（毒）种和样本应当设专库或者专柜单独储存。\n保藏机构储存、提供病原微生物菌（毒）种和样本，不得收取任何费用，其经费由同级财政在单位预算中予以保障。\n保藏机构的管理办法由国务院卫生主管部门会同国务院兽医主管部门制定。\n第十五条 保藏机构应当凭实验室依照本条例的规定取得的从事高致病性病原微生物相关实验活动的批准文件或者设区的市级人民政府卫生主管部门或者兽医主管部门发放的实验室备案凭证，向实验室提供高致病性病原微生物菌（毒）种和样本，并予以登记。\n第十六条 实验室在相关实验活动结束后，应当依照国务院卫生主管部门或者兽医主管部门的规定，及时将病原微生物菌（毒）种和样本就地销毁或者送交保藏机构保管。\n保藏机构接受实验室送交的病原微生物菌（毒）种和样本，应当予以登记，并开具接收证明。\n第十七条 高致病性病原微生物菌（毒）种或者样本在运输、储存中被盗、被抢、丢失、泄漏的，承运单位、护送人、保藏机构应当采取必要的控制措施，并在2小时内分别向承运单位的主管部门、护送人所在单位和保藏机构的主管部门报告，同时向所在地的县级人民政府卫生主管部门或者兽医主管部门报告，发生被盗、被抢、丢失的，还应当向公安机关报告；接到报告的卫生主管部门或者兽医主管部门应当在2小时内向本级人民政府报告，并同时向上级人民政府卫生主管部门或者兽医主管部门和国务院卫生主管部门或者兽医主管部门报告。\n县级人民政府应当在接到报告后2小时内向设区的市级人民政府或者上一级人民政府报告；设区的市级人民政府应当在接到报告后2小时内向省、自治区、直辖市人民政府报告。省、自治区、直辖市人民政府应当在接到报告后1小时内，向国务院卫生主管部门或者兽医主管部门报告。\n任何单位和个人发现高致病性病原微生物菌（毒）种或者样本的容器或者包装材料，应当及时向附近的卫生主管部门或者兽医主管部门报告；接到报告的卫生主管部门或者兽医主管部门应当及时组织调查核实，并依法采取必要的控制措施。","level":1},{"name":"第三章 实验室的设立与管理","text":"第十八条 国家根据实验室对病原微生物的生物安全防护水平，并依照实验室生物安全国家标准的规定，将实验室分为一级、二级、三级、四级。\n第十九条 新建、改建、扩建三级、四级实验室或者生产、进口移动式三级、四级实验室应当遵守下列规定：\n（一）符合国家生物安全实验室体系规划并依法履行有关审批手续；\n（二）经国务院卫生主管部门审查同意；\n（三）符合国家生物安全实验室建筑技术规范；\n（四）依法进行生态环境影响评价；\n（五）生物安全防护级别与其拟从事的实验活动相适应。\n前款规定所称国家生物安全实验室体系规划，由国务院投资主管部门会同国务院有关部门制定。制定国家生物安全实验室体系规划应当遵循总量控制、合理布局、资源共享的原则，并应当召开听证会或者论证会，听取公共卫生、环境保护、投资管理和实验室管理等方面专家的意见。\n第二十条 三级、四级实验室应当通过实验室国家认可。\n国务院认证认可监督管理部门确定的认可机构应当依照实验室生物安全国家标准以及本条例的有关规定，对三级、四级实验室进行认可；实验室通过认可的，颁发相应级别的生物安全实验室证书。证书有效期为5年。\n第二十一条 从事病原微生物实验活动应当在相应级别的实验室进行。实验室从事病原微生物实验活动，其级别应当不低于病原微生物目录规定的该项实验活动所需的实验室级别。\n一级、二级实验室仅可从事病原微生物目录规定的可以在一级、二级实验室进行的高致病性病原微生物实验活动。三级、四级实验室从事高致病性病原微生物实验活动，应当具备下列条件：\n（一）实验目的和拟从事的实验活动符合国务院卫生主管部门或者兽医主管部门的规定；\n（二）通过实验室国家认可；\n（三）具有与拟从事的实验活动相适应的工作人员；\n（四）工程质量经建筑主管部门依法检测验收合格。\n第二十二条 三级、四级实验室，需要从事病原微生物目录规定的应当在三级、四级实验室进行的高致病性病原微生物实验活动或者疑似高致病性病原微生物实验活动的，应当依照国务院卫生主管部门或者兽医主管部门的规定报省级以上人民政府卫生主管部门或者兽医主管部门批准。实验活动结果以及工作情况应当向原批准部门报告。\n实验室申报或者接受与高致病性病原微生物有关的科研项目，应当符合科研需要和生物安全要求，具有相应的生物安全防护水平。与动物间传染的高致病性病原微生物有关的科研项目，应当经国务院兽医主管部门同意；与人体健康有关的高致病性病原微生物科研项目，实验室应当将立项结果告知省级以上人民政府卫生主管部门。\n第二十三条 出入境检验检疫机构、医疗卫生机构、动物疫病预防控制机构在实验室开展检测、诊断工作时，发现高致病性病原微生物或者疑似高致病性病原微生物，需要进一步从事这类高致病性病原微生物相关实验活动的，应当在具备相应条件的实验室中进行；依照本条例的规定需要经过批准的，应当取得批准。\n专门从事检测、诊断的实验室应当严格依照国务院卫生主管部门或者兽医主管部门的规定，建立健全规章制度，保证实验室生物安全。\n第二十四条 省级以上人民政府卫生主管部门或者兽医主管部门应当自收到需要从事高致病性病原微生物相关实验活动的申请之日起15日内作出是否批准的决定。\n对出入境检验检疫机构为了检验检疫工作的紧急需要，申请在实验室对高致病性病原微生物或者疑似高致病性病原微生物开展进一步实验活动的，省级以上人民政府卫生主管部门或者兽医主管部门应当自收到申请之时起2小时内作出是否批准的决定；2小时内未作出决定的，实验室可以从事相应的实验活动。\n省级以上人民政府卫生主管部门或者兽医主管部门应当为申请人通过电报、电传、传真、电子数据交换和电子邮件等方式提出申请提供方便。\n第二十五条 新建、改建或者扩建一级、二级实验室，应当向设区的市级人民政府卫生主管部门或者兽医主管部门备案。设区的市级人民政府卫生主管部门或者兽医主管部门应当每年将备案情况汇总后报省、自治区、直辖市人民政府卫生主管部门或者兽医主管部门。\n第二十六条 国务院卫生主管部门和兽医主管部门应当定期汇总并互相通报实验室数量和实验室设立、分布情况，以及三级、四级实验室从事高致病性病原微生物实验活动的情况。\n第二十七条 已经建成并通过实验室国家认可的三级、四级实验室应当向所在地的县级人民政府环境保护主管部门备案。环境保护主管部门依照法律、行政法规的规定对实验室排放的废水、废气和其他废物处置情况进行监督检查。\n第二十八条 对我国尚未发现或者已经宣布消灭的病原微生物，任何单位和个人未经批准不得从事相关实验活动。\n为了预防、控制传染病，需要从事前款所指病原微生物相关实验活动的，应当经国务院卫生主管部门或者兽医主管部门批准，并在批准部门指定的专业实验室中进行。\n第二十九条 实验室使用新技术、新方法从事高致病性病原微生物相关实验活动的，应当符合防止高致病性病原微生物扩散、保证生物安全和操作者人身安全的要求，并经国家病原微生物实验室生物安全专家委员会论证；经论证可行的，方可使用。\n第三十条 需要在动物体上从事高致病性病原微生物相关实验活动的，应当按照病原微生物目录的规定，在符合动物实验室生物安全国家标准的相应级别的实验室进行。\n第三十一条 实验室的设立单位负责实验室的生物安全管理。\n实验室的设立单位应当依照本条例的规定制定科学、严格的管理制度，并定期对有关生物安全规定的落实情况进行检查，定期对实验室设施、设备、材料等进行检查、维护和更新，以确保其符合国家标准。\n实验室的设立单位及其主管部门应当加强对实验室日常活动的管理。\n第三十二条 实验室负责人为实验室生物安全的第一责任人。\n实验室从事实验活动应当严格遵守有关国家标准和实验室技术规范、操作规程。实验室负责人应当指定专人监督检查实验室技术规范和操作规程的落实情况。\n第三十三条 从事高致病性病原微生物相关实验活动的实验室的设立单位，应当建立健全安全保卫制度，采取安全保卫措施，严防高致病性病原微生物被盗、被抢、丢失、泄漏，保障实验室及其病原微生物的安全。实验室发生高致病性病原微生物被盗、被抢、丢失、泄漏的，实验室的设立单位应当依照本条例第十七条的规定进行报告。\n从事高致病性病原微生物相关实验活动的实验室应当向当地公安机关备案，并接受公安机关有关实验室安全保卫工作的监督指导。\n第三十四条 实验室或者实验室的设立单位应当每年定期对工作人员进行培训，保证其掌握实验室技术规范、操作规程、生物安全防护知识和实际操作技能，并进行考核。工作人员经考核合格的，方可上岗。\n从事高致病性病原微生物相关实验活动的实验室，应当每半年将培训、考核其工作人员的情况和实验室运行情况向省、自治区、直辖市人民政府卫生主管部门或者兽医主管部门报告。\n第三十五条 从事高致病性病原微生物相关实验活动应当有2名以上的工作人员共同进行。\n进入从事高致病性病原微生物相关实验活动的实验室的工作人员或者其他有关人员，应当经实验室负责人批准。实验室应当为其提供符合防护要求的防护用品并采取其他职业防护措施。从事高致病性病原微生物相关实验活动的实验室，还应当对实验室工作人员进行健康监测，每年组织对其进行体检，并建立健康档案；必要时，应当对实验室工作人员进行预防接种。\n第三十六条 在同一个实验室的同一个独立安全区域内，只能同时从事一种高致病性病原微生物的相关实验活动。\n第三十七条 实验室应当建立实验档案，记录实验室使用情况和安全监督情况。实验室从事高致病性病原微生物相关实验活动的实验档案保存期，不得少于20年。\n第三十八条 实验室应当依照环境保护的有关法律、行政法规和国务院有关部门的规定，对废水、废气以及其他废物进行处置，并制定相应的环境保护措施，防止环境污染。\n第三十九条 三级、四级实验室应当在明显位置标示国务院卫生主管部门和兽医主管部门规定的生物危险标识和生物安全实验室级别标志。\n第四十条 从事高致病性病原微生物相关实验活动的实验室应当制定实验室生物安全事件应急处置预案，并向该实验室所在地的省、自治区、直辖市人民政府卫生主管部门或者兽医主管部门备案。\n第四十一条 国务院卫生主管部门和兽医主管部门会同国务院有关部门组织病原学、免疫学、检验医学、流行病学、预防兽医学、环境保护和实验室管理等方面的专家，组成国家病原微生物实验室生物安全专家委员会。该委员会承担从事高致病性病原微生物相关实验活动的实验室的设立与运行的生物安全评估和技术咨询、论证工作。\n省、自治区、直辖市人民政府卫生主管部门和兽医主管部门会同同级人民政府有关部门组织病原学、免疫学、检验医学、流行病学、预防兽医学、环境保护和实验室管理等方面的专家，组成本地区病原微生物实验室生物安全专家委员会。该委员会承担本地区实验室设立和运行的技术咨询工作。","level":1},{"name":"第四章 实验室感染控制","text":"第四十二条 实验室的设立单位应当指定专门的机构或者人员承担实验室感染控制工作，定期检查实验室的生物安全防护、病原微生物菌（毒）种和样本保存与使用、安全操作、实验室排放的废水和废气以及其他废物处置等规章制度的实施情况。\n负责实验室感染控制工作的机构或者人员应当具有与该实验室中的病原微生物有关的传染病防治知识，并定期调查、了解实验室工作人员的健康状况。\n第四十三条 实验室工作人员出现与本实验室从事的高致病性病原微生物相关实验活动有关的感染临床症状或者体征时，实验室负责人应当向负责实验室感染控制工作的机构或者人员报告，同时派专人陪同及时就诊；实验室工作人员应当将近期所接触的病原微生物的种类和危险程度如实告知诊治医疗机构。接诊的医疗机构应当及时救治；不具备相应救治条件的，应当依照规定将感染的实验室工作人员转诊至具备相应传染病救治条件的医疗机构；具备相应传染病救治条件的医疗机构应当接诊治疗，不得拒绝救治。\n第四十四条 实验室发生高致病性病原微生物泄漏时，实验室工作人员应当立即采取控制措施，防止高致病性病原微生物扩散，并同时向负责实验室感染控制工作的机构或者人员报告。\n第四十五条 负责实验室感染控制工作的机构或者人员接到本条例第四十三条、第四十四条规定的报告后，应当立即启动实验室生物安全事件应急处置预案，并组织人员对该实验室生物安全状况等情况进行调查；确认发生实验室感染或者高致病性病原微生物泄漏的，应当依照本条例第十七条的规定进行报告，并同时采取控制措施，对有关人员进行医学观察或者隔离治疗，封闭实验室，防止扩散。\n第四十六条 卫生主管部门或者兽医主管部门接到关于实验室发生工作人员感染事故或者病原微生物泄漏事件的报告，或者发现实验室从事病原微生物相关实验活动造成实验室感染事故的，应当立即组织疾病预防控制机构、动物疫病预防控制机构和医疗机构以及其他有关机构依法采取下列预防、控制措施：\n（一）封闭被病原微生物污染的实验室或者可能造成病原微生物扩散的场所；\n（二）开展流行病学调查；\n（三）对病人进行隔离治疗，对相关人员进行医学检查；\n（四）对密切接触者进行医学观察；\n（五）进行现场消毒；\n（六）对染疫或者疑似染疫的动物采取隔离、扑杀等措施；\n（七）其他需要采取的预防、控制措施。\n第四十七条 医疗机构或者兽医医疗机构及其执行职务的医务人员发现由于实验室感染而引起的与高致病性病原微生物相关的传染病病人、疑似传染病病人或者患有疫病、疑似患有疫病的动物，诊治的医疗机构或者兽医医疗机构应当在2小时内报告所在地的县级人民政府卫生主管部门或者兽医主管部门；接到报告的卫生主管部门或者兽医主管部门应当在2小时内通报实验室所在地的县级人民政府卫生主管部门或者兽医主管部门。接到通报的卫生主管部门或者兽医主管部门应当依照本条例第四十六条的规定采取预防、控制措施。\n第四十八条 发生病原微生物扩散，有可能造成传染病暴发、流行时，县级以上人民政府卫生主管部门或者兽医主管部门应当依照有关法律、行政法规的规定以及实验室生物安全事件应急处置预案进行处理。","level":1},{"name":"第五章 监督管理","text":"第四十九条 县级以上地方人民政府卫生主管部门、兽医主管部门依照各自分工，履行下列职责：\n（一）对病原微生物菌（毒）种、样本的采集、运输、储存进行监督检查；\n（二）对从事高致病性病原微生物相关实验活动的实验室是否符合本条例规定的条件进行监督检查；\n（三）对实验室或者实验室的设立单位培训、考核其工作人员以及上岗人员的情况进行监督检查；\n（四）对实验室是否按照有关国家标准、技术规范和操作规程从事病原微生物相关实验活动进行监督检查。\n县级以上地方人民政府卫生主管部门、兽医主管部门，应当主要通过检查反映实验室执行国家有关法律、行政法规以及国家标准和要求的记录、档案、报告，切实履行监督管理职责。\n第五十条 县级以上人民政府卫生主管部门、兽医主管部门、环境保护主管部门在履行监督检查职责时，有权进入被检查单位和病原微生物泄漏或者扩散现场调查取证、采集样品，查阅复制有关资料。需要进入从事高致病性病原微生物相关实验活动的实验室调查取证、采集样品的，应当指定或者委托专业机构实施。被检查单位应当予以配合，不得拒绝、阻挠。\n第五十一条 国务院认证认可监督管理部门依照《中华人民共和国认证认可条例》的规定对实验室认可活动进行监督检查。\n第五十二条 卫生主管部门、兽医主管部门、环境保护主管部门应当依据法定的职权和程序履行职责，做到公正、公平、公开、文明、高效。\n第五十三条 卫生主管部门、兽医主管部门、环境保护主管部门的执法人员执行职务时，应当有2名以上执法人员参加，出示执法证件，并依照规定填写执法文书。\n现场检查笔录、采样记录等文书经核对无误后，应当由执法人员和被检查人、被采样人签名。被检查人、被采样人拒绝签名的，执法人员应当在自己签名后注明情况。\n第五十四条 卫生主管部门、兽医主管部门、环境保护主管部门及其执法人员执行职务，应当自觉接受社会和公民的监督。公民、法人和其他组织有权向上级人民政府及其卫生主管部门、兽医主管部门、环境保护主管部门举报地方人民政府及其有关主管部门不依照规定履行职责的情况。接到举报的有关人民政府或者其卫生主管部门、兽医主管部门、环境保护主管部门，应当及时调查处理。\n第五十五条 上级人民政府卫生主管部门、兽医主管部门、环境保护主管部门发现属于下级人民政府卫生主管部门、兽医主管部门、环境保护主管部门职责范围内需要处理的事项的，应当及时告知该部门处理；下级人民政府卫生主管部门、兽医主管部门、环境保护主管部门不及时处理或者不积极履行本部门职责的，上级人民政府卫生主管部门、兽医主管部门、环境保护主管部门应当责令其限期改正；逾期不改正的，上级人民政府卫生主管部门、兽医主管部门、环境保护主管部门有权直接予以处理。","level":1},{"name":"第六章 法律责任","text":"第五十六条 三级、四级实验室未经批准从事病原微生物目录规定的应当在三级、四级实验室进行的高致病性病原微生物实验活动或者疑似高致病性病原微生物实验活动的，由县级以上地方人民政府卫生主管部门、兽医主管部门依照各自职责，责令停止有关活动，监督其将用于实验活动的病原微生物销毁或者送交保藏机构，并给予警告；造成传染病传播、流行或者其他严重后果的，由实验室的设立单位对主要负责人、直接负责的主管人员和其他直接责任人员，依法给予撤职、开除的处分；构成犯罪的，依法追究刑事责任。\n第五十七条 卫生主管部门或者兽医主管部门违反本条例的规定，准予不符合本条例规定条件的实验室从事高致病性病原微生物相关实验活动的，由作出批准决定的卫生主管部门或者兽医主管部门撤销原批准决定，责令有关实验室立即停止有关活动，并监督其将用于实验活动的病原微生物销毁或者送交保藏机构，对直接负责的主管人员和其他直接责任人员依法给予行政处分；构成犯罪的，依法追究刑事责任。\n因违法作出批准决定给当事人的合法权益造成损害的，作出批准决定的卫生主管部门或者兽医主管部门应当依法承担赔偿责任。\n第五十八条 卫生主管部门或者兽医主管部门对出入境检验检疫机构为了检验检疫工作的紧急需要，申请在实验室对高致病性病原微生物或者疑似高致病性病原微生物开展进一步检测活动，不在法定期限内作出是否批准决定的，由其上级行政机关或者监察机关责令改正，给予警告；造成传染病传播、流行或者其他严重后果的，对直接负责的主管人员和其他直接责任人员依法给予撤职、开除的行政处分；构成犯罪的，依法追究刑事责任。\n第五十九条 违反本条例规定，在不符合相应生物安全要求的实验室从事病原微生物相关实验活动的，由县级以上地方人民政府卫生主管部门、兽医主管部门依照各自职责，责令停止有关活动，监督其将用于实验活动的病原微生物销毁或者送交保藏机构，并给予警告；造成传染病传播、流行或者其他严重后果的，由实验室的设立单位对主要负责人、直接负责的主管人员和其他直接责任人员，依法给予撤职、开除的处分；构成犯罪的，依法追究刑事责任。\n第六十条 实验室有下列行为之一的，由县级以上地方人民政府卫生主管部门、兽医主管部门依照各自职责，责令限期改正，给予警告；逾期不改正的，由实验室的设立单位对主要负责人、直接负责的主管人员和其他直接责任人员，依法给予撤职、开除的处分；有许可证件的，并由原发证部门吊销有关许可证件：\n（一）未依照规定在明显位置标示国务院卫生主管部门和兽医主管部门规定的生物危险标识和生物安全实验室级别标志的；\n（二）未向原批准部门报告实验活动结果以及工作情况的；\n（三）未依照规定采集病原微生物样本，或者对所采集样本的来源、采集过程和方法等未作详细记录的；\n（四）新建、改建或者扩建一级、二级实验室未向设区的市级人民政府卫生主管部门或者兽医主管部门备案的；\n（五）未依照规定定期对工作人员进行培训，或者工作人员考核不合格允许其上岗，或者批准未采取防护措施的人员进入实验室的；\n（六）实验室工作人员未遵守实验室生物安全技术规范和操作规程的；\n（七）未依照规定建立或者保存实验档案的；\n（八）未依照规定制定实验室生物安全事件应急处置预案并备案的。\n第六十一条 从事高致病性病原微生物相关实验活动的实验室的设立单位未建立健全安全保卫制度，或者未采取安全保卫措施的，由县级以上地方人民政府卫生主管部门、兽医主管部门依照各自职责，责令限期改正；逾期不改正，导致高致病性病原微生物菌（毒）种、样本被盗、被抢或者造成其他严重后果的，责令停止该项实验活动，该实验室2年内不得从事高致病性病原微生物实验活动；造成传染病传播、流行的，该实验室设立单位的主管部门还应当对该实验室的设立单位的直接负责的主管人员和其他直接责任人员，依法给予降级、撤职、开除的处分；构成犯罪的，依法追究刑事责任。\n第六十二条 未经批准运输高致病性病原微生物菌（毒）种或者样本，或者承运单位经批准运输高致病性病原微生物菌（毒）种或者样本未履行保护义务，导致高致病性病原微生物菌（毒）种或者样本被盗、被抢、丢失、泄漏的，由县级以上地方人民政府卫生主管部门、兽医主管部门依照各自职责，责令采取措施，消除隐患，给予警告；造成传染病传播、流行或者其他严重后果的，由托运单位和承运单位的主管部门对主要负责人、直接负责的主管人员和其他直接责任人员，依法给予撤职、开除的处分；构成犯罪的，依法追究刑事责任。\n第六十三条 有下列行为之一的，由实验室所在地的设区的市级以上地方人民政府卫生主管部门、兽医主管部门依照各自职责，责令有关单位立即停止违法活动，监督其将病原微生物销毁或者送交保藏机构；造成传染病传播、流行或者其他严重后果的，由其所在单位或者其上级主管部门对主要负责人、直接负责的主管人员和其他直接责任人员，依法给予撤职、开除的处分；有许可证件的，并由原发证部门吊销有关许可证件；构成犯罪的，依法追究刑事责任：\n（一）实验室在相关实验活动结束后，未依照规定及时将病原微生物菌（毒）种和样本就地销毁或者送交保藏机构保管的；\n（二）实验室使用新技术、新方法从事高致病性病原微生物相关实验活动未经国家病原微生物实验室生物安全专家委员会论证的；\n（三）未经批准擅自从事在我国尚未发现或者已经宣布消灭的病原微生物相关实验活动的；\n（四）在未经指定的专业实验室从事在我国尚未发现或者已经宣布消灭的病原微生物相关实验活动的；\n（五）在同一个实验室的同一个独立安全区域内同时从事两种或者两种以上高致病性病原微生物的相关实验活动的。\n第六十四条 认可机构对不符合实验室生物安全国家标准以及本条例规定条件的实验室予以认可，或者对符合实验室生物安全国家标准以及本条例规定条件的实验室不予认可的，由国务院认证认可监督管理部门责令限期改正，给予警告；造成传染病传播、流行或者其他严重后果的，由国务院认证认可监督管理部门撤销其认可资格，有上级主管部门的，由其上级主管部门对主要负责人、直接负责的主管人员和其他直接责任人员依法给予撤职、开除的处分；构成犯罪的，依法追究刑事责任。\n第六十五条 实验室工作人员出现该实验室从事的病原微生物相关实验活动有关的感染临床症状或者体征，以及实验室发生高致病性病原微生物泄漏时，实验室负责人、实验室工作人员、负责实验室感染控制的专门机构或者人员未依照规定报告，或者未依照规定采取控制措施的，由县级以上地方人民政府卫生主管部门、兽医主管部门依照各自职责，责令限期改正，给予警告；造成传染病传播、流行或者其他严重后果的，由其设立单位对实验室主要负责人、直接负责的主管人员和其他直接责任人员，依法给予撤职、开除的处分；有许可证件的，并由原发证部门吊销有关许可证件；构成犯罪的，依法追究刑事责任。\n第六十六条 拒绝接受卫生主管部门、兽医主管部门依法开展有关高致病性病原微生物扩散的调查取证、采集样品等活动或者依照本条例规定采取有关预防、控制措施的，由县级以上人民政府卫生主管部门、兽医主管部门依照各自职责，责令改正，给予警告；造成传染病传播、流行以及其他严重后果的，由实验室的设立单位对实验室主要负责人、直接负责的主管人员和其他直接责任人员，依法给予降级、撤职、开除的处分；有许可证件的，并由原发证部门吊销有关许可证件；构成犯罪的，依法追究刑事责任。\n第六十七条 发生病原微生物被盗、被抢、丢失、泄漏，承运单位、护送人、保藏机构和实验室的设立单位未依照本条例的规定报告的，由所在地的县级人民政府卫生主管部门或者兽医主管部门给予警告；造成传染病传播、流行或者其他严重后果的，由实验室的设立单位或者承运单位、保藏机构的上级主管部门对主要负责人、直接负责的主管人员和其他直接责任人员，依法给予撤职、开除的处分；构成犯罪的，依法追究刑事责任。\n第六十八条 保藏机构未依照规定储存实验室送交的菌（毒）种和样本，或者未依照规定提供菌（毒）种和样本的，由其指定部门责令限期改正，收回违法提供的菌（毒）种和样本，并给予警告；造成传染病传播、流行或者其他严重后果的，由其所在单位或者其上级主管部门对主要负责人、直接负责的主管人员和其他直接责任人员，依法给予撤职、开除的处分；构成犯罪的，依法追究刑事责任。\n第六十九条 县级以上人民政府有关主管部门，未依照本条例的规定履行实验室及其实验活动监督检查职责的，由有关人民政府在各自职责范围内责令改正，通报批评；造成传染病传播、流行或者其他严重后果的，对直接负责的主管人员，依法给予行政处分；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附 则","text":"第七十条 军队实验室由中国人民解放军卫生主管部门参照本条例负责监督管理。\n第七十一条 本条例施行前设立的实验室，应当自本条例施行之日起6个月内，依照本条例的规定，办理有关手续。\n第七十二条 本条例自公布之日起施行。","level":1}]},{"id":"n1295","sections":[{"name":"","text":"南水北调工程供用水管理条例\n（2014年2月16日中华人民共和国国务院令第647号公布 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强南水北调工程的供用水管理，充分发挥南水北调工程的经济效益、社会效益和生态效益，制定本条例。\n第二条 南水北调东线工程、中线工程的供用水管理，适用本条例。\n第三条 南水北调工程的供用水管理遵循先节水后调水、先治污后通水、先环保后用水的原则，坚持全程管理、统筹兼顾、权责明晰、严格保护，确保调度合理、水质合格、用水节约、设施安全。\n第四条 国务院水行政主管部门负责南水北调工程的水量调度、运行管理工作，国务院环境保护主管部门负责南水北调工程的水污染防治工作，国务院其他有关部门在各自职责范围内，负责南水北调工程供用水的有关工作。\n第五条 南水北调工程水源地、调水沿线区域、受水区县级以上地方人民政府负责本行政区域内南水北调工程供用水的有关工作，并将南水北调工程的水质保障、用水管理纳入国民经济和社会发展规划。\n国家对南水北调工程水源地、调水沿线区域的产业结构调整、生态环境保护予以支持，确保南水北调工程供用水安全。\n第六条 国务院确定的南水北调工程管理单位具体负责南水北调工程的运行和保护工作。\n南水北调工程受水区省、直辖市人民政府确定的单位具体负责本行政区域内南水北调配套工程的运行和保护工作。","level":1},{"name":"第二章 水量调度","text":"第七条 南水北调工程水量调度遵循节水为先、适度从紧的原则，统筹协调水源地、受水区和调水下游区域用水，加强生态环境保护。\n南水北调工程水量调度以国务院批准的多年平均调水量和受水区省、直辖市水量分配指标为基本依据。\n第八条 南水北调东线工程水量调度年度为每年10月1日至次年9月30日；南水北调中线工程水量调度年度为每年11月1日至次年10月31日。\n第九条 淮河水利委员会商长江水利委员会提出南水北调东线工程年度可调水量，于每年9月15日前报送国务院水行政主管部门，并抄送有关省人民政府和南水北调工程管理单位。\n长江水利委员会提出南水北调中线工程年度可调水量，于每年10月15日前报送国务院水行政主管部门，并抄送有关省、直辖市人民政府和南水北调工程管理单位。\n第十条 南水北调工程受水区省、直辖市人民政府水行政主管部门根据年度可调水量提出年度用水计划建议。属于南水北调东线工程受水区的于每年9月20日前、属于南水北调中线工程受水区的于每年10月20日前，报送国务院水行政主管部门，并抄送有关流域管理机构和南水北调工程管理单位。\n年度用水计划建议应当包括年度引水总量建议和月引水量建议。\n第十一条 国务院水行政主管部门综合平衡年度可调水量和南水北调工程受水区省、直辖市年度用水计划建议，按照国务院批准的受水区省、直辖市水量分配指标的比例，制订南水北调工程年度水量调度计划，征求国务院有关部门意见后，在水量调度年度开始前下达有关省、直辖市人民政府和南水北调工程管理单位。\n第十二条 南水北调工程管理单位根据年度水量调度计划制订月水量调度方案，涉及到航运的，应当与交通运输主管部门协商，协商不一致的，由县级以上人民政府决定；雨情、水情出现重大变化，月水量调度方案无法实施的，应当及时进行调整并报告国务院水行政主管部门。\n第十三条 南水北调工程供水实行由基本水价和计量水价构成的两部制水价，具体供水价格由国务院价格主管部门会同国务院有关部门制定。\n水费应当及时、足额缴纳，专项用于南水北调工程运行维护和偿还贷款。\n第十四条 南水北调工程受水区省、直辖市人民政府授权的部门或者单位应当与南水北调工程管理单位签订供水合同。供水合同应当包括年度供水量、供水水质、交水断面、交水方式、水价、水费缴纳时间和方式、违约责任等。\n第十五条 水量调度年度内南水北调工程受水区省、直辖市用水需求出现重大变化，需要转让年度水量调度计划分配的水量的，由有关省、直辖市人民政府授权的部门或者单位协商签订转让协议，确定转让价格，并将转让协议报送国务院水行政主管部门，抄送南水北调工程管理单位；国务院水行政主管部门和南水北调工程管理单位应当相应调整年度水量调度计划和月水量调度方案。\n第十六条 国务院水行政主管部门应当会同国务院有关部门和有关省、直辖市人民政府以及南水北调工程管理单位编制南水北调工程水量调度应急预案，报国务院批准。\n南水北调工程水源地和受水区省、直辖市人民政府有关部门、有关流域管理机构以及南水北调工程管理单位应当根据南水北调工程水量调度应急预案，制定相应的应急预案。\n第十七条 南水北调工程水量调度应急预案应当针对重大洪涝灾害、干旱灾害、生态破坏事故、水污染事故、工程安全事故等突发事件，规定应急管理工作的组织指挥体系与职责、预防与预警机制、处置程序、应急保障措施以及事后恢复与重建措施等内容。\n国务院或者国务院授权的部门宣布启动南水北调工程水量调度应急预案后，可以依法采取下列应急处置措施：\n（一）临时限制取水、用水、排水；\n（二）统一调度有关河道的水工程；\n（三）征用治污、供水等所需设施；\n（四）封闭通航河道。\n第十八条 国务院水行政主管部门、环境保护主管部门按照职责组织对南水北调工程省界交水断面、东线工程取水口、丹江口水库的水量、水质进行监测。\n国务院水行政主管部门、环境保护主管部门按照职责定期向社会公布南水北调工程供用水水量、水质信息，并建立水量、水质信息共享机制。","level":1},{"name":"第三章 水质保障","text":"第十九条 南水北调工程水质保障实行县级以上地方人民政府目标责任制和考核评价制度。\n南水北调工程水源地、调水沿线区域县级以上地方人民政府应当加强工业、城镇、农业和农村、船舶等水污染防治，建设防护林等生态隔离保护带，确保供水安全。\n依照有关法律、行政法规的规定，对南水北调工程水源地实行水环境生态保护补偿。\n第二十条 南水北调东线工程调水沿线区域和中线工程水源地实行重点水污染物排放总量控制制度。\n南水北调东线工程调水沿线区域和中线工程水源地省人民政府应当将国务院确定的重点水污染物排放总量控制指标逐级分解下达到有关市、县人民政府，由市、县人民政府分解落实到水污染物排放单位。\n第二十一条 南水北调东线工程调水沿线区域禁止建设不符合国家产业政策、不能实现水污染物稳定达标排放的建设项目。现有的落后生产技术、工艺、设备等，由当地省人民政府组织淘汰。\n南水北调中线工程水源地禁止建设增加污染物排放总量的建设项目。\n第二十二条 南水北调东线工程调水沿线区域和中线工程水源地的水污染物排放单位，应当配套建设与其排放量相适应的治理设施；实行排污许可重点管理的单位应当按照有关规定安装自动监测设备。\n南水北调东线工程干线、中线工程总干渠禁止设置排污口。\n第二十三条 南水北调东线工程调水沿线区域和中线工程水源地县级以上地方人民政府所在城镇排放的污水，应当经过集中处理，实现达标排放。\n南水北调东线工程调水沿线区域和中线工程水源地县级以上地方人民政府应当合理规划、建设污水集中处理设施和配套管网，并组织收集、无害化处理城乡生活垃圾，避免污染水环境。\n南水北调东线工程调水沿线区域和中线工程水源地的畜禽养殖场、养殖小区，应当按照国家有关规定对畜禽粪便、废水等进行无害化处理和资源化利用。\n第二十四条 南水北调东线工程调水沿线区域和中线工程水源地县级人民政府应当根据水源保护的需要，划定禁止或者限制采伐、开垦区域。\n南水北调东线工程调水沿线区域、中线工程水源地、中线工程总干渠沿线区域应当规划种植生态防护林；生态地位重要的水域应当采取建设人工湿地等措施，提高水体自净能力。\n第二十五条 南水北调东线工程取水口、丹江口水库、中线工程总干渠需要划定饮用水水源保护区的，依照《中华人民共和国生态环境法典》的规定划定，实行严格保护。\n第二十六条 丹江口水库库区和洪泽湖、骆马湖、南四湖、东平湖湖区应当按照水功能区和南水北调工程水质保障的要求，由当地省人民政府组织逐步拆除现有的网箱养殖、围网养殖设施，严格控制人工养殖的规模、品种和密度。对因清理水产养殖设施导致转产转业的农民，当地县级以上地方人民政府应当给予补贴和扶持，并通过劳动技能培训、纳入社会保障体系等方式，保障其基本生活。\n丹江口水库库区和洪泽湖、骆马湖、南四湖、东平湖湖区禁止餐饮等经营活动。\n第二十七条 南水北调东线工程干线规划通航河道、丹江口水库及其上游通航河道应当科学规划建设港口、码头等航运设施，港口、码头应当配备与其吞吐能力相适应的船舶污染物接收、处理设备。现有的港口、码头不能达到水环境保护要求的，由当地省人民政府组织治理或者关闭。\n在前款规定河道航行的船舶应当按照要求进行技术改造，实现污染物船内封闭、收集上岸，不向水体排放；达不到要求的船舶和运输危险废物、危险化学品的船舶，不得进入上述河道，有关船闸管理单位不得放行。\n第二十八条 建设穿越、跨越、邻接南水北调工程输水河道的桥梁、公路、石油天然气管道、雨污水管道等工程设施的，其建设、管理单位应当设置警示标志，并采取有效措施，防范工程建设或者交通事故、管道泄漏等带来的安全风险。","level":1},{"name":"第四章 用水管理","text":"第二十九条 南水北调工程受水区县级以上地方人民政府应当统筹配置南水北调工程供水和当地水资源，逐步替代超采的地下水，严格控制地下水开发利用，改善水生态环境。\n第三十条 南水北调工程受水区县级以上地方人民政府应当以南水北调工程供水替代不适合作为饮用水水源的当地水源，并逐步退还因缺水挤占的农业用水和生态环境用水。\n第三十一条 南水北调工程受水区县级以上地方人民政府应当对本行政区域的年度用水实行总量控制，加强用水定额管理，推广节水技术、设备和设施，提高用水效率和效益。\n南水北调工程受水区县级以上地方人民政府应当鼓励、引导农民和农业生产经营组织调整农业种植结构，因地制宜减少高耗水作物种植比例，推行节水灌溉方式，促进节水农业发展。\n第三十二条 南水北调工程受水区省、直辖市人民政府应当制订并公布本行政区域内禁止、限制类建设项目名录，淘汰、限制高耗水、高污染的建设项目。\n第三十三条 南水北调工程受水区省、直辖市人民政府应当将国务院批准的地下水压采总体方案确定的地下水开采总量控制指标和地下水压采目标，逐级分解下达到有关市、县人民政府，并组织编制本行政区域的地下水限制开采方案和年度计划，报国务院水行政主管部门、国土资源主管部门备案。\n第三十四条 南水北调工程受水区内地下水超采区禁止新增地下水取用水量。具备水源替代条件的地下水超采区，应当划定为地下水禁采区，禁止取用地下水。\n南水北调工程受水区禁止新增开采深层承压水。\n第三十五条 南水北调工程受水区省、直辖市人民政府应当统筹考虑南水北调工程供水价格与当地地表水、地下水等各种水源的水资源费和供水价格，鼓励充分利用南水北调工程供水，促进水资源合理配置。","level":1},{"name":"第五章 工程设施管理和保护","text":"第三十六条 南水北调工程水源地、调水沿线区域、受水区县级以上地方人民政府应当做好工程设施安全保护有关工作，防范和制止危害南水北调工程设施安全的行为。\n第三十七条 南水北调工程管理单位应当建立、健全安全生产责任制，加强对南水北调工程设施的监测、检查、巡查、维修和养护，配备必要的人员和设备，定期进行应急演练，确保工程安全运行，并及时组织清理管理范围内水域、滩地的垃圾。\n第三十八条 南水北调工程应当依法划定管理范围和保护范围。\n南水北调东线工程的管理范围和保护范围，由工程所在地的省人民政府组织划定；其中，省际工程的管理范围和保护范围，由国务院水行政主管部门或者其授权的流域管理机构商有关省人民政府组织划定。\n丹江口水库、南水北调中线工程总干渠的管理范围和保护范围，由国务院水行政主管部门或者其授权的流域管理机构商有关省、直辖市人民政府组织划定。\n第三十九条 南水北调工程管理范围按照国务院批准的设计文件划定。\n南水北调工程管理单位应当在工程管理范围边界和地下工程位置上方地面设立界桩、界碑等保护标志，并设立必要的安全隔离设施对工程进行保护。未经南水北调工程管理单位同意，任何人不得进入设置安全隔离设施的区域。\n南水北调工程管理范围内的土地不得转作其他用途，任何单位和个人不得侵占；管理范围内禁止擅自从事与工程管理无关的活动。\n第四十条 南水北调工程保护范围按照下列原则划定并予以公告：\n（一）东线明渠输水工程为从堤防背水侧的护堤地边线向外延伸至50米以内的区域，中线明渠输水工程为从管理范围边线向外延伸至200米以内的区域；\n（二）暗涵、隧洞、管道等地下输水工程为工程设施上方地面以及从其边线向外延伸至50米以内的区域；\n（三）倒虹吸、渡槽、暗渠等交叉工程为从管理范围边线向交叉河道上游延伸至不少于500米不超过1000米、向交叉河道下游延伸至不少于1000米不超过3000米以内的区域；\n（四）泵站、水闸、管理站、取水口等其他工程设施为从管理范围边线向外延伸至不少于50米不超过200米以内的区域。\n第四十一条 南水北调工程管理单位应当在工程沿线路口、村庄等地段设置安全警示标志；有关地方人民政府主管部门应当按照有关规定，在交叉桥梁入口处设置限制质量、轴重、速度、高度、宽度等标志，并采取相应的工程防范措施。\n第四十二条 禁止危害南水北调工程设施的下列行为：\n（一）侵占、损毁输水河道（渠道、管道）、水库、堤防、护岸；\n（二）在地下输水管道、堤坝上方地面种植深根植物或者修建鱼池等储水设施、堆放超重物品；\n（三）移动、覆盖、涂改、损毁标志物；\n（四）侵占、损毁或者擅自使用、操作专用输电线路设施、专用通信线路、闸门等设施；\n（五）侵占、损毁交通、通信、水文水质监测等其他设施。\n禁止擅自从南水北调工程取用水资源。\n第四十三条 禁止在南水北调工程保护范围内实施影响工程运行、危害工程安全和供水安全的爆破、打井、采矿、取土、采石、采砂、钻探、建房、建坟、挖塘、挖沟等行为。\n第四十四条 在南水北调工程管理范围和保护范围内建设桥梁、码头、公路、铁路、地铁、船闸、管道、缆线、取水、排水等工程设施，按照国家规定的基本建设程序报请审批、核准时，审批、核准单位应当征求南水北调工程管理单位对拟建工程设施建设方案的意见。\n前款规定的建设项目在施工、维护、检修前，应当通报南水北调工程管理单位，施工、维护、检修过程中不得影响南水北调工程设施安全和正常运行。\n第四十五条 在汛期，南水北调工程管理单位应当加强巡查，发现险情立即采取抢修等措施，并及时向有关防汛抗旱指挥机构报告。\n第四十六条 南水北调工程管理单位应当加强南水北调工程设施的安全保护，制定安全保护方案，建立健全安全保护责任制，加强安全保护设施的建设、维护，落实治安防范措施，及时排除隐患。\n南水北调工程重要水域、重要设施需要派出中国人民武装警察部队守卫或者抢险救援的，依照《中华人民共和国人民武装警察法》和国务院、中央军事委员会的有关规定执行。\n第四十七条 在紧急情况下，南水北调工程管理单位因工程抢修需要取土占地或者使用有关设施的，有关单位和个人应当予以配合。南水北调工程管理单位应当于事后恢复原状；造成损失的，应当依法予以补偿。","level":1},{"name":"第六章 法律责任","text":"第四十八条 行政机关及其工作人员违反本条例规定，有下列行为之一的，由主管机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任：\n（一）不及时制订下达或者不执行年度水量调度计划的；\n（二）不编制或者不执行水量调度应急预案的；\n（三）不编制或者不执行南水北调工程受水区地下水限制开采方案的；\n（四）不履行水量、水质监测职责的；\n（五）不履行本条例规定的其他职责的。\n第四十九条 南水北调工程管理单位及其工作人员违反本条例规定，有下列行为之一的，由主管机关或者监察机关责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员依法给予处分；直接负责的主管人员和其他直接责任人员构成犯罪的，依法追究刑事责任：\n（一）虚假填报或者篡改工程运行情况等资料的；\n（二）不执行年度水量调度计划或者水量调度应急预案的；\n（三）不及时制订或者不执行月水量调度方案的；\n（四）对工程设施疏于监测、检查、巡查、维修、养护，不落实安全生产责任制，影响工程安全、供水安全的；\n（五）不履行本条例规定的其他职责的。\n第五十条 违反本条例规定，实施排放水污染物等危害南水北调工程水质安全行为的，依照《中华人民共和国生态环境法典》的规定处理；构成犯罪的，依法追究刑事责任。\n违反本条例规定，在南水北调工程受水区地下水禁采区取用地下水、在受水区地下水超采区新增地下水取用水量、在受水区新增开采深层承压水，或者擅自从南水北调工程取用水资源的，依照《中华人民共和国水法》的规定处理。\n第五十一条 违反本条例规定，运输危险废物、危险化学品的船舶进入南水北调东线工程干线规划通航河道、丹江口水库及其上游通航河道的，由县级以上地方人民政府负责海事、渔业工作的行政主管部门按照职责权限予以扣押，对危险废物、危险化学品采取卸载等措施，所需费用由违法行为人承担；构成犯罪的，依法追究刑事责任。\n第五十二条 违反本条例规定，建设穿越、跨越、邻接南水北调工程输水河道的桥梁、公路、石油天然气管道、雨污水管道等工程设施，未采取有效措施，危害南水北调工程安全和供水安全的，由建设项目审批、核准单位责令采取补救措施；在补救措施落实前，暂停工程设施建设。\n第五十三条 违反本条例规定，侵占、损毁、危害南水北调工程设施，或者在南水北调工程保护范围内实施影响工程运行、危害工程安全和供水安全的行为的，依照《中华人民共和国水法》的规定处理；《中华人民共和国水法》未作规定的，由县级以上人民政府水行政主管部门或者流域管理机构按照职责权限，责令停止违法行为，限期采取补救措施；造成损失的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第五十四条 南水北调工程水源地、调水沿线区域有下列情形之一的，暂停审批有关行政区域除污染减排和生态恢复项目外所有建设项目的环境影响评价文件：\n（一）在东线工程干线、中线工程总干渠设置排污口的；\n（二）排污超过重点水污染物排放总量控制指标的；\n（三）违法批准建设污染水环境的建设项目造成重大水污染事故等严重后果，未落实补救措施的。","level":1},{"name":"第七章 附 则","text":"第五十五条 南水北调东线工程，指从江苏省扬州市附近的长江干流引水，调水到江苏省北部和山东省等地的主体工程。\n南水北调中线工程，指从丹江口水库引水，调水到河南省、河北省、北京市、天津市的主体工程。\n南水北调配套工程，指东线工程、中线工程分水口门以下，配置、调度分配给本行政区域使用的南水北调供水的工程。\n第五十六条 本条例自公布之日起施行。","level":1}]},{"id":"n1296","sections":[{"name":"","text":"生态环境监测条例\n（2025年10月31日中华人民共和国国务院令第820号公布 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了规范生态环境监测活动，提升生态环境监测能力和水平，保障生态环境监测数据质量，更好发挥生态环境监测在支撑生态文明和美丽中国建设、服务经济社会高质量发展中的重要作用，根据有关法律，制定本条例。\n第二条 在中华人民共和国领域及管辖的其他海域开展生态环境监测及其相关活动，适用本条例。法律、行政法规另有规定的，依照其规定。\n本条例所称生态环境监测，包括政府及其有关部门为履行生态环境保护等职责开展或者组织开展的生态环境监测（以下统称公共监测），以及负有法定监测义务的企业事业单位和其他生产经营者（以下统称企事业单位）就其相关活动对生态环境的影响开展的自行监测。\n第三条 生态环境监测工作应当贯彻党和国家路线方针政策、决策部署，坚持依法监测、科学监测、诚信监测，构建政府主导、部门协同、企事业单位履责、社会参与、公众监督的机制。\n第四条 国家建立健全生态环境监测制度，完善生态环境监测规范和标准。开展生态环境监测应当遵守生态环境监测规范和标准。\n第五条 国家加强生态环境监测能力建设，加快建立现代化生态环境监测体系，构建陆海统筹、天地一体、上下协同、信息共享的生态环境监测网络，全面提升生态环境监测的自动化、数字化、智能化水平。\n第六条 县级以上人民政府应当加强对生态环境监测工作的组织领导和支持保障，统筹协调解决生态环境监测工作中的重大问题，按照财政事权和支出责任划分原则将开展生态环境监测工作所需经费列入本级预算。\n第七条 国务院生态环境主管部门在其职责范围内负责全国的生态环境监测工作。国务院自然资源、住房和城乡建设、交通运输、水行政、农业农村、气象、林业草原、疾病预防控制等有关部门按照职责分工，负责生态环境监测有关工作。\n地方人民政府生态环境主管部门在其职责范围内负责本行政区域内生态环境监测工作。地方人民政府有关部门按照职责分工，负责本行政区域内生态环境监测有关工作。\n第八条 地方各级人民政府应当建立健全防范和惩治生态环境监测数据弄虚作假的责任体系和工作机制，确保生态环境监测数据真实、准确、全面。\n第九条 国家鼓励、支持生态环境监测先进技术和装备的研究、开发和应用，加大生态环境监测专业人才培养力度，促进生态环境监测国际交流合作。\n国家建立健全生态环境监测数据汇交制度和集成共享机制，鼓励、支持生态环境监测数据深度开发和应用。","level":1},{"name":"第二章 公共监测","text":"第十条 地方各级人民政府、县级以上人民政府有关部门应当认真履行生态环境监测职责，依照法律、法规规定以及生态环境保护工作需要，开展或者组织开展生态环境质量监测、生态环境监督监测、突发生态环境事件应急监测等公共监测。\n第十一条 国务院生态环境主管部门会同国务院有关部门组织国家生态环境监测网络。设区的市级以上地方人民政府生态环境主管部门会同同级有关部门组织本行政区域内地方生态环境监测网络。\n组织生态环境监测网络，应当坚持布局合理、功能完善、分级分类、共建共享的原则，推进国家生态环境监测网络和地方生态环境监测网络互联互通。\n第十二条 国务院生态环境主管部门会同国务院有关部门统一规划国家生态环境质量监测站点设置。省、自治区、直辖市人民政府生态环境主管部门会同同级有关部门统一规划本行政区域内地方生态环境质量监测站点设置。设置、调整和撤销地方生态环境质量监测站点，应当报国务院生态环境主管部门或者国务院有关部门备案。\n生态环境质量监测站点设置应当符合生态环境监测规范的要求，避免重复建设。\n第十三条 生态环境主管部门、其他有关部门应当按照职责分工，加强对生态环境质量监测站点的管理，保证生态环境质量监测站点正常运行。\n地方各级人民政府应当依法为生态环境质量监测站点的建设、运行提供保障，并采取措施加强对生态环境质量监测站点的保护。\n任何单位和个人不得侵占、损毁生态环境质量监测站点及其设施、设备，不得干扰生态环境质量监测站点正常运行。\n第十四条 国务院生态环境主管部门会同国务院有关部门组织开展重点区域、流域、海域生态环境质量监测，为推动区域协调发展、科学实施生态保护补偿、优化产业布局等提供支撑。\n县级以上地方人民政府及其有关部门可以根据实际需要，联合组织开展跨行政区域的生态环境质量监测，推动监测信息共享、监测数据互认。\n第十五条 国务院生态环境主管部门和省、自治区、直辖市人民政府生态环境主管部门按照有关规定统一发布生态环境质量监测信息，定期发布生态环境状况公报。\n任何单位和个人不得违法发布生态环境质量监测信息。\n第十六条 生态环境主管部门、其他有关部门应当按照职责分工，依法加强对各类污染源（包括移动污染源）等的监督监测，并根据监测结果向有关单位或者个人提出相关建议、要求或者作出处理决定。\n鼓励在生态环境监督监测中使用遥感监测等非接触式技术手段，提升监测效率，减少对正常生产经营活动等的影响。\n第十七条 生态环境主管部门、其他有关部门应当加强对生态环境风险的监测预警，提升生态环境风险预警能力；发现可能危害生态环境安全或者公众健康情形的，县级以上人民政府应当依法及时发布预警信息。\n第十八条 县级以上人民政府应当建立健全突发生态环境事件应急监测管理体系，将突发生态环境事件应急监测纳入相应的应急预案，提高突发生态环境事件应急监测响应能力。\n突发生态环境事件发生后，生态环境主管部门和其他有关部门应当根据应急处置工作统一部署开展应急监测。突发生态环境事件应急处置工作结束后，有关人民政府应当立即组织评估事件造成的环境影响和损失，并及时将评估结果向社会公布。\n第十九条 地方各级人民政府、县级以上人民政府有关部门工作人员不得以任何方式对公共监测数据弄虚作假或者明示、暗示有关单位、个人对公共监测数据弄虚作假，不得对依法履行职责或者拒绝、抵制监测违法行为的单位、个人打击报复。","level":1},{"name":"第三章 自行监测","text":"第二十条 企事业单位对其生产经营等活动中污染物、温室气体等的排放情况以及建设项目、突发生态环境事件等对生态环境的影响，依照法律、法规规定开展自行监测。\n第二十一条 开展自行监测应当按照生态环境监测有关规范和标准制定监测方案，明确监测点位设置、监测指标、监测频次、监测方式等。\n自行监测的主要监测点位应当按照规定安装、使用可以获取监测活动过程和监测设备运行情况的视频监控设备，并与生态环境主管部门或者其他有关部门联网。\n第二十二条 开展自行监测应当使用符合国家标准和规范的监测设备，并对监测设备进行经常性维护、保养和定期检定、校准，保证监测设备正常运行。\n第二十三条 依照法律、法规规定应当安装、使用自动监测设备的企事业单位，其自动监测设备应当与生态环境主管部门联网。\n企事业单位发现自动监测设备传输数据异常的，应当及时报告生态环境主管部门，并对自动监测设备进行检查、修复。\n第二十四条 采用手工监测方式开展自行监测的，应当如实记录手工监测期间的生产负荷、污染防治设施运行情况等工况，确保监测数据具有代表性。\n第二十五条 企事业单位应当建立健全监测数据质量管理制度。企事业单位及其负责人对监测数据的真实性、准确性负责。\n企事业单位不得实施或者明示、暗示有关单位、个人实施下列对监测数据弄虚作假的行为：\n（一）未实际开展监测，直接出具监测报告；\n（二）篡改、伪造原始监测记录、监测数据；\n（三）故意漏检监测项目或者改变监测条件；\n（四）调换监测样品或者擅自改变采样点位、时间等，干扰采样环境或者采样活动；\n（五）通过不正常运行、破坏监测设备，擅自修改监测设备参数设置，虚假标记自动监测设备状况或者生产设施、污染防治设施工况，或者使用作弊工具等手段，使监测数据失真；\n（六）其他对监测数据弄虚作假的行为。\n第二十六条 企事业单位应当依照法律、法规规定的期限保存自行监测的原始监测记录；法律、法规没有规定保存期限的，原始监测记录至少保存5年。\n企事业单位应当依法公开自行监测相关信息，接受社会监督。","level":1},{"name":"第四章 技术服务机构","text":"第二十七条 政府及其有关部门、企事业单位可以委托依法设立的技术服务机构开展生态环境监测相关服务（以下简称监测服务）。\n第二十八条 开展监测服务的技术服务机构应当具备相应的设施设备、技术能力、技术人员和管理能力，并按照规定向生态环境主管部门备案。其中从事检验检测活动的，应当依法取得检验检测机构资质认定。\n技术服务机构办理备案，应当向生态环境主管部门提交书面承诺，书面承诺应当包括其设施设备、技术能力、技术人员、管理能力方面的信息，技术服务机构对信息的真实性负责。\n生态环境主管部门应当将备案的技术服务机构及其书面承诺、业务范围等向社会公布，并提供备案信息查询服务。\n技术服务机构具体管理办法由国务院生态环境主管部门会同国务院有关部门制定。\n第二十九条 技术服务机构不得超出其业务范围接受委托，不得违反约定将受托业务转委托。\n技术服务机构应当独立、客观、公正开展监测服务，不得同时接受可能存在利益冲突的委托。\n第三十条 技术服务机构接受委托开展监测服务，应当遵守生态环境监测规范和标准。\n委托单位及其有关人员应当配合技术服务机构开展监测服务，并提供必要的便利和条件。\n委托单位应当按规定对技术服务机构监测服务活动加强监督。\n第三十一条 技术服务机构接受委托开展生态环境监测设备运行维护，应当建立运行维护记录制度；对发现的影响生态环境监测设备正常运行的问题，应当及时处理，不得隐瞒。\n第三十二条 接受委托开展监测服务的技术服务机构应当建立监测数据质量管理制度，不得以任何方式对监测数据弄虚作假。\n本条例第二十五条的规定，适用于接受委托开展监测服务的技术服务机构。\n技术服务机构及其负责人对技术服务机构出具的监测数据的真实性、准确性负责。\n第三十三条 接受委托开展监测服务的技术服务机构应当按照规定保存其开展业务的相关数据、报告、记录以及委托合同等材料，保证业务活动全过程可追溯。","level":1},{"name":"第五章 监督管理","text":"第三十四条 国务院生态环境主管部门推动通过生态环境监测管理服务平台开展监测数据报送、技术服务机构备案、相关信息公布等管理与服务，并与国务院有关部门建立信息共享机制。\n第三十五条 生态环境主管部门、其他有关部门应当按照职责分工，加强对生态环境监测活动的监督检查。生态环境主管部门、其他有关部门应当加强协调配合，能够联合检查的实行联合检查，鼓励通过非现场检查、使用非接触式技术手段开展监督检查。\n生态环境主管部门、其他有关部门根据需要对企事业单位、技术服务机构及相关场所等进行现场检查的，可以要求有关单位、个人就相关事项作出说明，查阅、复制相关资料，查询、检查相关信息系统，查封涉嫌违法的相关设备、场所等，并可以开展现场监测。有关单位、个人应当予以配合，不得拒绝、阻碍。\n检查人员对检查中知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息，依法负有保密义务。\n第三十六条 国务院生态环境主管部门会同国务院有关部门建立生态环境监测信用评价制度，依法依规将相关违法违规行为记入信用记录，纳入全国信用信息共享平台。\n第三十七条 生态环境主管部门根据技术服务机构的规模、技术能力、技术人员水平、管理能力、信用状况等，对技术服务机构实行分级分类监管，引导技术服务机构规模化发展，提升专业化水平和市场公信力。\n第三十八条 生态环境监测相关行业组织应当建立健全行业规范，加强行业自律管理，促进行业健康发展。\n第三十九条 任何单位和个人对违反本条例规定的行为，有权向生态环境主管部门和其他有关部门举报。接到举报的部门应当依法及时处理。","level":1},{"name":"第六章 法律责任","text":"第四十条 侵占、损毁生态环境质量监测站点及其设施、设备，或者干扰生态环境质量监测站点正常运行的，由生态环境主管部门或者其他有关部门依据职责责令改正，处2万元以上20万元以下的罚款。\n第四十一条 地方各级人民政府、县级以上人民政府有关部门工作人员有下列情形之一的，依法给予处分，并予以通报：\n（一）对公共监测数据弄虚作假或者明示、暗示有关单位、个人对公共监测数据弄虚作假；\n（二）对依法履行职责或者拒绝、抵制监测违法行为的单位、个人打击报复；\n（三）其他滥用职权、玩忽职守、徇私舞弊的情形。\n第四十二条 企事业单位在开展自行监测中有下列情形之一的，由生态环境主管部门或者其他有关部门依据职责责令改正，处2万元以上20万元以下的罚款；拒不改正的，可以责令限制生产、停产整治：\n（一）不遵守生态环境监测规范或者标准，导致监测数据失真；\n（二）使用不符合国家标准或者规范的监测设备，或者未对监测设备进行经常性维护、保养或者定期检定、校准；\n（三）未按照规定在主要监测点位安装、使用视频监控设备；\n（四）未按照规定安装、使用自动监测设备，或者发现自动监测设备传输数据异常未及时报告并对自动监测设备进行检查、修复；\n（五）主要监测点位视频监控设备或者自动监测设备未与生态环境主管部门或者其他有关部门联网；\n（六）未记录或者未如实记录手工监测期间的生产负荷、污染防治设施运行情况等工况；\n（七）未建立监测数据质量管理制度；\n（八）未保存或者未按照规定期限保存原始监测记录；\n（九）未依法公开或者不如实公开自行监测相关信息。\n生态环境主管部门或者其他有关部门发现企事业单位使用的监测设备不符合国家标准或者规范的，除依照前款规定对企事业单位予以处罚外，可以将该设备有关情况以及其生产者、销售者向社会公布，并通报市场监督管理部门，由市场监督管理部门对生产者、销售者依法处理。\n第四十三条 技术服务机构有下列情形之一的，由生态环境主管部门责令改正，处2万元以上20万元以下的罚款；有违法所得的，没收违法所得；拒不改正的，报经有批准权的人民政府批准，责令停业、关闭：\n（一）不具备相应的设施设备、技术能力、技术人员、管理能力；\n（二）未按照规定备案；\n（三）超出其业务范围接受委托，违反约定将受托业务转委托，或者同时接受可能存在利益冲突的委托；\n（四）开展监测服务使用不符合法律、行政法规规定和国家标准的监测设施、设备，或者未遵守生态环境监测规范、标准导致监测数据失真；\n（五）开展生态环境监测设备运行维护未建立运行维护记录制度，或者隐瞒、不及时处理发现的影响生态环境监测设备正常运行的问题；\n（六）未建立监测数据质量管理制度；\n（七）未按照规定保存其开展业务的相关数据、报告、记录、委托合同等材料。\n有前款第四项情形、拒不改正的，除依照前款规定处罚外，有许可证的吊销许可证。\n第四十四条 企事业单位实施或者明示、暗示有关单位、个人对监测数据弄虚作假的，由生态环境主管部门或者其他有关部门依据职责责令改正，处10万元以上100万元以下的罚款，对直接负责的主管人员和其他直接责任人员处5万元以上20万元以下的罚款；情节严重的，责令限制生产、停产整治。\n第四十五条 接受委托开展监测服务的技术服务机构对监测数据弄虚作假的，由生态环境主管部门处10万元以上50万元以下的罚款；情节严重的，处50万元以上200万元以下的罚款，禁止从事监测服务，报经有批准权的人民政府批准，责令停业、关闭，对其中取得监测服务相关资质的，由授予其资质的部门吊销其资质证书。\n技术服务机构因前款规定的违法行为受到处罚的，对其直接负责的主管人员和其他直接责任人员处1万元以上5万元以下的罚款，5年内禁止从事监测服务；情节严重的，10年内禁止从事监测服务。\n第四十六条 违反本条例规定，给他人造成损失的，依法承担赔偿责任；构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第七章 附 则","text":"第四十七条 军队的生态环境监测工作按照中央军事委员会的有关规定执行。\n第四十八条 生态环境监测数据安全保护，依照《中华人民共和国数据安全法》、《网络数据安全管理条例》的规定执行。\n第四十九条 本条例自2026年1月1日起施行。","level":1}]},{"id":"n1297","sections":[{"name":"","text":"碳排放权交易管理暂行条例\n（2024年1月25日中华人民共和国国务院令第775号公布 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》修订）\n第一条 为了规范碳排放权交易及相关活动，加强对温室气体排放的控制，积极稳妥推进碳达峰碳中和，促进经济社会绿色低碳发展，推进生态文明建设，制定本条例。\n第二条 本条例适用于全国碳排放权交易市场的碳排放权交易及相关活动。\n第三条 碳排放权交易及相关活动的管理，应当坚持中国共产党的领导，贯彻党和国家路线方针政策和决策部署，坚持温室气体排放控制与经济社会发展相适应，坚持政府引导与市场调节相结合，遵循公开、公平、公正的原则。\n国家加强碳排放权交易领域的国际合作与交流。\n第四条 国务院生态环境主管部门负责碳排放权交易及相关活动的监督管理工作。国务院有关部门按照职责分工，负责碳排放权交易及相关活动的有关监督管理工作。\n地方人民政府生态环境主管部门负责本行政区域内碳排放权交易及相关活动的监督管理工作。地方人民政府有关部门按照职责分工，负责本行政区域内碳排放权交易及相关活动的有关监督管理工作。\n第五条 全国碳排放权注册登记机构按照国家有关规定，负责碳排放权交易产品登记，提供交易结算等服务。全国碳排放权交易机构按照国家有关规定，负责组织开展碳排放权集中统一交易。登记和交易的收费应当合理，收费项目、收费标准和管理办法应当向社会公开。\n全国碳排放权注册登记机构和全国碳排放权交易机构应当按照国家有关规定，完善相关业务规则，建立风险防控和信息披露制度。\n国务院生态环境主管部门会同国务院市场监督管理部门、中国人民银行和国务院银行业监督管理机构，对全国碳排放权注册登记机构和全国碳排放权交易机构进行监督管理，并加强信息共享和执法协作配合。\n碳排放权交易应当逐步纳入统一的公共资源交易平台体系。\n第六条 碳排放权交易覆盖的温室气体种类和行业范围，由国务院生态环境主管部门会同国务院发展改革等有关部门根据国家温室气体排放控制目标研究提出，报国务院批准后实施。\n碳排放权交易产品包括碳排放配额和经国务院批准的其他现货交易产品。\n第七条 纳入全国碳排放权交易市场的温室气体重点排放单位（以下简称重点排放单位）以及符合国家有关规定的其他主体，可以参与碳排放权交易。\n生态环境主管部门、其他对碳排放权交易及相关活动负有监督管理职责的部门（以下简称其他负有监督管理职责的部门）、全国碳排放权注册登记机构、全国碳排放权交易机构以及本条例规定的技术服务机构的工作人员，不得参与碳排放权交易。\n第八条 国务院生态环境主管部门会同国务院有关部门，根据国家温室气体排放控制目标，制定重点排放单位的确定条件。省、自治区、直辖市人民政府（以下统称省级人民政府）生态环境主管部门会同同级有关部门，按照重点排放单位的确定条件制定本行政区域年度重点排放单位名录。\n重点排放单位的确定条件和年度重点排放单位名录应当向社会公布。\n第九条 国务院生态环境主管部门会同国务院有关部门，根据国家温室气体排放控制目标，综合考虑经济社会发展、产业结构调整、行业发展阶段、历史排放情况、市场调节需要等因素，制定年度碳排放配额总量和分配方案，并组织实施。碳排放配额实行免费分配，并根据国家有关要求逐步推行免费和有偿相结合的分配方式。\n省级人民政府生态环境主管部门会同同级有关部门，根据年度碳排放配额总量和分配方案，向本行政区域内的重点排放单位发放碳排放配额，不得违反年度碳排放配额总量和分配方案发放或者调剂碳排放配额。\n第十条 依照本条例第六条、第八条、第九条的规定研究提出碳排放权交易覆盖的温室气体种类和行业范围、制定重点排放单位的确定条件以及年度碳排放配额总量和分配方案，应当征求省级人民政府、有关行业协会、企业事业单位、专家和公众等方面的意见。\n第十一条 重点排放单位应当采取有效措施控制温室气体排放，按照国家有关规定和国务院生态环境主管部门制定的技术规范，制定并严格执行温室气体排放数据质量控制方案，使用依法经计量检定合格或者校准的计量器具开展温室气体排放相关检验检测，如实准确统计核算本单位温室气体排放量，编制上一年度温室气体排放报告（以下简称年度排放报告），并按照规定将排放统计核算数据、年度排放报告报送其生产经营场所所在地省级人民政府生态环境主管部门。\n重点排放单位应当对其排放统计核算数据、年度排放报告的真实性、完整性、准确性负责。\n重点排放单位应当按照国家有关规定，向社会公开其年度排放报告中的排放量、排放设施、统计核算方法等信息。年度排放报告所涉数据的原始记录和管理台账应当至少保存5年。\n重点排放单位可以委托依法设立的技术服务机构开展温室气体排放相关检验检测、编制年度排放报告。\n第十二条 省级人民政府生态环境主管部门应当对重点排放单位报送的年度排放报告进行核查，确认其温室气体实际排放量。核查工作应当在规定的时限内完成，并自核查完成之日起7个工作日内向重点排放单位反馈核查结果。核查结果应当向社会公开。\n省级人民政府生态环境主管部门可以通过政府购买服务等方式，委托依法设立的技术服务机构对年度排放报告进行技术审核。重点排放单位应当配合技术服务机构开展技术审核工作，如实提供有关数据和资料。\n第十三条 接受委托开展温室气体排放相关检验检测的技术服务机构，应当遵守国家有关技术规程和技术规范要求，对其出具的检验检测报告承担相应责任，不得出具不实或者虚假的检验检测报告。重点排放单位应当按照国家有关规定制作和送检样品，对样品的代表性、真实性负责。\n接受委托编制年度排放报告、对年度排放报告进行技术审核的技术服务机构，应当按照国家有关规定，具备相应的设施设备、技术能力和技术人员，建立业务质量管理制度，独立、客观、公正开展相关业务，对其出具的年度排放报告和技术审核意见承担相应责任，不得篡改、伪造数据资料，不得使用虚假的数据资料或者实施其他弄虚作假行为。年度排放报告编制和技术审核的具体管理办法由国务院生态环境主管部门会同国务院有关部门制定。\n技术服务机构在同一省、自治区、直辖市范围内不得同时从事年度排放报告编制业务和技术审核业务。\n第十四条 重点排放单位应当根据省级人民政府生态环境主管部门对年度排放报告的核查结果，按照国务院生态环境主管部门规定的时限，足额清缴其碳排放配额。\n重点排放单位可以通过全国碳排放权交易市场购买或者出售碳排放配额，其购买的碳排放配额可以用于清缴。\n重点排放单位可以按照国家有关规定，购买经核证的温室气体减排量用于清缴其碳排放配额。\n第十五条 碳排放权交易可以采取协议转让、单向竞价或者符合国家有关规定的其他现货交易方式。\n禁止任何单位和个人通过欺诈、恶意串通、散布虚假信息等方式操纵全国碳排放权交易市场或者扰乱全国碳排放权交易市场秩序。\n第十六条 国务院生态环境主管部门建立全国碳排放权交易市场管理平台，加强对碳排放配额分配、清缴以及重点排放单位温室气体排放情况等的全过程监督管理，并与国务院有关部门实现信息共享。\n第十七条 生态环境主管部门和其他负有监督管理职责的部门，可以在各自职责范围内对重点排放单位等交易主体、技术服务机构进行现场检查。\n生态环境主管部门和其他负有监督管理职责的部门进行现场检查，可以采取查阅、复制相关资料，查询、检查相关信息系统等措施，并可以要求有关单位和个人就相关事项作出说明。被检查者应当如实反映情况、提供资料，不得拒绝、阻碍。\n进行现场检查，检查人员不得少于2人，并应当出示执法证件。检查人员对检查中知悉的国家秘密、商业秘密，依法负有保密义务。\n第十八条 任何单位和个人对违反本条例规定的行为，有权向生态环境主管部门和其他负有监督管理职责的部门举报。接到举报的部门应当依法及时处理，按照国家有关规定向举报人反馈处理结果，并为举报人保密。\n第十九条 生态环境主管部门或者其他负有监督管理职责的部门的工作人员在碳排放权交易及相关活动的监督管理工作中滥用职权、玩忽职守、徇私舞弊的，应当依法给予处分。\n第二十条 生态环境主管部门、其他负有监督管理职责的部门、全国碳排放权注册登记机构、全国碳排放权交易机构以及本条例规定的技术服务机构的工作人员参与碳排放权交易的，由国务院生态环境主管部门责令依法处理持有的碳排放配额等交易产品，没收违法所得，可以并处所交易碳排放配额等产品的价款等值以下的罚款；属于国家工作人员的，还应当依法给予处分。\n第二十一条 重点排放单位有下列情形之一的，由生态环境主管部门责令改正，处5万元以上50万元以下的罚款；拒不改正的，可以责令停产整治：\n（一）未按照规定制定并执行温室气体排放数据质量控制方案；\n（二）未按照规定报送排放统计核算数据、年度排放报告；\n（三）未按照规定向社会公开年度排放报告中的排放量、排放设施、统计核算方法等信息；\n（四）未按照规定保存年度排放报告所涉数据的原始记录和管理台账。\n第二十二条 重点排放单位有下列情形之一的，由生态环境主管部门责令改正，没收违法所得，并处违法所得5倍以上10倍以下的罚款；没有违法所得或者违法所得不足50万元的，处50万元以上200万元以下的罚款；对其直接负责的主管人员和其他直接责任人员处5万元以上20万元以下的罚款；拒不改正的，按照50%以上100%以下的比例核减其下一年度碳排放配额，可以责令停产整治：\n（一）未按照规定统计核算温室气体排放量；\n（二）编制的年度排放报告存在重大缺陷或者遗漏，在年度排放报告编制过程中篡改、伪造数据资料，使用虚假的数据资料或者实施其他弄虚作假行为；\n（三）未按照规定制作和送检样品。\n第二十三条 技术服务机构出具不实或者虚假的检验检测报告的，由生态环境主管部门责令改正，没收违法所得，并处违法所得5倍以上10倍以下的罚款；没有违法所得或者违法所得不足2万元的，处2万元以上10万元以下的罚款；情节严重的，由负责资质认定的部门取消其检验检测资质。\n技术服务机构出具的年度排放报告或者技术审核意见存在重大缺陷或者遗漏，在年度排放报告编制或者对年度排放报告进行技术审核过程中篡改、伪造数据资料，使用虚假的数据资料或者实施其他弄虚作假行为的，由生态环境主管部门责令改正，没收违法所得，并处违法所得5倍以上10倍以下的罚款；没有违法所得或者违法所得不足20万元的，处20万元以上100万元以下的罚款；情节严重的，禁止其从事年度排放报告编制和技术审核业务。\n技术服务机构因本条第一款、第二款规定的违法行为受到处罚的，对其直接负责的主管人员和其他直接责任人员处2万元以上20万元以下的罚款，5年内禁止从事温室气体排放相关检验检测、年度排放报告编制和技术审核业务；情节严重的，终身禁止从事前述业务。\n第二十四条 重点排放单位未按照规定的期限足额清缴其碳排放配额的，由生态环境主管部门责令限期改正，处100万元以上500万元以下的罚款；限期内未完成清缴的，处未清缴的碳排放配额清缴时限前1个月市场交易平均成交价格5倍以上10倍以下的罚款，可以责令停产整治。\n第二十五条 操纵全国碳排放权交易市场的，由国务院生态环境主管部门责令改正，没收违法所得，并处违法所得1倍以上10倍以下的罚款；没有违法所得或者违法所得不足50万元的，处50万元以上500万元以下的罚款。单位因前述违法行为受到处罚的，对其直接负责的主管人员和其他直接责任人员给予警告，并处10万元以上100万元以下的罚款。\n扰乱全国碳排放权交易市场秩序的，由国务院生态环境主管部门责令改正，没收违法所得，并处违法所得1倍以上10倍以下的罚款；没有违法所得或者违法所得不足10万元的，处10万元以上100万元以下的罚款。单位因前述违法行为受到处罚的，对其直接负责的主管人员和其他直接责任人员给予警告，并处5万元以上50万元以下的罚款。\n第二十六条 拒绝、阻碍生态环境主管部门或者其他负有监督管理职责的部门依法实施监督检查的，由生态环境主管部门或者其他负有监督管理职责的部门责令改正，处5万元以上20万元以下的罚款；对直接负责的主管人员和其他直接责任人员，处5000元以上5万元以下的罚款。\n第二十七条 国务院生态环境主管部门会同国务院有关部门建立重点排放单位等交易主体、技术服务机构信用记录制度，将重点排放单位等交易主体、技术服务机构因违反本条例规定受到行政处罚等信息纳入国家有关信用信息系统，并依法向社会公布。\n第二十八条 违反本条例规定，给他人造成损害的，依法承担民事责任；构成违反治安管理行为的，依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第二十九条 对本条例施行前建立的地方碳排放权交易市场，应当参照本条例的规定健全完善有关管理制度，加强监督管理。\n本条例施行后，不再新建地方碳排放权交易市场，重点排放单位不再参与相同温室气体种类和相同行业的地方碳排放权交易市场的碳排放权交易。\n第三十条 本条例下列用语的含义：\n（一）温室气体，是指大气中吸收和重新放出红外辐射的自然和人为的气态成分，包括二氧化碳、甲烷、氧化亚氮、氢氟碳化物、全氟化碳、六氟化硫和三氟化氮。\n（二）碳排放配额，是指分配给重点排放单位规定时期内的二氧化碳等温室气体的排放额度。1个单位碳排放配额相当于向大气排放1吨的二氧化碳当量。\n（三）清缴，是指重点排放单位在规定的时限内，向生态环境主管部门缴纳等同于其经核查确认的上一年度温室气体实际排放量的碳排放配额的行为。\n第三十一条 重点排放单位消费非化石能源电力的，按照国家有关规定对其碳排放配额和温室气体排放量予以相应调整。\n第三十二条 国务院生态环境主管部门会同国务院民用航空等主管部门可以依照本条例规定的原则，根据实际需要，结合民用航空等行业温室气体排放控制的特点，对民用航空等行业的重点排放单位名录制定、碳排放配额发放与清缴、温室气体排放数据统计核算和年度排放报告报送与核查等制定具体管理办法。\n第三十三条 本条例自2024年5月1日起施行。","level":0}]},{"id":"n1298","sections":[{"name":"","text":"中华人民共和国审计法实施条例\n（1997年10月21日中华人民共和国国务院令第231号发布 2010年2月11日中华人民共和国国务院令第571号第一次修订 2026年9月19日中华人民共和国国务院令第847号第二次修订）","level":0},{"name":"第一章 总 则","text":"第一条 根据《中华人民共和国审计法》（以下简称审计法）的规定，制定本条例。\n第二条 审计工作应当坚持中国共产党的领导，全面贯彻落实党的路线方针政策和党中央决策部署。\n第三条 审计法所称审计，是指审计机关依法独立检查被审计单位的会计凭证、会计账簿、财务会计报告以及其他与财政收支、财务收支有关的资料和资产，监督财政收支、财务收支真实、合法和效益的行为。\n审计法所称被审计单位，是指依法应当接受审计机关审计监督的单位。\n第四条 审计法所称财政收支，是指依照《中华人民共和国预算法》和国家其他有关规定，应当纳入各级政府预算的各项收入和支出。\n第五条 审计法所称财务收支，是指国有的金融机构、企业事业组织以及依法应当接受审计机关审计监督的其他单位，按照国家统一的财务会计制度的规定，应当实行会计核算的各项收入和支出。\n第六条 审计机关依照审计法和本条例以及其他有关法律、法规规定的职责、权限和程序进行审计监督。\n审计机关依照有关财政收支、财务收支的法律、法规，以及国家有关政策、标准、项目目标等方面的规定进行审计评价，对被审计单位违反国家规定的财政收支、财务收支行为，在法定职权范围内作出处理、处罚的决定。\n第七条 审计机关开展审计监督，应当加强与纪检监察监督、巡视巡察监督、组织人事监督、人大监督、民主监督、行政监督、司法监督、财会监督、统计监督、出资人监督等各类监督贯通协同，健全信息沟通、线索移交、措施配合、成果共享工作机制。\n第八条 国家加强审计信息化建设，鼓励运用大数据等现代信息技术手段，提升审计监督质量和效率。\n第九条 任何单位和个人对被审计单位违反国家规定的财政收支、财务收支行为，有权向审计机关举报。审计机关接到举报，应当依法及时处理。","level":1},{"name":"第二章 审计机关和审计人员","text":"第十条 审计署在国务院总理领导下，主管全国的审计工作，履行审计法和国务院规定的职责。\n地方各级审计机关在本级人民政府行政首长和上一级审计机关的领导下，负责本行政区域的审计工作，履行法律、法规和本级人民政府规定的职责。\n第十一条 省、自治区人民政府设有派出机关的，派出机关的审计机关对派出机关和省、自治区人民政府审计机关负责并报告工作，审计业务以省、自治区人民政府审计机关领导为主。\n第十二条 审计机关派出机构依照法律、法规和审计机关的规定，在审计机关的授权范围内开展审计工作，不受其他行政机关、社会团体和个人的干涉。\n第十三条 审计机关编制年度经费预算草案的依据主要包括：\n（一）法律、法规；\n（二）本级人民政府的决定和要求；\n（三）审计机关的年度审计工作计划；\n（四）定员定额标准；\n（五）上一年度经费预算执行情况和本年度的变化因素。\n第十四条 审计人员实行审计专业技术资格制度，具体按照国家有关规定执行。\n审计机关根据工作需要，可以聘请具有与审计事项相关专业知识的人员参加审计工作。被聘请人员参加审计工作，应当遵守国家有关审计工作的规定。\n第十五条 审计人员办理审计事项，有下列情形之一的，应当申请回避，被审计单位也有权申请审计人员回避：\n（一）与被审计单位负责人或者有关主管人员有夫妻关系、直系血亲关系、三代以内旁系血亲或者近姻亲关系；\n（二）与被审计单位或者审计事项有经济利益关系；\n（三）与被审计单位、审计事项、被审计单位负责人或者有关主管人员有其他利害关系，可能影响公正执行公务。\n审计人员的回避，由审计机关负责人决定；审计机关负责人办理审计事项时的回避，由本级人民政府或者上一级审计机关负责人决定。\n第十六条 审计机关对打探干预审计事项行为实行登记报告制度。审计人员遇有打探干预审计事项行为的，应当按照规定登记报告。具体办法由审计署制定。\n第十七条 地方各级审计机关正职和副职负责人的任免，应当事先征求上一级审计机关的意见。\n第十八条 审计机关负责人在任职期间没有下列情形之一的，不得随意撤换：\n（一）因犯罪被追究刑事责任；\n（二）因严重违法、失职受到处分，不适宜继续担任审计机关负责人；\n（三）因健康原因不能履行职责1年以上；\n（四）不符合国家规定的其他任职条件。","level":1},{"name":"第三章 审计机关职责","text":"第十九条 审计机关对本级人民政府财政部门具体组织本级预算执行情况和编制的决算草案，本级预算收入征收部门和单位征收预算收入的情况，与本级人民政府财政部门直接发生预算缴款、拨款关系的部门、单位的预算执行情况和决算，下级人民政府的预算执行情况和决算，以及其他财政收支情况，依法进行审计监督。经本级人民政府批准，审计机关对其他取得财政资金的单位和项目接受、运用财政资金的真实、合法和效益情况，依法进行审计监督。\n第二十条 审计机关对本级预算收入和支出的执行情况、决算草案以及其他财政收支情况进行审计监督的内容包括：\n（一）财政部门按照本级人民代表大会批准的本级预算向本级各部门（含直属单位）批复预算的情况，具体组织本级预算执行情况和编制的决算草案，本级预算执行中调整情况和预算收支变化情况；\n（二）预算收入征收部门和单位依照法律、行政法规的规定和国家其他有关规定征收预算收入情况；\n（三）财政部门按照批准的年度预算、用款计划，调度、拨付预算资金情况，使用预算周转金、预算稳定调节基金情况；\n（四）财政部门依照法律、行政法规的规定和财政管理体制，拨付和管理政府间财政转移支付资金情况，上级政府对本级政府、本级政府对下级政府的税收返还情况，以及办理结算、结转情况；\n（五）财政部门管理政府债务的举借、支出与偿还情况；\n（六）国库按照国家有关规定办理预算收入的收纳、划分、留解、退付情况和预算支出资金的拨付情况；\n（七）本级各部门（含直属单位）年度预算执行情况和决算；\n（八）依照国家有关规定实行专项管理的预算资金收支情况；\n（九）政府综合财务报告和部门财务报告；\n（十）法律、法规规定的其他与预算执行、决算以及其他财政收支有关的情况。\n第二十一条 审计法第十九条所称审计结果报告，应当包括下列内容：\n（一）本级预算执行、决算草案和其他财政收支，以及国有资源、国有资产管理使用的基本情况；\n（二）审计机关对本级预算执行、决算草案和其他财政收支，以及国有资源、国有资产管理使用情况作出的审计评价；\n（三）本级预算执行、决算草案和其他财政收支，以及国有资源、国有资产管理使用中存在的问题和审计机关依法采取的措施；\n（四）审计机关提出的改进本级预算执行、决算草案和其他财政收支，以及国有资源、国有资产管理使用工作的建议；\n（五）本级人民政府要求报告的其他情况。\n第二十二条 审计署对中央银行及其分支机构履行职责所发生的各项财务收支，依法进行审计监督。\n审计署向国务院总理提出的审计结果报告，应当包括对中央银行的财务收支的审计情况。\n第二十三条 审计法第二十二条所称国有资本占控股地位或者主导地位的企业、金融机构，包括：\n（一）国有资本占企业、金融机构资本（股本）总额的比例超过50%的；\n（二）国有资本占企业、金融机构资本（股本）总额的比例在50%以下，但国有资本投资主体拥有实际控制权的。\n第二十四条 审计法第二十三条所称政府投资和以政府投资为主的建设项目，包括：\n（一）全部使用预算安排的资金的；\n（二）未全部使用预算安排的资金，预算安排的资金占项目总投资的比例超过50%，或者占项目总投资的比例在50%以下，但政府拥有项目建设、运营实际控制权的。\n审计机关对前款规定的建设项目的总预算或者概算的执行情况、年度预算的执行情况和年度决算、工程结算和竣工决算，依法进行审计监督；对前款规定的建设项目进行审计时，可以对有关的设计、施工、供货等单位取得建设项目资金的真实性、合法性进行调查。\n第二十五条 审计法第二十三条所称其他关系国家利益和公共利益的重大公共工程项目，包括：\n（一）全部使用和主要使用政府部门管理或者受政府委托管理的公共资金的重大公共工程项目；\n（二）政府利用国有资源、国有资产与社会资本合作的重大公共工程项目；\n（三）国有企业、国有金融机构和国有资本占控股地位或者主导地位的企业、金融机构投资的重大公共工程项目；\n（四）其他关系国家利益和公共利益的基础设施、公用事业等领域重大公共工程项目。\n第二十六条 审计法第二十四条所称社会保险基金、全国社会保障基金，是指《中华人民共和国社会保险法》规定的社会保险基金、全国社会保障基金；所称社会捐赠资金，包括来源于境内外的货币、有价证券和实物等各种形式的捐赠。\n第二十七条 审计法第二十五条所称国际组织和外国政府援助、贷款项目，包括：\n（一）国际组织、外国政府及其机构向中国政府及其机构提供的贷款项目；\n（二）国际组织、外国政府及其机构向中国企业事业组织以及其他组织提供的由中国政府及其机构担保的贷款项目；\n（三）国际组织、外国政府及其机构向中国政府及其机构提供的援助和赠款项目；\n（四）国际组织、外国政府及其机构向受中国政府委托管理有关基金、资金的单位提供的援助和赠款项目；\n（五）国际组织、外国政府及其机构提供援助、贷款的其他项目。\n第二十八条 审计机关有权依照审计法和本条例规定的审计程序、方法以及国家其他有关规定，对预算管理或者国有资源、国有资产管理使用等与国家财政收支有关的特定事项，向有关地方、部门、单位进行专项审计调查。\n第二十九条 审计机关根据被审计单位的财政、财务隶属关系，确定审计管辖范围；不能根据财政、财务隶属关系确定审计管辖范围的，根据国有资源、国有资产监督管理关系，确定审计管辖范围。\n两个以上国有资本投资主体投资的金融机构、企业事业组织和建设项目，由对主要投资主体有审计管辖权的审计机关进行审计监督。\n第三十条 各级审计机关应当按照确定的审计管辖范围进行审计监督。\n第三十一条 被审计单位的内部审计工作，应当接受审计机关的业务指导和监督。\n被审计单位可以根据内部审计工作的需要，参加依法成立的内部审计自律组织。审计机关可以通过内部审计自律组织，加强对内部审计工作的业务指导和监督。\n第三十二条 审计机关进行审计或者专项审计调查时，有权对社会审计机构出具的相关审计报告进行核查。\n审计机关核查社会审计机构出具的相关审计报告时，发现社会审计机构存在违反法律、法规或者执业准则等情况的，应当移送有关主管机关依法追究责任。","level":1},{"name":"第四章 审计机关权限","text":"第三十三条 被审计单位应当依照审计法第三十四条规定，按照审计机关的要求提供财务、会计资料以及与财政收支、财务收支有关的业务、管理等资料，包括电子数据和有关文档。被审计单位负责人应当对本单位提供资料的及时性、真实性和完整性负责，并作出书面承诺。\n第三十四条 各级财政、税务以及其他部门（含直属单位）应当向本级审计机关报送下列资料：\n（一）本级人民代表大会批准的本级预算和本级人民政府财政部门向本级各部门（含直属单位）批复的预算，预算收入征收部门和单位的年度收入预期目标，以及本级各部门（含直属单位）向所属各单位批复的预算；\n（二）本级预算收支执行、预算收入征收部门和单位的收入预期目标完成情况月报、年报，以及决算情况；\n（三）综合性财政税务工作统计年报、情况简报，财政、预算、国有资源、国有资产、税务、财务和会计等规章制度；\n（四）本级各部门（含直属单位）汇总编制的本部门决算草案。\n第三十五条 审计机关依照审计法第三十七条规定查询被审计单位在金融机构的账户的，应当由县级以上人民政府审计机关负责人签发协助查询单位账户通知书；查询其他单位、个人在金融机构与审计事项相关的存款的，应当由县级以上人民政府审计机关主要负责人签发协助查询单位、个人存款通知书。查询时，审计人员应当不少于二人，并出示其工作证件和协助查询通知书。\n有关金融机构应当予以协助，及时提供证明材料，不得泄露有关情况。审计机关和审计人员负有保密义务。\n第三十六条 审计法第三十八条所称违反国家规定取得的资产，包括：\n（一）弄虚作假骗取的财政拨款、实物以及金融机构贷款；\n（二）违反国家规定享受国家补贴、补助、贴息、免息、减税、免税、退税等优惠政策取得的资产；\n（三）违反国家规定向他人收取的款项、有价证券、实物；\n（四）违反国家规定处分国有资产取得的收益；\n（五）违反国家规定取得的其他资产。\n第三十七条 审计机关依照审计法第三十八条规定封存被审计单位有关资料和违反国家规定取得的资产的，应当持县级以上人民政府审计机关负责人签发的封存通知书，并在依法收集与审计事项相关的证明材料或者采取其他措施后解除封存。封存的期限为7日以内；有特殊情况需要延长的，经县级以上人民政府审计机关负责人批准，可以适当延长，但延长的期限不得超过7日。\n对封存的资料、资产，审计机关可以指定被审计单位负责保管，被审计单位不得损毁或者擅自转移。\n第三十八条 审计机关依照审计法第四十条规定，可以就有关审计事项向政府有关部门通报或者向社会公布对被审计单位的审计、专项审计调查结果。\n审计机关经与有关主管机关协商，可以在向社会公布的审计、专项审计调查结果中，一并公布对社会审计机构相关审计报告核查的结果。\n审计机关拟向社会公布对上市公司的审计、专项审计调查结果的，应当在5日前将拟公布的内容告知上市公司。\n第三十九条 审计机关依照审计法第四十一条规定提请有关机关予以协助的，应当明确需要协助办理的事项和有关工作要求。有关机关应当按照审计机关的要求，依法协助采取有关措施、提供相关资料和专业技术支持，配合开展审计工作，不得泄露有关情况。","level":1},{"name":"第五章 审计程序","text":"第四十条 审计机关应当根据法律、法规和国家其他有关规定，按照本级人民政府和上级审计机关的要求，确定年度审计工作重点，编制年度审计项目计划，并按照规定程序报经批准。\n审计机关在年度审计项目计划中确定对国有资本占控股地位或者主导地位的企业、金融机构进行审计的，应当自确定之日起7日内告知列入年度审计项目计划的企业、金融机构。\n第四十一条 审计机关应当根据年度审计项目计划，组成审计组，调查了解被审计单位的有关情况，编制审计方案，并在实施审计3日前，向被审计单位送达审计通知书。\n第四十二条 审计法第四十二条所称特殊情况，包括：\n（一）办理紧急事项的；\n（二）被审计单位涉嫌严重违法违规的；\n（三）其他特殊情况。\n第四十三条 审计人员实施审计时，应当按照下列规定办理：\n（一）通过检查、查询、监督盘点、发函询证等方法实施审计；\n（二）通过收集原件、原物或者复制、拍照等方法取得证明材料；\n（三）对与审计事项有关的会议和谈话内容作出记录，或者要求被审计单位提供会议记录材料；\n（四）记录审计实施过程和查证结果。\n第四十四条 审计人员向有关单位和个人调查取得的证明材料，应当有提供者的签名或者盖章；不能取得提供者签名或者盖章的，审计人员应当注明原因。\n第四十五条 审计组向审计机关提出审计报告前，应当书面征求被审计单位意见。被审计单位应当自接到审计组的审计报告之日起10日内，提出书面意见；10日内未提出书面意见的，视同无异议。\n审计组应当针对被审计单位提出的书面意见，进一步核实情况，对审计组的审计报告作必要修改，连同被审计单位的书面意见和采纳情况一并报送审计机关。\n第四十六条 审计机关有关业务机构和专门机构或者人员对审计组的审计报告以及相关审计事项进行复核、审理后，由审计机关按照下列规定办理：\n（一）出具审计机关的审计报告，内容主要包括：被审计单位基本情况，对审计事项的审计评价，审计查出的问题以及分类提出的整改要求，改进财政收支、财务收支管理工作的建议；\n（二）对违反国家规定的财政收支、财务收支行为，依法应当给予处理、处罚的，在法定职权范围内作出处理、处罚的审计决定；\n（三）对需要移送监察机关、司法机关和有关主管机关、单位处理、处罚的，依法移送。\n第四十七条 审计机关在审计中发现损害国家利益和社会公共利益的事项，但处理、处罚依据又不明确的，应当向本级人民政府和上一级审计机关报告。\n第四十八条 被审计单位承担审计整改主体责任，应当按照审计机关规定的时间落实整改要求和审计决定，并按照规定书面报告整改情况。对应当上缴的款项，被审计单位应当按照财政管理体制和国家有关规定缴入国库或者财政专户。\n国务院各部门和地方各级人民政府以及有关主管机关、单位应当加强统筹协调，督促被审计单位整改审计查出的问题；对普遍性、倾向性、苗头性问题，应当及时纠正并建立健全有关制度。\n审计机关应当对被审计单位整改情况进行跟踪检查，及时审核认定。\n第四十九条 上级审计机关应当对下级审计机关的审计业务依法进行监督。\n下级审计机关作出的审计决定违反国家有关规定的，上级审计机关可以责成下级审计机关予以变更或者撤销，也可以直接作出变更或者撤销的决定；审计决定被撤销后需要重新作出审计决定的，上级审计机关可以责成下级审计机关在规定的期限内重新作出审计决定，也可以直接作出审计决定。\n下级审计机关应当作出而没有作出审计决定的，上级审计机关可以责成下级审计机关在规定的期限内作出审计决定，也可以直接作出审计决定。\n第五十条 审计机关进行专项审计调查时，应当向被调查的地方、部门、单位出示专项审计调查的书面通知，并说明有关情况；有关地方、部门、单位应当接受调查，如实反映情况，提供有关资料。\n在专项审计调查中，被审计单位有违反国家规定的财政收支、财务收支行为或者其他违法违规行为的，审计机关可以依照审计法和本条例的规定出具审计报告，作出审计决定，或者移送监察机关、司法机关和有关主管机关、单位处理、处罚，依法追究责任。\n第五十一条 审计机关应当按照国家有关规定建立、健全审计档案制度。\n第五十二条 审计机关送达审计文书，可以直接送达，也可以邮寄送达或者以其他方式送达。直接送达的，以被审计单位在送达回证上注明的签收日期或者见证人证明的收件日期为送达日期；邮寄送达的，以邮政回执上注明的收件日期为送达日期；以其他方式送达的，以签收或者收件日期为送达日期。\n审计机关的审计文书的种类、内容和格式，由审计署规定。","level":1},{"name":"第六章 法律责任","text":"第五十三条 被审计单位违反审计法和本条例的规定，拒绝、拖延提供与审计事项有关的资料，或者提供的资料不真实、不完整，或者拒绝、阻碍检查、调查、核实有关情况的，由审计机关责令改正，可以通报批评，给予警告；拒不改正的，对被审计单位可以处5万元以下的罚款，对直接负责的主管人员和其他直接责任人员，可以处2万元以下的罚款，审计机关认为依法应当给予处分的，应当向被审计单位提出处理建议，或者移送监察机关和有关主管机关、单位。\n与审计事项有关的其他单位、个人，拒不配合审计或者阻碍审计人员依法执行职务的，由审计机关责令改正。\n有前两款行为，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。\n第五十四条 对本级各部门（含直属单位）和下级人民政府违反预算的行为或者其他违反国家规定的财政收支行为，审计机关在法定职权范围内，依照法律、行政法规的规定，区别情况采取审计法第四十九条规定的处理措施。\n第五十五条 对被审计单位违反国家规定的财务收支行为，审计机关在法定职权范围内，区别情况采取审计法第四十九条规定的处理措施，可以通报批评，给予警告；有违法所得的，没收违法所得，并处违法所得1倍以上5倍以下的罚款；没有违法所得的，可以处5万元以下的罚款；对直接负责的主管人员和其他直接责任人员，可以处2万元以下的罚款，审计机关认为依法应当给予处分的，应当向被审计单位提出处理建议，或者移送监察机关和有关主管机关、单位；构成犯罪的，依法追究刑事责任。\n法律、行政法规对被审计单位违反国家规定的财务收支行为处理、处罚另有规定的，从其规定。\n第五十六条 审计机关在作出较大数额罚款或者没收较大数额违法所得的处罚决定前，应当告知被审计单位和有关人员有要求举行听证的权利。较大数额罚款和较大数额违法所得的具体标准由审计署规定。\n第五十七条 对审计机关提出的处理建议以及移送的事项，有关主管机关、单位应当依法及时作出决定。\n第五十八条 被审计单位对审计机关依照审计法第十八条、第十九条和本条例第十九条规定进行审计监督作出的审计决定不服的，可以自审计决定送达之日起60日内，提请审计机关的本级人民政府裁决，本级人民政府的裁决为最终决定。\n审计机关应当在审计决定中告知被审计单位提请裁决的途径和期限。\n裁决期间，审计决定不停止执行。但是，有下列情形之一的，可以停止执行：\n（一）审计机关认为需要停止执行；\n（二）受理裁决的人民政府认为需要停止执行；\n（三）被审计单位申请停止执行，受理裁决的人民政府认为其要求合理，决定停止执行。\n裁决由本级人民政府法治部门办理。裁决决定应当自接到提请之日起60日内作出；有特殊情况需要延长的，经政府法治部门负责人批准，可以适当延长，并告知审计机关和提请裁决的被审计单位，但延长的期限不得超过30日。\n第五十九条 除本条例第五十八条规定的可以提请裁决的审计决定外，被审计单位对审计机关作出的其他审计决定不服的，可以依法申请行政复议或者提起行政诉讼。\n审计机关应当在审计决定中告知被审计单位申请行政复议或者提起行政诉讼的途径和期限。\n第六十条 被审计单位对审计查出的问题拒不整改、未按照要求整改到位或者虚假整改的，由审计机关责令改正，可以通报批评，给予警告；对直接负责的主管人员和其他直接责任人员，审计机关认为依法应当给予处分的，应当向被审计单位提出处理建议，或者移送监察机关和有关主管机关、单位；构成犯罪的，依法追究刑事责任。\n被审计单位不执行审计决定的，审计机关应当责令限期执行；逾期仍不执行的，审计机关可以申请人民法院强制执行。\n第六十一条 审计人员滥用职权、徇私舞弊、玩忽职守或者泄露、向他人非法提供所知悉的国家秘密、工作秘密、商业秘密、个人隐私和个人信息的，依法给予处分；构成犯罪的，依法追究刑事责任。\n审计人员违法违纪取得的财物，依法予以追缴、没收或者责令退赔。","level":1},{"name":"第七章 附 则","text":"第六十二条 本条例所称以上、以下，包括本数。\n本条例第五十八条规定的期间的最后一日是法定节假日的，以节假日后的第一个工作日为期间届满日。审计法和本条例规定的其他期间以工作日计算，不含法定节假日。\n第六十三条 领导干部经济责任审计和自然资源资产离任审计，依照审计法和本条例以及有关规定执行。\n第六十四条 本条例自2026年12月1日起施行。","level":1}]},{"id":"n1299","sections":[{"name":"","text":"风景名胜区条例\n（2006年9月19日中华人民共和国国务院令第474号公布 根据2016年2月6日《国务院关于修改部分行政法规的决定》第一次修订 根据2026年1月30日《国务院关于修改和废止部分行政法规的决定》第二次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强对风景名胜区的管理，有效保护和合理利用风景名胜资源，制定本条例。\n第二条 风景名胜区的设立、规划、保护、利用和管理，适用本条例。\n本条例所称风景名胜区，是指具有观赏、文化或者科学价值，自然景观、人文景观比较集中，环境优美，可供人们游览或者进行科学、文化活动的区域。\n第三条 国家对风景名胜区实行科学规划、统一管理、严格保护、永续利用的原则。\n第四条 风景名胜区所在地县级以上地方人民政府设置的风景名胜区管理机构，负责风景名胜区的保护、利用和统一管理工作。\n第五条 国务院林业草原主管部门负责全国风景名胜区的监督管理工作。国务院其他有关部门按照国务院规定的职责分工，负责风景名胜区的有关监督管理工作。\n省、自治区、直辖市人民政府林业草原主管部门，负责本行政区域内风景名胜区的监督管理工作。省、自治区、直辖市人民政府其他有关部门按照规定的职责分工，负责风景名胜区的有关监督管理工作。\n第六条 任何单位和个人都有保护风景名胜资源的义务，并有权制止、检举破坏风景名胜资源的行为。","level":1},{"name":"第二章 设 立","text":"第七条 设立风景名胜区，应当有利于保护和合理利用风景名胜资源。\n新设立的风景名胜区与自然保护区不得重合或者交叉；已设立的风景名胜区与自然保护区重合或者交叉的，风景名胜区规划与自然保护区规划应当相协调。\n第八条 风景名胜区划分为国家级风景名胜区和省级风景名胜区。\n自然景观和人文景观能够反映重要自然变化过程和重大历史文化发展过程，基本处于自然状态或者保持历史原貌，具有国家代表性的，可以申请设立国家级风景名胜区；具有区域代表性的，可以申请设立省级风景名胜区。\n第九条 申请设立风景名胜区应当提交包含下列内容的有关材料：\n（一）风景名胜资源的基本状况；\n（二）拟设立风景名胜区的范围以及核心景区的范围；\n（三）拟设立风景名胜区的性质和保护目标；\n（四）拟设立风景名胜区的游览条件；\n（五）与拟设立风景名胜区内的土地、森林等自然资源和房屋等财产的所有权人、使用权人协商的内容和结果。\n第十条 设立国家级风景名胜区，由省、自治区、直辖市人民政府提出申请，国务院林业草原主管部门会同国务院自然资源、生态环境、住房城乡建设、文物等有关部门组织论证，提出审查意见，报国务院批准公布。\n设立省级风景名胜区，由县级人民政府提出申请，省、自治区、直辖市人民政府林业草原主管部门会同其他有关部门组织论证，提出审查意见，报省、自治区、直辖市人民政府批准公布。\n第十一条 风景名胜区内的土地、森林等自然资源和房屋等财产的所有权人、使用权人的合法权益受法律保护。\n申请设立风景名胜区的人民政府应当在报请审批前，与风景名胜区内的土地、森林等自然资源和房屋等财产的所有权人、使用权人充分协商。\n因设立风景名胜区对风景名胜区内的土地、森林等自然资源和房屋等财产的所有权人、使用权人造成损失的，应当依法给予补偿。","level":1},{"name":"第三章 规 划","text":"第十二条 风景名胜区规划分为总体规划和详细规划。\n第十三条 风景名胜区总体规划的编制，应当体现人与自然和谐相处、区域协调发展和经济社会全面进步的要求，坚持保护优先、开发服从保护的原则，突出风景名胜资源的自然特性、文化内涵和地方特色。\n风景名胜区总体规划应当包括下列内容：\n（一）风景资源评价；\n（二）生态资源保护措施、重大建设项目布局、开发利用强度；\n（三）风景名胜区的功能结构和空间布局；\n（四）禁止开发和限制开发的范围；\n（五）风景名胜区的游客容量；\n（六）有关专项规划。\n第十四条 风景名胜区应当自设立之日起2年内编制完成总体规划。总体规划的规划期一般为20年。\n第十五条 风景名胜区详细规划应当根据核心景区和其他景区的不同要求编制，确定基础设施、旅游设施、文化设施等建设项目的选址、布局与规模，并明确建设用地范围和规划设计条件。\n风景名胜区详细规划，应当符合风景名胜区总体规划。\n第十六条 国家级风景名胜区规划由省、自治区、直辖市人民政府林业草原主管部门组织编制。\n省级风景名胜区规划由县级人民政府组织编制。\n第十七条 编制风景名胜区规划，应当采用招标等公平竞争的方式选择具有相应资质等级的单位承担。\n风景名胜区规划应当按照经审定的风景名胜区范围、性质和保护目标，依照国家有关法律、法规和技术规范编制。\n第十八条 编制风景名胜区规划，应当广泛征求有关部门、公众和专家的意见；必要时，应当进行听证。\n风景名胜区规划报送审批的材料应当包括社会各界的意见以及意见采纳的情况和未予采纳的理由。\n第十九条 国家级风景名胜区的总体规划，经所在地省、自治区、直辖市人民政府审查后，由省、自治区、直辖市人民政府林业草原主管部门报国务院林业草原主管部门审批。国务院林业草原主管部门应当会同国务院自然资源、生态环境、住房城乡建设、文物等有关部门进行审查。\n国家级风景名胜区的详细规划，由省、自治区、直辖市人民政府林业草原主管部门报国务院林业草原主管部门审批。\n第二十条 省级风景名胜区的总体规划，由省、自治区、直辖市人民政府审批，报国务院林业草原主管部门备案。\n省级风景名胜区的详细规划，由省、自治区、直辖市人民政府林业草原主管部门审批。\n第二十一条 风景名胜区规划经批准后，应当向社会公布，任何组织和个人有权查阅。\n风景名胜区内的单位和个人应当遵守经批准的风景名胜区规划，服从规划管理。\n风景名胜区规划未经批准的，不得在风景名胜区内进行各类建设活动。\n第二十二条 经批准的风景名胜区规划不得擅自修改。确需对风景名胜区总体规划中的风景名胜区范围、性质、保护目标、生态资源保护措施、重大建设项目布局、开发利用强度以及风景名胜区的功能结构、空间布局、游客容量进行修改的，应当报原审批机关批准；对其他内容进行修改的，应当报原审批机关备案。\n风景名胜区详细规划确需修改的，应当报原审批机关批准。\n政府或者政府部门修改风景名胜区规划对公民、法人或者其他组织造成财产损失的，应当依法给予补偿。\n第二十三条 风景名胜区总体规划的规划期届满前2年，规划的组织编制机关应当组织专家对规划进行评估，作出是否重新编制规划的决定。在新规划批准前，原规划继续有效。","level":1},{"name":"第四章 保 护","text":"第二十四条 风景名胜区内的景观和自然环境，应当根据可持续发展的原则，严格保护，不得破坏或者随意改变。\n风景名胜区管理机构应当建立健全风景名胜资源保护的各项管理制度。\n风景名胜区内的居民和游览者应当保护风景名胜区的景物、水体、林草植被、野生动物和各项设施。\n第二十五条 风景名胜区管理机构应当对风景名胜区内的重要景观进行调查、鉴定，并制定相应的保护措施。\n第二十六条 在风景名胜区内禁止进行下列活动：\n（一）开山、采石、开矿、开荒、修坟立碑等破坏景观、植被和地形地貌的活动；\n（二）修建储存爆炸性、易燃性、放射性、毒害性、腐蚀性物品的设施；\n（三）在景物或者设施上刻划、涂污；\n（四）乱扔垃圾。\n第二十七条 禁止违反风景名胜区规划，在风景名胜区内设立各类开发区和在核心景区内建设宾馆、招待所、培训中心、疗养院以及与风景名胜资源保护无关的其他建筑物；已经建设的，应当按照风景名胜区规划，逐步迁出。\n第二十八条 在风景名胜区内从事本条例第二十六条、第二十七条禁止范围以外的建设活动，应当经风景名胜区管理机构审核后，依照有关法律、法规的规定办理审批手续。\n在国家级风景名胜区内修建缆车、索道等重大建设工程，项目的选址方案应当报省、自治区、直辖市人民政府林业草原主管部门核准。\n第二十九条 在风景名胜区内进行下列活动，应当经风景名胜区管理机构审核后，依照有关法律、法规的规定报有关主管部门批准：\n（一）设置、张贴商业广告；\n（二）举办大型游乐等活动；\n（三）改变水资源、水环境自然状态的活动；\n（四）其他影响生态和景观的活动。\n第三十条 风景名胜区内的建设项目应当符合风景名胜区规划，并与景观相协调，不得破坏景观、污染环境、妨碍游览。\n在风景名胜区内进行建设活动的，建设单位、施工单位应当制定污染防治和水土保持方案，并采取有效措施，保护好周围景物、水体、林草植被、野生动物资源和地形地貌。\n第三十一条 国家建立风景名胜区管理信息系统，对风景名胜区规划实施和资源保护情况进行动态监测。\n国家级风景名胜区所在地的风景名胜区管理机构应当每年向国务院林业草原主管部门报送风景名胜区规划实施和土地、森林等自然资源保护的情况；国务院林业草原主管部门应当将土地、森林等自然资源保护的情况，及时抄送国务院有关部门。","level":1},{"name":"第五章 利用和管理","text":"第三十二条 风景名胜区管理机构应当根据风景名胜区的特点，保护民族民间传统文化，开展健康有益的游览观光和文化娱乐活动，普及历史文化和科学知识。\n第三十三条 风景名胜区管理机构应当根据风景名胜区规划，合理利用风景名胜资源，改善交通、服务设施和游览条件。\n风景名胜区管理机构应当在风景名胜区内设置风景名胜区标志和路标、安全警示等标牌。\n第三十四条 风景名胜区内宗教活动场所的管理，依照国家有关宗教活动场所管理的规定执行。\n风景名胜区内涉及自然资源保护、利用、管理和文物保护以及自然保护区管理的，还应当执行国家有关法律、法规的规定。\n第三十五条 国务院林业草原主管部门应当对国家级风景名胜区的规划实施情况、资源保护状况进行监督检查和评估。对发现的问题，应当及时纠正、处理。\n第三十六条 风景名胜区管理机构应当建立健全安全保障制度，加强安全管理，保障游览安全，并督促风景名胜区内的经营单位接受有关部门依据法律、法规进行的监督检查。\n禁止超过允许容量接纳游客和在没有安全保障的区域开展游览活动。\n第三十七条 进入风景名胜区的门票，由风景名胜区管理机构负责出售。门票价格依照有关价格的法律、法规的规定执行。\n风景名胜区内的交通、服务等项目，应当由风景名胜区管理机构依照有关法律、法规和风景名胜区规划，采用招标等公平竞争的方式确定经营者。\n风景名胜区管理机构应当与经营者签订合同，依法确定各自的权利义务。经营者应当缴纳风景名胜资源有偿使用费。\n第三十八条 风景名胜区的门票收入和风景名胜资源有偿使用费，实行收支两条线管理。\n风景名胜区的门票收入和风景名胜资源有偿使用费应当专门用于风景名胜资源的保护和管理以及风景名胜区内财产的所有权人、使用权人损失的补偿。具体管理办法，由国务院财政部门、价格主管部门会同国务院林业草原主管部门等有关部门制定。\n第三十九条 风景名胜区管理机构不得从事以营利为目的的经营活动，不得将规划、管理和监督等行政管理职能委托给企业或者个人行使。\n风景名胜区管理机构的工作人员，不得在风景名胜区内的企业兼职。","level":1},{"name":"第六章 法律责任","text":"第四十条 违反本条例的规定，有下列行为之一的，由风景名胜区管理机构责令停止违法行为、恢复原状或者限期拆除，没收违法所得，并处50万元以上100万元以下的罚款：\n（一）在风景名胜区内进行开山、采石、开矿等破坏景观、植被、地形地貌的活动的；\n（二）在风景名胜区内修建储存爆炸性、易燃性、放射性、毒害性、腐蚀性物品的设施的；\n（三）在核心景区内建设宾馆、招待所、培训中心、疗养院以及与风景名胜资源保护无关的其他建筑物的。\n县级以上地方人民政府及其有关主管部门批准实施本条第一款规定的行为的，对直接负责的主管人员和其他直接责任人员依法给予降级或者撤职的处分；构成犯罪的，依法追究刑事责任。\n第四十一条 违反本条例的规定，在风景名胜区内从事禁止范围以外的建设活动，未经风景名胜区管理机构审核的，由风景名胜区管理机构责令停止建设、限期拆除，对个人处2万元以上5万元以下的罚款，对单位处20万元以上50万元以下的罚款。\n第四十二条 违反本条例的规定，在国家级风景名胜区内修建缆车、索道等重大建设工程，项目的选址方案未经省、自治区、直辖市人民政府林业草原主管部门核准，县级以上地方人民政府有关部门核发选址意见书的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任。\n第四十三条 违反本条例的规定，个人在风景名胜区内进行开荒、修坟立碑等破坏景观、植被、地形地貌的活动的，由风景名胜区管理机构责令停止违法行为、限期恢复原状或者采取其他补救措施，没收违法所得，并处1000元以上1万元以下的罚款。\n第四十四条 违反本条例的规定，在景物、设施上刻划、涂污或者在风景名胜区内乱扔垃圾的，由风景名胜区管理机构责令恢复原状或者采取其他补救措施，处50元的罚款；刻划、涂污或者以其他方式故意损坏国家保护的文物、名胜古迹的，按照治安管理处罚法的有关规定予以处罚；构成犯罪的，依法追究刑事责任。\n第四十五条 违反本条例的规定，未经风景名胜区管理机构审核，在风景名胜区内进行下列活动的，由风景名胜区管理机构责令停止违法行为、限期恢复原状或者采取其他补救措施，没收违法所得，并处5万元以上10万元以下的罚款；情节严重的，并处10万元以上20万元以下的罚款：\n（一）设置、张贴商业广告的；\n（二）举办大型游乐等活动的；\n（三）改变水资源、水环境自然状态的活动的；\n（四）其他影响生态和景观的活动。\n第四十六条 违反本条例的规定，施工单位在施工过程中，对周围景物、水体、林草植被、野生动物资源和地形地貌造成破坏的，由风景名胜区管理机构责令停止违法行为、限期恢复原状或者采取其他补救措施，并处2万元以上10万元以下的罚款；逾期未恢复原状或者采取有效措施的，由风景名胜区管理机构责令停止施工。\n第四十七条 违反本条例的规定，国务院林业草原主管部门、县级以上地方人民政府及其有关主管部门有下列行为之一的，对直接负责的主管人员和其他直接责任人员依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）违反风景名胜区规划在风景名胜区内设立各类开发区的；\n（二）风景名胜区自设立之日起未在2年内编制完成风景名胜区总体规划的；\n（三）选择不具有相应资质等级的单位编制风景名胜区规划的；\n（四）风景名胜区规划批准前批准在风景名胜区内进行建设活动的；\n（五）擅自修改风景名胜区规划的；\n（六）不依法履行监督管理职责的其他行为。\n第四十八条 违反本条例的规定，风景名胜区管理机构有下列行为之一的，由设立该风景名胜区管理机构的县级以上地方人民政府责令改正；情节严重的，对直接负责的主管人员和其他直接责任人员给予降级或者撤职的处分；构成犯罪的，依法追究刑事责任：\n（一）超过允许容量接纳游客或者在没有安全保障的区域开展游览活动的；\n（二）未设置风景名胜区标志和路标、安全警示等标牌的；\n（三）从事以营利为目的的经营活动的；\n（四）将规划、管理和监督等行政管理职能委托给企业或者个人行使的；\n（五）允许风景名胜区管理机构的工作人员在风景名胜区内的企业兼职的；\n（六）审核同意在风景名胜区内进行不符合风景名胜区规划的建设活动的；\n（七）发现违法行为不予查处的。\n第四十九条 本条例第四十条第一款、第四十一条、第四十三条、第四十四条、第四十五条、第四十六条规定的违法行为，依照有关法律、行政法规的规定，有关部门已经予以处罚的，风景名胜区管理机构不再处罚。\n第五十条 本条例第四十条第一款、第四十一条、第四十三条、第四十四条、第四十五条、第四十六条规定的违法行为，侵害国家、集体或者个人的财产的，有关单位或者个人应当依法承担民事责任。\n第五十一条 依照本条例的规定，责令限期拆除在风景名胜区内违法建设的建筑物、构筑物或者其他设施的，有关单位或者个人必须立即停止建设活动，自行拆除；对继续进行建设的，作出责令限期拆除决定的机关有权制止。有关单位或者个人对责令限期拆除决定不服的，可以在接到责令限期拆除决定之日起15日内，向人民法院起诉；期满不起诉又不自行拆除的，由作出责令限期拆除决定的机关依法申请人民法院强制执行，费用由违法者承担。","level":1},{"name":"第七章 附 则","text":"第五十二条 本条例自2006年12月1日起施行。1985年6月7日国务院发布的《风景名胜区管理暂行条例》同时废止。","level":1}]},{"id":"n1300","sections":[{"name":"","text":"植物检疫条例\n（1983年1月3日国务院发布 根据1992年5月13日《国务院关于修改〈植物检疫条例〉的决定》第一次修订 根据2017年10月7日《国务院关于修改部分行政法规的决定》第二次修订 根据2026年1月30日《国务院关于修改和废止部分行政法规的决定》第三次修订）\n第一条 为了防止危害植物的危险性病、虫、杂草传播蔓延，保护农业、林业生产安全，制定本条例。\n第二条 国务院农业主管部门、林业主管部门主管全国的植物检疫工作，各省、自治区、直辖市农业主管部门、林业主管部门主管本地区的植物检疫工作。\n第三条 县级以上地方各级农业主管部门、林业主管部门所属的植物检疫机构，负责执行国家的植物检疫任务。\n植物检疫人员进入车站、机场、港口、仓库以及其他有关场所执行植物检疫任务，应穿着检疫制服和佩带检疫标志。\n第四条 凡局部地区发生的危险性大、能随植物及其产品传播的病、虫、杂草，应定为植物检疫对象。农业、林业植物检疫对象和应施检疫的植物、植物产品名单，由国务院农业主管部门、林业主管部门制定。各省、自治区、直辖市农业主管部门、林业主管部门可以根据本地区的需要，制定本省、自治区、直辖市的补充名单，并报国务院农业主管部门、林业主管部门备案。\n第五条 局部地区发生植物检疫对象的，应划为疫区，采取封锁、消灭措施，防止植物检疫对象传出；发生地区已比较普遍的，则应将未发生地区划为保护区，防止植物检疫对象传入。\n疫区应根据植物检疫对象的传播情况、当地的地理环境、交通状况以及采取封锁、消灭措施的需要来划定，其范围应严格控制。\n在发生疫情的地区，植物检疫机构可以派人参加当地的道路联合检查站或者木材检查站；发生特大疫情时，经省、自治区、直辖市人民政府批准，可以设立植物检疫检查站，开展植物检疫工作。\n第六条 疫区和保护区的划定，由省、自治区、直辖市农业主管部门、林业主管部门提出，报省、自治区、直辖市人民政府批准，并报国务院农业主管部门、林业主管部门备案。\n疫区和保护区的范围涉及两省、自治区、直辖市以上的，由有关省、自治区、直辖市农业主管部门、林业主管部门共同提出，报国务院农业主管部门、林业主管部门批准后划定。\n疫区、保护区的改变和撤销的程序，与划定时同。\n第七条 调运植物和植物产品，属于下列情况的，必须经过检疫：\n（一）列入应施检疫的植物、植物产品名单的，运出发生疫情的县级行政区域之前，必须经过检疫；\n（二）凡种子、苗木和其他繁殖材料，不论是否列入应施检疫的植物、植物产品名单和运往何地，在调运之前，都必须经过检疫。\n第八条 按照本条例第七条的规定必须检疫的植物和植物产品，经检疫未发现植物检疫对象的，发给植物检疫证书。发现有植物检疫对象，但能彻底消毒处理的，托运人应按植物检疫机构的要求，在指定地点作消毒处理，经检查合格后发给植物检疫证书；无法消毒处理的，应停止调运。\n植物检疫证书的格式由国务院农业主管部门、林业主管部门制定。\n对可能被植物检疫对象污染的包装材料、运载工具、场地、仓库等，也应实施检疫。如已被污染，托运人应按植物检疫机构的要求处理。\n因实施检疫需要的车船停留、货物搬运、开拆、取样、储存、消毒处理等费用，由托运人负责。\n第九条 按照本条例第七条的规定必须检疫的植物和植物产品，交通运输部门和邮政部门一律凭植物检疫证书承运或收寄。植物检疫证书应随货运寄。具体办法由国务院农业主管部门、林业主管部门会同铁道、交通、民航、邮政部门制定。\n第十条 省、自治区、直辖市间调运本条例第七条规定必须经过检疫的植物和植物产品的，调入单位必须事先征得所在地的省、自治区、直辖市植物检疫机构同意，并向调出单位提出检疫要求；调出单位必须根据该检疫要求向所在地的省、自治区、直辖市植物检疫机构申请检疫。对调入的植物和植物产品，调入单位所在地的省、自治区、直辖市的植物检疫机构应当查验检疫证书，必要时可以复检。\n省、自治区、直辖市内调运植物和植物产品的检疫办法，由省、自治区、直辖市人民政府规定。\n第十一条 种子、苗木和其他繁殖材料的繁育单位，必须有计划地建立无植物检疫对象的种苗繁育基地、母树林基地。试验、推广的种子、苗木和其他繁殖材料，不得带有植物检疫对象。植物检疫机构应实施产地检疫。\n第十二条 从国外引进种子、苗木，引进单位应当向所在地的省、自治区、直辖市植物检疫机构提出申请，办理检疫审批手续。但是，国务院有关部门所属的在京单位从国外引进种子、苗木，应当向国务院农业主管部门、林业主管部门所属的植物检疫机构提出申请，办理检疫审批手续。具体办法由国务院农业主管部门、林业主管部门制定。\n从国外引进、可能潜伏有危险性病、虫的种子、苗木和其他繁殖材料，必须隔离试种，植物检疫机构应进行调查、观察和检疫，证明确实不带危险性病、虫的，方可分散种植。\n第十三条 农林院校和试验研究单位对植物检疫对象的研究，不得在检疫对象的非疫区进行。因教学、科研确需在非疫区进行时，应当遵守国务院农业主管部门、林业主管部门的规定。\n第十四条 植物检疫机构对于新发现的检疫对象和其他危险性病、虫、杂草，必须及时查清情况，立即报告省、自治区、直辖市农业主管部门、林业主管部门，采取措施，彻底消灭，并报告国务院农业主管部门、林业主管部门。\n第十五条 疫情由国务院农业主管部门、林业主管部门发布。\n第十六条 按照本条例第五条第一款和第十四条的规定，进行疫情调查和采取消灭措施所需的紧急防治费和补助费，由省、自治区、直辖市在每年的植物保护费、森林保护费或者国营农场生产费中安排。特大疫情的防治费，国家酌情给予补助。\n第十七条 在植物检疫工作中作出显著成绩的单位和个人，由人民政府给予奖励。\n第十八条 有下列行为之一的，植物检疫机构应当责令纠正，可以处以罚款；造成损失的，应当负责赔偿；构成犯罪的，由司法机关依法追究刑事责任：\n（一）未依照本条例规定办理植物检疫证书或者在报检过程中弄虚作假的；\n（二）伪造、涂改、买卖、转让植物检疫单证、印章、标志、封识的；\n（三）未依照本条例规定调运、隔离试种或者生产应施检疫的植物、植物产品的；\n（四）违反本条例规定，擅自开拆植物、植物产品包装，调换植物、植物产品，或者擅自改变植物、植物产品的规定用途的；\n（五）违反本条例规定，引起疫情扩散的。\n有前款第（一）、（二）、（三）、（四）项所列情形之一，尚不构成犯罪的，植物检疫机构可以没收非法所得。\n对违反本条例规定调运的植物和植物产品，植物检疫机构有权予以封存、没收、销毁或者责令改变用途。销毁所需费用由责任人承担。\n第十九条 植物检疫人员在植物检疫工作中，交通运输部门和邮政部门有关工作人员在植物、植物产品的运输、邮寄工作中，徇私舞弊、玩忽职守的，由其所在单位或者上级主管机关依法给予处分；构成犯罪的，由司法机关依法追究刑事责任。\n第二十条 当事人对行政处罚决定不服的，可以依法申请行政复议，也可以依法提起行政诉讼。当事人逾期不申请行政复议或者不起诉又不履行行政处罚决定的，由作出行政处罚决定的机关申请人民法院强制执行。\n第二十一条 植物检疫机构执行检疫任务可以收取检疫费，具体办法由国务院农业主管部门、林业主管部门制定。\n第二十二条 进出口植物的检疫，按照《中华人民共和国进出境动植物检疫法》的规定执行。\n第二十三条 本条例的实施细则由国务院农业主管部门、林业主管部门制定。各省、自治区、直辖市可根据本条例及其实施细则，结合当地具体情况，制定实施办法。\n第二十四条 本条例自发布之日起施行。国务院批准，农业部一九五七年十二月四日发布的《国内植物检疫试行办法》同时废止。","level":0}]},{"id":"n1301","sections":[{"name":"","text":"中华人民共和国标准化法实施条例\n（1990年4月6日中华人民共和国国务院令第53号发布 根据2024年3月10日《国务院关于修改和废止部分行政法规的决定》第一次修订 根据2026年1月30日《国务院关于修改和废止部分行政法规的决定》第二次修订）","level":0},{"name":"第一章 总 则","text":"第一条 根据《中华人民共和国标准化法》（以下简称《标准化法》）的规定，制定本条例。\n第二条 对下列需要统一的技术要求，应当制定标准：\n（一）工业产品的品种、规格、质量、等级或者安全、卫生要求；\n（二）工业产品的设计、生产、试验、检验、包装、储存、运输、使用的方法或者生产、储存、运输过程中的安全、卫生要求；\n（三）有关环境保护的各项技术要求和检验方法；\n（四）建设工程的勘察、设计、施工、验收的技术要求和方法；\n（五）有关工业生产、工程建设和环境保护的技术术语、符号、代号、制图方法、互换配合要求；\n（六）农业（含林业、牧业、渔业，下同）产品（含种子、种苗、种畜、种禽，下同）的品种、规格、质量、等级、检验、包装、储存、运输以及生产技术、管理技术的要求；\n（七）信息、能源、资源、交通运输的技术要求。\n第三条 国家有计划地发展标准化事业。标准化工作应当纳入各级国民经济和社会发展计划。\n第四条 国家鼓励采用国际标准和国外先进标准，积极参与制定国际标准。","level":1},{"name":"第二章 标准化工作的管理","text":"第五条 标准化工作的任务是制定标准、组织实施标准和对标准的实施进行监督。\n第六条 国务院标准化行政主管部门统一管理全国标准化工作，履行下列职责：\n（一）组织贯彻国家有关标准化工作的法律、法规、方针、政策；\n（二）组织制定全国标准化工作规划、计划；\n（三）组织制定国家标准；\n（四）指导国务院有关行政主管部门和省、自治区、直辖市人民政府标准化行政主管部门的标准化工作，协调和处理有关标准化工作问题；\n（五）组织实施标准；\n（六）对标准的实施情况进行监督检查；\n（七）统一管理全国的产品质量认证工作；\n（八）统一负责对有关国际标准化组织的业务联系。\n第七条 国务院有关行政主管部门分工管理本部门、本行业的标准化工作，履行下列职责：\n（一）贯彻国家标准化工作的法律、法规、方针、政策，并制定在本部门、本行业实施的具体办法；\n（二）制定本部门、本行业的标准化工作规划、计划；\n（三）承担国家下达的草拟国家标准的任务，组织制定行业标准；\n（四）指导省、自治区、直辖市有关行政主管部门的标准化工作；\n（五）组织本部门、本行业实施标准；\n（六）对标准实施情况进行监督检查；\n（七）经国务院标准化行政主管部门授权，分工管理本行业的产品质量认证工作。\n第八条 省、自治区、直辖市人民政府标准化行政主管部门统一管理本行政区域的标准化工作，履行下列职责：\n（一）贯彻国家标准化工作的法律、法规、方针、政策，并制定在本行政区域实施的具体办法；\n（二）制定地方标准化工作规划、计划；\n（三）组织制定地方标准；\n（四）指导本行政区域有关行政主管部门的标准化工作，协调和处理有关标准化工作问题；\n（五）在本行政区域组织实施标准；\n（六）对标准实施情况进行监督检查。\n第九条 省、自治区、直辖市有关行政主管部门分工管理本行政区域内本部门、本行业的标准化工作，履行下列职责：\n（一）贯彻国家和本部门、本行业、本行政区域标准化工作的法律、法规、方针、政策，并制定实施的具体办法；\n（二）制定本行政区域内本部门、本行业的标准化工作规划、计划；\n（三）承担省、自治区、直辖市人民政府下达的草拟地方标准的任务；\n（四）在本行政区域内组织本部门、本行业实施标准；\n（五）对标准实施情况进行监督检查。\n第十条 市、县标准化行政主管部门和有关行政主管部门的职责分工，由省、自治区、直辖市人民政府规定。","level":1},{"name":"第三章 标准的制定","text":"第十一条 对需要在全国范围内统一的下列技术要求，应当制定国家标准（含标准样品的制作）：\n（一）互换配合、通用技术语言要求；\n（二）保障人体健康和人身、财产安全的技术要求；\n（三）基本原料、燃料、材料的技术要求；\n（四）通用基础件的技术要求；\n（五）通用的试验、检验方法；\n（六）通用的管理技术要求；\n（七）工程建设的重要技术要求；\n（八）国家需要控制的其他重要产品的技术要求。\n第十二条 国家标准由国务院标准化行政主管部门编制计划，组织草拟，统一审批、编号、发布。\n工程建设、药品、食品卫生、兽药、环境保护的国家标准，分别由国务院工程建设主管部门、卫生主管部门、农业主管部门、环境保护主管部门组织草拟、审批；其编号、发布办法由国务院标准化行政主管部门会同国务院有关行政主管部门制定。\n法律对国家标准的制定另有规定的，依照法律的规定执行。\n第十三条 对没有国家标准而又需要在全国某个行业范围内统一的技术要求，可以制定行业标准（含标准样品的制作）。制定行业标准的项目由国务院有关行政主管部门确定。\n第十四条 行业标准由国务院有关行政主管部门编制计划，组织草拟，统一审批、编号、发布，并报国务院标准化行政主管部门备案。\n行业标准在相应的国家标准实施后，自行废止。\n第十五条 对没有国家标准和行业标准而又需要在省、自治区、直辖市范围内统一的工业产品的安全、卫生要求，可以制定地方标准。制定地方标准的项目，由省、自治区、直辖市人民政府标准化行政主管部门确定。\n第十六条 地方标准由省、自治区、直辖市人民政府标准化行政主管部门编制计划，组织草拟，统一审批、编号、发布，并报国务院标准化行政主管部门和国务院有关行政主管部门备案。\n法律对地方标准的制定另有规定的，依照法律的规定执行。\n地方标准在相应的国家标准或行业标准实施后，自行废止。\n第十七条 企业生产的产品没有国家标准、行业标准和地方标准的，应当制定相应的企业标准，作为组织生产的依据。企业标准由企业组织制定（农业企业标准制定办法另定），并按省、自治区、直辖市人民政府的规定备案。\n对已有国家标准、行业标准或者地方标准的，鼓励企业制定严于国家标准、行业标准或者地方标准要求的企业标准，在企业内部适用。\n第十八条 国家标准、行业标准分为强制性标准和推荐性标准。\n下列标准属于强制性标准：\n（一）药品标准，食品卫生标准，兽药标准；\n（二）产品及产品生产、储运和使用中的安全、卫生标准，劳动安全、卫生标准，运输安全标准；\n（三）工程建设的质量、安全、卫生标准及国家需要控制的其他工程建设标准；\n（四）环境保护的污染物排放标准和环境质量标准；\n（五）重要的通用技术术语、符号、代号和制图方法；\n（六）通用的试验、检验方法标准；\n（七）互换配合标准；\n（八）国家需要控制的重要产品质量标准。\n国家需要控制的重要产品目录由国务院标准化行政主管部门会同国务院有关行政主管部门确定。\n强制性标准以外的标准是推荐性标准。\n省、自治区、直辖市人民政府标准化行政主管部门制定的工业产品的安全、卫生要求的地方标准，在本行政区域内是强制性标准。\n第十九条 制定标准应当发挥行业协会、科学技术研究机构和学术团体的作用。\n制定国家标准、行业标准和地方标准的部门应当组织由用户、生产单位、行业协会、科学技术研究机构、学术团体及有关部门的专家组成标准化技术委员会，负责标准草拟和参加标准草案的技术审查工作。未组成标准化技术委员会的，可以由标准化技术归口单位负责标准草拟和参加标准草案的技术审查工作。\n制定企业标准应当充分听取使用单位、科学技术研究机构的意见。\n第二十条 标准实施后，制定标准的部门应当根据科学技术的发展和经济建设的需要适时进行复审。标准复审周期一般不超过五年。\n第二十一条 国家标准、行业标准和地方标准的代号、编号办法，由国务院标准化行政主管部门统一规定。\n企业标准的代号、编号办法，由国务院标准化行政主管部门会同国务院有关行政主管部门规定。\n第二十二条 标准的出版、发行办法，由制定标准的部门规定。","level":1},{"name":"第四章 标准的实施与监督","text":"第二十三条 从事科研、生产、经营的单位和个人，必须严格执行强制性标准。不符合强制性标准的产品，禁止生产、销售和进口。\n第二十四条 企业生产执行国家标准、行业标准、地方标准或企业标准，应当在产品或其说明书、包装物上标注所执行标准的代号、编号、名称。\n第二十五条 出口产品的技术要求由合同双方约定。\n出口产品在国内销售时，属于我国强制性标准管理范围的，必须符合强制性标准的要求。\n第二十六条 企业研制新产品、改进产品、进行技术改造，应当符合标准化要求。\n第二十七条 国务院标准化行政主管部门组织或授权国务院有关行政主管部门建立行业认证机构，进行产品质量认证工作。\n第二十八条 国务院标准化行政主管部门统一负责全国标准实施的监督。国务院有关行政主管部门分工负责本部门、本行业的标准实施的监督。\n省、自治区、直辖市标准化行政主管部门统一负责本行政区域内的标准实施的监督。省、自治区、直辖市人民政府有关行政主管部门分工负责本行政区域内本部门、本行业的标准实施的监督。\n市、县标准化行政主管部门和有关行政主管部门，按照省、自治区、直辖市人民政府规定的各自的职责，负责本行政区域内的标准实施的监督。\n第二十九条 国家检验机构由国务院标准化行政主管部门会同国务院有关行政主管部门规划、审查。地方检验机构由省、自治区、直辖市人民政府标准化行政主管部门会同省级有关行政主管部门规划、审查。\n处理有关产品是否符合标准的争议，以本条规定的检验机构的检验数据为准。\n第三十条 国务院有关行政主管部门可以根据需要和国家有关规定设立检验机构，负责本行业、本部门的检验工作。\n第三十一条 国家机关、社会团体、企业事业单位及全体公民均有权检举、揭发违反强制性标准的行为。","level":1},{"name":"第五章 法律责任","text":"第三十二条 违反《标准化法》和本条例有关规定，有下列情形之一的，由标准化行政主管部门或有关行政主管部门在各自的职权范围内责令限期改进，并可通报批评：\n（一）企业未按规定制定标准作为组织生产依据的；\n（二）企业未按规定要求将产品标准上报备案的；\n（三）企业的产品未按规定附有标识或与其标识不符的；\n（四）企业研制新产品、改进产品、进行技术改造，不符合标准化要求的；\n（五）科研、设计、生产中违反有关强制性标准规定的。\n第三十三条 生产不符合强制性标准的产品的，应当责令其停止生产，并没收产品，监督销毁或作必要技术处理；处以该批产品货值金额百分之二十至百分之五十的罚款；对有关责任者处以五千元以下罚款。\n销售不符合强制性标准的商品的，应当责令其停止销售，并限期追回已售出的商品，监督销毁或作必要技术处理；没收违法所得；处以该批商品货值金额百分之十至百分之二十的罚款；对有关责任者处以五千元以下罚款。\n进口不符合强制性标准的产品的，应当封存并没收该产品，监督销毁或作必要技术处理；处以进口产品货值金额百分之二十至百分之五十的罚款；对有关责任者处以五千元以下罚款。\n本条规定的责令停止生产，由有关行政主管部门决定；其他行政处罚由市场监督管理部门决定。\n第三十四条 生产、销售、进口不符合强制性标准的产品，造成严重后果，构成犯罪的，由司法机关依法追究直接责任人员的刑事责任。\n第三十五条 当事人对行政处罚决定不服的，可以依法申请行政复议，也可以依法提起行政诉讼。当事人逾期不申请行政复议、不向人民法院起诉又不履行行政处罚决定的，由作出行政处罚决定的机关申请人民法院强制执行。\n第三十六条 本条例第三十二条至第三十四条规定的处罚不免除由此产生的对他人的损害赔偿责任。受到损害的有权要求责任人赔偿损失。赔偿责任和赔偿金额纠纷可以由有关行政主管部门处理，当事人也可以直接向人民法院起诉。\n第三十七条 标准化工作的监督、检验、管理人员有下列行为之一的，由有关主管部门依法给予处分，构成犯罪的，由司法机关依法追究刑事责任：\n（一）违反本条例规定，工作失误，造成损失的；\n（二）伪造、篡改检验数据的；\n（三）徇私舞弊、滥用职权、索贿受贿的。\n第三十八条 罚没收入全部上缴财政。对单位的罚款，一律从其自有资金中支付，不得列入成本。对责任人的罚款，不得从公款中核销。","level":1},{"name":"第六章 附 则","text":"第三十九条 军用标准化管理条例，由国务院、中央军委另行制定。\n第四十条 工程建设标准化管理规定，由国务院工程建设主管部门依据《标准化法》和本条例的有关规定另行制定，报国务院批准后实施。\n第四十一条 本条例自发布之日起施行。","level":1}]},{"id":"n1302","sections":[{"name":"","text":"中华人民共和国道路运输条例\n（2004年4月30日中华人民共和国国务院令第406号公布 根据2012年11月9日《国务院关于修改和废止部分行政法规的决定》第一次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第二次修订 根据2019年3月2日《国务院关于修改部分行政法规的决定》第三次修订 根据2022年3月29日《国务院关于修改和废止部分行政法规的决定》第四次修订 根据2023年7月20日《国务院关于修改和废止部分行政法规的决定》第五次修订 根据2026年1月30日《国务院关于修改和废止部分行政法规的决定》第六次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了维护道路运输市场秩序，保障道路运输安全，保护道路运输有关各方当事人的合法权益，促进道路运输业的健康发展，制定本条例。\n第二条 从事道路运输经营以及道路运输相关业务的，应当遵守本条例。\n前款所称道路运输经营包括道路旅客运输经营（以下简称客运经营）和道路货物运输经营（以下简称货运经营）；道路运输相关业务包括站（场）经营、机动车维修经营、机动车驾驶员培训。\n第三条 从事道路运输经营以及道路运输相关业务，应当依法经营，诚实信用，公平竞争。\n第四条 道路运输管理，应当公平、公正、公开和便民。\n第五条 国家鼓励发展乡村道路运输，并采取必要的措施提高乡镇和行政村的通班车率，满足广大农民的生活和生产需要。\n第六条 国家鼓励道路运输企业实行规模化、集约化经营。任何单位和个人不得封锁或者垄断道路运输市场。\n第七条 国务院交通运输主管部门主管全国道路运输管理工作。\n县级以上地方人民政府交通运输主管部门负责本行政区域的道路运输管理工作。","level":1},{"name":"第二章 道路运输经营","text":"","level":1},{"name":"第一节 客 运","text":"第八条 申请从事客运经营的，应当具备下列条件：\n（一）有与其经营业务相适应并经检测合格的车辆；\n（二）有符合本条例第九条规定条件的驾驶人员；\n（三）有健全的安全生产管理制度。\n申请从事班线客运经营的，还应当有明确的线路和站点方案。\n第九条 从事客运经营的驾驶人员，应当符合下列条件：\n（一）取得相应的机动车驾驶证；\n（二）符合国务院交通运输主管部门规定的年龄要求；\n（三）3年内无重大以上交通责任事故记录；\n（四）经设区的市级人民政府交通运输主管部门对有关客运法律法规、机动车维修和旅客急救基本知识考试合格。\n第十条 申请从事客运经营的，应当依法向市场监督管理部门办理有关登记手续后，按照下列规定提出申请并提交符合本条例第八条规定条件的相关材料：\n（一）从事县级行政区域内和毗邻县行政区域间客运经营的，向所在地县级人民政府交通运输主管部门提出申请；\n（二）从事省际、市际、县际（除毗邻县行政区域间外）客运经营的，向所在地设区的市级人民政府交通运输主管部门提出申请；\n（三）在直辖市申请从事客运经营的，向所在地直辖市人民政府确定的交通运输主管部门提出申请。\n依照前款规定收到申请的交通运输主管部门，应当自受理申请之日起20日内审查完毕，作出许可或者不予许可的决定。予以许可的，向申请人颁发道路运输经营许可证，并向申请人投入运输的车辆配发车辆营运证；不予许可的，应当书面通知申请人并说明理由。\n对从事省际和市际客运经营的申请，收到申请的交通运输主管部门依照本条第二款规定颁发道路运输经营许可证前，应当与运输线路目的地的相应交通运输主管部门协商，协商不成的，应当按程序报省、自治区、直辖市人民政府交通运输主管部门协商决定。对从事设区的市内毗邻县客运经营的申请，有关交通运输主管部门应当进行协商，协商不成的，报所在地市级人民政府交通运输主管部门决定。\n第十一条 取得道路运输经营许可证的客运经营者，需要增加客运班线的，应当依照本条例第十条的规定办理有关手续。\n第十二条 县级以上地方人民政府交通运输主管部门在审查客运申请时，应当考虑客运市场的供求状况、普遍服务和方便群众等因素。\n同一线路有3个以上申请人时，可以通过招标的形式作出许可决定。\n第十三条 县级以上地方人民政府交通运输主管部门应当定期公布客运市场供求状况。\n第十四条 客运班线的经营期限为4年到8年。经营期限届满需要延续客运班线经营许可的，应当重新提出申请。\n第十五条 客运经营者需要终止客运经营的，应当在终止前30日内告知原许可机关。\n第十六条 客运经营者应当为旅客提供良好的乘车环境，保持车辆清洁、卫生，并采取必要的措施防止在运输过程中发生侵害旅客人身、财产安全的违法行为。\n第十七条 旅客应当持有效客票乘车，遵守乘车秩序，讲究文明卫生，不得携带国家规定的危险物品及其他禁止携带的物品乘车。\n第十八条 班线客运经营者取得道路运输经营许可证后，应当向公众连续提供运输服务，不得擅自暂停、终止或者转让班线运输。\n第十九条 从事包车客运的，应当按照约定的起始地、目的地和线路运输。\n从事旅游客运的，应当在旅游区域按照旅游线路运输。\n第二十条 客运经营者不得强迫旅客乘车，不得甩客、敲诈旅客；不得擅自更换运输车辆。","level":2},{"name":"第二节 货 运","text":"第二十一条 申请从事货运经营的，应当具备下列条件：\n（一）有与其经营业务相适应并经检测合格的车辆；\n（二）有符合本条例第二十二条规定条件的驾驶人员；\n（三）有健全的安全生产管理制度。\n第二十二条 从事货运经营的驾驶人员，应当符合下列条件：\n（一）取得相应的机动车驾驶证；\n（二）符合国务院交通运输主管部门规定的年龄要求；\n（三）经设区的市级人民政府交通运输主管部门对有关货运法律法规、机动车维修和货物装载保管基本知识考试合格（使用总质量4500千克及以下普通货运车辆的驾驶人员除外）。\n第二十三条 申请从事危险货物运输经营的，还应当具备下列条件：\n（一）有5辆以上经检测合格的危险货物运输专用车辆、设备；\n（二）有经所在地设区的市级人民政府交通运输主管部门考试合格，取得上岗资格证的驾驶人员、装卸管理人员、押运人员；\n（三）危险货物运输专用车辆配有必要的通讯工具；\n（四）有健全的安全生产管理制度。\n第二十四条 申请从事货运经营的，应当依法向市场监督管理部门办理有关登记手续后，按照下列规定提出申请并分别提交符合本条例第二十一条、第二十三条规定条件的相关材料：\n（一）从事危险货物运输经营以外的货运经营的，向县级人民政府交通运输主管部门提出申请；\n（二）从事危险货物运输经营的，向设区的市级人民政府交通运输主管部门提出申请。\n依照前款规定收到申请的交通运输主管部门，应当自受理申请之日起20日内审查完毕，作出许可或者不予许可的决定。予以许可的，向申请人颁发道路运输经营许可证，并向申请人投入运输的车辆配发车辆营运证；不予许可的，应当书面通知申请人并说明理由。\n使用总质量4500千克及以下普通货运车辆从事普通货运经营的，无需按照本条规定申请取得道路运输经营许可证及车辆营运证。\n第二十五条 货运经营者不得运输法律、行政法规禁止运输的货物。\n法律、行政法规规定必须办理有关手续后方可运输的货物，货运经营者应当查验有关手续。\n第二十六条 国家鼓励货运经营者实行封闭式运输，保证环境卫生和货物运输安全。\n货运经营者应当采取必要措施，防止货物脱落、扬撒等。\n运输危险货物应当采取必要措施，防止危险货物燃烧、爆炸、辐射、泄漏等。\n第二十七条 运输危险货物应当配备必要的押运人员，保证危险货物处于押运人员的监管之下，并悬挂明显的危险货物运输标志。\n托运危险货物的，应当向货运经营者说明危险货物的品名、性质、应急处置方法等情况，并严格按照国家有关规定包装，设置明显标志。","level":2},{"name":"第三节 客运和货运的共同规定","text":"第二十八条 客运经营者、货运经营者应当加强对从业人员的安全教育、职业道德教育，确保道路运输安全。\n道路运输从业人员应当遵守道路运输操作规程，不得违章作业。驾驶人员连续驾驶时间不得超过4个小时。\n第二十九条 生产（改装）客运车辆、货运车辆的企业应当按照国家规定标定车辆的核定人数或者载重量，严禁多标或者少标车辆的核定人数或者载重量。\n客运经营者、货运经营者应当使用符合国家规定标准的车辆从事道路运输经营。\n第三十条 客运经营者、货运经营者应当加强对车辆的维护和检测，确保车辆符合国家规定的技术标准；不得使用报废的、擅自改装的和其他不符合国家规定的车辆从事道路运输经营。\n第三十一条 客运经营者、货运经营者应当制定有关交通事故、自然灾害以及其他突发事件的道路运输应急预案。应急预案应当包括报告程序、应急指挥、应急车辆和设备的储备以及处置措施等内容。\n第三十二条 发生交通事故、自然灾害以及其他突发事件，客运经营者和货运经营者应当服从县级以上人民政府或者有关部门的统一调度、指挥。\n第三十三条 道路运输车辆应当随车携带车辆营运证，不得转让、出租。\n第三十四条 道路运输车辆运输旅客的，不得超过核定的人数，不得违反规定载货；运输货物的，不得运输旅客，运输的货物应当符合核定的载重量，严禁超载；载物的长、宽、高不得违反装载要求。\n违反前款规定的，由公安机关交通管理部门依照《中华人民共和国道路交通安全法》的有关规定进行处罚。\n第三十五条 客运经营者、危险货物运输经营者应当分别为旅客或者危险货物投保承运人责任险。","level":2},{"name":"第三章 道路运输相关业务","text":"第三十六条 从事道路运输站（场）经营的，应当具备下列条件：\n（一）有经验收合格的运输站（场）；\n（二）有相应的专业人员和管理人员；\n（三）有相应的设备、设施；\n（四）有健全的业务操作规程和安全管理制度。\n第三十七条 从事机动车维修经营的，应当具备下列条件：\n（一）有相应的机动车维修场地；\n（二）有必要的设备、设施和技术人员；\n（三）有健全的机动车维修管理制度；\n（四）有必要的环境保护措施。\n国务院交通运输主管部门根据前款规定的条件，制定机动车维修经营业务标准。\n第三十八条 从事机动车驾驶员培训的，应当具备下列条件：\n（一）取得企业法人资格；\n（二）有健全的培训机构和管理制度；\n（三）有与培训业务相适应的教学人员、管理人员；\n（四）有必要的教学车辆和其他教学设施、设备、场地。\n第三十九条 申请从事道路旅客运输站（场）经营业务的，应当在依法向市场监督管理部门办理有关登记手续后，向所在地县级人民政府交通运输主管部门提出申请，并附送符合本条例第三十六条规定条件的相关材料。县级人民政府交通运输主管部门应当自受理申请之日起15日内审查完毕，作出许可或者不予许可的决定，并书面通知申请人。\n从事道路货物运输站（场）经营、机动车维修经营和机动车驾驶员培训业务的，应当在依法向市场监督管理部门办理有关登记手续后，向所在地县级人民政府交通运输主管部门进行备案，并分别附送符合本条例第三十六条、第三十七条、第三十八条规定条件的相关材料。\n第四十条 道路运输站（场）经营者应当对出站的车辆进行安全检查，禁止无证经营的车辆进站从事经营活动，防止超载车辆或者未经安全检查的车辆出站。\n道路运输站（场）经营者应当公平对待使用站（场）的客运经营者和货运经营者，无正当理由不得拒绝道路运输车辆进站从事经营活动。\n道路运输站（场）经营者应当向旅客和货主提供安全、便捷、优质的服务；保持站（场）卫生、清洁；不得随意改变站（场）用途和服务功能。\n第四十一条 道路旅客运输站（场）经营者应当为客运经营者合理安排班次，公布其运输线路、起止经停站点、运输班次、始发时间、票价，调度车辆进站、发车，疏导旅客，维持上下车秩序。\n道路旅客运输站（场）经营者应当设置旅客购票、候车、行李寄存和托运等服务设施，按照车辆核定载客限额售票，并采取措施防止携带危险品的人员进站乘车。\n第四十二条 道路货物运输站（场）经营者应当按照国务院交通运输主管部门规定的业务操作规程装卸、储存、保管货物。\n第四十三条 机动车维修经营者应当按照国家有关技术规范对机动车进行维修，保证维修质量，不得使用假冒伪劣配件维修机动车。\n机动车维修经营者应当公布机动车维修工时定额和收费标准，合理收取费用，维修服务完成后应当提供维修费用明细单。\n第四十四条 机动车维修经营者对机动车进行二级维护、总成修理或者整车修理的，应当进行维修质量检验。检验合格的，维修质量检验人员应当签发机动车维修合格证。\n机动车维修实行质量保证期制度。质量保证期内因维修质量原因造成机动车无法正常使用的，机动车维修经营者应当无偿返修。\n机动车维修质量保证期制度的具体办法，由国务院交通运输主管部门制定。\n第四十五条 机动车维修经营者不得承修已报废的机动车，不得擅自改装机动车。\n第四十六条 机动车驾驶员培训机构应当按照国务院交通运输主管部门规定的教学大纲进行培训，确保培训质量。培训结业的，应当向参加培训的人员颁发培训结业证书。","level":1},{"name":"第四章 国际道路运输","text":"第四十七条 国务院交通运输主管部门应当及时向社会公布中国政府与有关国家政府签署的双边或者多边道路运输协定确定的国际道路运输线路。\n第四十八条 从事国际道路运输经营的，应当具备下列条件：\n（一）依照本条例第十条、第二十四条规定取得道路运输经营许可证的企业法人；\n（二）在国内从事道路运输经营满3年，且未发生重大以上道路交通责任事故。\n第四十九条 申请从事国际道路旅客运输经营的，应当向省、自治区、直辖市人民政府交通运输主管部门提出申请并提交符合本条例第四十八条规定条件的相关材料。省、自治区、直辖市人民政府交通运输主管部门应当自受理申请之日起20日内审查完毕，作出批准或者不予批准的决定。予以批准的，应当向国务院交通运输主管部门备案；不予批准的，应当向当事人说明理由。\n从事国际道路货物运输经营的，应当向省、自治区、直辖市人民政府交通运输主管部门进行备案，并附送符合本条例第四十八条规定条件的相关材料。\n国际道路运输经营者应当持有关文件依法向有关部门办理相关手续。\n第五十条 中国国际道路运输经营者应当在其投入运输车辆的显著位置，标明中国国籍识别标志。\n外国国际道路运输经营者的车辆在中国境内运输，应当标明本国国籍识别标志，并按照规定的运输线路行驶；不得擅自改变运输线路，不得从事起止地都在中国境内的道路运输经营。\n第五十一条 在口岸设立的国际道路运输管理机构应当加强对出入口岸的国际道路运输的监督管理。\n第五十二条 外国国际道路运输经营者依法在中国境内设立的常驻代表机构不得从事经营活动。","level":1},{"name":"第五章 执法监督","text":"第五十三条 县级以上地方人民政府交通运输、公安、市场监督管理等部门应当建立信息共享和协同监管机制，按照职责分工加强对道路运输及相关业务的监督管理。\n第五十四条 县级以上人民政府交通运输主管部门应当加强执法队伍建设，提高其工作人员的法制、业务素质。\n县级以上人民政府交通运输主管部门的工作人员应当接受法制和道路运输管理业务培训、考核，考核不合格的，不得上岗执行职务。\n第五十五条 上级交通运输主管部门应当对下级交通运输主管部门的执法活动进行监督。\n县级以上人民政府交通运输主管部门应当建立健全内部监督制度，对其工作人员执法情况进行监督检查。\n第五十六条 县级以上人民政府交通运输主管部门及其工作人员执行职务时，应当自觉接受社会和公民的监督。\n第五十七条 县级以上人民政府交通运输主管部门应当建立道路运输举报制度，公开举报电话号码、通信地址或者电子邮件信箱。\n任何单位和个人都有权对县级以上人民政府交通运输主管部门的工作人员滥用职权、徇私舞弊的行为进行举报。县级以上人民政府交通运输主管部门及其他有关部门收到举报后，应当依法及时查处。\n第五十八条 县级以上人民政府交通运输主管部门的工作人员应当严格按照职责权限和程序进行监督检查，不得乱设卡、乱收费、乱罚款。\n县级以上人民政府交通运输主管部门的工作人员应当重点在道路运输及相关业务经营场所、客货集散地进行监督检查。\n县级以上人民政府交通运输主管部门的工作人员在公路路口进行监督检查时，不得随意拦截正常行驶的道路运输车辆。\n第五十九条 县级以上人民政府交通运输主管部门的工作人员实施监督检查时，应当有2名以上人员参加，并向当事人出示执法证件。\n第六十条 县级以上人民政府交通运输主管部门的工作人员实施监督检查时，可以向有关单位和个人了解情况，查阅、复制有关资料。但是，应当保守被调查单位和个人的商业秘密。\n被监督检查的单位和个人应当接受依法实施的监督检查，如实提供有关资料或者情况。\n第六十一条 县级以上人民政府交通运输主管部门的工作人员在实施道路运输监督检查过程中，发现车辆超载行为的，应当立即予以制止，并采取相应措施安排旅客改乘或者强制卸货。\n第六十二条 县级以上人民政府交通运输主管部门的工作人员在实施道路运输监督检查过程中，对没有车辆营运证又无法当场提供其他有效证明的车辆予以暂扣的，应当妥善保管，不得使用，不得收取或者变相收取保管费用。","level":1},{"name":"第六章 法律责任","text":"第六十三条 违反本条例的规定，有下列情形之一的，由县级以上地方人民政府交通运输主管部门责令停止经营，并处罚款；构成犯罪的，依法追究刑事责任：\n（一）未取得道路运输经营许可，擅自从事道路普通货物运输经营，违法所得超过1万元的，没收违法所得，处违法所得1倍以上5倍以下的罚款；没有违法所得或者违法所得不足1万元的，处3000元以上1万元以下的罚款，情节严重的，处1万元以上5万元以下的罚款；\n（二）未取得道路运输经营许可，擅自从事道路客运经营，违法所得超过2万元的，没收违法所得，处违法所得2倍以上10倍以下的罚款；没有违法所得或者违法所得不足2万元的，处1万元以上10万元以下的罚款；\n（三）未取得道路运输经营许可，擅自从事道路危险货物运输经营，违法所得超过2万元的，没收违法所得，处违法所得2倍以上10倍以下的罚款；没有违法所得或者违法所得不足2万元的，处3万元以上10万元以下的罚款。\n第六十四条 不符合本条例第九条、第二十二条规定条件的人员驾驶道路运输经营车辆的，由县级以上地方人民政府交通运输主管部门责令改正，处200元以上2000元以下的罚款；构成犯罪的，依法追究刑事责任。\n第六十五条 违反本条例的规定，未经许可擅自从事道路旅客运输站（场）经营的，由县级以上地方人民政府交通运输主管部门责令停止经营；有违法所得的，没收违法所得，处违法所得2倍以上10倍以下的罚款；没有违法所得或者违法所得不足1万元的，处2万元以上5万元以下的罚款；构成犯罪的，依法追究刑事责任。\n从事机动车维修经营业务不符合国务院交通运输主管部门制定的机动车维修经营业务标准的，由县级以上地方人民政府交通运输主管部门责令改正；情节严重的，由县级以上地方人民政府交通运输主管部门责令停业整顿。\n从事道路货物运输站（场）经营、机动车驾驶员培训业务，未按规定进行备案的，由县级以上地方人民政府交通运输主管部门责令改正；拒不改正的，处5000元以上2万元以下的罚款。\n从事机动车维修经营业务，未按规定进行备案的，由县级以上地方人民政府交通运输主管部门责令改正；拒不改正的，处3000元以上1万元以下的罚款。\n备案时提供虚假材料情节严重的，其直接负责的主管人员和其他直接责任人员5年内不得从事原备案的业务。\n第六十六条 违反本条例的规定，客运经营者、货运经营者、道路运输相关业务经营者非法转让、出租道路运输许可证件的，由县级以上地方人民政府交通运输主管部门责令停止违法行为，收缴有关证件，处2000元以上1万元以下的罚款；有违法所得的，没收违法所得。\n第六十七条 违反本条例的规定，客运经营者、危险货物运输经营者未按规定投保承运人责任险的，由县级以上地方人民政府交通运输主管部门责令限期投保；拒不投保的，由原许可机关吊销道路运输经营许可证。\n第六十八条 违反本条例的规定，客运经营者有下列情形之一的，由县级以上地方人民政府交通运输主管部门责令改正，处1000元以上2000元以下的罚款；情节严重的，由原许可机关吊销道路运输经营许可证：\n（一）不按批准的客运站点停靠或者不按规定的线路、公布的班次行驶的；\n（二）在旅客运输途中擅自变更运输车辆或者将旅客移交他人运输的；\n（三）未报告原许可机关，擅自终止客运经营的。\n客运经营者强行招揽旅客，货运经营者强行招揽货物或者没有采取必要措施防止货物脱落、扬撒等的，由县级以上地方人民政府交通运输主管部门责令改正，处1000元以上3000元以下的罚款；情节严重的，由原许可机关吊销道路运输经营许可证。\n第六十九条 违反本条例的规定，客运经营者、货运经营者不按规定维护和检测运输车辆的，由县级以上地方人民政府交通运输主管部门责令改正，处1000元以上5000元以下的罚款。\n违反本条例的规定，客运经营者、货运经营者擅自改装已取得车辆营运证的车辆的，由县级以上地方人民政府交通运输主管部门责令改正，处5000元以上2万元以下的罚款。\n第七十条 违反本条例的规定，道路旅客运输站（场）经营者允许无证经营的车辆进站从事经营活动以及超载车辆、未经安全检查的车辆出站或者无正当理由拒绝道路运输车辆进站从事经营活动的，由县级以上地方人民政府交通运输主管部门责令改正，处1万元以上3万元以下的罚款。\n道路货物运输站（场）经营者有前款违法情形的，由县级以上地方人民政府交通运输主管部门责令改正，处3000元以上3万元以下的罚款。\n违反本条例的规定，道路运输站（场）经营者擅自改变道路运输站（场）的用途和服务功能，或者不公布运输线路、起止经停站点、运输班次、始发时间、票价的，由县级以上地方人民政府交通运输主管部门责令改正；拒不改正的，处3000元的罚款；有违法所得的，没收违法所得。\n第七十一条 违反本条例的规定，机动车维修经营者使用假冒伪劣配件维修机动车，承修已报废的机动车或者擅自改装机动车的，由县级以上地方人民政府交通运输主管部门责令改正；有违法所得的，没收违法所得，处违法所得2倍以上10倍以下的罚款；没有违法所得或者违法所得不足1万元的，处2万元以上5万元以下的罚款，没收假冒伪劣配件及报废车辆；情节严重的，由县级以上地方人民政府交通运输主管部门责令停业整顿；构成犯罪的，依法追究刑事责任。\n第七十二条 违反本条例的规定，机动车维修经营者签发虚假的机动车维修合格证，由县级以上地方人民政府交通运输主管部门责令改正；有违法所得的，没收违法所得，处违法所得2倍以上10倍以下的罚款；没有违法所得或者违法所得不足3000元的，处5000元以上2万元以下的罚款；情节严重的，由县级以上地方人民政府交通运输主管部门责令停业整顿；构成犯罪的，依法追究刑事责任。\n第七十三条 违反本条例的规定，机动车驾驶员培训机构不严格按照规定进行培训或者在培训结业证书发放时弄虚作假的，由县级以上地方人民政府交通运输主管部门责令改正；拒不改正的，责令停业整顿。\n第七十四条 违反本条例的规定，外国国际道路运输经营者未按照规定的线路运输，擅自从事中国境内道路运输的，由省、自治区、直辖市人民政府交通运输主管部门责令停止运输；有违法所得的，没收违法所得，处违法所得2倍以上10倍以下的罚款；没有违法所得或者违法所得不足1万元的，处3万元以上6万元以下的罚款。\n外国国际道路运输经营者未按照规定标明国籍识别标志的，由省、自治区、直辖市人民政府交通运输主管部门责令停止运输，处200元以上2000元以下的罚款。\n从事国际道路货物运输经营，未按规定进行备案的，由省、自治区、直辖市人民政府交通运输主管部门责令改正；拒不改正的，处5000元以上2万元以下的罚款。\n第七十五条 县级以上人民政府交通运输主管部门应当将道路运输及其相关业务经营者和从业人员的违法行为记入信用记录，并依照有关法律、行政法规的规定予以公示。\n第七十六条 违反本条例的规定，县级以上人民政府交通运输主管部门的工作人员有下列情形之一的，依法给予处分；构成犯罪的，依法追究刑事责任：\n（一）不依照本条例规定的条件、程序和期限实施行政许可的；\n（二）参与或者变相参与道路运输经营以及道路运输相关业务的；\n（三）发现违法行为不及时查处的；\n（四）违反规定拦截、检查正常行驶的道路运输车辆的；\n（五）违法扣留运输车辆、车辆营运证的；\n（六）索取、收受他人财物，或者谋取其他利益的；\n（七）其他违法行为。","level":1},{"name":"第七章 附 则","text":"第七十七条 内地与香港特别行政区、澳门特别行政区之间的道路运输，参照本条例的有关规定执行。\n第七十八条 外商可以依照有关法律、行政法规和国家有关规定，在中华人民共和国境内采用中外合资、中外合作、独资形式投资有关的道路运输经营以及道路运输相关业务。\n第七十九条 从事非经营性危险货物运输的，应当遵守本条例有关规定。\n第八十条 县级以上地方人民政府交通运输主管部门依照本条例发放经营许可证件和车辆营运证，可以收取工本费。工本费的具体收费标准由省、自治区、直辖市人民政府财政部门、价格主管部门会同同级交通运输主管部门核定。\n第八十一条 出租车客运和城市公共汽车客运的管理办法由国务院另行规定。\n第八十二条 本条例自2004年7月1日起施行。","level":1}]},{"id":"n1303","sections":[{"name":"","text":"地下水管理条例\n（2021年10月21日中华人民共和国国务院令第748号公布 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了加强地下水管理，防治地下水超采和污染，保障地下水质量和可持续利用，推进生态文明建设，根据《中华人民共和国生态环境法典》和《中华人民共和国水法》等法律，制定本条例。\n第二条 地下水调查与规划、节约与保护、超采治理、污染防治、监督管理等活动，适用本条例。\n本条例所称地下水，是指赋存于地表以下的水。\n第三条 地下水管理坚持统筹规划、节水优先、高效利用、系统治理的原则。\n第四条 国务院水行政主管部门负责全国地下水统一监督管理工作。国务院生态环境主管部门负责全国地下水污染防治监督管理工作。国务院自然资源等主管部门按照职责分工做好地下水调查、监测等相关工作。\n第五条 县级以上地方人民政府对本行政区域内的地下水管理负责，应当将地下水管理纳入本级国民经济和社会发展规划，并采取控制开采量、防治污染等措施，维持地下水合理水位，保护地下水水质。\n县级以上地方人民政府水行政主管部门按照管理权限，负责本行政区域内地下水统一监督管理工作。地方人民政府生态环境主管部门负责本行政区域内地下水污染防治监督管理工作。县级以上地方人民政府自然资源等主管部门按照职责分工做好本行政区域内地下水调查、监测等相关工作。\n第六条 利用地下水的单位和个人应当加强地下水取水工程管理，节约、保护地下水，防止地下水污染。\n第七条 国务院对省、自治区、直辖市地下水管理和保护情况实行目标责任制和考核评价制度。国务院有关部门按照职责分工负责考核评价工作的具体组织实施。\n第八条 任何单位和个人都有权对损害地下水的行为进行监督、检举。\n对在节约、保护和管理地下水工作中作出突出贡献的单位和个人，按照国家有关规定给予表彰和奖励。\n第九条 国家加强对地下水节约和保护的宣传教育，鼓励、支持地下水先进科学技术的研究、推广和应用。","level":1},{"name":"第二章 调查与规划","text":"第十条 国家定期组织开展地下水状况调查评价工作。地下水状况调查评价包括地下水资源调查评价、地下水污染调查评价和水文地质勘查评价等内容。\n第十一条 县级以上人民政府应当组织水行政、自然资源、生态环境等主管部门开展地下水状况调查评价工作。调查评价成果是编制地下水保护利用和污染防治等规划以及管理地下水的重要依据。调查评价成果应当依法向社会公布。\n第十二条 县级以上人民政府水行政、自然资源、生态环境等主管部门根据地下水状况调查评价成果，统筹考虑经济社会发展需要、地下水资源状况、污染防治等因素，编制本级地下水保护利用和污染防治等规划，依法履行征求意见、论证评估等程序后向社会公布。\n地下水保护利用和污染防治等规划是节约、保护、利用、修复治理地下水的基本依据。地下水保护利用和污染防治等规划应当服从水资源综合规划和环境保护规划。\n第十三条 国民经济和社会发展规划以及国土空间规划等相关规划的编制、重大建设项目的布局，应当与地下水资源条件和地下水保护要求相适应，并进行科学论证。\n第十四条 编制工业、农业、市政、能源、矿产资源开发等专项规划，涉及地下水的内容，应当与地下水保护利用和污染防治等规划相衔接。\n第十五条 国家建立地下水储备制度。国务院水行政主管部门应当会同国务院自然资源、发展改革等主管部门，对地下水储备工作进行指导、协调和监督检查。\n县级以上地方人民政府水行政主管部门应当会同本级人民政府自然资源、发展改革等主管部门，根据本行政区域内地下水条件、气候状况和水资源储备需要，制定动用地下水储备预案并报本级人民政府批准。\n除特殊干旱年份以及发生重大突发事件外，不得动用地下水储备。","level":1},{"name":"第三章 节约与保护","text":"第十六条 国家实行地下水取水总量控制制度。国务院水行政主管部门会同国务院自然资源主管部门，根据各省、自治区、直辖市地下水可开采量和地表水水资源状况，制定并下达各省、自治区、直辖市地下水取水总量控制指标。\n第十七条 省、自治区、直辖市人民政府水行政主管部门应当会同本级人民政府有关部门，根据国家下达的地下水取水总量控制指标，制定本行政区域内县级以上行政区域的地下水取水总量控制指标和地下水水位控制指标，经省、自治区、直辖市人民政府批准后下达实施，并报国务院水行政主管部门或者其授权的流域管理机构备案。\n第十八条 省、自治区、直辖市人民政府水行政主管部门制定本行政区域内地下水取水总量控制指标和地下水水位控制指标时，涉及省际边界区域且属于同一水文地质单元的，应当与相邻省、自治区、直辖市人民政府水行政主管部门协商确定。协商不成的，由国务院水行政主管部门会同国务院有关部门确定。\n第十九条 县级以上地方人民政府应当根据地下水取水总量控制指标、地下水水位控制指标和国家相关技术标准，合理确定本行政区域内地下水取水工程布局。\n第二十条 县级以上地方人民政府水行政主管部门应当根据本行政区域内地下水取水总量控制指标、地下水水位控制指标以及科学分析测算的地下水需求量和用水结构，制定地下水年度取水计划，对本行政区域内的年度取用地下水实行总量控制，并报上一级人民政府水行政主管部门备案。\n第二十一条 取用地下水的单位和个人应当遵守取水总量控制和定额管理要求，使用先进节约用水技术、工艺和设备，采取循环用水、综合利用及废水处理回用等措施，实施技术改造，降低用水消耗。\n对下列工艺、设备和产品，应当在规定的期限内停止生产、销售、进口或者使用：\n（一）列入淘汰落后的、耗水量高的工艺、设备和产品名录的；\n（二）列入限期禁止采用的严重污染水环境的工艺名录和限期禁止生产、销售、进口、使用的严重污染水环境的设备名录的。\n第二十二条 新建、改建、扩建地下水取水工程，应当同时安装计量设施。已有地下水取水工程未安装计量设施的，应当按照县级以上地方人民政府水行政主管部门规定的期限安装。\n单位和个人取用地下水量达到取水规模以上的，应当安装地下水取水在线计量设施，并将计量数据实时传输到有管理权限的水行政主管部门。取水规模由省、自治区、直辖市人民政府水行政主管部门制定、公布，并报国务院水行政主管部门备案。\n第二十三条 以地下水为灌溉水源的地区，县级以上地方人民政府应当采取保障建设投入、加大对企业信贷支持力度、建立健全基层水利服务体系等措施，鼓励发展节水农业，推广应用喷灌、微灌、管道输水灌溉、渠道防渗输水灌溉等节水灌溉技术，以及先进的农机、农艺和生物技术等，提高农业用水效率，节约农业用水。\n第二十四条 国务院根据国民经济和社会发展需要，对取用地下水的单位和个人试点征收水资源税。地下水水资源税根据当地地下水资源状况、取用水类型和经济发展等情况实行差别税率，合理提高征收标准。征收水资源税的，停止征收水资源费。\n尚未试点征收水资源税的省、自治区、直辖市，对同一类型取用水，地下水的水资源费征收标准应当高于地表水的标准，地下水超采区的水资源费征收标准应当高于非超采区的标准，地下水严重超采区的水资源费征收标准应当大幅高于非超采区的标准。\n第二十五条 有下列情形之一的，对取用地下水的取水许可申请不予批准：\n（一）不符合地下水取水总量控制、地下水水位控制要求；\n（二）不符合限制开采区取用水规定；\n（三）不符合行业用水定额和节水规定；\n（四）不符合强制性国家标准；\n（五）水资源紧缺或者生态脆弱地区新建、改建、扩建高耗水项目；\n（六）违反法律、法规的规定开垦种植而取用地下水。\n第二十六条 建设单位和个人应当采取措施防止地下工程建设对地下水补给、径流、排泄等造成重大不利影响。对开挖达到一定深度或者达到一定排水规模的地下工程，建设单位和个人应当于工程开工前，将工程建设方案和防止对地下水产生不利影响的措施方案报有管理权限的水行政主管部门备案。开挖深度和排水规模由省、自治区、直辖市人民政府制定、公布。\n第二十七条 除下列情形外，禁止开采难以更新的地下水：\n（一）应急供水取水；\n（二）无替代水源地区的居民生活用水；\n（三）为开展地下水监测、勘探、试验少量取水。\n已经开采的，除前款规定的情形外，有关县级以上地方人民政府应当采取禁止开采、限制开采措施，逐步实现全面禁止开采；前款规定的情形消除后，应当立即停止取用地下水。\n第二十八条 县级以上地方人民政府应当加强地下水水源补给保护，充分利用自然条件补充地下水，有效涵养地下水水源。\n城乡建设应当统筹地下水水源涵养和回补需要，按照海绵城市建设的要求，推广海绵型建筑、道路、广场、公园、绿地等，逐步完善滞渗蓄排等相结合的雨洪水收集利用系统。河流、湖泊整治应当兼顾地下水水源涵养，加强水体自然形态保护和修复。\n城市人民政府应当因地制宜采取有效措施，推广节水型生活用水器具，鼓励使用再生水，提高用水效率。\n第二十九条 县级以上地方人民政府应当根据地下水水源条件和需要，建设应急备用饮用水水源，制定应急预案，确保需要时正常使用。\n应急备用地下水水源结束应急使用后，应当立即停止取水。\n第三十条 有关县级以上地方人民政府水行政主管部门会同本级人民政府有关部门编制重要泉域保护方案，明确保护范围、保护措施，报本级人民政府批准后实施。\n对已经干涸但具有重要历史文化和生态价值的泉域，具备条件的，应当采取措施予以恢复。","level":1},{"name":"第四章 超采治理","text":"第三十一条 国务院水行政主管部门应当会同国务院自然资源主管部门根据地下水状况调查评价成果，组织划定全国地下水超采区，并依法向社会公布。\n第三十二条 省、自治区、直辖市人民政府水行政主管部门应当会同本级人民政府自然资源等主管部门，统筹考虑地下水超采区划定、地下水利用情况以及地质环境条件等因素，组织划定本行政区域内地下水禁止开采区、限制开采区，经省、自治区、直辖市人民政府批准后公布，并报国务院水行政主管部门备案。\n地下水禁止开采区、限制开采区划定后，确需调整的，应当按照原划定程序进行调整。\n第三十三条 有下列情形之一的，应当划为地下水禁止开采区：\n（一）已发生严重的地面沉降、地裂缝、海（咸）水入侵、植被退化等地质灾害或者生态损害的区域；\n（二）地下水超采区内公共供水管网覆盖或者通过替代水源已经解决供水需求的区域；\n（三）法律、法规规定禁止开采地下水的其他区域。\n第三十四条 有下列情形之一的，应当划为地下水限制开采区：\n（一）地下水开采量接近可开采量的区域；\n（二）开采地下水可能引发地质灾害或者生态损害的区域；\n（三）法律、法规规定限制开采地下水的其他区域。\n第三十五条 除下列情形外，在地下水禁止开采区内禁止取用地下水：\n（一）为保障地下工程施工安全和生产安全必须进行临时应急取（排）水；\n（二）为消除对公共安全或者公共利益的危害临时应急取水；\n（三）为开展地下水监测、勘探、试验少量取水。\n除前款规定的情形外，在地下水限制开采区内禁止新增取用地下水，并逐步削减地下水取水量；前款规定的情形消除后，应当立即停止取用地下水。\n第三十六条 省、自治区、直辖市人民政府水行政主管部门应当会同本级人民政府有关部门，编制本行政区域地下水超采综合治理方案，经省、自治区、直辖市人民政府批准后，报国务院水行政主管部门备案。\n地下水超采综合治理方案应当明确治理目标、治理措施、保障措施等内容。\n第三十七条 地下水超采区的县级以上地方人民政府应当加强节水型社会建设，通过加大海绵城市建设力度、调整种植结构、推广节水农业、加强工业节水、实施河湖地下水回补等措施，逐步实现地下水采补平衡。\n国家在替代水源供给、公共供水管网建设、产业结构调整等方面，加大对地下水超采区地方人民政府的支持力度。\n第三十八条 有关县级以上地方人民政府水行政主管部门应当会同本级人民政府自然资源主管部门加强对海（咸）水入侵的监测和预防。已经出现海（咸）水入侵的地区，应当采取综合治理措施。","level":1},{"name":"第五章 污染防治","text":"第三十九条 国务院生态环境主管部门应当会同国务院水行政、自然资源等主管部门，指导全国地下水污染防治重点区划定工作。省、自治区、直辖市人民政府生态环境主管部门应当会同本级人民政府水行政、自然资源等主管部门，根据本行政区域内地下水污染防治需要，划定地下水污染防治重点区。\n第四十条 禁止下列污染或者可能污染地下水的行为：\n（一）利用渗井、渗坑、裂隙、溶洞以及私设暗管等逃避监管的方式排放水污染物；\n（二）利用岩层孔隙、裂隙、溶洞、废弃矿坑等贮存石化原料及产品、农药、危险废物、城镇污水处理设施产生的污泥和处理后的污泥或者其他有毒有害物质；\n（三）利用无防渗漏措施的沟渠、坑塘等输送或者贮存含有毒污染物的废水、含病原体的污水和其他废弃物；\n（四）法律、法规禁止的其他污染或者可能污染地下水的行为。\n第四十一条 企业事业单位和其他生产经营者应当采取下列措施，防止地下水污染：\n（一）兴建地下工程设施或者进行地下勘探、采矿等活动，依法编制的环境影响评价文件中，应当包括地下水污染防治的内容，并采取防护性措施；\n（二）化工园区和化工项目、矿山开采区、尾矿库、危险废物处置场、垃圾填埋场等的运营、管理单位，应当采取防渗漏等措施，并建设地下水水质监测井进行监测；\n（三）加油站、采油厂等的地下油罐应当使用双层罐或者采取建造防渗池等其他有效措施，并进行防渗漏监测；\n（四）存放可溶性剧毒废渣的场所，应当采取防水、防渗漏、防流失的措施；\n（五）法律、法规规定应当采取的其他防止地下水污染的措施。\n第四十二条 在泉域保护范围以及岩溶强发育、存在较多落水洞和岩溶漏斗的区域内，不得新建、改建、扩建可能造成地下水污染的建设项目。\n第四十三条 多层含水层开采、回灌地下水应当防止串层污染。\n多层地下水的含水层水质差异大的，应当分层开采；对已受污染的潜水和承压水，不得混合开采。\n已经造成地下水串层污染的，应当按照封填井技术要求限期回填串层开采井，并对造成的地下水污染进行治理和修复。\n人工回灌补给地下水，应当符合相关的水质标准，不得使地下水水质恶化。\n第四十四条 农业生产经营者等有关单位和个人应当科学、合理使用农药、肥料等农业投入品，农田灌溉用水应当符合相关水质标准，防止地下水污染。\n县级以上地方人民政府及其有关部门应当加强农药、肥料等农业投入品使用指导和技术服务，鼓励和引导农业生产经营者等有关单位和个人合理使用农药、肥料等农业投入品，防止地下水污染。\n第四十五条 依照《中华人民共和国生态环境法典》的有关规定，安全利用类和严格管控类农用地地块的土壤污染影响或者可能影响地下水安全的，制定防治污染的方案时，应当包括地下水污染防治的内容。\n污染物含量超过土壤污染风险管控标准的建设用地地块，编制土壤污染风险评估报告时，应当包括地下水是否受到污染的内容；列入风险管控和修复名录的建设用地地块，采取的风险管控措施中应当包括地下水污染防治的内容。\n对需要实施修复的农用地地块，以及列入风险管控和修复名录的建设用地地块，修复方案中应当包括地下水污染防治的内容。","level":1},{"name":"第六章 监督管理","text":"第四十六条 县级以上人民政府水行政、自然资源、生态环境等主管部门应当依照职责加强监督管理，完善协作配合机制。\n国务院水行政、自然资源、生态环境等主管部门建立统一的国家地下水监测站网和地下水监测信息共享机制，对地下水进行动态监测。\n县级以上地方人民政府水行政、自然资源、生态环境等主管部门根据需要完善地下水监测工作体系，加强地下水监测。\n第四十七条 任何单位和个人不得侵占、毁坏或者擅自移动地下水监测设施设备及其标志。\n新建、改建、扩建建设工程应当避开地下水监测设施设备；确实无法避开、需要拆除地下水监测设施设备的，应当由县级以上人民政府水行政、自然资源、生态环境等主管部门按照有关技术要求组织迁建，迁建费用由建设单位承担。\n任何单位和个人不得篡改、伪造地下水监测数据。\n第四十八条 建设地下水取水工程的单位和个人，应当在申请取水许可时附具地下水取水工程建设方案，并按照取水许可批准文件的要求，自行或者委托具有相应专业技术能力的单位进行施工。施工单位不得承揽应当取得但未取得取水许可的地下水取水工程。\n以监测、勘探为目的的地下水取水工程，不需要申请取水许可，建设单位应当于施工前报有管辖权的水行政主管部门备案。\n地下水取水工程的所有权人负责工程的安全管理。\n第四十九条 县级以上地方人民政府水行政主管部门应当对本行政区域内的地下水取水工程登记造册，建立监督管理制度。\n报废的矿井、钻井、地下水取水工程，或者未建成、已完成勘探任务、依法应当停止取水的地下水取水工程，应当由工程所有权人或者管理单位实施封井或者回填；所有权人或者管理单位应当将其封井或者回填情况告知县级以上地方人民政府水行政主管部门；无法确定所有权人或者管理单位的，由县级以上地方人民政府或者其授权的部门负责组织实施封井或者回填。\n实施封井或者回填，应当符合国家有关技术标准。\n第五十条 县级以上地方人民政府应当组织水行政、自然资源、生态环境等主管部门，划定集中式地下水饮用水水源地并公布名录，定期组织开展地下水饮用水水源地安全评估。\n第五十一条 县级以上地方人民政府水行政主管部门应当会同本级人民政府自然资源等主管部门，根据水文地质条件和地下水保护要求，划定需要取水的地热能开发利用项目的禁止和限制取水范围。\n禁止在集中式地下水饮用水水源地建设需要取水的地热能开发利用项目。禁止抽取难以更新的地下水用于需要取水的地热能开发利用项目。\n建设需要取水的地热能开发利用项目，应当对取水和回灌进行计量，实行同一含水层等量取水和回灌，不得对地下水造成污染。达到取水规模以上的，应当安装取水和回灌在线计量设施，并将计量数据实时传输到有管理权限的水行政主管部门。取水规模由省、自治区、直辖市人民政府水行政主管部门制定、公布。\n对不符合本条第一款、第二款、第三款规定的已建需要取水的地热能开发利用项目，取水单位和个人应当按照水行政主管部门的规定限期整改，整改不合格的，予以关闭。\n第五十二条 矿产资源开采、地下工程建设疏干排水量达到规模的，应当依法申请取水许可，安装排水计量设施，定期向取水许可审批机关报送疏干排水量和地下水水位状况。疏干排水量规模由省、自治区、直辖市人民政府制定、公布。\n为保障矿井等地下工程施工安全和生产安全必须进行临时应急取（排）水的，不需要申请取水许可。取（排）水单位和个人应当于临时应急取（排）水结束后5个工作日内，向有管理权限的县级以上地方人民政府水行政主管部门备案。\n矿产资源开采、地下工程建设疏干排水应当优先利用，无法利用的应当达标排放。\n第五十三条 县级以上人民政府水行政、生态环境等主管部门应当建立从事地下水节约、保护、利用活动的单位和个人的诚信档案，记录日常监督检查结果、违法行为查处等情况，并依法向社会公示。","level":1},{"name":"第七章 法律责任","text":"第五十四条 县级以上地方人民政府，县级以上人民政府水行政、生态环境、自然资源主管部门和其他负有地下水监督管理职责的部门有下列行为之一的，由上级机关责令改正，对负有责任的主管人员和其他直接责任人员依法给予处分：\n（一）未采取有效措施导致本行政区域内地下水超采范围扩大，或者地下水污染状况未得到改善甚至恶化；\n（二）未完成本行政区域内地下水取水总量控制指标和地下水水位控制指标；\n（三）对地下水水位低于控制水位未采取相关措施；\n（四）发现违法行为或者接到对违法行为的检举后未予查处；\n（五）有其他滥用职权、玩忽职守、徇私舞弊等违法行为。\n第五十五条 违反本条例规定，未经批准擅自取用地下水，或者利用渗井、渗坑、裂隙、溶洞以及私设暗管等逃避监管的方式排放水污染物等违法行为，依照《中华人民共和国生态环境法典》、《中华人民共和国水法》、《取水许可和水资源费征收管理条例》等法律、行政法规的规定处罚。\n第五十六条 地下水取水工程未安装计量设施的，由县级以上地方人民政府水行政主管部门责令限期安装，并按照日最大取水能力计算的取水量计征相关费用，处10万元以上50万元以下罚款；情节严重的，吊销取水许可证。\n计量设施不合格或者运行不正常的，由县级以上地方人民政府水行政主管部门责令限期更换或者修复；逾期不更换或者不修复的，按照日最大取水能力计算的取水量计征相关费用，处10万元以上50万元以下罚款；情节严重的，吊销取水许可证。\n第五十七条 地下工程建设对地下水补给、径流、排泄等造成重大不利影响的，由县级以上地方人民政府水行政主管部门责令限期采取措施消除不利影响，处10万元以上50万元以下罚款；逾期不采取措施消除不利影响的，由县级以上地方人民政府水行政主管部门组织采取措施消除不利影响，所需费用由违法行为人承担。\n地下工程建设应当于开工前将工程建设方案和防止对地下水产生不利影响的措施方案备案而未备案的，或者矿产资源开采、地下工程建设疏干排水应当定期报送疏干排水量和地下水水位状况而未报送的，由县级以上地方人民政府水行政主管部门责令限期补报；逾期不补报的，处2万元以上10万元以下罚款。\n第五十八条 报废的矿井、钻井、地下水取水工程，或者未建成、已完成勘探任务、依法应当停止取水的地下水取水工程，未按照规定封井或者回填的，由县级以上地方人民政府或者其授权的部门责令封井或者回填，处10万元以上50万元以下罚款；不具备封井或者回填能力的，由县级以上地方人民政府或者其授权的部门组织封井或者回填，所需费用由违法行为人承担。\n第五十九条 利用岩层孔隙、裂隙、溶洞、废弃矿坑等贮存石化原料及产品、农药、危险废物或者其他有毒有害物质的，由地方人民政府生态环境主管部门责令限期改正，处10万元以上100万元以下罚款。\n利用岩层孔隙、裂隙、溶洞、废弃矿坑等贮存城镇污水处理设施产生的污泥和处理后的污泥的，由县级以上地方人民政府城镇排水主管部门责令限期改正，处20万元以上200万元以下罚款，对直接负责的主管人员和其他直接责任人员处2万元以上10万元以下罚款；造成严重后果的，处200万元以上500万元以下罚款，对直接负责的主管人员和其他直接责任人员处5万元以上50万元以下罚款。\n在泉域保护范围以及岩溶强发育、存在较多落水洞和岩溶漏斗的区域内，新建、改建、扩建造成地下水污染的建设项目的，由地方人民政府生态环境主管部门处10万元以上50万元以下罚款，并报经有批准权的人民政府批准，责令拆除或者关闭。\n第六十条 侵占、毁坏或者擅自移动地下水监测设施设备及其标志的，由县级以上地方人民政府水行政、自然资源、生态环境主管部门责令停止违法行为，限期采取补救措施，处2万元以上20万元以下罚款；逾期不采取补救措施的，由县级以上地方人民政府水行政、自然资源、生态环境主管部门组织补救，所需费用由违法行为人承担。\n第六十一条 以监测、勘探为目的的地下水取水工程在施工前应当备案而未备案的，由县级以上地方人民政府水行政主管部门责令限期补办备案手续；逾期不补办备案手续的，责令限期封井或者回填，处2万元以上10万元以下罚款；逾期不封井或者回填的，由县级以上地方人民政府水行政主管部门组织封井或者回填，所需费用由违法行为人承担。\n第六十二条 违反本条例规定，构成违反治安管理行为的，由公安机关依法给予治安管理处罚；构成犯罪的，依法追究刑事责任。","level":1},{"name":"第八章 附 则","text":"第六十三条 本条例下列用语含义是：\n地下水取水工程，是指地下水取水井及其配套设施，包括水井、集水廊道、集水池、渗渠、注水井以及需要取水的地热能开发利用项目的取水井和回灌井等。\n地下水超采区，是指地下水实际开采量超过可开采量，引起地下水水位持续下降、引发生态损害和地质灾害的区域。\n难以更新的地下水，是指与大气降水和地表水体没有密切水力联系，无法补给或者补给非常缓慢的地下水。\n第六十四条 本条例自2021年12月1日起施行。","level":1}]},{"id":"n1304","sections":[{"name":"","text":"快递暂行条例\n（2018年3月2日中华人民共和国国务院令第697号公布 根据2019年3月2日《国务院关于修改部分行政法规的决定》第一次修订 根据2025年4月13日《国务院关于修改〈快递暂行条例〉的决定》第二次修订 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》第三次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为促进快递业健康发展，保障快递安全，保护快递用户合法权益，加强对快递业的监督管理，根据《中华人民共和国邮政法》和其他有关法律，制定本条例。\n第二条 在中华人民共和国境内从事快递业务经营、接受快递服务以及对快递业实施监督管理，适用本条例。\n第三条 快递业发展应当遵循市场主导、保障安全、创新驱动、协同发展的原则，构建普惠城乡、技术先进、服务优质、安全高效、绿色节能的快递服务体系。\n第四条 地方各级人民政府应当创造良好的快递业营商环境，支持经营快递业务的企业创新商业模式和服务方式，引导经营快递业务的企业加强服务质量管理、健全规章制度、完善安全保障措施，为用户提供迅速、准确、安全、方便的快递服务。\n地方各级人民政府应当确保政府相关行为符合公平竞争要求和相关法律法规，维护快递业竞争秩序，不得出台违反公平竞争、可能造成地区封锁和行业垄断的政策措施。\n第五条 任何单位或者个人不得利用信件、包裹、印刷品以及其他寄递物品（以下统称快件）从事危害国家安全、社会公共利益或者他人合法权益的活动。\n除有关部门依照法律对快件进行检查外，任何单位或者个人不得非法检查他人快件。任何单位或者个人不得私自开拆、隐匿、毁弃、倒卖他人快件。\n第六条 国务院邮政管理部门负责对全国快递业实施监督管理。国务院公安、国家安全、海关、市场监督管理等有关部门在各自职责范围内负责相关的快递监督管理工作。\n省、自治区、直辖市邮政管理机构和按照国务院规定设立的省级以下邮政管理机构负责对本辖区的快递业实施监督管理。县级以上地方人民政府有关部门在各自职责范围内负责相关的快递监督管理工作。\n第七条 国务院邮政管理部门和省、自治区、直辖市邮政管理机构以及省级以下邮政管理机构（以下统称邮政管理部门）应当与公安、国家安全、海关、市场监督管理等有关部门相互配合，建立健全快递安全监管机制，加强对快递业安全运行的监测预警，收集、共享与快递业安全运行有关的信息，依法处理影响快递业安全运行的事件。\n第八条 依法成立的快递行业组织应当保护企业合法权益，加强行业自律，促进企业守法、诚信、安全经营，督促企业落实安全生产主体责任，引导企业不断提高快递服务质量和水平。\n第九条 国家加强快递业诚信体系建设，建立健全快递业信用记录、信息公开、信用评价制度，依法实施联合惩戒措施，提高快递业信用水平。\n第十条 国家完善综合性支持政策，推进快递包装绿色化、减量化、可循环。\n国家鼓励经营快递业务的企业和寄件人使用可降解、可重复利用的环保包装材料。","level":1},{"name":"第二章 发展保障","text":"第十一条 国务院邮政管理部门应当制定快递业发展规划，促进快递业健康发展。\n县级以上地方人民政府应当将快递业发展纳入本级国民经济和社会发展规划，在国土空间规划中统筹考虑快件大型集散、分拣等基础设施用地的需要。\n县级以上地方人民政府建立健全促进快递业健康发展的政策措施，完善相关配套规定，依法保障经营快递业务的企业及其从业人员的合法权益。\n第十二条 国家支持和鼓励经营快递业务的企业在农村、偏远地区发展快递服务网络，完善快递末端网点布局。\n第十三条 国家鼓励和引导经营快递业务的企业采用先进技术，促进自动化分拣设备、机械化装卸设备、智能末端服务设施、快递电子运单以及快件信息化管理系统等的推广应用。\n第十四条 县级以上地方人民政府公安、交通运输等部门和邮政管理部门应当加强协调配合，建立健全快递运输保障机制，依法保障快递服务车辆通行和临时停靠的权利，不得禁止快递服务车辆依法通行。\n邮政管理部门会同县级以上地方人民政府公安等部门，依法规范快递服务车辆的管理和使用，对快递专用电动三轮车的行驶时速、装载质量等作出规定，并对快递服务车辆加强统一编号和标识管理。经营快递业务的企业应当对其从业人员加强道路交通安全培训。\n快递从业人员应当遵守道路交通安全法律法规的规定，按照操作规范安全、文明驾驶车辆。快递从业人员因执行工作任务造成他人损害的，由快递从业人员所属的经营快递业务的企业依照民事侵权责任相关法律的规定承担侵权责任。\n第十五条 企业事业单位、住宅小区管理单位应当根据实际情况，采取与经营快递业务的企业签订合同、设置快件收寄投递专门场所等方式，为开展快递服务提供必要的便利。鼓励多个经营快递业务的企业共享末端服务设施，为用户提供便捷的快递末端服务。\n第十六条 国家鼓励快递业与制造业、农业、商贸业等行业建立协同发展机制，推动快递业与电子商务融合发展，加强信息沟通，共享设施和网络资源。\n国家引导和推动快递业与铁路、公路、水路、民航等行业的标准对接，支持在大型车站、码头、机场等交通枢纽配套建设快件运输通道和接驳场所。\n第十七条 国家鼓励经营快递业务的企业依法开展进出境快递业务，支持在重点口岸建设进出境快件处理中心、在境外依法开办快递服务机构并设置快件处理场所。\n海关、邮政管理等部门应当建立协作机制，完善进出境快件管理，推动实现快件便捷通关。","level":1},{"name":"第三章 经营主体","text":"第十八条 经营快递业务，应当依法取得快递业务经营许可。邮政管理部门应当根据《中华人民共和国邮政法》第五十二条、第五十三条规定的条件和程序核定经营许可的业务范围和地域范围，向社会公布取得快递业务经营许可的企业名单，并及时更新。\n第十九条 经营快递业务的企业及其分支机构可以根据业务需要开办快递末端网点，并应当自开办之日起20日内向所在地邮政管理部门备案。快递末端网点无需办理营业执照。\n第二十条 两个以上经营快递业务的企业可以使用统一的商标、字号或者快递运单经营快递业务。\n前款规定的经营快递业务的企业应当签订书面协议明确各自的权利义务，遵守共同的服务约定，在服务质量、安全保障、业务流程等方面实行统一管理，为用户提供统一的快件跟踪查询和投诉处理服务。\n用户的合法权益因快件延误、丢失、损毁或者内件短少而受到损害的，用户可以要求该商标、字号或者快递运单所属企业赔偿，也可以要求实际提供快递服务的企业赔偿。\n第二十一条 经营快递业务的企业应当依法保护其从业人员的合法权益。\n经营快递业务的企业应当对其从业人员加强职业操守、服务规范、作业规范、安全生产、车辆安全驾驶等方面的教育和培训。","level":1},{"name":"第四章 快递服务","text":"第二十二条 经营快递业务的企业在寄件人填写快递运单前，应当提醒其阅读快递服务合同条款、遵守禁止寄递和限制寄递物品的有关规定，告知相关保价规则和保险服务项目。\n寄件人交寄贵重物品的，应当事先声明；经营快递业务的企业可以要求寄件人对贵重物品予以保价。\n第二十三条 寄件人交寄快件，应当如实提供以下事项：\n（一）寄件人姓名、地址、联系电话；\n（二）收件人姓名（名称）、地址、联系电话；\n（三）寄递物品的名称、性质、数量。\n除信件和已签订安全协议用户交寄的快件外，经营快递业务的企业收寄快件，应当对寄件人身份进行查验，并登记身份信息，但不得在快递运单上记录除姓名（名称）、地址、联系电话以外的用户身份信息。寄件人拒绝提供身份信息或者提供身份信息不实的，经营快递业务的企业不得收寄。\n第二十四条 国家鼓励经营快递业务的企业在节假日期间根据业务量变化实际情况，为用户提供正常的快递服务。\n第二十五条 经营快递业务的企业应当规范操作，防止造成快件损毁。\n法律法规对食品、药品等特定物品的运输有特殊规定的，寄件人、经营快递业务的企业应当遵守相关规定。\n第二十六条 经营快递业务的企业应当将快件投递到约定的收件地址、收件人或者收件人指定的代收人，并告知收件人或者代收人当面验收。收件人或者代收人有权当面验收。\n第二十七条 快件无法投递的，经营快递业务的企业应当退回寄件人或者根据寄件人的要求进行处理；属于进出境快件的，经营快递业务的企业应当依法办理海关和检验检疫手续。\n快件无法投递又无法退回的，依照下列规定处理：\n（一）属于信件，自确认无法退回之日起超过6个月无人认领的，由经营快递业务的企业在所在地邮政管理部门的监督下销毁；\n（二）属于信件以外其他快件的，经营快递业务的企业应当登记，并按照国务院邮政管理部门的规定处理；\n（三）属于进境快件的，交由海关依法处理。\n第二十八条 快件延误、丢失、损毁或者内件短少的，对保价的快件，应当按照经营快递业务的企业与寄件人约定的保价规则确定赔偿责任；对未保价的快件，依照民事法律的有关规定确定赔偿责任。\n国家鼓励保险公司开发快件损失赔偿责任险种，鼓励经营快递业务的企业投保。\n第二十九条 经营快递业务的企业应当实行快件寄递全程信息化管理，公布联系方式，保证与用户的联络畅通，向用户提供业务咨询、快件查询等服务。用户对快递服务质量不满意的，可以向经营快递业务的企业投诉，经营快递业务的企业应当自接到投诉之日起7日内予以处理并告知用户。\n第三十条 经营快递业务的企业停止经营的，应当提前10日向社会公告，书面告知邮政管理部门，交回快递业务经营许可证，并依法妥善处理尚未投递的快件。\n经营快递业务的企业或者其分支机构因不可抗力或者其他特殊原因暂停快递服务的，应当及时向邮政管理部门报告，向社会公告暂停服务的原因和期限，并依法妥善处理尚未投递的快件。","level":1},{"name":"第五章 快递安全","text":"第三十一条 寄件人交寄快件和经营快递业务的企业收寄快件应当遵守《中华人民共和国邮政法》第二十四条关于禁止寄递或者限制寄递物品的规定。\n禁止寄递物品的目录及管理办法，由国务院邮政管理部门会同国务院有关部门制定并公布。\n第三十二条 经营快递业务的企业收寄快件，应当依照《中华人民共和国邮政法》的规定验视内件，并作出验视标识。寄件人拒绝验视的，经营快递业务的企业不得收寄。\n经营快递业务的企业受寄件人委托，长期、批量提供快递服务的，应当与寄件人签订安全协议，明确双方的安全保障义务。\n第三十三条 经营快递业务的企业可以自行或者委托第三方企业对快件进行安全检查，并对经过安全检查的快件作出安全检查标识。经营快递业务的企业委托第三方企业对快件进行安全检查的，不免除委托方对快件安全承担的责任。\n经营快递业务的企业或者接受委托的第三方企业应当使用符合强制性国家标准的安全检查设备，并加强对安全检查人员的背景审查和技术培训；经营快递业务的企业或者接受委托的第三方企业对安全检查人员进行背景审查，公安机关等相关部门应当予以配合。\n第三十四条 经营快递业务的企业发现寄件人交寄禁止寄递物品的，应当拒绝收寄；发现已经收寄的快件中有疑似禁止寄递物品的，应当立即停止分拣、运输、投递。对快件中依法应当没收、销毁或者可能涉及违法犯罪的物品，经营快递业务的企业应当立即向有关部门报告并配合调查处理；对其他禁止寄递物品以及限制寄递物品，经营快递业务的企业应当按照法律、行政法规或者国务院和国务院有关主管部门的规定处理。\n第三十五条 经营快递业务的企业应当建立快递运单及电子数据管理制度，妥善保管用户信息等电子数据，定期销毁快递运单，采取有效技术手段保证用户信息安全。具体办法由国务院邮政管理部门会同国务院有关部门制定。\n经营快递业务的企业及其从业人员不得出售、泄露或者非法提供快递服务过程中知悉的用户信息。发生或者可能发生用户信息泄露的，经营快递业务的企业应当立即采取补救措施，并向所在地邮政管理部门报告。\n第三十六条 经营快递业务的企业应当依法建立健全安全生产责任制，确保快递服务安全。\n经营快递业务的企业应当依法制定突发事件应急预案，定期开展突发事件应急演练；发生突发事件的，应当按照应急预案及时、妥善处理，并立即向所在地邮政管理部门报告。","level":1},{"name":"第六章 快递包装","text":"第三十七条 快递包装应当符合寄递生产作业的要求，节约使用资源，避免过度包装，防止污染环境。\n国务院标准化行政主管部门和国务院邮政管理等部门按照职责分工组织制定快递包装的国家标准、行业标准。快递包装应当符合强制性国家标准。\n第三十八条 国家鼓励科技创新，支持采用新技术、新材料、新工艺研发、生产符合绿色环保要求的快递包装。\n第三十九条 经营快递业务的企业应当在保障快递安全的前提下，优化快递包装方式和包装结构设计，节约使用包装物。\n鼓励经营快递业务的企业使用通过绿色产品认证的包装物。\n第四十条 国家推动经营快递业务的企业与商品生产企业、电子商务企业协同发展，推广商品原装直发，减少寄递环节的二次包装。\n第四十一条 经营快递业务的企业应当制定并实施快递包装操作规范，加强对其从业人员快递包装操作技能的培训。\n第四十二条 经营快递业务的企业应当制定并实施包装物回收利用管理制度，优化业务流程，提高包装物的回收利用率。\n鼓励在快递经营场所和企业事业单位、住宅小区等其他适当场所设置包装物回收设施设备。\n第四十三条 经营快递业务的企业应当按照国家有关规定向邮政管理部门报告包装物中一次性塑料制品的使用、回收情况。\n第四十四条 国务院有关部门、县级以上地方人民政府及其有关部门应当组织开展多种形式的宣传教育活动，新闻媒体应当开展公益宣传，提高公众的环保包装意识。\n鼓励经营快递业务的企业通过积分奖励、寄件优惠等方式引导用户重复使用包装物。\n第四十五条 依法成立的快递行业组织应当将经营快递业务的企业使用、回收包装物等情况纳入行业自律范围，并及时向社会公布有关情况。","level":1},{"name":"第七章 监督检查","text":"第四十六条 邮政管理部门应当加强对快递业的监督检查。监督检查应当以下列事项为重点：\n（一）从事快递活动的企业是否依法取得快递业务经营许可；\n（二）经营快递业务的企业的安全管理制度是否健全并有效实施；\n（三）经营快递业务的企业是否妥善处理用户的投诉、保护用户合法权益；\n（四）经营快递业务的企业是否落实快递包装有关管理制度和强制性国家标准。\n第四十七条 邮政管理部门应当建立和完善以随机抽查为重点的日常监督检查制度，公布抽查事项目录，明确抽查的依据、频次、方式、内容和程序，随机抽取被检查企业，随机选派检查人员。抽查情况和查处结果应当及时向社会公布。\n邮政管理部门应当充分利用计算机网络等先进技术手段，加强对快递业务活动的日常监督检查，提高快递业管理水平。\n第四十八条 邮政管理部门依法履行职责，有权采取《中华人民共和国邮政法》第六十一条规定的监督检查措施。邮政管理部门实施现场检查，有权查阅经营快递业务的企业管理快递业务的电子数据。\n国家安全机关、公安机关为维护国家安全和侦查犯罪活动的需要依法开展执法活动，经营快递业务的企业应当提供技术支持和协助。\n《中华人民共和国邮政法》第十一条规定的处理场所，包括快件处理场地、设施、设备。\n第四十九条 邮政管理部门应当向社会公布本部门的联系方式，方便公众举报违法行为。\n邮政管理部门接到举报的，应当及时依法调查处理，并为举报人保密。对实名举报的，邮政管理部门应当将处理结果告知举报人。","level":1},{"name":"第八章 法律责任","text":"第五十条 未取得快递业务经营许可从事快递活动的，由邮政管理部门依照《中华人民共和国邮政法》的规定予以处罚。\n经营快递业务的企业或者其分支机构有下列行为之一的，由邮政管理部门责令改正，可以处1万元以下的罚款；情节严重的，处1万元以上5万元以下的罚款，并可以责令停业整顿：\n（一）开办快递末端网点未向所在地邮政管理部门备案；\n（二）停止经营快递业务，未提前10日向社会公告，未书面告知邮政管理部门并交回快递业务经营许可证，或者未依法妥善处理尚未投递的快件；\n（三）因不可抗力或者其他特殊原因暂停快递服务，未及时向邮政管理部门报告并向社会公告暂停服务的原因和期限，或者未依法妥善处理尚未投递的快件。\n第五十一条 两个以上经营快递业务的企业使用统一的商标、字号或者快递运单经营快递业务，未遵守共同的服务约定，在服务质量、安全保障、业务流程等方面未实行统一管理，或者未向用户提供统一的快件跟踪查询和投诉处理服务的，由邮政管理部门责令改正，处1万元以上5万元以下的罚款；情节严重的，处5万元以上10万元以下的罚款，并可以责令停业整顿。\n第五十二条 冒领、私自开拆、隐匿、毁弃、倒卖或者非法检查他人快件，尚不构成犯罪的，依法给予治安管理处罚。\n经营快递业务的企业有前款规定行为，或者非法扣留快件的，由邮政管理部门责令改正，没收违法所得，并处5万元以上10万元以下的罚款；情节严重的，并处10万元以上20万元以下的罚款，并可以责令停业整顿直至吊销其快递业务经营许可证。\n第五十三条 经营快递业务的企业有下列情形之一的，由邮政管理部门依照《中华人民共和国邮政法》、《中华人民共和国反恐怖主义法》的规定予以处罚：\n（一）不建立或者不执行收寄验视制度；\n（二）违反法律、行政法规以及国务院和国务院有关部门关于禁止寄递或者限制寄递物品的规定；\n（三）收寄快件未查验寄件人身份并登记身份信息，或者发现寄件人提供身份信息不实仍予收寄；\n（四）未按照规定对快件进行安全检查。\n寄件人在快件中夹带禁止寄递的物品，尚不构成犯罪的，依法给予治安管理处罚。\n第五十四条 经营快递业务的企业有下列行为之一的，由邮政管理部门责令改正，没收违法所得，并处1万元以上5万元以下的罚款；情节严重的，并处5万元以上10万元以下的罚款，并可以责令停业整顿直至吊销其快递业务经营许可证：\n（一）未按照规定建立快递运单及电子数据管理制度；\n（二）未定期销毁快递运单；\n（三）出售、泄露或者非法提供快递服务过程中知悉的用户信息；\n（四）发生或者可能发生用户信息泄露的情况，未立即采取补救措施，或者未向所在地邮政管理部门报告。\n第五十五条 经营快递业务的企业及其从业人员在经营活动中有危害国家安全行为的，依法追究法律责任；对经营快递业务的企业，由邮政管理部门吊销其快递业务经营许可证。\n第五十六条 经营快递业务的企业采用的快递包装不符合强制性国家标准，或者未按照国家有关规定向邮政管理部门报告包装物中一次性塑料制品的使用情况的，由邮政管理部门依照《中华人民共和国生态环境法典》、《中华人民共和国标准化法》等法律、行政法规的规定予以处罚。\n经营快递业务的企业未按照规定制定、实施快递包装操作规范或者包装物回收利用管理制度的，由邮政管理部门责令改正；拒不改正的，处5000元以上2万元以下的罚款。\n第五十七条 邮政管理部门和其他有关部门的工作人员在监督管理工作中滥用职权、玩忽职守、徇私舞弊的，依法给予处分。\n第五十八条 违反本条例规定，构成犯罪的，依法追究刑事责任；造成人身、财产或者其他损害的，依法承担赔偿责任。","level":1},{"name":"第九章 附 则","text":"第五十九条 本条例自2018年5月1日起施行。","level":1}]},{"id":"n1305","sections":[{"name":"","text":"全国污染源普查条例\n（2007年10月9日中华人民共和国国务院令第508号公布 根据2019年3月2日《国务院关于修改部分行政法规的决定》第一次修订 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》第二次修订）","level":0},{"name":"第一章 总 则","text":"第一条 为了科学、有效地组织实施全国污染源普查，保障污染源普查数据的准确性和及时性，根据《中华人民共和国生态环境法典》和《中华人民共和国统计法》，制定本条例。\n第二条 污染源普查的任务是，掌握各类污染源的数量、行业和地区分布情况，了解主要污染物的产生、排放和处理情况，建立健全重点污染源档案、污染源信息数据库和环境统计平台，为制定经济社会发展和环境保护政策、规划提供依据。\n第三条 本条例所称污染源，是指因生产、生活和其他活动向环境排放污染物或者对环境产生不良影响的场所、设施、装置以及其他污染发生源。\n第四条 污染源普查按照全国统一领导、部门分工协作、地方分级负责、各方共同参与的原则组织实施。\n第五条 污染源普查所需经费，由中央和地方各级人民政府共同负担，并列入相应年度的财政预算，按时拨付，确保足额到位。\n污染源普查经费应当统一管理，专款专用，严格控制支出。\n第六条 全国污染源普查每10年进行1次，标准时点为普查年份的12月31日。\n第七条 报刊、广播、电视和互联网等新闻媒体，应当及时开展污染源普查工作的宣传报道。","level":1},{"name":"第二章 污染源普查的对象、范围、内容和方法","text":"第八条 污染源普查的对象是中华人民共和国境内有污染源的单位和个体经营户。\n第九条 污染源普查对象有义务接受污染源普查领导小组办公室、普查人员依法进行的调查，并如实反映情况，提供有关资料，按照要求填报污染源普查表。\n污染源普查对象不得迟报、虚报、瞒报和拒报普查数据；不得推诿、拒绝和阻挠调查；不得转移、隐匿、篡改、毁弃原材料消耗记录、生产记录、污染物治理设施运行记录、污染物排放监测记录以及其他与污染物产生和排放有关的原始资料。\n第十条 污染源普查范围包括：工业污染源，农业污染源，生活污染源，集中式污染治理设施和其他产生、排放污染物的设施。\n第十一条 工业污染源普查的主要内容包括：企业基本登记信息，原材料消耗情况，产品生产情况，产生污染的设施情况，各类污染物产生、治理、排放和综合利用情况，各类污染防治设施建设、运行情况等。\n农业污染源普查的主要内容包括：农业生产规模，用水、排水情况，化肥、农药、饲料和饲料添加剂以及农用薄膜等农业投入品使用情况，秸秆等种植业剩余物处理情况以及养殖业污染物产生、治理情况等。\n生活污染源普查的主要内容包括：从事第三产业的单位的基本情况和污染物的产生、排放、治理情况，机动车污染物排放情况，城镇生活能源结构和能源消费量，生活用水量、排水量以及污染物排放情况等。\n集中式污染治理设施普查的主要内容包括：设施基本情况和运行状况，污染物的处理处置情况，渗滤液、污泥、焚烧残渣和废气的产生、处置以及利用情况等。\n第十二条 每次污染源普查的具体范围和内容，由国务院批准的普查方案确定。\n第十三条 污染源普查采用全面调查的方法，必要时可以采用抽样调查的方法。\n污染源普查采用全国统一的标准和技术要求。","level":1},{"name":"第三章 污染源普查的组织实施","text":"第十四条 全国污染源普查领导小组负责领导和协调全国污染源普查工作。\n全国污染源普查领导小组办公室设在国务院生态环境主管部门，负责全国污染源普查日常工作。\n第十五条 县级以上地方人民政府污染源普查领导小组，按照全国污染源普查领导小组的统一规定和要求，领导和协调本行政区域的污染源普查工作。\n县级以上地方人民政府污染源普查领导小组办公室设在同级生态环境主管部门，负责本行政区域的污染源普查日常工作。\n乡（镇）人民政府、街道办事处和村（居）民委员会应当广泛动员和组织社会力量积极参与并认真做好污染源普查工作。\n第十六条 县级以上人民政府生态环境主管部门和其他有关部门，按照职责分工和污染源普查领导小组的统一要求，做好污染源普查相关工作。\n第十七条 全国污染源普查方案由全国污染源普查领导小组办公室拟订，经全国污染源普查领导小组审核同意，报国务院批准。\n全国污染源普查方案应当包括：普查的具体范围和内容、普查的主要污染物、普查方法、普查的组织实施以及经费预算等。\n拟订全国污染源普查方案，应当充分听取有关部门和专家的意见。\n第十八条 全国污染源普查领导小组办公室根据全国污染源普查方案拟订污染源普查表，报国家统计局审定。\n省、自治区、直辖市人民政府污染源普查领导小组办公室，可以根据需要增设本行政区域污染源普查附表，报全国污染源普查领导小组办公室批准后使用。\n第十九条 在普查启动阶段，污染源普查领导小组办公室应当进行单位清查。\n县级以上人民政府机构编制、民政、市场监督管理以及其他具有设立审批、登记职能的部门，应当向同级污染源普查领导小组办公室提供其审批或者登记的单位资料，并协助做好单位清查工作。\n污染源普查领导小组办公室应当以本行政区域现有的基本单位名录库为基础，按照全国污染源普查方案确定的污染源普查的具体范围，结合有关部门提供的单位资料，对污染源逐一核实清查，形成污染源普查单位名录。\n第二十条 列入污染源普查范围的大、中型工业企业，应当明确相关机构负责本企业污染源普查表的填报工作，其他单位应当指定人员负责本单位污染源普查表的填报工作。\n第二十一条 污染源普查领导小组办公室可以根据工作需要，聘用或者从有关单位借调人员从事污染源普查工作。\n污染源普查领导小组办公室应当与聘用人员依法签订劳动合同，支付劳动报酬，并为其办理社会保险。借调人员的工资由原单位支付，其福利待遇保持不变。\n第二十二条 普查人员应当坚持实事求是，恪守职业道德，具有执行普查任务所需要的专业知识。\n污染源普查领导小组办公室应当对普查人员进行业务培训，对考核合格的颁发全国统一的普查员工作证。\n第二十三条 普查人员依法独立行使调查、报告、监督和检查的职权，有权查阅普查对象的原材料消耗记录、生产记录、污染物治理设施运行记录、污染物排放监测记录以及其他与污染物产生和排放有关的原始资料，并有权要求普查对象改正其填报的污染源普查表中不真实、不完整的内容。\n第二十四条 普查人员应当严格执行全国污染源普查方案，不得伪造、篡改普查资料，不得强令、授意普查对象提供虚假普查资料。\n普查人员执行污染源调查任务，不得少于2人，并应当出示普查员工作证；未出示普查员工作证的，普查对象可以拒绝接受调查。\n第二十五条 普查人员应当依法直接访问普查对象，指导普查对象填报污染源普查表。污染源普查表填写完成后，应当由普查对象签字或者盖章确认。普查对象应当对其签字或者盖章的普查资料的真实性负责。\n污染源普查领导小组办公室对其登记、录入的普查资料与普查对象填报的普查资料的一致性负责，并对其加工、整理的普查资料的准确性负责。\n污染源普查领导小组办公室在登记、录入、加工和整理普查资料过程中，对普查资料有疑义的，应当向普查对象核实，普查对象应当如实说明或者改正。\n第二十六条 各地方、各部门、各单位的负责人不得擅自修改污染源普查领导小组办公室、普查人员依法取得的污染源普查资料；不得强令或者授意污染源普查领导小组办公室、普查人员伪造或者篡改普查资料；不得对拒绝、抵制伪造或者篡改普查资料的普查人员打击报复。","level":1},{"name":"第四章 数据处理和质量控制","text":"第二十七条 污染源普查领导小组办公室应当按照全国污染源普查方案和有关标准、技术要求进行数据处理，并按时上报普查数据。\n第二十八条 污染源普查领导小组办公室应当做好污染源普查数据备份和数据入库工作，建立健全污染源信息数据库，并加强日常管理和维护更新。\n第二十九条 污染源普查领导小组办公室应当按照全国污染源普查方案，建立污染源普查数据质量控制岗位责任制，并对普查中的每个环节进行质量控制和检查验收。\n污染源普查数据不符合全国污染源普查方案或者有关标准、技术要求的，上一级污染源普查领导小组办公室可以要求下一级污染源普查领导小组办公室重新调查，确保普查数据的一致性、真实性和有效性。\n第三十条 全国污染源普查领导小组办公室统一组织对污染源普查数据的质量核查。核查结果作为评估全国或者各省、自治区、直辖市污染源普查数据质量的重要依据。\n污染源普查数据的质量达不到规定要求的，有关污染源普查领导小组办公室应当在全国污染源普查领导小组办公室规定的时间内重新进行污染源普查。","level":1},{"name":"第五章 数据发布、资料管理和开发应用","text":"第三十一条 全国污染源普查公报，根据全国污染源普查领导小组的决定发布。\n地方污染源普查公报，经上一级污染源普查领导小组办公室核准发布。\n第三十二条 普查对象提供的资料和污染源普查领导小组办公室加工、整理的资料属于国家秘密的，应当注明秘密的等级，并按照国家有关保密规定处理。\n污染源普查领导小组办公室、普查人员对在污染源普查中知悉的普查对象的商业秘密，负有保密义务。\n第三十三条 污染源普查领导小组办公室应当建立污染源普查资料档案管理制度。污染源普查资料档案的保管、调用和移交应当遵守国家有关档案管理规定。\n第三十四条 国家建立污染源普查资料信息共享制度。\n污染源普查领导小组办公室应当在污染源信息数据库的基础上，建立污染源普查资料信息共享平台，促进普查成果的开发和应用。\n第三十五条 污染源普查取得的单个普查对象的资料严格限定用于污染源普查目的，不得作为考核普查对象是否完成污染物总量削减计划的依据，不得作为依照其他法律、行政法规对普查对象实施行政处罚和征收排污费的依据。","level":1},{"name":"第六章 表彰和处罚","text":"第三十六条 对在污染源普查工作中做出突出贡献的集体和个人，应当给予表彰和奖励。\n第三十七条 地方、部门、单位的负责人有下列行为之一的，依法给予处分，并由县级以上人民政府统计机构予以通报批评；构成犯罪的，依法追究刑事责任：\n（一）擅自修改污染源普查资料的；\n（二）强令、授意污染源普查领导小组办公室、普查人员伪造或者篡改普查资料的；\n（三）对拒绝、抵制伪造或者篡改普查资料的普查人员打击报复的。\n第三十八条 普查人员不执行普查方案，或者伪造、篡改普查资料，或者强令、授意普查对象提供虚假普查资料的，依法给予处分。\n污染源普查领导小组办公室、普查人员泄露在普查中知悉的普查对象商业秘密的，对直接负责的主管人员和其他直接责任人员依法给予处分；对普查对象造成损害的，应当依法承担民事责任。\n第三十九条 污染源普查对象有下列行为之一的，污染源普查领导小组办公室应当及时向同级人民政府统计机构通报有关情况，提出处理意见，由县级以上人民政府统计机构责令改正，予以通报批评；情节严重的，可以建议对直接负责的主管人员和其他直接责任人员依法给予处分：\n（一）迟报、虚报、瞒报或者拒报污染源普查数据的；\n（二）推诿、拒绝或者阻挠普查人员依法进行调查的；\n（三）转移、隐匿、篡改、毁弃原材料消耗记录、生产记录、污染物治理设施运行记录、污染物排放监测记录以及其他与污染物产生和排放有关的原始资料的。\n单位有本条第一款所列行为之一的，由县级以上人民政府统计机构予以警告，可以处5万元以下的罚款。\n个体经营户有本条第一款所列行为之一的，由县级以上人民政府统计机构予以警告，可以处1万元以下的罚款。\n第四十条 污染源普查领导小组办公室应当设立举报电话和信箱，接受社会各界对污染源普查工作的监督和对违法行为的检举，并对检举有功的人员依法给予奖励，对检举的违法行为，依法予以查处。","level":1},{"name":"第七章 附 则","text":"第四十一条 军队、武装警察部队的污染源普查工作，由中国人民解放军总后勤部按照国家统一规定和要求组织实施。\n新疆生产建设兵团的污染源普查工作，由新疆生产建设兵团按照国家统一规定和要求组织实施。\n第四十二条 本条例自公布之日起施行。","level":1}]},{"id":"n1306","sections":[{"name":"","text":"中华人民共和国进出口商品检验法实施条例\n（2005年8月31日中华人民共和国国务院令第447号公布 根据2013年7月18日《国务院关于废止和修改部分行政法规的决定》第一次修订 根据2016年2月6日《国务院关于修改部分行政法规的决定》第二次修订 根据2017年3月1日《国务院关于修改和废止部分行政法规的决定》第三次修订 根据2019年3月2日《国务院关于修改部分行政法规的决定》第四次修订 根据2022年3月29日《国务院关于修改和废止部分行政法规的决定》第五次修订 根据2026年8月8日《国务院关于修改和废止部分行政法规的决定》第六次修订）","level":0},{"name":"第一章 总 则","text":"第一条 根据《中华人民共和国进出口商品检验法》（以下简称商检法）的规定，制定本条例。\n第二条 海关总署主管全国进出口商品检验工作。\n海关总署设在省、自治区、直辖市以及进出口商品的口岸、集散地的出入境检验检疫机构及其分支机构（以下简称出入境检验检疫机构），管理所负责地区的进出口商品检验工作。\n第三条 海关总署应当依照商检法第四条规定，制定、调整必须实施检验的进出口商品目录（以下简称目录）并公布实施。\n目录应当至少在实施之日30日前公布；在紧急情况下，应当不迟于实施之日公布。\n海关总署制定、调整目录时，应当征求国务院对外贸易主管部门等有关方面的意见。\n第四条 出入境检验检疫机构对列入目录的进出口商品以及法律、行政法规规定须经出入境检验检疫机构检验的其他进出口商品实施检验（以下称法定检验）。\n出入境检验检疫机构对法定检验以外的进出口商品，根据国家规定实施抽查检验。\n第五条 进出口药品的质量检验、计量器具的量值检定、锅炉压力容器的安全监督检验、船舶（包括海上平台、主要船用设备及材料）和集装箱的规范检验、飞机（包括飞机发动机、机载设备）的适航检验以及核承压设备的安全检验等项目，由有关法律、行政法规规定的机构实施检验。\n第六条 进出境的样品、礼品、暂时进出境的货物以及其他非贸易性物品，免予检验。但是，法律、行政法规另有规定的除外。\n列入目录的进出口商品符合国家规定的免予检验条件的，由收货人、发货人或者生产企业申请，经海关总署审查批准，出入境检验检疫机构免予检验。\n免予检验的具体办法，由海关总署商有关部门制定。\n第七条 法定检验的进出口商品，由出入境检验检疫机构依照商检法第七条规定实施检验。\n海关总署根据进出口商品检验工作的实际需要和国际标准，可以制定进出口商品检验方法的技术规范和行业标准。\n进出口商品检验依照或者参照的技术规范、标准以及检验方法的技术规范和标准，应当至少在实施之日6个月前公布；在紧急情况下，应当不迟于实施之日公布。\n第八条 出入境检验检疫机构根据便利对外贸易的需要，对进出口企业实施分类管理，并按照根据国际通行的合格评定程序确定的检验监管方式，对进出口商品实施检验。\n第九条 出入境检验检疫机构对进出口商品实施检验的内容，包括是否符合安全、卫生、健康、环境保护、防止欺诈等要求以及相关的品质、数量、重量等项目。\n第十条 出入境检验检疫机构依照商检法的规定，对实施许可制度和国家规定必须经过认证的进出口商品实行验证管理，查验单证，核对证货是否相符。\n实行验证管理的进出口商品目录，由海关总署商有关部门后制定、调整并公布。\n第十一条 进出口商品的收货人或者发货人可以自行办理报检手续，也可以委托代理报检企业办理报检手续；采用快件方式进出口商品的，收货人或者发货人应当委托出入境快件运营企业办理报检手续。\n第十二条 进出口商品的收货人或者发货人办理报检手续，应当依法向出入境检验检疫机构备案。\n第十三条 代理报检企业接受进出口商品的收货人或者发货人的委托，以委托人的名义办理报检手续的，应当向出入境检验检疫机构提交授权委托书，遵守本条例对委托人的各项规定；以自己的名义办理报检手续的，应当承担与收货人或者发货人相同的法律责任。\n出入境快件运营企业接受进出口商品的收货人或者发货人的委托，应当以自己的名义办理报检手续，承担与收货人或者发货人相同的法律责任。\n委托人委托代理报检企业、出入境快件运营企业办理报检手续的，应当向代理报检企业、出入境快件运营企业提供所委托报检事项的真实情况；代理报检企业、出入境快件运营企业接受委托人的委托办理报检手续的，应当对委托人所提供情况的真实性进行合理审查。\n第十四条 海关总署建立进出口商品风险预警机制，通过收集进出口商品检验方面的信息，进行风险评估，确定风险的类型，采取相应的风险预警措施及快速反应措施。\n海关总署和出入境检验检疫机构应当及时向有关方面提供进出口商品检验方面的信息。\n第十五条 出入境检验检疫机构工作人员依法执行职务，有关单位和个人应当予以配合，任何单位和个人不得非法干预和阻挠。","level":1},{"name":"第二章 进口商品的检验","text":"第十六条 法定检验的进口商品的收货人应当持合同、发票、装箱单、提单等必要的凭证和相关批准文件，向报关地的出入境检验检疫机构报检；通关放行后20日内，收货人应当依照本条例第十八条的规定，向出入境检验检疫机构申请检验。法定检验的进口商品未经检验的，不准销售，不准使用。\n进口实行验证管理的商品，收货人应当向报关地的出入境检验检疫机构申请验证。出入境检验检疫机构按照海关总署的规定实施验证。\n第十七条 法定检验的进口商品、实行验证管理的进口商品，海关按照规定办理海关通关手续。\n第十八条 法定检验的进口商品应当在收货人报检时申报的目的地检验。\n大宗散装商品、易腐烂变质商品以及已发生残损、短缺的商品，应当在卸货口岸检验。\n对前两款规定的进口商品，海关总署可以根据便利对外贸易和进出口商品检验工作的需要，指定在其他地点检验。\n第十九条 除法律、行政法规另有规定外，法定检验的进口商品经检验，涉及人身财产安全、健康、环境保护项目不合格的，由出入境检验检疫机构责令当事人销毁，或者出具退货处理通知单，办理退运手续；其他项目不合格的，可以在出入境检验检疫机构的监督下进行技术处理，经重新检验合格的，方可销售或者使用。当事人申请出入境检验检疫机构出证的，出入境检验检疫机构应当及时出证。\n出入境检验检疫机构对检验不合格的进口成套设备及其材料，签发不准安装使用通知书。经技术处理，并经出入境检验检疫机构重新检验合格的，方可安装使用。\n第二十条 法定检验以外的进口商品，经出入境检验检疫机构抽查检验不合格的，依照本条例第十九条的规定处理。\n实行验证管理的进口商品，经出入境检验检疫机构验证不合格的，参照本条例第十九条的规定处理或者移交有关部门处理。\n法定检验以外的进口商品的收货人，发现进口商品质量不合格或者残损、短缺，申请出证的，出入境检验检疫机构或者其他检验机构应当在检验后及时出证。\n第二十一条 对属于法定检验范围内的关系国计民生、价值较高、技术复杂的以及其他重要的进口商品和大型成套设备，应当按照对外贸易合同约定监造、装运前检验或者监装。收货人保留到货后最终检验和索赔的权利。\n出入境检验检疫机构可以根据需要派出检验人员参加或者组织实施监造、装运前检验或者监装。\n第二十二条 对价值较高，涉及人身财产安全、健康、环境保护项目的高风险进口旧机电产品，应当依照国家有关规定实施装运前检验，进口时，收货人应当提供出入境检验检疫机构或者检验机构出具的装运前检验证书。\n进口国家允许进口的旧机电产品到货后，由出入境检验检疫机构依法实施检验。\n第二十三条 进口机动车辆到货后，收货人凭出入境检验检疫机构签发的进口机动车辆检验证单以及有关部门签发的其他单证向车辆管理机关申领行车牌证。在使用过程中发现有涉及人身财产安全的质量缺陷的，出入境检验检疫机构应当及时作出相应处理。","level":1},{"name":"第三章 出口商品的检验","text":"第二十四条 法定检验的出口商品的发货人应当在海关总署统一规定的地点和期限内，持合同等必要的凭证和相关批准文件向出入境检验检疫机构报检。法定检验的出口商品未经检验或者经检验不合格的，不准出口。\n出口商品应当在商品的生产地检验。海关总署可以根据便利对外贸易和进出口商品检验工作的需要，指定在其他地点检验。\n出口实行验证管理的商品，发货人应当向出入境检验检疫机构申请验证。出入境检验检疫机构按照海关总署的规定实施验证。\n第二十五条 在商品生产地检验的出口商品需要在口岸换证出口的，由商品生产地的出入境检验检疫机构按照规定签发检验换证凭单。发货人应当在规定的期限内持检验换证凭单和必要的凭证，向口岸出入境检验检疫机构申请查验。经查验合格的，由口岸出入境检验检疫机构签发货物通关单。\n第二十六条 法定检验的出口商品、实行验证管理的出口商品，海关按照规定办理海关通关手续。\n第二十七条 法定检验的出口商品经出入境检验检疫机构检验或者经口岸出入境检验检疫机构查验不合格的，可以在出入境检验检疫机构的监督下进行技术处理，经重新检验合格的，方准出口；不能进行技术处理或者技术处理后重新检验仍不合格的，不准出口。\n第二十八条 法定检验以外的出口商品，经出入境检验检疫机构抽查检验不合格的，依照本条例第二十七条的规定处理。\n实行验证管理的出口商品，经出入境检验检疫机构验证不合格的，参照本条例第二十七条的规定处理或者移交有关部门处理。\n第二十九条 出口危险货物包装容器的生产企业，应当向出入境检验检疫机构申请包装容器的性能鉴定。包装容器经出入境检验检疫机构鉴定合格并取得性能鉴定证书的，方可用于包装危险货物。\n出口危险货物的生产企业，应当向出入境检验检疫机构申请危险货物包装容器的使用鉴定。使用未经鉴定或者经鉴定不合格的包装容器的危险货物，不准出口。\n第三十条 对装运出口的易腐烂变质食品、冷冻品的集装箱、船舱、飞机、车辆等运载工具，承运人、装箱单位或者其代理人应当在装运前向出入境检验检疫机构申请清洁、卫生、冷藏、密固等适载检验。未经检验或者经检验不合格的，不准装运。","level":1},{"name":"第四章 监督管理","text":"第三十一条 出入境检验检疫机构根据便利对外贸易的需要，可以对列入目录的出口商品进行出厂前的质量监督管理和检验。\n出入境检验检疫机构进行出厂前的质量监督管理和检验的内容，包括对生产企业的质量保证工作进行监督检查，对出口商品进行出厂前的检验。\n第三十二条 国家对进出口食品生产企业实施卫生注册登记管理。获得卫生注册登记的出口食品生产企业，方可生产、加工、储存出口食品。获得卫生注册登记的进出口食品生产企业生产的食品，方可进口或者出口。\n实施卫生注册登记管理的进口食品生产企业，应当按照规定向海关总署申请卫生注册登记。\n实施卫生注册登记管理的出口食品生产企业，应当按照规定向出入境检验检疫机构申请卫生注册登记。\n出口食品生产企业需要在国外卫生注册的，依照本条第三款规定进行卫生注册登记后，由海关总署统一对外办理。\n第三十三条 出入境检验检疫机构根据需要，对检验合格的进出口商品加施商检标志，对检验合格的以及其他需要加施封识的进出口商品加施封识。具体办法由海关总署制定。\n第三十四条 出入境检验检疫机构按照有关规定对检验的进出口商品抽取样品。验余的样品，出入境检验检疫机构应当通知有关单位在规定的期限内领回；逾期不领回的，由出入境检验检疫机构处理。\n第三十五条 进出口商品的报检人对出入境检验检疫机构作出的检验结果有异议的，可以自收到检验结果之日起15日内，向作出检验结果的出入境检验检疫机构或者其上级出入境检验检疫机构以至海关总署申请复验，受理复验的出入境检验检疫机构或者海关总署应当自收到复验申请之日起60日内作出复验结论。技术复杂，不能在规定期限内作出复验结论的，经本机构负责人批准，可以适当延长，但是延长期限最多不超过30日。\n第三十六条 海关总署或者出入境检验检疫机构根据进出口商品检验工作的需要，可以指定符合规定资质条件的国内外检测机构承担出入境检验检疫机构委托的进出口商品检测。被指定的检测机构经检查不符合规定要求的，海关总署或者出入境检验检疫机构可以取消指定。\n第三十七条 对检验机构的检验鉴定业务活动有异议的，可以向海关总署或者出入境检验检疫机构投诉。\n第三十八条 海关总署、出入境检验检疫机构实施监督管理或者对涉嫌违反进出口商品检验法律、行政法规的行为进行调查，有权查阅、复制当事人的有关合同、发票、账簿以及其他有关资料。出入境检验检疫机构对有根据认为涉及人身财产安全、健康、环境保护项目不合格的进出口商品，经本机构负责人批准，可以查封或者扣押。\n第三十九条 海关总署、出入境检验检疫机构应当根据便利对外贸易的需要，采取有效措施，简化程序，方便进出口。\n办理进出口商品报检、检验、鉴定等手续，符合条件的，可以采用电子数据文件的形式。\n第四十条 出入境检验检疫机构依照有关法律、行政法规的规定，签发出口货物普惠制原产地证明、区域性优惠原产地证明、专用原产地证明。\n出口货物一般原产地证明的签发，依照有关法律、行政法规的规定执行。\n第四十一条 出入境检验检疫机构对进出保税区、出口加工区等海关特殊监管区域的货物以及边境小额贸易进出口商品的检验管理，由海关总署另行制定办法。","level":1},{"name":"第五章 法律责任","text":"第四十二条 擅自销售、使用未报检或者未经检验的属于法定检验的进口商品，或者擅自销售、使用应当申请进口验证而未申请的进口商品的，由出入境检验检疫机构没收违法所得，并处商品货值金额5%以上20%以下罚款；构成犯罪的，依法追究刑事责任。\n第四十三条 擅自出口未报检或者未经检验的属于法定检验的出口商品，或者擅自出口应当申请出口验证而未申请的出口商品的，由出入境检验检疫机构没收违法所得，并处商品货值金额5%以上20%以下罚款；构成犯罪的，依法追究刑事责任。\n第四十四条 销售、使用经法定检验、抽查检验或者验证不合格的进口商品，或者出口经法定检验、抽查检验或者验证不合格的商品的，由出入境检验检疫机构责令停止销售、使用或者出口，没收违法所得和违法销售、使用或者出口的商品，并处违法销售、使用或者出口的商品货值金额等值以上3倍以下罚款；构成犯罪的，依法追究刑事责任。\n第四十五条 进出口商品的收货人、发货人、代理报检企业或者出入境快件运营企业、报检人员不如实提供进出口商品的真实情况，取得出入境检验检疫机构的有关证单，或者对法定检验的进出口商品不予报检，逃避进出口商品检验的，由出入境检验检疫机构没收违法所得，并处商品货值金额5%以上20%以下罚款。\n进出口商品的收货人或者发货人委托代理报检企业、出入境快件运营企业办理报检手续，未按照规定向代理报检企业、出入境快件运营企业提供所委托报检事项的真实情况，取得出入境检验检疫机构的有关证单的，对委托人依照前款规定予以处罚。\n代理报检企业、出入境快件运营企业、报检人员对委托人所提供情况的真实性未进行合理审查或者因工作疏忽，导致骗取出入境检验检疫机构有关证单的结果的，由出入境检验检疫机构对代理报检企业、出入境快件运营企业处2万元以上20万元以下罚款。\n第四十六条 伪造、变造、买卖或者盗窃检验证单、印章、标志、封识、货物通关单或者使用伪造、变造的检验证单、印章、标志、封识、货物通关单，构成犯罪的，依法追究刑事责任；尚不够刑事处罚的，由出入境检验检疫机构责令改正，没收违法所得，并处商品货值金额等值以下罚款。\n第四十七条 擅自调换出入境检验检疫机构抽取的样品或者出入境检验检疫机构检验合格的进出口商品的，由出入境检验检疫机构责令改正，给予警告；情节严重的，并处商品货值金额10%以上50%以下罚款。\n第四十八条 进口或者出口国家实行卫生注册登记管理而未获得卫生注册登记的生产企业生产的食品的，由出入境检验检疫机构责令停止进口或者出口，没收违法所得，并处商品货值金额10%以上50%以下罚款。\n已获得卫生注册登记的进出口食品生产企业，经检查不符合规定要求的，由海关总署或者出入境检验检疫机构责令限期整改；整改仍未达到规定要求或者有其他违法行为，情节严重的，吊销其卫生注册登记证书。\n第四十九条 进口国家允许进口的旧机电产品未按照规定进行装运前检验的，按照国家有关规定予以退货；情节严重的，由出入境检验检疫机构并处100万元以下罚款。\n第五十条 提供或者使用未经出入境检验检疫机构鉴定的出口危险货物包装容器的，由出入境检验检疫机构处10万元以下罚款。\n提供或者使用经出入境检验检疫机构鉴定不合格的包装容器装运出口危险货物的，由出入境检验检疫机构处20万元以下罚款。\n第五十一条 提供或者使用未经出入境检验检疫机构适载检验的集装箱、船舱、飞机、车辆等运载工具装运易腐烂变质食品、冷冻品出口的，由出入境检验检疫机构处10万元以下罚款。\n提供或者使用经出入境检验检疫机构检验不合格的集装箱、船舱、飞机、车辆等运载工具装运易腐烂变质食品、冷冻品出口的，由出入境检验检疫机构处20万元以下罚款。\n第五十二条 擅自调换、损毁出入境检验检疫机构加施的商检标志、封识的，由出入境检验检疫机构处5万元以下罚款。\n第五十三条 从事进出口商品检验鉴定业务的检验机构违反国家有关规定，扰乱检验鉴定秩序的，由出入境检验检疫机构责令改正，没收违法所得，可以并处10万元以下罚款，海关总署或者出入境检验检疫机构可以暂停其6个月以内检验鉴定业务。\n第五十四条 代理报检企业、出入境快件运营企业违反国家有关规定，扰乱报检秩序的，由出入境检验检疫机构责令改正，没收违法所得，可以处10万元以下罚款，海关总署或者出入境检验检疫机构可以暂停其6个月以内代理报检业务。\n第五十五条 出入境检验检疫机构的工作人员滥用职权，故意刁难当事人的，徇私舞弊，伪造检验结果的，或者玩忽职守，延误检验出证的，依法给予行政处分；违反有关法律、行政法规规定签发出口货物原产地证明的，依法给予行政处分，没收违法所得；构成犯罪的，依法追究刑事责任。\n第五十六条 出入境检验检疫机构对没收的商品依法予以处理所得价款、没收的违法所得、收缴的罚款，全部上缴国库。","level":1},{"name":"第六章 附 则","text":"第五十七条 当事人对出入境检验检疫机构、海关总署作出的复验结论、处罚决定不服的，可以依法申请行政复议，也可以依法向人民法院提起诉讼。\n当事人逾期不履行处罚决定，又不申请行政复议或者向人民法院提起诉讼的，作出处罚决定的机构可以申请人民法院强制执行。\n第五十八条 出入境检验检疫机构实施法定检验、依法设立的检验机构办理检验鉴定业务，按照国家有关规定收取费用。\n第五十九条 本条例自2005年12月1日起施行。1992年10月7日国务院批准、1992年10月23日原国家进出口商品检验局发布的《中华人民共和国进出口商品检验法实施条例》同时废止。","level":1}]}]);
